window.__D("text/zohar/c021",{"p":[[9520011799,"<p><Noneb>פִרְקָא תִּנְיָינָא</b> דִּיקְנָא (אד\"ר מן דף קל\"א עד קל\"ה) מְהֵימָנוּתָא. (דיקנא) לָא אַדְכַּר בְּגִין דְּהִיא יַקִירוּתָא דְּכֹלָּא מֵאֻדְנִין נַפְקַת, בְּסָחֲרָנָהָא דְּבֹּסִיטָא, סָלִיק וְנָחִית חוּטָא חִוְורָא. בִּתְלֵיסָר מִתְפְּרַשׁ.</p>\n<p>בְּיָקִירָא דִּבְיָקִירוּתָא הַהִיא, כְּתִיב (ירמיהו ב׳:ו׳) לא עָבַר בָּהּ אִישׁ וְלָא יָשַׁב אָדָם שָׁם. אָדָם (ויקרא מ\"ח ע\"א) לְבַר הוּא. אָדָם לָא כָּלִיל הָכָא. כָּל שֶׁכֵּן אִישׁ. בִּתְלֵיסָר נְבִיעִין מַבּוּעִין מִתְפָּרְשָׁן, אַרְבַּע בִּלְחוֹדוֹי אִסְתָּמָרוּ. תִּשְׁעָה אַשְׁקְיוּן לְגוּפָא. (נ\"א לגנתא).</p>\n<p>(תיקונא קדמאה) מִקָּמֵי פְּתִחָא דְּאֻדְנִין, שָׁאֲרִי יָקִירוּ לְאִתְתָּקָן, (תניינא) נָחִית בִּשְׁפִּירִי בְּרֵישָׁא דְּשִׂפְוָון. מֵהַאי רֵישָׁא לְהַאי רִישָׁא קָאִים. (תליתאה) אָרְחָא דְּנָפִיק תְּחוֹת תְּרֵין נוּקְבִין דְּפַרְדַּשְׂקָא, לְאַעְבְרָא חוֹבָה, דְּכְתִּיב (משלי י״ט:י״א) וְתִפְאַרְתּוֹ עֲבוֹר עַל פָּשַׁע. (רביעאה) תְּחוֹת שִׂפְוָון אַסְחַר שַׂעֲרָא לְרִישָׁא אַחֲרָא. (חמישאה) אָרְחָא אַחֲרָא נָפִיק תְּחוֹתוֹי. (שתיתאה) חָפֵי תַּקְרוּבְתָּא דְּבוּסְמָא, לְרֵישָׁא דִּלְעֵילָּא. (שביעאה) תְּרֵין תַּפּוּחִין אִתְחָזוּן לְאַנְהָרָא בּוּצִינִין. (תמינאה) מַזָּלָא דְּכֹלָּא, תַּלְיָיא עַד לִבָּא, בֵּיהּ תַּלְיָין עִלָּאִין וְתַתָּאִין.</p>\n<p>(תשיעאה) אִינּוּן דְּתַלְיָין לָא נָפְקִין דָּא מִן דָּא. (עשיראה) חַפְיָין זְעִירִין עַל גְּרוֹנָא (חד סר) דְּיָקִירוּ. רַבְרְבִין, מִתְשַׁעֲרִין בְשִׁיעוּרָא שְׁלִים. (תריסר) (וכד) שִׂפְוָון אִתְפְּנוּן מִכָּל סִטְרִין, זַכָּאָה לְמַאן דְּנָשִׁיק מֵאִינּוּן נְשִׁיקִין. (תליסר) בְּהַהִיא מַזָּלָא דְּכֹלָּא נַגְדִּין תְּלֵיסַר מְשִׁיחִין דְּאֲפַרְסְמוֹנָא דַּכְיָא. כֹּלָּא בְּהַאי מַזָּלָא שְׁכִיחַ, וְסָתִים.</p>\n<p>בְּזִמְנָא דְּמָטָא תִּשְׁרֵי, יַרְחָא שְׁבִיעָאָה, מִשְׁתַּכְחֵי (ירחי) אִלֵּין תְּרֵיסַר (ס\"א תליסר) בְּעַלְמָא עִלָּאָה וּמִתְפַּתְּחֵי תְּרֵיסַר (ס\"א תליסר) תַּרְעֵי דְּרַחֲמֵי, בְּהַהוּא זִמְנָא (ישעיה נה) דִּרְשׁוּ יְיָ' בְּהִמָּצְאוֹ כְּתִּיב.</p>\n<p>(בראשית א׳:י״א) וַיֹּאמֶר אֱלֹהִים תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע עֵץ פְּרִי וְגוֹ', הַיְינוּ דְּכְתִּיב (ויקרא ט״ז:ל״א) וְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם בְּתִשְׁעָה לַחֹדֶשׁ בָּעֶרֶב. (בהאי זמנא) (דברים ג׳:כ״ד) אֲדֹנָי ידו\"ד אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְךָ אֶת גָּדְלְךָ. יהו\"ה שְׁלִים בְּסִטְרוֹי. וְהָכָא בִּרְחִישׁוּתָא דָּא דְּאַרְעָא, לָא שְׁלִים.</p>\n<p>יְהִ\"י לָא כְּתִיב, קָרֵינָן יוֹ\"ד עִלָּאָה יוֹ\"ד תַּתָּאָה, וַיִּיצֶר י' עִלָּאָה י' תַּתָּאָה, (יהי) י' עִלָּאָה, י' תַּתָּאָה. ה' בְגַוַויְיהוּ. כְּלָלָא דִּשְׁלִימוּ. שְׁלִים, וְלָא לְכָל סְטָר. אִתְּעֲקָר מֵהַאי אֲתָר שְׁמָא דָּא, וְאַשְׁתִּיל בְּאַחֲרָא, כְּתִיב וַיִּטַּע יְיָ' אֱלהִים.</p>\n<p>ה ' בֵּין יוֹ\"ד לְיוֹ\"ד דִּיְהִ\"י, נָשְׁבָא דְּפַרְדַּשְׂקָא דְעַתִּיקָא, לִזְעִירָא דְּאַנְפִּין בְּלָא רוּחָא לָא אִתְקְיָּים. בְּהֵ\"א, אִשְׁתָּכְלַל הֵ\"א עִלָּאָה הֵ\"א תַּתָּאָה, דְּכְתִּיב (ירמיהו א׳:ו׳) אֲהָהּ אֲדֹנָי אֱלהִים.</p>\n<p>בְּקִיטְפוֹי דְּקַטְפִין, (צרירא) בְּרוּחָא דְּמַתְקְלִין, יה\"ו. י' עִלָּאָה דְּאִתְעַטָּר בְּקִטְרָא (ס\"א בעטרא) דְעַתִּיקָא, הוּא קְרוּמָא עִלָּאָה דְּאִזְדְּכַךְ וְסָתִים. הֵ\"א עִלָּאָה, דְּאִתְעַטָּר בְּרוּחָא דְּנוּקְבִין דְּפַרְדַּשְׂקָא, דְּנָפִיק לְאַחֲיָיא. ו' עִלָּאָה, בּוֹצִינָא דְּקַרְדִּינוּתָא דְּאִתְעַטָּר בְּסִטְרוֹי, (ס\"א בעטרוי) מִתְפַּשְּׁטָן אַתְוָון לְבָתַר, וְאִתְכְּלָלוּ בִּזְעֵירָא דְּאַפִּין. כְּמָה דְּשַׁרְיָא בְּגוּלְגֹלְתָא, אִשְׁתַּכְּחוּ מִתְפַּשְּׁטָן בְּכָל גּוּפָא, לְשַׁכְלְלָא כֹּלָּא. בַּעֲמָר נְקֵא. כַּד תָּלֵי תַּלְיָין אִלֵּין אַתְוָון. כַּד אִתְגְּלֵי לִזְעֵירָא מִתְיַישְּׁבָן בֵּיהּ אִלֵּין אַתְוָון, וְאִתְקְרֵי בְּהוֹן.</p>\n<p>יוֹ\"ד דְּעַתִּיקָא סָתִים בְּעִטְרוֹי, בְּגִין שְׂמָאלָא אִשְׁתְּכַח ה\"ה אִתְפְּתַח בְּאַחֲרָא וְאִינְקִיב בִּתְרֵין נוּקְבִין, וְאִשְׁתְּכַח בְּתִקוּנִין. וָ\"ו אִתְפְּתַח בְּאַחֲרָא, דִּכְתִּיב, (שיר השירים ז׳:י׳) הוֹלֵךְ לְדוֹדִי לְמֵישָׁרִים. בְּבוּצִינָא דְּקַרְדִּינוּתָא לִמְכַסְיָא פִּתְחָא.</p>\n<p>ו' לְעֵילָּא ו' לְתַתָּא, ה' לְעֵילָּא ה' לְתַתָּא. י' לְעֵילָּא וּבָהּ לָא אִשְׁתָּתַּף אַחֲרָא, וְלָא סָלִיק בַּהֲדָהּ, בַּר רְמִיזָא דְּרָמִיז כַּד אִתְגַּלְּיָין תְּרֵין (באורייתא) וּמִתְחַבְּרָן בְּחַד דַּרְגָּא, חַד רִגְּשָׁא בְּגִין לְאִתְפָּרְשָׁא, ו\"ד כְּלִילָן בְּיוֹ\"ד וַוי כַּד אִסְתַּלָּק הַאי, וְאִתְגַּלְיָין.</p>\n<p>אִינּוּן בּוּסְמִין דְּטִיפְסָא שְׁרִיקִין, דְּעַבְרֵי (ס\"א עבד) לָא מִתְעַכְּבָא בְּדוּכְתָּא, וְהַחַיּוֹת רָצוֹא וָשׁוֹב. בְּרַח לְךָ אֶל מְקוֹמֶךָ. אִם תַּגְבִּיהַ כַּנֶּשֶׁר וְאִם בֵּין כּוֹכָבִים שִׂים קִנֶּךָ מִשָּׁם אוֹרִידְךָ.</p>\n<p>וַתּוֹצֵא הָאָרֶץ <Nonei></i>דֶּשֶׁא. אֵימָתַי, כַּד שְׁמָא אִתְנְטַע. וּכְדֵין אֲוִירָא נָפִיק, וְנִצוֹצָא אִזְדָּמָן. (תיקונא קדמאה דרישא) חַד גּוּלְגַלְתָּא אִתְפָּשָּׁט בְּסִטְרוֹי, טַלָּא מָלֵּי עָלָהּ, דִּתְרֵי גְּוָונֵי.</p>\n<p>תְּלַת חַלָלִּין דְּאַתְוָון רְשִׁימִין, אִתְגַּלְּיָין בֵּיהּ. (תליתאה) אוּכָמִין (ס\"א כעורבא) כְּעַרְבָאָה תַּלְיָין עַל נוּקְבִין עֲמִיקִין, דְּלָא יָכִיל לְמִשְׁמַע יְמִינָא וּשְׂמָאלָא. הָכָא חַד אָרְחָא לְעֵילָּא דָּקִיק.</p>\n<p>(רביעאה) מִצְחָא דְּלָא נָהִיר, קְטָטוּתָא דְּעָלְמָא. בַּר כַּד רַעֲוָא אַשְׁגַּח בֵּיהּ. (חמישאה) עַיְינִין דִּתְלַת גְּוָונֵי, לְמִרְתַּת קָמַיְיהוּ אִתְסְחָן בְּחֲלָבָא דְּנָהִיר. כְּתִיב (ישעיהו ל״ג:כ׳) עֵינֶיךָ תִרְאֶינָה יְרוּשָׁלַיִם נָוְה שַׁאֲנָן, וּכְתִיב (ישעיהו א׳:כ״א) צֶדֶק יָלִין בָּה. נָוֶה שַׁאֲנָן, עַתִּיקָא דְּסָתִים, עֵינְךָ כְּתִיב.</p>\n<p>(שתיתאה) חוֹטָמָא פַּרְצוּפָא דִּזְעֵירָא, לְאִשְׁתְּמוֹדְעָא. תְּלַת שַׁלְהוֹבִין מִתּוֹקָדִין בְּנוּקְבוֹי. (שביעאה) דַּרְגָּא עֲקִימָא, לְמִשְׁמַע טָב וּבִישׁ.</p>\n<p>כְּתִיב (ישעיהו מ״ב:ח׳) אֲנִי יְיָ' הוּא שְׁמִי. וּכְתִיב (דברים לכ) אֲנִי אֲמִית וַאֲחֲיֶּה. וּכְתִיב (ישעיהו מ״ו:ד׳) וַאֲנִי אֶשָּׂא וַאֲנִי אֶסְבּוֹל. (קל\"ד ע\"ב) (תהלים ק) הוּא עָשָׂנוּ וְלוֹ אֲנַחְנוּ. (איוב כ״ג:י״ג) וְהוּא בְּאֶחָד וּמִי יְשִׁיבֶנּוּ. הוּא אִקְרֵי מַאן דְּסָתִים וְלָא שְׁכִיחַ, הוּא מַאן דְּלָא אִזְדָּמָן לְעֵינָא. הוּא מַאן דְּלָא אִקְרֵי בִּשְׁמָא.</p>\n<p>(ה\"א ה\"י) א' כָּלִיל (הוא') ו'. ו' כָּלִיל א' וְלָא כָּלִיל ה\"ו. (ס\"א ה\"י) א' אָזִיל לְאָלֶף. אל\"ף אָזִיל ליו\"ד, יו\"ד אָזִיל ליו\"ד, דְּסָתִים מִכָּל סְתִימִין, דְּלָא מִתְּחַבְּרָן בֵּיהּ ו\"ד. וַוי כַּד לָא נָהִיר י' בו\"ד.</p>\n<p>כַּד אִסְתַּלָּק י' מִן ו\"ד בְּחוֹבֵי עָלְמָא, עֶרְיָיתָא דְּכֹלָּא אִשְׁתְּכַח, עַל דָּא כְּתִיב (ויקרא י״ח:ח׳) עֶרְוַת אָבִיךָ לא תְגַלֵּה. וְכַד אִסְתָּלִיק יוֹ\"ד מִן הֵ\"א, עַל דָּא כְּתִיב וְעֶרְוַת אִמְּךָ לא תְגַלֶּה אִמְּךָ הִיא לֹא תְגַלֵּה עֶרְוָתָהּ. אִמְּךָ הִיא וַדַּאי, (משלי ב׳:ג׳) כִּי אִם לַבִּינָה תִקְרָא וְגוֹ'.</p>"],[9520011800,"<p><Noneb>פִּרְקָא תְּלִיתָאָה</b> תִּשְׁעָה תִּקּוּנִין יַקִּירִין אִתְמְסָרוּ לְדִיקְנָא כָּל מָה דְּאִתְטְמַּר וְלָא אִתְגַּלְיָיא עִלָּאָה וְיַקִּירָא אִשְׁתְּכַח. (והוא) והָא (ס\"א דיקנא) גַּנְזֵיהּ (ס\"א יקירא) קְרָא.</p>\n<p>תִּיקוּנָא קַדְמָאָה דְּדִיקְנָא, נִימִין עַל נִימִין מִקָּמֵי פִּתְחָא דְּאֻדְנִין עַד רֵישָׁא דְּפוּמָא. (תניינא) מֵרֵישָׁא הַאי, עַד רֵישָׁא אַחֲרָא אִשְׁתְּכַח. (תליתאה) מִתְּחוֹת תְּרֵין נוּקְבִין אָרְחָא מַלְיָיא דְּלָא אִתְחַזְיָיא. (רביעאה) עַלְעִין אִתְחַפְיָּין מֵהַאי גִּיסָא וּמֵהַאי גִּיסָא. (חמישאה) בְּהוּ אִתְחַזְּיָין תַּפּוּחִין סוּמָקִין כְּוורְדָא. (שתיתאה) בְּחַד חוּטָא תַּלְיָין אוּכָמִין תַּקִּיפִין עַד חַדּוֹי. (שביעאה) שִׂפְוָון סוּמָקִין כְּוורְדָא אִתְפְּנוּן.</p>\n<p>(תמינאה) זְעִירִין נַחְתִּין בִּגְרוֹנָא, וּמְחַפְיָין קְדָלָא. (תשיעאה) רַבְרְבִין וּזְעִירִין כְּגִידִין (ס\"א נגדין) (ס\"א נחתין) בְּשִׁקּוּלָא. בְּאִלֵּין אִשְׁתְּכַח גִּיבָּר וְתַקִּיף מַאן דְּאִשְׁתְּכַח.</p>\n<p>כְּתִיב (תהילים קי״ח:ה׳) מִן הַמֵּצַר קָרָאתִי יָהּ. תִּשְׁעָה אָמַר דָּוִד עַד כָּל גּוֹיִם סְבָבוּנִי, לְאַסְחֲרָא וּלְאַגָּנָא עֲלוֹי. וַתּוֹצֵא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע לְמִינֵהוּ וְעֵץ עוֹשֶׂה פְּרִי אֲשֶׁר זַרְעוֹ בוֹ לְמִינֵהוּ. (נשא קל\"ט ע\"ב) תִּשְׁעָה אִלֵּין אִתְעֲקָרוּ מִשְּׁמָא שְׁלִים, וְאַשְׁתִּילוּ לְבָתַר בִּשְׁמָא שְׁלִים, דִּכְתִּיב וַיִּטַּע יְיָ' אֱלהִים. תִּקּוּנִין דְּדִיקְנָא בִּתְלֵיסָר אִשְׁתַּכְּחָן אִיהִי, דְּהִיא עִלָּאָה. תַּתָּאָה, בְּתִשְׁעָה אִתְחָזוּן. כ\"ב אַתְוָון אִתְגְּלִיפוּ בְּגווַֹנֵיהוֹן (ס\"א בגינהון.)</p>\n<p>עַל הַאי, (ס\"א על האי מאן דחזי בחלמיה דיקנא) חֶלְמָא דְּאָחִיד דִּיקְנָא דְּבַּר נָשׁ עִלָּאָה בִּידֵיהּ, (נ\"א או דאושיט ידיה ליה אנדע דשלים במאריה) שְׁלִים בְּמָארֵיהּ. שַׂנְאִין תְּחוֹתוֹי יִכְנְעוּן. כָּל שֶׁכֵּן דִּיקְנָא עִלָּאָה דִּנְהִירָא (ס\"א לתתאה) בְּתַתָּאָה, דְּעִלָּאָה רַב חֶסֶד אִקְרֵיהּ, בִּזְעֵירָא חֶסֶ\"ד סְתָם, כַּד אִצְטְרִיךְ נְהִירוּ אַנְהַר וְאִקְרֵי רַב חֶסֶד. (ס\"א בידיה הא מתרחיץ דהא בשלם עם מאריה ושנאוי יכנעון תחותוי ודין הוא בדיל דחזא בחלמיה כל שכן אם זכה לאודעא מה היא דיקנא עלאה דהוא נהיר לתתאה ארים עלאה רב בחסד אקרי בזעירא חסד סתם)</p>\n<p>כְּתִיב וַיֹּאמֶר אֱלהִים יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה, כְּלוֹמַר, (נ\"א ח\"י י\"ה) י\"ה אִתְפָּשַׁט נְהִירוּ דְּדָא בְּדָא, כֹּלָּא אִתְרַחֲשׁוּן בְּזִמְנָא חֲדָא, מַיִם טָבָאן מַיִם בִּישָׁן. בְּגִין דְּאָמַר יִשְׁרְצוּ, אִתְכְּלָלוּ דָּא בְּדָא. חַיָּה עִלָּאָה, חַיָּה תַּתָּאָה. חַיָּה <Nonei></i>טָבָא. חַיָּה בִּישָׁא.</p>\n<p><Nonei></i>דָּבָר אַחֵר יִשְׁרְצּוּ הַמַּיִם, תַּרְגּוּם יְרַחֲשׁוּן. כְּלוֹמַר, כַּד מְרַחֲשִׁין בְּשִׂפְוָותֵיהּ פִּתְגָּמֵי צְּלוֹתָא, בְּזָכּוּתָא, וּבִנְקִיוּת דַּעְתָּא, וּבְמַיָא הֲוָה רָחִישׁ נַפְשָׁא חַיָּתָא. וְכַד בָּעֵי בַּר נָשׁ לְסַדְּרָא צְּלוֹתֵיהּ לְמָארֵיהּ, וְשִׂפְוָותֵיהּ מְרַחֲשָׁן בְּהַאי גַּוונָא מִתַּתָּא לְעֵילָּא, לְסַלְּקָא יְקָרָא דְּמָארֵיהּ, לְאֲתָר דְּשַׁקְיוּ דַּעֲמִיקוּ דְּבֵירָא, נָגִיד וְנָפִיק. לְבָתַר יָנְגִיד לְאַמְשָׁכָא מִלְעֵילָּא לְתַתָּא, מֵהַהוּא שַׁקְיָא דְּנַחֲלָא, לְכָל דַּרְגָּא ודַרְגָּא, עַד דַּרְגָּא בַּתְרָאָה לְאַמְשָׁכָא נְדָבָה לְכֹלָּא מֵעֵילָּא לְתַתָּא. לְבָתַר בָּעֵי לְקַשְּׁרָא קִשְׁרָא בְּכֹלָּא, קִשְׁרָא דְּכַוָּנָה דִּמְהֵימְנוּתָא ויַעְבְּדוּן כָּל מִשְׁאַלוֹהִי, בֵּין שְׁאֶלְתָּא דְּצִּבּוּרָא, בֵּין שְׁאֶלְתָּא דְּיָחִידָא.</p>\n<p>וּשְׁאֶלְתָּא דְּאִית לְבַר נָשׁ לְשַּׁאֲלָא מִמָּארֵיהּ, הֵן מְסוּדָרוֹת בט' גְּוָונֵי, אִית בְּאַלְפָא בֵּיתָא, וְאִית בְּאַדְכָּר מְכִילּוֹהִי דְּקוּדְשָׁא בְּרִיךְ הוּא, רַחוּם וְחַנּוּן וגוֹ'. אִית בִּשְׁמָהָן יַקִירָן דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּגוֹן אֶהְיֶה, יָהּ, יהו, אֵל, אֱלהִים, יְיָ' צְּבָאוֹת, שַׁדַּי, אֲדֹנָי. אִית בְּעֶשֶׂר סְפִירָא, כְּגוֹן: מַלְכוּת, יְסוֹד, הוֹד, נְצַּח, תִפְאֶרֶת, גְּבוּרָה, חֶסֶד, בִּינָה, חָכְמָה, כֶּתֶר. אִית בְּאַדְכָּר צַּדִּיקַיָּיא, כְּגוֹן הָאָבוֹת וְהַנְּבִיאִים וְהַמְּלָכִים. אִית בְּשִׁירֵי וּבְתוּשְׁבַּחְתֵּי, דְּאִית בְּהוֹן קַבָּלָה אֲמִיתִּית. וְעֵילָּא מִנְּהוֹן מַאן דְּיָדַע לְתַקֵּן תִּקּוּנִין לְמָארֵיהּ, כְּדְקָא יֵאוֹת. ואִית בִּידִיעָה סַלְּקָא מִתַּתָּא לְעֵילָּא, וְאִית מַאן דְּיָדַע לְהַמְשִׁיךְ שִׁפְעָא מֵעֵילָּא לְתַתָּא.</p>\n<p>וּבְכָל ט' גְּוָונִי אִלֵּין, צְּרִיכָא כַּוָנָה גְּדוֹלָה, וְאִי לָא עָלֵיהּ קְרָא דִּכְתִּיב, (שמואל א ב׳:ל׳) וּבוֹזַי יִקָלּוּ. וּבְכַוָונַת אָמֵן, דְּהוּא כָּלִיל תְּרֵין שְׁמָהָן יְהוָֹ\"ה אֲדֹנָ\"י. וְהָאֶחָד גָּנִיז טוּבֵיהּ וּבִרְכוֹהִי, בְּאוֹצָּר הַנִּקְרָא הֵיכָל, וְהוּא רָמוּז בַּפָּסוּק (חבקוק ב׳:כ׳) וה' בְּהֵיכַל קָדְשׁוֹ הַס מִפָּנָיו וּלְדָּא רָמְזּוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה, כָּל טוּב הָאָדָם בְּבֵיתוֹ, שֶׁנֶּאֱמַר (במדבר י״ב:ז׳) בְכָל בֵּיתִי נֶאֱמָן הוּא, וּמְתַּרְגְמִינָן בְכָל דְּעִמִּי.</p>\n<p>ואִי מְכַוּון בְכָל חַד וְחַד מט' גְּוָונִי כְּדְקָא יֵאוֹת, דָּא הוּא בַּר נָשׁ דְּאוֹקִיר לִשְׁמָא דְּמָארֵיהּ לִשְׁמָא קַדִּישָׁא, וְעַל דָּא כְּתִיב כִּי מְכַבְּדַי אֲכַבֵּד וּבוֹזַי יֵקָלּוּ, אֲכַבֵּד בְּעָלְמָא דֵּין, לְקַיִּים וּלְמֶעְבַּד כָּל צָּרְכוֹי. וְיְחֶזּוּן כָּל עַמָּמֵי אַרְעָא, אֲרֵי שְׁמָא דְּה' אִתְקְרֵי עָלֵיהּ, וִידַחֲלוּן מִנִּיהּ. וּבְעָלְמָא דְּאָתֵי, יִזְכֵּי לְמֵיקָם בִּמְחִיצַּת חֲסִידִים, אַף עַל פִּי דְּלָא קָרֵי כָּל צּוֹרְכֵיהּ, כֵּיוָן דְּזָכָה לְאַשְׁגְּחָא יְדִיעַת מָארֵיהּ, וְאִיכְוָון בֵּיהּ כַּדְקָא יֵאוֹת.</p>\n<p>מַאי וּבוֹזַי יֵקָלּוּ. דָּא הוּא מַאן דְּלָא יָדַע לְאַחֲדָא שְׁמָא קַדִּישָׁא, וּלְקַשְּׁרָא קִשְׁרָא דִּמְהֵימְנוּתָא, וּלְאַמְשָׁכָא <Nonei></i>לְאֲתָר דְּאִצְּטְרִיךְ, וּלְאוֹקִיר שְׁמָא דְּמָארֵיהּ טָב לֵיהּ דְּלָא אִתְבְּרֵי. וְכָּל שֶׁכֵּן מַאן דְּלָא אִתְכַּוָּון בְּאָמֵן. וְעַל דָּא, כָּל מַאן דְּמַרְחִישׁ בְּשִׂפְוָותֵיהּ בִּנְקִיוּתָא דְּלִבָּא, בְּמַיָּא דִּמְנַקֵּי, מַאי כְּתִיב בַּהֲדֵיהּ, וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם, כְּלוֹמַר, בִּשְׁבִיל אָדָם דְּיָדַע לְאַחֲדָא צֶּלֶם וּדְמוּת כְּדְקָא יֵאוֹת, וירְדוּ בִדְגַּת הַיָּם. (עד כאן דבר אחר)</p>\n<p><Nonei></i>וַיֹּאמֶר אֱלהִים נַעֲשֶׂה אָדָם. הָאָדָם לָא כְּתִיב, אֶלָּא אָדָם סְתָם, לְאַפָּקָא אָדָם דִּלְעֵילָּא. דְּאִתְעָבִיד בִּשְׁמָא שְׁלִים. כַּד אִשְׁתְּלִים דָּא, אִשְׁתְּלִים דָּא. אִשְׁתְּלִים דְּכַר וְנוּקְבָּא לְאַשְׁלְמָא כֹּלָּא. יְדוָֹ\"ד סִטְרָא דִּדְּכַר. אֱלהִים סִטְרָא דְּנוּקְבָּא. אִתְפָּשַׁט דְּכוּרָא, וְאִתְתְּקַּן בְּתִקּוּנוֹי כְּאִמָּא, בְּפוּמֵיהּ דְּאָמָה. מַלְכִין דְּאִתְבְּטָלוּ, הָכָא אִתְקָיָּימוּ.</p>\n<p>דִּינִין (קמ\"ב ע\"ב) דִּדְכוּרָא תַּקִּיפִין בְּרִישָׁא, בְּסוֹפָא נַיְיחִין. דְּנוּקְבָּא בְּאִיפְּכָא. וְי\"ה קוּנְטִירִין דְּקִיטוּרָא בְּעִטְפוֹי שְׁקִיעִין. י' זְעֵירָא בְּגַוָוהָא אִשְׁתְּכַח.</p>\n<p>אִי אִתְבְּסָמוּ דִּינִין, בָּעָא עַתִּיקָא. אָתָא חִוְיָא עַל נוּקְבָּא, וְקִינָא דְּזוּהֲמָא אִתְתָּקַן בְּגַוָוהּ, לְמֶעְבַּד מָדוֹרָא בִּישָׁא. דִּכְתִּיב וַתַּהַר ותֵּלֶד אֶת קַיִן. קִינָּא דְּמָדּוֹרָא דְּרוּחִין בִּישִׁין וְעִלְעוּלִין וְקַטְפוּרִין.</p>\n<p>אַתְקִין בֵּיהּ בְּהַאי אָדָם, כְּתָּרִים, בִּכְלַל וּפְרַט, אִתְכְּלָלוּ בִּפְרַט וּכְלָל, שׁוֹקִין וּדְרוֹעִין, יְמִינָא וּשְׂמָאלָא.</p>\n<p>דָּא אִתְפְּלַג בְּסִטְרוֹי אִתְתַּקַּן דְּכַר וְנוּקְבָּא יה\"ו. י' דְּכַר. ה' נוּקְבָּא. ו' כְּתִיב זָכָר וּנְקֵבָה בְּרָאָם ויְבָרֶךְ אוֹתָם ויִּקְרָא שְׁמָם אָדָם. דִּיּוּקְנָא וּפַרְצוּפָא דְּאָדָם יָתִיב עַל כֻּרְסְיָּא, וּכְתִיב (יחזקאל א׳:כ״ו) ועַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה.</p>"],[9520011801,"<p><Noneb>פִּרְקָא רְבִיעָאָה.</b> עַתִּיקָא, טָמִיר וסָתִים. זְעֵירָא דְּאַנְפִּין, אִתְגַּלְיָיא ולָא אִתְגַּלְיָיא. דְּאִתְגַּלְיָיא, בְּאַתְוָון כְּתִיב. דְּאְתְכַּסְיָיא, סָתִים בְּאַתְוָון, דְּלָא מִתְיַישְּׁבָן בְּאַתְרוֹי, בְּגִין דְּאִיהוּ לָא אִתְיְישָׁבוּ בֵּיהּ עִלָּאִין וְתַתָּאִין.</p>\n<p>וַיֹּאמֶר אֱלהִים תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ בְּהֵמָה וָרֶמֶשׂ וְגוֹ', הַיְינוּ דִּכְתִּיב, (תהילים ל״ו:ז׳) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ'. חַד בִּכְלָלָא דְּאַחֲרָא מִשְׁתַּכְּחָא. בְּהֵמָה בִּכְלָלָא דְּאָדָם, (ויקרא א׳:ב׳) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַיְיָ' מִן הַבְּהֵמָה, מִשּׁוּם דְּאִתְכְּלַל בִּכְלָלָא דְּאָדָם.</p>\n<p>כַּד נָחַת אָדָם דִּלְתַתָּא <Nonei></i>בְּדִיּוּקְנָא עִלָּאָה, אִשְׁתְּכָחוּ תְּרֵין (תזריע מ\"ח ע\"ב) רוּחִין מִתְּרִין סִטְרִין, דִּימִינָא וּשְׂמָאלָא כָּלִיל אָדָם. דִּימִינָא, נִשְׁמְתָא קַדִּישָׁא. דִּשְׂמָאלָא נֶפֶשׁ חַיָּה. חָב אָדָם אִתְפָּשָׁט שְׂמָאלָא, וְאִתְפָּשָׁטוּ אִינּוּן בְּלָא גּוּפָא.</p>\n<p>כַּד מִתְדַּבְּקִין דָּא בְּדָא, אִתְיַּילְדָן כְּהַאי חַיָּה דְּאוֹלִידַת (רוחין) סַגִּיאִין בְּקִטְרָא חֲדָא. כ\"ב אַתְוָון סְתִימִין, כ\"ב אַתְוָון אִתְגַּלְּיָין, י' סָתִים, י' גַּלְיָיא. סָתִים וְגַלְיָיא, בְּמַתְקְלָא דְּטַפְסִין, אַתְּקָלוּ.</p>\n<p>י' נָפְקִין מִנֵּיהּ דְּכַר וְנוּקְבָּא ו\"ד, בְּהַאי אֲתָר, ו' דְּכַר, ד' נוּקְבָּא. בְּגִין דָּא, ד\"וּ תְּרֵין. ד\"וּ דְּכַר וְנוּקְבָּא. ד\"וּ תְּרֵין קַפְלִין. תְּרֵין י' בִּלְחוֹדוֹי דְּכַר. ה' נוּקְבָּא. ה' ד' הֲוַת בְּקַדְמִיתָא, (ק\"פ ע\"ב) וּמִדְּאִתְעַבְּרַת בְּו' בְּגַוָּהּ, (אולידת) אַפִּיקַת ו', (הרי כי בה' אית ד\"ו וביה אית ה\"ה הרי יה\"ו) אִתְחָזֵי יוֹ\"ד בְּחֶזְוֵיהּ כְּלָלָא דיה\"ו. מִדְּאַפִּיקַת יוֹ\"ד דְּהוּא דְּכַר וְנוּקְבָּא, אִתְיַישְּׁבַת לְבָתַר, וּמְכַסְיָיא לְאִמָא.</p>\n<p>(בראשית ו׳:ב׳) וַיִּרְאוּ בְּנִי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם, הַיְינוּ דִּכְתִּיב, (יהושע ב׳:א׳) שְׁנַיִם אֲנָשִׁים מְרַגְּלִים חֶרֶשׁ לֵאמֹר, מַאי בְּנוֹת הָאָדָם. דִּכְתִּיב, (מלכים א ג׳:ט״ז) אָז תָּבֹאנָה שְׁתַּיִם נָשִׁים זוֹנוֹת אֶל הַמֶּלֶךְ. בְּגִינֵיהוֹן כְּתִיב, כִּי רְאוּ כִּי חָכְמַת אֱלהִים בְּקִרְבּוֹ וְגוֹ'. אָז תָּבֹאנָה וְלָא בְּקַדְמִיתָא. בְּקִיסְטְרָא דְּקִיטוּרֵי דְּפִיגָאן, תְּרֵין מִתְחַבְּקָן הֲווֹ לְעֵילָּא, לְתַתָּא נָחְתוּ יַרְתּוּ עַפְרָא, אִבֵּדוּ חוּלָקָא טָבָא דְּהֲוָה בְּהוּ. עָטָרָא דְבוּמְלָא (ס\"א דחמלא') וְאִתְעַטָּר בְּקוּסְטָא דְּעִנְבָא.</p>\n<p>(שמות י״ד:ט״ו) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. אֵלָי דַּיְיקָא. דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִּסָּעוּ. וְיִּסָּעוּ דַּיְיקָא.</p>\n<p>בְּמַזָּלָא הֲוָה תָּלֵי, דְּבָעָא לְאוֹקִיר דִּקְנֵיהּ. (שמות ט״ו:כ״ו) וְהַיָּשָׁר בְּעֵינָיו תַּעֲשֶׂה וְהַאֲזַנְתָּ לְמִצְוֹתָיו וְשָׁמַרְתָּ כָּל חֻקָּיו עַד כָּאן. כִּי אֲנִי יְיָ' רֹפְאֶיךָ, לְהַאי דַּוקָא.</p>"],[9520011802,"<p><Noneb>פִּרְקָא חֲמִישָׁאָה.</b> (ישעיהו א׳:ד׳) הוֹי גּוֹי חוֹטֵא עַם כֶּבֶד עָוֹן זֶרַע מְרֵעִים בָּנִים וְגוֹ'. שִׁבְעָה דַּרְגִּין יוֹ\"ד ה\"ה ו\"ה ה\"י ו\"ו אַפִּיק ד' ה\"ה הו\"י, ה\"ה אַפִּיק ו\"ו ד\"ו לְבַר אַסְתִּיר אָדָם דְּכַר וְנוּקְבָּא דְּאִינּוּן ד\"ו דִּכְתִּיב בָּנִים מַשְׁחִיתִים.</p>\n<p>בְּרֵאשִׁית בָּרָא. בְּרֵאשִׁית מַאֲמָר. בָּרָא חֲצִי מַאֲמָר. אָב וּבֵן. סָתִים וְגַלְיָא. עֵדֶן עִלָּאָה דְּסָתִים וְגָנִיז. עֵדֶן תַּתָּאָה, נָפִיק לִמְטָלְטְלֵי (ס\"א למטלנוי) וְאִתְגַּלְיָא יְהוָֹה. יָהּ. אֱלֹהִים. אֵת. אֲדֹנָי אֶהְיֶה. יְמִינָא וּשְׂמָאלָא כַּחֲדָא אִשְׁתָּתָפוּ, הַשָּׁמַיִם. ואֵת, דִּכְתִּיב, (דבה הימים א כט) וְהַתִּפְאֶרֶת וְהַנֵּצַח אִינּוּן כַּחֲדָא אִשְׁתָּתָפוּ. הָאָרֶץ, דִּכְתִּיב, (תהילים ח׳:ב׳) מָה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ. (ישעיהו ו׳:ג׳) מְלא כָל הָאָרֶץ כְּבוֹדוֹ.</p>\n<p>יְהִי רָקִיעַ בְּתוֹךְ הַמַּיִם לְהַבְדִּיל בֵּין הַקֹּדֶשׁ וּבֵין קֹדֶשׁ הַקֳּדָשִׁים, עַתִּיקָא לִזְעֵירָא, אִתְפְּרַשׁ, וְאִתְדְּבַק. לָא אִתְפְּרַשׁ מַמָּשׁ פּוּמָא מְמַלֵּל רַבְרְבָן.</p>\n<p>אַנְתִּיק וְאִתְעַטָּר בְּכִתְרִין זְעִירִין, בַּחֲמִשָּׁה זִינִין מַיִם, וּכְתִיב (במדבר י״ט:י״ז) וְנָתַן עָלָיו מַיִם חַיִּים. (ירמיהו י׳:י׳) הוּא אֱלֹהִים חַיִּים וּמֶלֶךְ עוֹלָם. (תהילים קט״ז:ט׳) אֶתְהַלֵּךְ לִפְנֵי יְיָ' בְּאַרְצוֹת הַחַיִּים. (שמואל א כ״ה:כ״ט) וְהָיְתָה נֶפֶשׁ אֲדֹנִי צְרוּרָה וְגוֹ'. וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן. י\"ה, יו\"ד ה\"א, אהי\"י בֵּין מַיִם לָמָּיִם. מַיִם שְׁלֵימִין, וּמַיִם דְּלָא שְׁלִימִין. רַחֲמִין שְׁלִימִין, רַחֲמִין דְּלָא שְׁלֵימִין.</p>\n<p>(בראשית ו׳:ג׳) וַיֹּאמֶר יְיָ' לָא יָדוֹן רוּחִי בָאָדָם לְעוֹלָם בְּשַׁגַּם הוּא בָשָׂר. וַיֹּאמֶר יְיָ', כַּד אִתְיַישְׁבָא בִּזְעֵירָא. מִכָּאן (נ\"א דכד אמר בשם אמרו) (לומר) דָּבָר. דְּעַתִּיקָא סָתִים קָאָמַר לָא יָדוֹן רוּחִי בָאָדָם דִּלְעֵילָּא, מִשּׁוּם דִּבְהַהוּא רוּחָא דְּאִתְנָשְׁבָא מִתְּרֵין נוּקְבִין דְּפַרְדַּשְׂקָא, מָשִׁיךְ לְתַתָּאֵי.</p>\n<p>וּבְגִין כָּךְ כְּתִיב (ימי עולם) וְהָיוּ יָמָיו מֵאָה וְעֶשְׂרִים שָׁנָה. יוֹ\"ד שְׁלִים וְלָא שְׁלִים. י' בִּלְחוֹדוֹי מֵאָה. תְּרֵין אַתְוָון תְּרֵין זִמְנִין, מֵאָה וְעֶשְׂרִים שָׁנָה. י' בִּלְחוֹדוֹי כַּד <Nonei></i>אִתְגַּלְיָא בִּזְעֵירָא, אִתְמְשָׁךְ בְּעֶשֶׂר אַלְפִין שְׁנִין. מִכָּאן כְּתִיב, (תהילים קל״ט:ה׳) וַתָּשֶׁת עָלַי כַּפֶּכָה.</p>\n<p>(בראשית ו׳:ד׳) הַנְּפִילִים הָיוּ בָאָרֶץ, הַיְינוּ דִּכְתִּיב וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים. מֵאֲתָר דְּאִתְפְּרַשׁ גִּנְתָּא, אִקְרֵי הַנְּפִילִים, דִּכְתִּיב וּמִשָּׁם יִפָּרֵד. הָיוּ בָאָרֶץ בַּיָּמִים הָהֵם, וְלָא לְבָתַר זִמְנָא. עַד דְּאָתָא יְהוֹשֻׁעַ, וּבְנֵי הָאֱלֹהִים אִסְטָמָרוּ.</p>\n<p>עַד דְּאָתָא שְׁלמֹה וּבְנוֹת הָאָדָם אִתְכְּלָלָא, הֲדָא הוּא דִכְתִיב, (קהלת ב) וְתַעֲנוּגוֹת. תַּעֲנֻגֹת קָארֵי (תענוגים לא קארי) בְּנֵי הָאָדָם (נ\"א דאתרמיזו) דְּאִתְרְמִיוּ מֵהַאי רוּחִין אַחֲרָנִין, דְּלָא אִתְכְּלָלוּ בְּחָכְמָה עִלָּאָה. דִּכְתִּיב, (מלכים א ה׳:כ״ו) וַיְיָ' נָתַן חָכְמָה לִשְׁלֹמֹה. וּכְתִיב (מלכים א ה׳:י״א) וַיֶּחְכַּם מִכָּל הָאָדָם. מִשּׁוּם דְּהָנֵי לָא אִתְכָּלָלוּ בְּאָדָם.</p>\n<p>וַיְיָ' נָתַן חָכְמָה, ה' עִלָּאָה. וַיֶּחְכַּם, דְּמִינָהּ אִתְחַכָּם לְתַתָּא. הֵמָּה הַגִּבּוֹרִים אֲשֶׁר מֵעוֹלָם, עוֹלָם דִּלְעֵילָּא. אַנְשֵׁי הַשֵּׁם, דְּאִתְנָהֲגָן בִּשְׁמָא. מַאי שְׁמָא. שְׁמָא קַדִּישָׁא, דְּאִתְנָהֲגָן בֵּיהּ דְּלָא קַדִּישִׁין לְתַתָּא, וְלָא אִתְנָהֲגָן אֶלָּא בִּשְׁמָא. אַנְשֵׁי הַשֵּׁם סְתָם, וְלָא אַנְשֵׁי הוי\"ה. לָאו מִסְתִּים סְתִימָא, אֶלָּא גְּרִיעוּתָא, וְלָא גְּרִיעוּתָא אַנְשֵׁי הַשֵּׁם סְתָם, מִכְּלָלָא דְּאָדָם נַפְקוּ, כְּתִיב (תהילים מ״ט:י״ג) אָדָם בִּיקָר בַּל יָלִין, אָדָם בִּיקָר, בְּיָקִרוּ דְּמַלְכָּא, בַּל יָלִין, בְּלָא רוּחָא.</p>\n<p>תְּלֵיסַר מַלְכֵּי קְרָבָא, בְּשִׁבְעָה. שִׁבְעָה. מַלְכִּין בְּאַרְעָא, אִתְחֲזִיאוּ נָצְחֵי קְרָבָא. תִּשְׁעָה דְּסַלְּקִין בְּדַרְגִּין, דְּרַהֲטִין בִּרְעוּתְהוֹן, וְלֵית דְּיִמְחֵי בִּידֵיהוֹן. חֲמִשָּׁה מַלְכִּין קַיְימִין בִּבְהִילוּ, לְקַמֵּי אַרְבַּע לָא יַכְלִין לְמֵיקָם.</p>\n<p>אַרְבַּע מַלְכִּין נָפְקִין לְקַדְמוּת אַרְבַּע, בְּהוֹן תַּלְיָין כַּעֲנָבִין בְּאִתְכְּלָא צְרִירָן בְּהוּ שִׁבְעָה רְהִיטִין. סָהֲדִין סָהֲדוּתָא וְלָא קַיְימִין בְּדוּכְתַּיְיהוּ. אִילָנָא דְּמִבְסָם יָתִיב בְּגוֹ. בַּעֲנָפוֹי אֲחִידָן וּמְקַנְנָן צִפֹּרִין. תְּחוֹתוֹי תַּטְלֵל חֵיוָתָא דִּשְׁלִיטָא בְּהַהוּא אִילָנָא בִּתְרֵי כְּבִישִׁין, לְמֵהַךְ בְּשִׁבְעָה סַמְכִין סָחֲרָנֵיהּ, בְּאַרְבַּע חֵיוָון, מִתְגַּלְגְּלִין בְּאַרְבַּע סִטְרִין.</p>\n<p>חִוְיָא דְּרָהִיט בש\"ע דִּלּוּגִין, דָּלִיג עַל טוּרִין, מְקַפֵּץ עַל גִּבְעָתָא, דִּכְתִּיב, (שיר השירים ב׳:ח׳) מְדַלֵּג עַל הֶהָרִים מְקַפֵּץ עַל הַגְּבָעוֹת. זְנָבֵיהּ בְּפוּמֵיהּ, בְּשִׁנוֹי, נָקִיב בִּתְרֵין גִּיסִין. כַּד נָטִיל גִּיסְטְרָא אִתְעָבִיד לִתְלַת רוּחִין.</p>\n<p>כְּתִיב וַיִּתְהַלֵּךְ חֲנוֹךְ אֶת הָאֱלֹהִים. וּכְתִיב (משלי כ״ב:ו׳) חֲנוֹךְ לַנַּעַר עַל פִּי דַּרְכּוֹ. לַנַּעַר הַיָּדוּעַ. אֶת הָאֱלֹהִים, וְלָא אֶת יְיָ'. וְאֵינֶנּוּ, בְּשֵׁם זֶה, כִּי לָקַח אוֹתוֹ אֱלֹהִים לְהִקָרֵא בִּשְׁמוֹ.</p>\n<p>תְּלַת בָּתֵּי דִּינִין, אַרְבַּע אִינּוּן. אַרְבַּע בָּתֵּי דִּינִין דִּלְעֵילָּא. אַרְבַּע לְתַתָּא. דִּכְתִּיב, (ויקרא י״ט:ל״ה) לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט בַּמִּדָּה בַּמִּשְׁקָל וּבַמְּשׂוּרָה. דִּינָא קַשְׁיָא. דִּינָא דְּלָא קַשְׁיָא, דִּינָא בְּשִׁקּוּלָא, דִּינָא דְּלָא בְּשִׁקּוּלָא. דִּינָא רַפְיָא. (דינא) דְּאֲפִילּוּ לָא הַאי וְלָא הַאי.</p>\n<p>וַיְהִי כִּי הֵחֵל הָאָדָם לָרֹב עַל פְּנֵי הָאֲדָמָה. הֵחֵל הָאָדָם לָרֹב. הַיְינוּ דִּכְתִּיב בְּשַׁגַּם וְגוֹ', הָאָדָם דִּלְעֵילָּא. וּכְתִיב עַל פְּנֵי הָאֲדָמָה. (שמות לה) וּמֹשֶׁה לָא יָדַע כִּי קָרַן עוֹר פָּנָיו, הַיְינוּ דִּכְתִּיב, (בראשית ג׳:כ״א) כָּתְנוֹת עוֹר.</p>\n<p>קָרַן, דִּכְתִּיב, (שמואל א ט״ז:י״ג) וַיִּקַּח שְׁמוּאֵל אֶת קֶרֶן הַשֶּׁמֶן. לֵית מְשִׁיחָא אֶלָּא בְּקֶרֶן, (תהילים פ״ט:כ״ה) וּבְשִׁמְךָ תָּרוּם קַרְנִנוּ. (תהילים קל״ב:י״ז) שָׁם אַצְמִיחַ קֶרֶן לְדָוִד. הַיְינוּ עֲשִׂירָאָה דְּמַלְכָּא. וְאַתְיָא מִן יוֹבְלָא דְּהִיא אִימָא, דִּכְתִּיב, (יהושע ו׳:ה׳) וְהָיָה בִּמְשׁוֹךְ בְּקֶרֶן הַיּוֹבֵל. קֶרֶן בְּיוֹבְלָא אִתְעַטָּר עֲשִׂירָאָה בְּאִימָּא. קֶרֶן, דְּנָטִיל קֶרֶן וְרוּחַ לְאָתָבָא רוּחֵיהּ לֵיהּ.</p>\n<p>וְהַאי קֶרֶן דְּיוֹבְלָא הוּא. וְיוֹבֵל ה'. וה' נְשִׁיבָא דְּרוּחָא לְכֹלָּא. וְכֹלָּא תַּיְיבִין לְאַתְרַיְיהוּ, דִּכְתִּיב, (ירמיה א) אֲהָהּ יְיָ' אֱלֹהִים, כַּד אִתְחָזֵי ה' לה', יְיָ' אֱלהִים אִתְקְרֵי שֵׁם מָלֵּא וּכְתִיב (ישעיהו ב׳:י״א) וְנִשְׂגַּב יְיָ' לְבַדּוֹ בַּיּוֹם הַהוּא. (ס\"א כד אתחזר ה' לה' ואסתלק י' פורענותא אתי לעלמא ואי לאו בשביל אדם יהו\"ה לא אתקיים עלמא וכלא אתחרב ועל דא כתיב ונשגב וגו') עַל כֵּן סָתִים וְאִתְעַטַּר צְנִיעוּתָא דְּמַלְכָּא, דְּהַיְינוּ סִפְרָא דִּצְנִיעוּתָא. זַכָּאָה (נ\"א למאן דנפק וידע) לְמַאן דְּעָאל וְנָפַק וְיָדַע שְׁבִילוֹי וְאָרְחוֹי.</p>"],[9520011803,"<p><Nonei></i>(שמות כ״ז:כ׳) וְאַתָּה תְּצַוֵּה אֶת בְּנֵי יִשְׂרָאֵל וְגו'. וְאַתָּה הַקְרֵב אֵלֶיךָ אֶת אַהֲרֹן אָחִיךָ וְגו'. אָמַר רִבִּי חִיָּיא, מַאי שְׁנָא הָכָא מִבְכָל אֲתָר, דִּכְתִּיב וְאַתָּה הַקְרֵב אֵלֶיךָ וְאַתָּה תְּדַבֵּר אֶל כָּל חַכְמֵי לֵב. וְאַתָּה תְּצַוֵּה אֶת בְּנִי יִשְׂרָאֵל. (שמות ל׳:כ״ג) וְאַתָּה קַח לְךָ בְּשָׂמִים רֹאשׁ מָר דְּרוֹר. אֶלָּא כֹּלָּא בְּרָזָא עִלָּאָה אִיהוּ, לְאַכְלְלָא שְׁכִינְתָּא בַהֲדֵיהּ.</p>\n<p>אָמַר רִבִּי יִצְחָק, נְהוֹרָא עִלָּאָה, וּנְהוֹרָא תַּתָּאָה כָּלִיל כַּחֲדָא, אִקְרֵי (קל\"ח ע\"ב) וְאַתָּה. כְּמָה דְּאַתְּ אָמַר (נחמיה ט׳:ו׳) וְאַתָּה מְחַיֶּה אֶת כֻּלָּם. וְעַל דָּא לָא כְּתִיב, וְהִקְרַבְתָּ אֶת אַהֲרֹן אָחִיךְ. וְצִוִיתָ אֶת בְּנֵי יִשְׂרָאֵל. וְדִבַּרְתָּ אֶל כָּל חַכְמֵי לֵב. בְּגִין דְּהַהוּא זִמְנָא שַׁרְיָא שִׁמְשָׁא בְּסִיהֲרָא, וְאִשְׁתָּתַּף כֹּלָּא כַּחֲדָא, לְשַׁרְיָא עַל אוּמָנוּתָא דְּעוֹבָדָא. אָמַר רִבִּי אֶלְעָזָר, מֵהָכָא, (שמות ל״ו:א׳) אֲשֶׁר נָתַן יְיָ' חָכְמָה וּתְבוּנָה בָּהֵמָּה.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר מֵהָכָא, וְאַתָּה תְּדַבֵּר אֶל כָּל חַכְמֵי לֵב אֲשֶׁר מִלֵּאתִיו רוּחַ חָכְמָה. אֲשֶׁר מִלֵּאתִים מִבָּעֵי לֵיהּ. אֶלָּא אֲשֶׁר מִלֵּאתִיו, לְהַהוּא לִבָּא, מִלֵּאתִיו רוּחַ חָכְמָה. כְּמָה דְאַתְּ אָמֵר (ישעיהו י״א:ב׳) וְנָחָה עָלָיו רוּחַ יְיָ' רוּחַ חָכְמָה וְגוֹ' וְעַל דָּא אִצְטְרִיךְ אֲשֶׁר מִלֵּאתִיו רוּחַ חָכְמָה, דְּשַׁרְיָא שִׁמְשָׁא בְּסִיהֲרָא בְּאַשְׁלְמוּתָא דְּכֹלָּא, וְעַל דָּא אִתְרְשִׁים כֹּלָּא בְכָל אֲתָר. אָמַר רִבִּי אֶלְעָזָר, אִי הָכִי הָנֵי וְאַתָּה וְאַתָּה, הֵיאַךְ מִתְיַישְּׁבָן בִּקְרָאֵי.</p>\n<p>אָמַר לֵיהּ, כֻּלְּהוּ מִתְיַישְּׁבָן נִינְהוּ. וְאַתָּה הַקְּרֵב אֵלֶיךָ: לְיַחֲדָא בַּהֲדֵיהּ, וּלְקָרְבָא בַּהֲדֵיהּ, רָזָא דִּשְׁמָא קַדִישָׁא כְּדְקָא יֵאוֹת. וְאַתָּה תְּדַבֵּר אֶל כָּל חַכְמֵי לֵב: בְּגִין דְּכֻלְּהוּ לָא אַתְיָין לְמֶעְבַּד עֲבִידְתָּא, עַד דְּרוּחַ קֻדְשָׁא מְמַלְּלָא בְּגַוַּויְיהוּ, וְלָחַשׁ לוֹן בִּלְחִישׁוּ, וּכְדֵין עַבְדֵי עֲבִידְתָּא. וְאַתָּה תְּצַוֵּה אֶת בְּנִי יִשְׂרָאֵל: רוּחַ קֻדְשָׁא פַּקְדָא עָלַיְיהוּ, וְאַנְהִיר עָלַיְיהוּ, לְמֶעְבַּד עוֹבָדָא בִּרְעוּתָא שְׁלִים. וְאַתָּה קַח לְךָ: כְּמָה דְּאוֹקִימְנָא. (דכתיב) וְאַתָּה הַקְרֵב אֵלֶיךָ, וְהָנִי כֻּלְּהוּ, הָכָא בְּעוֹבָדָא דְּמַשְׁכְּנָא. דְּכֹלָּא אִתְעָבִיד בְּרָזָא דָּא.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר (תהילים כ״ב:כ׳) וְאַתָּה יְיָ' אַל תִּרְחָק אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה. וְאַתָּה יְיָ' כֹּלָּא חַד. אַל תִּרְחָק: לְאִסְתַּלְּקָא מִינָן, לְמֶהֱוֵי סָלִיק נְהוֹרָא עִלָּאָה מִתַּתָּאָה. דְּהָא כַּד אִסְתָּלַּק נְהוֹרָא עִלָּאָה מִתַּתָּאָה, כְּדֵין אִתְחֲשָׁךְ כָּל נְהוֹרָא, וְלָא אִשְׁתְּכַח כְּלַל בְּעָלְמָא.</p>\n<p>וְעַל דָּא אִתְחָרַב בֵּי מַקְדְּשָׁא בְּיוֹמוֹי דְּיִרְמְיָהוּ. וְאַף עַל גַּב דְּאִתְבְּנֵי לְבָתַר, לָא אַהְדָר נְהוֹרָא לְאַתְרֵיהּ כַּדְקָא יֵאוֹת. וְעַל רָזָא דָּא, שְׁמָא דְּהַהוּא נְבִיאָה דְּאִתְנַבֵּי עַל דָּא, יִרְמְיָהוּ. אִסְתַּלְקוּתָא דִּנְהוֹרָא עִלָּאָה, דְּאִסְתָּלַּק לְעֵילָא לְעֵילָּא, וְלָא אַהְדָר לְאַנְהָרָא לְבָתַר כְּדְקָא יֵאוֹת. יִרְמְיָהוּ: אִסְתָּלַּק וְלָא אַהְדָר לְאַתְרֵיהּ, וְאִתְחָרַב בֵּי מַקְדְשָׁא וְאִתְחֲשָׁכוּ נְהוֹרִין.</p>\n<p>אֲבָל יְשַׁעְיָהוּ, שְׁמָא גָּרִים לְפוּרְקָנָא, וּלְאַהְדָּרָא נְהוֹרָא עִלָּאָה לְאַתְרִיהּ, (ישעיהו לאנהרא ההוא נהורא עלאה ולמעבד פורקנא) וּלְמִבְנֵי בֵּי מַקְדְשָׁא, וְכָל טָבִין וְכָל נְהוֹרִין, יָהַדְרוּן כְּדִבְּקַדְמֵיתָא. וְעַל דָּא, שְׁמָהָן דִּתְרֵין נְבִיאִין אִלֵּין, קַיְימִין דָּא לָקֳבֵל דָּא, בְּגִין דִּשְׁמָא גָּרִים, וְצֵרוּפָא דְּאַתְוָון דָּא בְּדָא, גַּרְמִין עוֹבָדָא, הֵן לְטָב וְהֵן לְבִישׁ. וְעַל רָזָא דָּא, צֵרוּפָא דְּאַתְוָון דִּשְׁמָהָן קַדִּישִׁין, וְכֵן אָתְוָון בְּגַרְמַיְיהוּ, גַּרְמִין לְאִתְחֲזָאָה רָזִין עִלָּאִין, כְּגַוְונָא דִּשְׁמָא קַדִּישָׁא, דְּאַתְוָון בְּגַרְמַיְיהוּ, גַּרְמִין רָזִין עִלָּאִין קַדִּישִׁין לְאִתְחֲזָאָה בְּהוּ.</p>"],[9520011804,"<p>רָזָא קַדְמָאָה, יוֹ\"ד, נְקוּדָה קַדְמָאָה <Nonei></i>דְּקַיְּימָא עַל תֵּשַׁע סַמְכִין דְּסַמְכִין לָהּ. וְאִינּוּן קַיְימִין לְאַרְבַּע סִטְרֵי עָלְמָא. כְּמָה דְּסוֹפָא דְּמַחֲשָׁבָה, נְקוּדָה בַּתְרָאָה, קַיְּימָא לְאַרְבַּע סִטְרֵי עָלְמָא. בַּר דְּהַאי דְּכָר, וְאִיהִי נוּקְבָּא.</p>\n<p>וְהַאי קַיְּימָא בְּלָא גּוּפָא, וְכַד קַיְּימָא בִּלְבוּשָׁא, דְּאִתְלָבַּשׁ בְּהוּ, אִיהִי קַיְּימָא עַל תֵּשַׁע סַמְכִין, בְּרָזָא דְּאָת ם בְּלָא עִגּוּלָא. וְאַף עַל גַּב דְּאָת ס' אִיהִי בְּעִגּוּלָא, וְקַיְּימָא בְּעִגּוּלָא. אֲבָל בְּרָזָא דְּאַתְוָון חֲקִיקִן, גּוֹ נְקוּדֵי, טְהִירִין לְעֵילָּא, אִינּוּן בְּרִבּוּעָא, דִּלְתַתָּא אִיהוּ בְּעִגּוּלָא.</p>\n<p>הַאי בְּרִבּוּעַ אִיהִי קַיְּימָא בְּשִׁיעוּרָא דְּתֵשַׁע נְקוּדִין, תְּלַת תְּלַת לְכָל סְטָר. וְאִינּוּן בְּשִׁיעוּרָא דְּחוּשְׁבָּנָא תְּמַּנְיָא נְקוּדִין, וְאִינּוּן תֵּשַׁע. וְאִלֵּין אִינּוּן דְּקַיְימִין מֵרָזָא דְּבוּצִינָא בְּרִיבּוּעָא בְּסַמְכִין תִּשְׁעָה לְאָת יוֹ\"ד, נְקוּדָה חֲדָא. אִינּוּן תִּשְׁעָה. אִינּוּן תְּמַנְיָא בְּרָזָא דְּאָת ם בְּרִבּוּעָא, כְּגַוְונָא דָּא:: תְלָת תְלָת לְכָל סְטָר</p>\n<p>וְדָא אִיהוּ רָזָא : דְּאָת יוֹ\"ד נְקוּדָה חֲדָא, וְאַף עַל גַּב דְּאִיהִי נְקוּדָה חֲדָא, דִּיּוּקְנָא דִּילָהּ, רֵישָׁא לְעֵילָּא, וְקוֹצָא לְתַתָּא, וְשִׁיעוּרָא דִּילָהּ תְּלַת נְקוּדִין כְּגַוְונָא דָּא וְעַל דָא אִתְפַּשְׁטוּתָא לְאַרְבַּע סִטְרִין, תְלָת, תְלָת לְכָל סְטָר אִיהִי תֵשַׁע וְאִיהִי תְמַנְיָא.</p>\n<p>וְאִלֵּין אִינּוּן סַמְכִין דְּנָפְקִין מֵרָזָא דְּבוּצִינָא, לְמֶהוֵי סַמְכִין לְאָת יוֹ\"ד, וְאִלֵּין אִקְרוּן רְתִיכָא דִּילָהּ. וְלָא קַיְּימִין בִּשְׁמָא, בַּר בְּרָזָא דְּתֵשַׁע נְקוּדִין דְּאוֹרַיְיתָא.</p>\n<p>וּבְרָזָא דְּסִפְרָא דְּאָדָם, אִתְפְּלָגוּ אִלֵּין תֵּשַׁע דְּאִינּוּן תְּמַנְיָא, בְּצֵרוּפָא דְּאַתְוָון דִּשְׁמָא קַדִּישָׁא, לְצָרְפָא לוֹן וּלְיַחֲדָא לוֹן בְכָל אִינּוּן גַּוְונִין, כַּד נַטְלִין אִלֵּין תְּמַנְיָא דְּאִינּוּן תֵּשַׁע, נַהֲרִין בִּנְהִירוּ דְּאָת ם בְּרִבּוּעָא, וְאַפִּיק נְהוֹרִין תְּמַנְיָא, (ס\"א תמניא אתחזון) אִתְחָזוּן וְאַתְוָון תִּשְׁעָה. וְאִתְפַּלְגָּן לְתַתָּא לְנַטְלָא כָּל מַשְׁכְּנָא.</p>\n<p>וְאִינּוּן צֵרוּפָא דִּשְׁמָא קַדִּישָׁא, בְּרָזָא דְּשִׁבְעִין וּתְרֵין אַתְוָון מְחַקְּקָן, דְּנַפְקֵי מֵרָזָא דִּתְלַת גַּוְונִין, יְמִינָא וּשְׂמָאלָא וְאֶמְצָעִיתָא. וְכֹלָּא מֵרָזָא דִּתְלַת נְקוּדִין, שִׁיעוּרָא דְּאָת יוֹ\"ד, דְּאִיהִי לְד' סִטְרִין, וְאִינּוּן תְּמַנְיָא נְקוּדִין, וְאִינּוּן תֵּשַׁע נְקוּדִין, וְאִינּוּן תְּרֵיסַר נְקוּדִין עִלָּאִין. ג' ג' לְכָל סְטָר וּסְטָר, וּמֵהָכָא נַחְתִּין לְתַתָּא בִּתְרֵיסַר לְשִׁית סִטְרִין. וְכַד אִתְחָקְּקָן תְּרֵיסַר אִלֵּין בְּשִׁית סִטְרִין, אִינּוּן שִׁבְעִין וּתְרֵין שְׁמָהָן, רָזָא דִּשְׁמָא קַדִּישָׁא דְּשִׁבְעִין וּתְרֵין דְּאִינּוּן שְׁמָא דָּא קַדִּישָׁא.</p>\n<p>וְכֹלָּא אִיהוּ סָלִיק בִּרְעוּתָא, דִּסְמִיכוּ דְּמַחֲשָׁבָה בְּאִינּוּן סַמְכִין דְּאָת יוֹ\"ד, וְעַל דָּא אַתְוָון בְּצִרוּפַיְּיהוּ, תְּלַת תְּלַת בְכָל צֵרוּפָא דִּילֵיהּ, בְּגִין לְסַלְּקָא בִּרְעוּתָא דְּאָת י', דִּתְלַת נְקוּדִין, כְּמָה דְּאִתְּמַר, וְעַל דָּא לָא אִסְתְּלִיק בִּסְלִיקוּ דְּצֵרוּפָא, אֶלָּא מֵעִקָרָא וְשָׁרְשָׁא דְּרָזָא דְּאִלֵּין סַמְכִין, דְּסַמְכִין לְאָת י' רָזָא דְּאָת ם' בְּרִבּוּעָא, ט' נְקוּדִין, תְּמַנְיָא נְקוּדִין, תְּרֵיסַר נְקוּדִין, שִׁבְעִין וּתְרֵין נְקוּדִין. אִשְׁתְּכַח, דְּכָל רָזָא דִּשְׁמָא קַדִּישָׁא, קַיְּימָא בְּאָת י', וְכֹלָּא רָזָא חֲדָא, וְקַיְּימָא בְּרָזָא דְּבוּצִינָא, כְּמָה דְּאִתְּמַר לְמֶעְבַּד סְמִיכוּ לְכָל אָת וְאָת. וְאִינּוּן סַמְכִין אִינּוּן רְתִיכָא דִּלְהוֹן, דְּכָל אָת וְאָת, כְּמָה דְּאִתְּמַר.</p>\n<p>רָזָא תִּנְיָינָא, אָת ה', דְּקַיְּימָא עַל חֲמִשָּׁה סַמְכִין, דְּסַמְכִין לָהּ, דְּנָפְקִין מֵרָזָא דְּבוּצִינָא, כַּד אִתְכְּנַשׁ לְאִסְתַּלְּקָא לְעֵילָּא, מֵרָזָא (ר\"ד ע\"א) דְּמִשְׁחָתָא.</p>\n<p>אָת דָּא הֵיכְלָא קַדִּישָׁא אִקְרֵי, לְגוֹ, נְקוּדָה דִּקְאַמְרָן. וְכֹלָּא אִיהוּ בְּרָזָא דִּקְאַמְרָן דְּאָת ם בְּרִבּוּעָא. אֲבָל הָכָא לָא אִתְרְשִׁים בַּר אָת ה', וּרְתִיכָא דִּילָהּ חֲמִשָּׁה סַמְכִין דִּקְאַמְרָן.</p>\n<p>דְּכַד בָּטַשׁ נְהִירוּ דְּבוּצִינָא בְּאָת י', אִתְנְהִיר, וּמֵהַהוּא בְּטִישׁוּתָא, אִתְעָבִידוּ אִינּוּן תֵּשַׁע (פנחס רפ\"ג ע\"ב, תצא ר\"ח ע\"א) סַמְכִין דִּקְאַמְרָן. וּמִגּוֹ נְהִירוּ דְּאִתְנְהָר אָת י', אִתְפְּשָּׁטוּ תְּלַת נְקוּדִין דְּי'. תְּרֵין לְעֵילָּא, דְּאִינּוּן רֵישָׁא. וְחַד לְתַתָּא, דְּאִיהוּ קוֹצָא דְּי', כְּגַוְונָא דָּא דְּקַאֲמְרָן. כַּד אִתְפְּשָּׁטוּ, תְּרֵין, אִתְעָבִידוּ תְּלַת. חַד אִתְעָבִיד תְּרֵין. וְאִתְפָּשָׁטוּ, וְאִתְעָבִיד חַד הֵיכָלָא. דָּא הֵיכָלָא, לְבָתַר דְּאִתְעָבִיד הֵיכָלָא לְחַד נְקוּדָה קַדְמָאָה, <Nonei></i>אִתְעָבִיד בִּגְנִיזוּ טָמִיר רָזָא דְּאָת דָּא, וְקַיְּימָא עַל חָמֵשׁ אַחֲרָנִין.</p>\n<p>אַרְבְּעָה גְּנִיזִין אִינּוּן, בְּחַד נְקוּדָה דְּקַיְּימָא לְגוֹ בְּאֶמְצָעִיתָא, אִינּוּן חָמֵשׁ. וְאִיהִי ה'. כְּמָה דְּהֵ\"א דִּלְתַתָּא, קַיְּימָא עַל אַרְבַּע, וְאִיהִי נְקוּדָה עַל אַרְבַּע, דְּקַיְּימָא בְּגוֹ אֶמְצָעִיתָא. אוּף הָכָא נָמֵי הַאי. וּמַה דְּקַיְּימָא עַל ה' סַמְכִין, הָכִי הוּא וַדַאי, בְּגִין דְּהַאי נְקוּדָה עִלָּאָה, אִיהִי עַל תְּרֵין גַּוְונִין, חַד בִּלְחוֹדוֹי, וְחַד בִּטְמִירוּ.</p>\n<p>וּבְסִפְרָא דְּרָזִין דְּחֲנוֹךְ, ה' וַדַאי קַיְּימָא עַל חָמֵשׁ סַמְכִין דְּנָפְקִין מִגּוֹ בּוּצִינָא. וּכְדֵין אַפִּיק חֲמֵשׁ קַיְימִין אַחֲרָנִין, וְאִשְׁתְּכַח הַאי ה' בְּרָזָא דַּעֲשָׂרָה. וְכַד אִתְפַּרְשַׁת, קַיְּימָא ה' דָּא, עַל סַמְכִין, וְאִינּוּן הֲווֹ תְּלֵיסַר מְכִילָן דְּרַחֲמֵי, בְּחַד דַּרְגָּא דְּאִתּוֹסָף עָלַיְיהוּ.</p>\n<p>וְאִלֵּין אִינּוּן (ק\"פ) תְּרֵיסַר דְּקַיְימִין בְּשִׁית. זִמְנִין אִינּוּן אַרְבְּעִין וּתְרֵין. זִמְנִין שִׁבְעִין וּתְרֵין הֲווֹ, אֲבָל (קל\"ב) נַחְתִּין לְתַתָּא. וְהָכָא אִתְפְּרָשׁוּ שְׁבִילִין לְכָל סְטַר, דְּאִינּוּן תְּלָתִין וּתְרֵין, אִשְׁתְּאַר אַרְבְּעִין. וּתְרֵין אוּדְנִין יְמִינָא וּשְׂמָאלָא, הָא אַרְבְּעִין וּתְרֵין, אִלֵּין מ\"ב אַתְוָון עִלָּאִין, דְּאִינּוּן אַתְוָון רַבְרְבָן דְּאוֹרַיְיתָא.</p>\n<p>בְּגִין (הקדמה ג' ע\"ב) דְּאִית אַתְוָון רַבְרְבָן, וְאִית אַתְוָון זְעִירִין. אַתְוָון רַבְרְבִין אִינּוּן לְעֵילָּא, אַתְוָון זְעִירִין לְתַתָּא. וְכֹלָּא לְתַתָּא כְּגַוְונָא דִּלְעֵילָּא. בְּגִין דְּאִית שְׁמָהָן קַדִּישִׁין עִלָּאִין, דְּקַיְימִין בִּרְעוּ דְּרוּחָא וְלִבָּא בְּלָא מִלּוּלָא כְּלַל.</p>\n<p>וְאִית שְׁמָהָן קַדִּישִׁין תַּתָּאִין, דְּקַיְימִין בְּמִלָּה, וּבִמְשִׁיכוּ דְּמַחֲשָׁבָה וּרְעוּ עָלַיְיהוּ. וְאִית שְׁמָהָן אַחֲרָנִין לְתַתָּא, דְּאִינּוּן מֵהַהוּא סִטְרָא אַחֲרָא, דְּאִיהוּ מִסִּטְרָא דִּמְסָאֲבָא, וְאִלֵּין לָא קַיְימִין, אֶלָּא בִּרְעוּ דְּעוֹבָדָא לְתַתָּא, לְסַלְּקָא רְעוּ דְּהַהוּא עוֹבָדָא דִּלְתַתָּא לְגַבֵּיהּ. בְּגִין דְּאִיהוּ סִטְרָא אַחֲרָא לָאו אִיהוּ, אֶלָּא בְּעוֹבָדִין דְּהַאי עָלְמָא, לְאִסְתַּאֲבָא בְּהוֹן. כְּגַוְונָא דְּבִלְעָם, וְאִינּוּן בְּנֵי קֶדֶם, וְכָל אִינּוּן דְּמִתְעַסְּקֵי בְּהַהוּא סִטְרָא אַחֲרָא.</p>\n<p>וְאִלֵּין, לָא קַיְימֵי בְּאַתְוָון רְשִׁימִין מִן כ\"ב דְּאוֹרַיְיתָא, בַּר תְּרֵין, וְאִלֵּין ח' וק', וְסַמְכִין לוֹן בִּסְמִיכוּ (בראשית ב' ע\"א) אַתְוָון דְּשֶׁקֶר. אֲבָל אִלֵּין אִינּוּן אִשְׁתְּמוֹדְעָאן לְגַבַּיְיהוּ יַתִּיר. וְעַל דָּא בִּתְּהִלָּה לְדָוִד, בְּכֻלְּהוּ כְּתִיב ו' בְּכָל אָת וְאָת, בַּר מֵאִלֵּין תְּרֵין, דְּלָא כְּתִיב ו', דְּהָא ו' שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ.</p>\n<p>וּבְּגִין כָּךְ אִינּוּן אַרְבְּעִין וּתְרֵין אַתְוָון, דְּעָלְמָא דָּא אִתְבְּרֵי בְּהוּ, אִשְׁתְּכַח הַאי ה' עִלָּאָה, לְסַלְּקָא לְתִשְׁעִין וּתְרֵין, תִּשְׁעִין הֲווֹ, בַּר תְּרֵין אוּדְנִין יְמִינָא וּשְׂמָאלָא. וְרָזָא דָּא (ס\"א וסימניך) (בראשית י״ז:י״ז) וְאִם שָׂרָה הֲבַת תִּשְׁעִים שָׁנָה תֵּלֵד. אֲבָל אִיהוּ בְּחֻשְׁבָּנָא תִּשְׁעִין וּתְרֵין, וְכַד אִתּוֹסָף דַּרְגָּא דְּרָזָא דִּבְרִית, דְּאִיהוּ רְקִיעָא תְּמִינָאָה, וְקַיְּימָא לִתְמַנְיָא יוֹמִין, הָא מֵאָה. וְאִלֵּין וַדַּאי מֵאָה בִּרְכָאן בְּכָל יוֹמָא דְּאִצְטְרִיכָא כְּנֶסֶת יִשְׂרָאֵל לְאִתְעַטְרָא בְּהוּ. וְכֹלָּא בְּרָזָא דְּה'.</p>\n<p>הַאי ה', אִיהִי דִּיּוּקְנָא דִּילָהּ בִּתְרֵין נוּנִין, רָזָא דְּמֵאָה, וְאִינּוּן חָמֵשׁ סַמְכִין רְתִיכִין, דְּנַפְקֵי מִגּוֹ בּוּצִינָא, וְאִינּוּן חָמֵשׁ אַחֲרָנִין דְּנַפְקִין מִינָּהּ. וְעַל דָּא דְּיוּקְנָהָא כְּגַוְונָא דָּא ן ן, תְּרֵין נוּנִין, וּנְקוּדָה דְּקַיְימָא בְּאֶמְצָעִיתָא. וְעַל דָּא ו' קַיְּימָא בֵּינַיְיהוּ תָּדִיר, כְּגַוְונָא דָּא (רל\"ה ע\"ב) נוּן, בְּגִין דְּהָכָא אִיהוּ אַתְרֵיהּ לְאִתְעַטְרָא, וְאַף עַל גַּב דְּרָזִין אַחֲרָנִין אִינּוּן בְּרָזָא דְּה', אֲבָל דָּא אִיהוּ בְּרָזִין דְּסִפְרָא דְּחֲנוֹךְ, וְהָכִי הוּא וַדַּאי.</p>\n<p>וְכַד אִתְתַּקְנָא בְּאִינּוּן חַמְשִׁין בִּלְחוֹדַיְיהוּ, אִיהוּ נְקוּדָה חֲדָא דְּקַיְּימָא בְּרָזָא דְּנ', כְּגַוְונָא דָּא (ה') נ', נוּ\"ן. וְחַד נְקוּדָה בְּאֶמְצָעִיתָא דְּאִיהִי שַׁלְטָא עָלַיְיהוּ, וְכֹלָּא רָזָא חֲדָא. זַכָּאִין אִינּוּן דְּיַדְעֵי אָרְחוֹי דְּאוֹרַיְיתָא, לְמֵהַךְ בְּאָרְחֵי קְשׁוֹט. זַכָּאִין אִינּוּן בְּהַאי עָלְמָא, וְזַכָּאִין אִינּוּן בְּעָלְמָא דְּאָתֵי.</p>\n<p>רָזָא תְּלִיתָאָה אָת ו', הַאי אָת דִּיּוּקְנָא דְּרָזָא דְּאָדָם, כְּמָה דְּאִתְּמַר. וְהָא אוּקִימְנָא, דְּהַאי אָת, קַיְּימָא עַל י\"ב רְתִיכִין. וְכַד מִתְפָּרְשָׁאן, אִינּוּן כ\"ד רְתִיכִין, דִּכְלִילָן בְּהַאי אָת פְּשִׁיטוּ דִּיּוּקְנָא דְּבַר נָשׁ, לָקֳבֵל דְּרוֹעִין וְיַרְכִין וְגוּפָא <Nonei></i>שַׁיְיפִין דִּלְהוֹן כ\"ד אִינּוּן דִּדְּרוֹעִין, וְיַרְכִין, וְגוּפָא, הָא אִתְּמַר, אֲבָל כֻּלְּהוּ סְתִימִין בְּגוּפָא, וְגוּפָא קַיְּימָא בְּכֻלְּהוּ כ\"ד, וְכֻלְּהוּ רְתִיכִין כְּלִילָן בֵּיהּ בְּגוּפָא, וּבְגִין דִּכְלִילָן כֻּלְּהוּ בֵּיהּ, קַיְּימָא, ו' פְּשִׁיטוּ חַד.</p>\n<p>גּוּפָא חַד כָּלִיל בְּכ\"ד רְתִיכִין, וְאִלֵּין אִינּוּן: רֵישָׁא בְּשִׁית. גּוּפָא בְּי\"ח, וְאַף עַל גַּב דְּכָל רְתִיכִין אִינּוּן (נ\"א י' י') (נ\"א י\"ח) י\"ב לְכָל סְטָר, בְּכֹלָּא קַיְּימָא גּוּפָא. אֲבָל עֶשְׂרִים וְאַרְבַּע אִינּוּן שִׁית דְּרֵישָׁא, דְּאִינּוּן שַׁיְיפִין לְאַעֲלָאָה רֵישָׁא. תִּמְנִי סְרֵי חוּלְיָין דְּקַיְּימָא רֵישָׁא, וְסַמְכָא גּוּפָא עָלַיְיהוּ.</p>\n<p>וְכֻלְּהוּ פְּשִׁיטוּ חַד, בְּרֵישָׁא וְגוּפָא, וְאִינּוּן שִׁיתִּין כֻּלְּהוּ כָּלִיל לוֹן, דְּאִיהוּ רָזָא דְּשִׁית. וְעַל דָּא שִׁיעוּרָא דְּאָת ו', רֵישָׁא שִׁיעוּרָא בְּשִׁית נְקוּדִין מַמָּשׁ, גּוּפָא בְּתַמְנֵי סְרֵי. כְּגַוְונָא דָּא כָּל אִלֵּין רָזִין מִתְפָּרְשָׁן, לְאַכְלְלָא לוֹן בְּגוּפָא, בְּגִין דִּדְּרוֹעִין וְיַרְכִין כֻּלְּהוּ בִּגְנִיזוּ, וְעַל דָּא כֹּלָּא אִתְכְּלִיל בְּרָזָא דְּאָת ו' וּדְיּוּקְנָא דִּילָהּ.</p>\n<p>וְכַד שְׁלִימוּ דְּאָת דָּא אִתְחָזֵי, כְּדֵין כָּל סִטְרִין בִּישִׁין אִסְתָּתָמוּ, וְאִתְפָּרְשָׁן מִסִּיהֲרָא, וְלָא אִתְחַפְיָין, בְּגִין דְּאִיהוּ מַבְקַע כָּל מַשְׁקוֹפִין דִּרְקִיעִין, וְאַנְהִיר לָהּ, וְלָא יַכְלָא מְקַטְרְגָא לְאַבְאָשָׁא כְּלַל. וְכַד הַאי אִסְתַּלָּק, כְּדֵין סָלִיק וְאַסְטֵי וּמְפַתֵּי, וְיָכִיל לְקַטְרְגָא עַל כָּל בְּנֵי עָלְמָא, בְּגִין דְּאִיהוּ מֶלֶךְ זָקֵן וּכְסִיל, וְהָא אוֹקִימְנָא.</p>\n<p>ו' אִיהוּ נְהוֹרָא דְּנָהִיר לְסִיהֲרָא, וְאַף עַל גַּב דִּנְהִירִין סַגִּיאִין אִתְכְּלִילָן בֵּיהּ, נְהוֹרָא דְּנָהִיר לְסִיהֲרָא אִיהוּ חַד פְּשִׁיטוּ לְמַלְיָּא לָהּ. וְאִיהוּ רָזָא דְּאָלֶף, רְשִׁימוּ בְּכָל אִינּוּן רָזִין. וְכַד נָהִיר לְסִיהֲרָא בְּרָזָא דְּו' נָהִיר לָהּ.</p>\n<p>וּבְסִפְרָא דְּאָדָם קַדְמָאָה, בְּדִיּוּקְנִין דְּאַתְוָון, ו' חַד נְקוּדָה לְעֵילָּא, וְחָמֵשׁ נְקוּדִין דִּלְתַתָּא, וְכֵן שִׁיעוּרָא דִּילָהּ כְּגַוְונָא דָּא, ו' וְכָל נְקוּדָה קַיְּימָא בְּרָזָא דְּעֶשֶׂר, בְּגִין דְּלֵית לָךָ נְקוּדָה דְּלָא אַשְׁלִים לְעֶשֶׂר, דְּכָל נְקוּדָה אִית בֵּיהּ תֵּשַׁע סַמְכִין רְתִיכִין, וְהַהִיא נְקוּדָה אַשְׁלִים לְעֶשֶׂר. נְקוּדָה דִּימִינָא תֵּשַׁע סַמְכִין רְתִיכִין לָהּ, וְאִיהִי עֲשָׂרָה. וְכֵן לִשְׂמָאלָא. וְכֵן לְכָל סִטְרִין. וְעַל דָּא, כֻּלְּהוּ נְקוּדִין אִינּוּן כָּל חַד וְחַד כְּלָלָא דְּעֶשֶׂר, אִיהִי וּרְתִּיכוֹי. וְכֻלְּהוּ כְּלִילָן בְּהַהוּא פְּשִׁיטוּ דְּאָת ו', בְּגִין כָּךְ כֹּלָּא אִיהוּ בְּדִיּוּקְנָא בְּרָזָא דְּאָת ו'.</p>\n<p>וְכַד עָיִיִל שִׁמְשָׁא בְּסִיהֲרָא, (סיהרא) נָפַק מֵהַאי ו' חַד פְּשִׁיטוּ רָזָא דִּבְרִית, כְּגַוְונָא דָּא ג', וְדָא אִיהוּ לְאָעֲלָא בְּנוּקְבָּא. וְכַד אִתְכְּלִיל כֹּלָּא בְּהַאי פְּשִׁיטוּ דְּאָת ו', כְּדֵין קַיְּימָא לְשַׁמְּשָׁא בְּנוּקְבָּא. וְרָזָא דָּא דִּכְתִּיב, וְאַתָּה הַקְרֵב אֵלֶיךָ אֶת אַהֲרֹן אָחִיךָ, לְאִתְכַּלְּלָא (וילך רמ\"ג ע\"ב, קצ\"א ע\"ב) דְּרוֹעָא בְּגוּפָא, וְאֶת בָּנָיו אִתּוֹ, אִלֵּין כָּל אִינּוּן רְתִיכִין וְסַמְכִין דִּילֵיהּ. דְּרוֹעָא שְׂמָאלָא לְגַבֵּיהּ, דִּכְתִּיב, (במדבר ג׳:מ״ה) קַח אֶת הַלְוִיִּם, לְאִשְׁתַּכְּחָא ו' דְּכָלִיל כֹּלָּא. בְּחַד פְּשִׁיטוּ, לְמֶהֱוֵי חַד.</p>\n<p>וְעַל דָּא אִשְׁתְּכַח יִחוּדָא בְּהַאי, יְמִינָא וּשְׂמָאלָא וְאֶמְצָעִיתָא, כֹּלָּא אִיהוּ חַד. וְעַל דָּא אִתְעָבִיד חַד פְּשִׁיטוּ, וְאִקְרֵי אֶחָד, וְלָא תִּשְׁכַּח בַּר פְּשִׁיטוּ חַד בִּלְחוֹדוֹי, וְדָא הוּא חַד.</p>\n<p>ה' בַּתְרָאָה, אִתְעָבִיד חַד גּוּפָא, בְּהַאי נְקוּדָה דְּאֶמְצָעִיתָא. וְאָעִיל בָּהּ ו', וְאִשְׁתְּכַח ו' בֵּין ב' נְקוּדִין, חַד לְעֵילָּא, וְחַד לְתַתָּא. וּכְדֵין, אִתְאֲחִיד עָלְמָא עִלָּאָה, בְּעָלְמָא תַּתָּאָה, וְאִיהוּ חַד. וְאוֹקִימְנָא. אָתָא רִבִּי אֶלְעָזָר וְרִבִּי אַבָּא וְנָשְׁקוּ יְדוֹי. בָּכָה רִבִּי אַבָּא וְאָמַר, וַוי לְעָלְמָא כַּד יִתְכְּנִישׁ שִׁמְשָׁא וְיִתְחֲשָּׁךְ עָלְמָא.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, יַרְכִּין לְתַתָּא, בְּרָזָא דְּאָת ו', מְנָא לָן דְּאִתְכְּלִילוּ בְּהַאי אָת. אָמַר לֵיהּ, דִּכְתִּיב, (מלאכי ג׳:כ״ב) זִכְרוּ תּוֹרַת מֹשֶׁה עַבְדִּי, וְלָא כְּתִיב נְבִיאִי, לְאִתְחֲזָאָה דְּכֹלָּא אִתְכְּלִיל בְּרָזָא דְּו', וְאָת ו' אִקְרֵי חַד, וְאִיהוּ חַד בִּלְחוֹדָהָא, וּפְשִׁיטוּ חַד וְהָא אִתְּמַר.</p>"],[9520011805,"<p>(שמות כ״ח:א׳) וְאַתָּה הַקְרֵב אֵלֶיךָ וְגוֹ'. אָמַר רִבִּי שִׁמְעוֹן, לָא שִׁמֵשׁ מֹשֶׁה (נ\"א שמשא) (נ\"א דאיהו שמשא) בְּסִיהֲרָא, עַד דְּאִתְכְּלִיל בְּכָל סִטְרִין בְּרָזָא דְּו', כְּמָה דְּאוֹקִימְנָא. תָּא חֲזֵי, מַה כְּתִיב, מִתּוֹךְ בְּנֵי יִשְׂרָאֵל לְכַהֲנוֹ לִי. לְכַהֵן לִי לָא כְּתִיב, אֶלָּא לְכַהֲנוֹ לִי, לְשִׁמּוּשָׁא דִּילֵיהּ, לְשִׁמּוּשָׁא דְּאָת דָּא, לְשִׁמּוּשָׁא דִּילֵיהּ וַדַּאי. לִי דָּא אָת ה', לְאַעֲלָא וּלְשַׁמְּשָׁא ו' בְּה', לְמֶהֱוֵי כֹּלָּא חַד. זַכָּאִין אִינּוּן יִשְׂרָאֵל, <Nonei></i>דְּעָאלוּ וְנַפְקוּ, וְיַדְעֵי בְּרָזָא דְּאָרְחוֹי דְּאוֹרַיְיתָא, לְמֵהָךְ בְּאֹרַח קְשׁוֹט.</p>\n<p>מִתּוֹךָ בְּנֵי יִשְׂרָאֵל אֲמַאי מִתּוֹךְ בְּנֵי יִשְׂרָאֵל. אֶלָּא כֹּלָּא לָא אִתְקְרֵי לְמֶהֱוֵי חַד כְּדְקָא יֵאוֹת, אֶלָּא מִתּוֹךְ בְּנֵי יִשְׂרָאֵל. דְּהָא בְּנֵי יִשְׂרָאֵל קַיְימֵי לְתַתָּא, לְאִתְפַּתְּחָא אָרְחִין, וּלְאַנְהָרָא שְׁבִילִין, וּלְאַדְלְקָא בּוּצִינִין, וּלְקָרְבָא כֹּלָּא מִתַּתָּא לְעֵילָּא, לְמֶהֱוֵי כֹּלָּא חַד, וּבְגִינֵי כַּךְ כְּתִיב (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' וְגוֹ'.</p>\n<p>וְאַתָּה הַקְרֵב אֵלֶיךָ וְגוֹ' אָמַר רַבִּי שִׁמְעוֹן, כֹּלָּא אִיהוּ קְרִיבָה, לְמַאן דְּיָדַע לְיַחֲדָא יִחוּדָא, וּלְמִפְלַח לְמָארֵיהּ, דְּהָא בְּזִמְנָא דְּאִשְׁתְּכַח קָרְבְּנָא כְּדְקָא יֵאוֹת, כְּדֵין אִתְקְרִיב כֹּלָּא כַּחֲדָא, (נ\"א דרגין כלהו כחד) וּנְהִירוּ דְּאַנְפִּין, אִשְׁתְּכַח, בְּעָלְמָא בְּבֵי מַקְדְּשָׁא, וְאִתְכַּפְיָא וְאִתְכַּסְיָא סִטְרָא אַחֲרָא, וְשָׁלִיט סִטְרָא דִּקְדוּשָּׁא בִּנְהִירוּ וְחִידוּ. וְכַד קָרְבְּנָא לָא אִשְׁתְּכַח כְּדְקָא יֵאוֹת, אוֹ יִחוּדָא לָא הֲוֵי כְּדְקָא יֵאוֹת, כְּדֵין אַנְפִּין עֲצִיבוּ. וּנְהִירוּ לָא אִשְׁתְּכַח, וְאִתְכַּסְיָא סִיהֲרָא, וְשַׁלְטָא סִטְרָא אַחֲרָא בְּעָלְמָא, (נ\"א דלא אתחריב בי מקדשא אלא בגין וכו') בְּגִין דְּלָא אִית מַאן דְּיָדַע לְיַחֲדָא שְׁמָא קַדִּישָׁא, כְּדְקָא יֵאוֹת.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, (פ' בא ל\"ד ע\"א) קוּדְשָׁא בְּרִיךְ הוּא לָא נַסֵּי לְאִיּוֹב, וְלָא אָתָא עִמֵּיהּ בְּנִסְיוֹנָא, כְּנִסְיוֹנָא דִּשְׁאַר צַדִּיקַיָּא, דְּהָא לָא כְּתִיב בֵּיהּ וְהָאֱלהִים נִסָּה אֶת אִיּוֹב, כְּמָה דִּכְתִּיב בְּאַבְרָהָם (בראשית כ״ב:א׳) וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. דְּאִיהוּ בְּיָדֵיהּ אַקְרִיב לִבְרֵיהּ יְחִידָאי לְגַבֵּיהּ. וְאִיּוֹב לָא יָהִיב לֵיהּ וְלָא מָסַר לֵיהּ כְּלוּם. וְלָא אִתְּמַר לֵיהּ, אֲבָל אִתְמְסָר בִּיְדָא דִּמְקַטְרְגָא, בְּדִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא. דְּאִיהוּ אַתְּעָר לְהַהוּא מְקַטְרְגָא לְגַבֵּיהּ, מַה דְּאִיהוּ לָא בָּעָא. דְּהָא בְּכָל זִמְנָא אָתָא הַהוּא מְקַטְרְגָא לְאַתְעֲרָא עַל בְּנֵי נָשָׁא, וְהָכָא קוּדְשָׁא בְּרִיךְ הוּא אַתְּעָר לְגַבֵּיהּ, דִּכְתִּיב, (איוב א׳:ח׳) הֲשַׂמְתָּ לִבְּךָ עַל עַבְדִּי אִיּוֹב. אֲבָל רָזָא עֲמִיקָא אִיהוּ.</p>"],[9520011806,"<p>פָּתַח וְאָמַר (בראשית ד׳:ג׳) וַיְהִי מִקֵּץ יָמִים וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה מִנְחָה לַיְיָ'. וַיְהִי מִקֵּץ יָמִים, רָזָא אִיהוּ, מִקֵּץ יָמִים, וְלָא מִקֵּץ (קל\"ד ע\"א) יָמִין, דָּחָה לְקֵּץ יָמִין, וְקָרִיב לְקֵּץ יָמִים. וְהָא אוֹקִימְנָא, דִּכְתִּיב, (דניאל י״ב:י״ג) וְאַתָּה לֵךְ לַקֵּץ. אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְדָנִיאֵל וְאַתָּה לֵךְ לַקֵּץ. אָמַר לֵיהּ, לְאָן קֵץ, לְקֵּץ הַיָּמִים אוֹ לְקֵּץ הַיָּמִין, עַד דְּאָמַר לֵיהּ לְקֵּץ הַיָּמִין.</p>\n<p>וְעַל דָּא דָּחִיל דָּוִד, דִּכְתִּיב, (תהילים ל״ט:ה׳) הוֹדִיעֵנִי יְיָ' קִצִּי. אוֹ לְקֵּץ הַיָּמִים, אוֹ לְקֵּץ הַיָּמִין. וְהָכָא מָה כְּתִיב, וַיְהִי מִקֵּץ יָמִים וְלָא מִקֵּץ יָמִין. וּבְגִינֵי כַּךְ לָא אִתְקַבָּל קָרְבָּנֵיהּ דְּהָא מִסִּטְרָא אַחֲרָא הֲוָה כֹּלָּא.</p>\n<p>תָּא חֲזֵי מָה כְּתִיב, (בראשית ד׳:ד׳) וְהֶבֶל הֵבִיא גַּם הוּא. מַאי גַּם הוּא. לְאַסְגָּאָה כֹּלָּא דָּא בְּדָא. קָרְבָּנָא כֹּלָּא וְעִקָרָא דִּילֵיהּ הֲוָה לְקוּדְשָׁא בְּרִיךְ הוּא, וְיָהִיב חוּלָקֵיהּ לְסִטְרָא אַחֲרָא, כְּמָה דְאַתְּ אָמֵר וּמֵחֶלְבֵיהֶן. וְקַיִן, עִקָּרָא עָבֵד מִקֵּץ יָמִים, וְיָהַב חוּלָקָא לְקוּדְשָׁא בְּרִיךְ הוּא, וְעַל דָּא אִתְדָחָא אִיהוּ וְקָרְבָּנֵיהּ.</p>\n<p>בְּאִיּוֹב מַה כְּתִיב, (איוב א׳:ה׳) וְהָלְכוּ בָנָיו וְעָשׂוּ מִשְׁתֶּה וְגוֹ'. וּכְתִיב וַיְהִי כִּי הִקִּיפוּ יְמֵי הַמִּשְׁתֶּה. וּכְתִיב וְשָׁלְחוּ וְקָרְאוּ לִשְׁלשֶׁת אַחְיוֹתֵיהֶם לֶאֱכוֹל וְלִשְׁתּוֹת עִמָּהֶם, דְּדָא אִיהוּ עִקָּרָא לְסִטְרָא אַחֲרָא. וּלְבָתַר אַקְרִיב עוֹלוֹת, וְעוֹלָה אִיהוּ דְּכַר, וְלָא נוּקְבָּא, וְסַלְּקָא לְעֵילָּא, וְקָרְבָּנָא לָא קָרִיב לְאַכְלְלָא לֵיהּ כְּדְקָא יֵאוֹת.</p>"],[9520011807,"<p>וְתָּא חֲזֵי, אִלְמָלֵא חוּלָקָא יָהַב לְכֹלָּא, מְקַטְרְגָא לָא יָכִיל לֵיהּ לְבָתַר, וְאִי תֵּימָא אֲמַאי אַבְאִישׁ לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. אֶלָּא, בְּגִין דְּגָרִים לְכַסְיָּא נְהוֹרָא וּלְאִתְחַפְיָּא, וְאִיהוּ לָא קָרִיב קָרֵבְּנָא אַחֲרָא, לְאַתְּזָנָא בֵּיהּ אַחֲרָנִין, אֶלָּא עוֹלָה, דְּסַלְּקָא לְעֵילָּא, וְעַל דָּא כְּתִיב, כָּכָה יַעֲשֶׂה אִיּוֹב כָּל הַיָּמִים, דְּאִלְמָלֵא סִטְרָא אַחֲרָא אִתְּזָנַת בְּחוּלָקָא, אִתְעֲבַר מֵעַל מַקְדְּשָׁא וְאִסְתַּלָּק מִנֵּיהּ, וְסִטְרָא דִּקְדוּשָׁה הֲוָה סָלִיק לְעֵילָּא לְעֵילָּא.</p>\n<p>אֲבָל אִיהוּ לָא בָּעָא דְּאִתְהֲנֵי אַחֲרָא מִקָרְבָּנֵיה, וְאַעְדֵּי גַּרְמֵיהּ מִנֵּיהּ. מְנָא לָן. דִּכְתִּיב, (איוב א׳:א׳) וְסָר מֵרָע. וְעַל דָּא קָרִיב תָּדִיר עוֹלָה, דְּהָא עוֹלָה לָא אִתְהָנֵי מִנֵּיהּ סִטְרָא אַחֲרָא לְעָלְמִין. וּבְגִין כַּךְ, כָּל מָה דְּנָטִיל לְבָתַר, מִדִּידֵיהּ נָטִיל. וְעַל דָּא אִיּוֹב גָּרִים לְחַפְיָא עָרְלָה עַל בְּרִית קַיָימָא, דְּלָא הֲוָה אַעְדֵּי מִנֵּיהּ. וּבְגִין כַּךְ קוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר לְהַהוּא מְקַטְרְגָא, דִּכְתִּיב הֲשַׂמְתָּ לִבְּךָ עַל עַבְדִּי אִיּוֹב.</p>\n<p>תָּא חֲזֵי, כַּד בָּעָא <Nonei></i>קוּדְשָׁא בְּרִיךְ הוּא לְאִתְאַחֲדָא בְּהוּ בְּיִשְׂרָאֵל בְּמִצְרַיִם, לָא קַיְּימָא שַׁעֲתָא. בְּגִין דְּעָרְלָה חַפְיָא נְהוֹרָא, עַד זִמְנָא דְּהַהוּא מְקַטְרְגָא הֲוָה נָטִיל דִּילֵיהּ מֵאִיּוֹב, וְעַל דָּא פָּקִיד לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמֵיכְלֵיהּ לְהַהוּא פֶּסַח בִּבְהִילוּ, עַד דְּהַהוּא סִטְרָא אַחֲרָא אִשְׁתָּדַּל בֵּיהּ בְּאִיּוֹב, וּפָקִיד לְאִתְעַבְּרָא עָרְלָה מִנַּיְיהוּ, וּכְדֵין אִתְאֲחָד קוּדְשָׁא בְּרִיךְ הוּא בְּיִשְׂרָאֵל, וְהַהוּא סִטְרָא אַחֲרָא אִתְפְּרַשׁ מִן קֻדְשָׁא, וְאִשְׁתָּדַּל בֵּיהּ בְּאִיּוֹב, וְנָטִיל מִדִילֵיהּ. וּכְדֵין (שמות יב) פֶּסַח הוּא לַיְיָ' וַדַּאי. דְּעַד הַשְׁתָּא לָא הֲוָה פֶּסַח לַיְיָ'. זַכָּאִין אִינּוּן דְּיַדְעֵי וּמְיַחֲדֵי יִחוּדָא דְּמָארֵיהוֹן כְּדְקָא יֵאוֹת.</p>\n<p>כְּתִיב (שמות לד יז) אֱלהֵי מַסֵּכָה לא תַעֲשֶׂה לָּךְ, וּכְתִיב בַּתְרֵיהּ אֶת חַג הַמַּצוֹת תִּשְׁמֹר. (מאי עביד) מַאי הַאי לְגַבֵּי הַאי. אֶלָּא הָכִי אוּקְמוּהָ, מַאן דְּאָכִיל חָמֵץ בְּפֶסַח (כאילו עביד כוכבים ומזלות למפלח לגרמיה, דהא רזא הכי הוא דחמץ בפסח) כְּמַאן דְּפָלַח לְכּוֹכָבִים וּמַזָּלוֹת אִיהוּ.</p>\n<p>תָּא חֲזֵי, כַּד נָפְקוּ יִשְׂרָאֵל מִמִּצְרָיִם נָפְקוּ מֵרְשׁוּ דִּלְהוֹן, מֵרְשׁוּ אַחֲרָא, מֵהַהוּא רְשׁוּ דְּאִקְרֵי חָמֵץ, נַהֲמָא בִּישָׁא. וְעַל דָּא אִקְרֵי כּוֹכָבִים וּמַזָּלוֹת הָכִי, וְדָא אִיהוּ רָזָא דְּיֵצֶר הָרָע, פּוּלְחָנָא נוֹכְרָאָה, דְּאִקְרֵי אוּף הָכִי שְׂאוֹר. וְדָא אִיהוּ יֵצֶר הָרָע, דְּהָכִי אִיהוּ יֵצֶר הָרָע בְּבַר נָשׁ, כְּחָמִיר בְּעִיסָה, עָאל בִּמְעוֹי דְּבַר נָשׁ זְעֵיר זְעֵיר, וּלְבָתַר אַסְגֵּי בֵּיהּ, עַד דְּכָל גּוּפָא אִתְעֲרַב בַּהֲדֵיהּ. וְדָא אִיהוּ כּוֹכָבִים וּמַזָּלוֹת. וְעַל דָּא כְּתִיב, (תהילים פ״א:י׳) לֹא יִהְיֶה בְךָ אֵל זָר. אֵל זָר וַדַּאי.</p>"],[9520011808,"<p>אֶת חַג הַמַּצּוֹת תִּשְׁמֹר, רִבִּי יְהוּדָה פָּתַח, (ישעיהו ב׳:כ״ב) חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ כִּי בַמֶּה נֶחְשָׁב הוּא. הַאי קְרָא אוּקְמוּהָ. אֲבָל מַאי חִדְלוּ לָכֶם מִן הָאָדָם, וְכִי אַזְהַר לֵיהּ לְבַר נָשׁ לְאִתְמָנְע מִשְּׁאָר בְּנֵי נָשָׁא. אוּף אִינּוּן נָמֵי לְגַבֵּיהּ, יִשְׁתַּכְחוּן בְּנֵי נָשָׁא דְּלָא יִקְרְבוּן אִלֵּין בְּאִלֵּין לְעָלְמִין. אֶלָּא הָא אוּקְמוּהָ בְּמַאן דְּאֲשְׁכִּים לְפִתְחָא דְּחַבְרֵיהּ לְמֵיהָב לֵיהּ שְׁלָם.</p>\n<p>וַאֲנָא אוֹקִימְנָא לֵיהּ בִּקְרָא אַחֲרָא, דִּכְתִּיב, (משלי כ״ז:י״ד) מְבָרֵךְ רֵעֵהוּ בְּקוֹל (רכ\"ו ע\"ב) גָּדוֹל בַּבֹּקֶר הַשְׁכֵּם קְלָלָה תֵּחָשֶׁב לוֹ. וְאַף עַל גַּב דְּכֹלָּא שַׁפִּיר. אֲבָל מַאי חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ. הָכָא פָּקִיד קוּדְשָׁא בְּרִיךְ הוּא לְבַר נָשׁ, וְאַזְהִיר לֵיהּ לְאִסְתַּמְּרָא מֵאִינּוּן בְּנֵי נָשָׁא, דְּסָטוּ אָרְחַיְיהוּ מֵאֹרַח טָב לְאֹרַח בִּישׁ, וּמְסָאֲבֵי נַפְשַׁיְיהוּ בְּהַהוּא מְסָאֲבוּ אַחֲרָא.</p>\n<p>דְּהָא כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא לְבַר נָשׁ, עָבֵד לֵיהּ בְּדִיּוּקְנָא עִלָּאָה, וְנָפַח בֵּיהּ רוּחָא (נ\"א נשמתא) קַדִּישָׁא, דְּכָלִיל בִּתְלַת כְּמָה דְּאוֹקִימְנָא, דְּאִית בֵּיהּ נֶפֶשׁ רוּחַ וּנְשָׁמָה, וְעֵילָּא מִכֹּלָּא נְשָׁמָה, דְּאִיהִי חֵילָא עִלָּאָה לְמִנְדַּע, וּלְמֵטַר פִּקּוּדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא. וְאִי הַהִיא נִשְׁמְתָא קַדִּישָׁא אָעִיל לָהּ בְּפוּלְחָנָא אַחֲרָא, הַאי אִיהוּ מַסְאִיב לָהּ, וְנָפִיק מִפּוּלְחָנָא דְּמָארֵיהּ. בְּגִין דִּתְלַת חֵילִין אִלֵּין, כֻּלְּהוּ חַד, נֶפֶשׁ רוּחַ וּנְשָׁמָה מִשְׁתַּתְּפֵי כַּחֲדָא, וַהֲווּ חַד, וְכֹלָּא כְּגַוְונָא דְּרָזָא עִלָּאָה. (על דא נאמר (שם י\"ג) הולך את חכמים וגו')</p>\n<p>וְאִי חָזֵינָן לְהַאי בַּר נָשׁ, דַּהֲווֹ בֵּיהּ אִלֵּין דַּרְגִּין כֻּלְּהוּ. עַד לָא קַיְּימָא בְּקִיּוּמֵיהּ לְמִנְדַּע מַאן אִיהוּ, בְּמַאי אִתְיְדַע (דלא) לְקָרְבָא בַּר נָשׁ בַּהֲדֵיהּ, אוֹ לְאִתְמָנְעָא מִנֵּיה. (ס\"א בר נש דאית ביה דרגין אלין כלהו וקיימא בקיומיה דא איהו גבר שלים עבדא מהימנא דמאריה ובעי לאשתתפא ביה ולאתחברא בהדיה למילף אורחוי מניה. ובמאי אתיידע בר נש למנדע מאן איהו לקרבא בהדיה או לאתמנעא מניה) בְּרוּגְזֵיהּ מַמָּשׁ, יְדַע לֵיהּ בַּר נָשׁ, וְיִשְׁתְּמוֹדַע מַאן אִיהוּ. אִי הַהִיא נִשְׁמְתָא קַדִּישָׁא נָטַר בְּשַׁעֲתָא דְּרוּגְזוֹי, (אתיא עליה) דְּלָא יֶעְקַר לָהּ מֵאַתְרָהָא, בְּגִין לְמִשְׁרֵי תְּחוֹתָהּ הַהוּא אֵל זָר, דָּא אִיהוּ בַּר נָשׁ כְּדְקָא יֵאוֹת. דָּא אִיהוּ עַבְדָּא דְּמָארִיהּ, דָּא אִיהוּ גְּבָר שְׁלִים.</p>\n<p>וְאִי הַהוּא בַּר נָשׁ לָא נָטִיר לָהּ, וְאִיהוּ עָקַר קְדוּשָּׁה דָּא עִלָּאָה מֵאַתְרֵיהּ, לְמִשְׁרֵי בְּאַתְרֵיהּ סִטְרָא אַחֲרָא. וַדַּאי דָּא אִיהוּ בַּר נָשׁ דְּמָרִיד בְּמָארֵיהּ, וְאָסִיר לְקָרְבָא בַּהֲדֵיהּ וּלְאִתְחַבְּרָא עִמֵּיהּ, וְדָא אִיהוּ (איוב י״ח:ד׳) טֹרֵף נַפְשׁוֹ בְּאַפּוֹ. אִיהוּ טָרִיף וְעָקַר נַפְשֵׁיהּ, בְּגִין רוּגְזֵיהּ, וְאַשְׁרֵי בְּגַוֵּיהּ אֵל זָר. וְעַל דָּא כְּתִיב חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ, דְּהַהִיא נִשְׁמְתָא קַדִּישָׁא טָרִיף לָהּ, וְסָאִיב לָהּ, בְּגִין אַפּוֹ. אֲשֶׁר נְשָׁמָה <Nonei></i>אַחְלַף בְּאַפּוֹ. כִּי בַמֶּה נֶחְשָׁב הוּא. כּוֹכָבִים וּמַזָּלוֹת אִתְחֲשִׁיב הַהוּא בַּר נָשׁ.</p>\n<p>וּמַאן דְּאִתְחַבָּר עִמֵּיהּ, וּמַאן דְּאִשְׁתָּעֵי (ס\"א משתתף) בַּהֲדֵיהּ, כְּמַאן דְּאִתְחַבָּר בְּכּוֹכָבִים וּמַזָּלוֹת מַמָּשׁ. מַאי טַעְמָא. בְּגִין דְכּוֹכָבִים וּמַזָּלוֹת מַמָּשׁ שָׁארֵי בְּגַוֵּיהּ. וְלָא עוֹד, אֶלָּא דְּעָקַר קְדוּשָּׁה עִלָּאָה מֵאַתְרֵיהּ, וְשָׁארִי בְּאַתְרֵיהּ כּוֹכָבִים וּמַזָּלוֹת אֵל זָר. מַה אֵל זָר כְּתִיב בֵּיהּ (ויקרא י״ט:ד׳) אַל תִּפְנוּ אֶל הָאֱלִילִים, כְּגַוְונָא דָּא, אָסִיר לְאִסְתַּכְּלָא בְּאַנְפּוֹי.</p>\n<p>וְאִי תֵּימָא הָא רוּגְזָא דְּרַבָּנָן. רוּגְזָא דְּרַבָּנָן טָב אִיהוּ לְכָל סִטְרִין, דְּהָא תָּנֵינָן דְּאוֹרַיְיתָא אֶשָּׁא אִיהִי, וְאוֹרַיְיתָא קָא מַרְתְּחָא לֵיהּ, דִּכְתִּיב, (ירמיהו כ״ג:כ״ט) הֲלֹא כֹה דְּבָרִי כָּאֵשׁ נְאֻם יְיָ'. רוּגְזָא דְּרַבָּנָן בְּמִלֵּי דְּאוֹרַיְיתָא. רוּגְזָא דְּרַבָּנָן לְמֵיהַב יְקָרָא לְאוֹרַיְיתָא, וְכֹלָּא לְפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוִי, לְכַךְ נֶאֱמַר (דברים ד׳:כ״ד) כִּי יְיָ' אֱלהֶיךָ אֵשׁ אוֹכְלָה הוּא אֵל קַנָּא.</p>\n<p>אֲבָל אִי בְּמִלִּין אַחֲרָנִין, לָאו פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא הַאי, בְּגִין דִּבְכָל חַטָּאִים דְּקָא עָבִיד בַּר נָשׁ, לָאו אִיהוּ כּוֹכָבִים וּמַזָּלוֹת מַמָּשׁ כְּהַאי, וְאָסִיר לְקָרְבָא בַּהֲדֵיהּ דְּהַאי. וְאִי תֵּימָא הָא לְשַׁעֲתָא הֲוָה, דְּעָבַר וְהָדַר אַהְדָּר. לָאו הָכִי, דְּכֵיוָן דְּאִעֲקָר קְדוּשָּׁא דְּנַפְשֵׁיהּ מִנֵּיהּ וּמֵאַתְרֵיהּ, וְהַהוּא אֵל זָר, מַקְפַּח הַהוּא אֲתָר, אִתְתָּקַּף בֵּיהּ, וְלָא שָׁבִיק לֵיהּ. בַּר כַּד אִתְדָּכֵי בַּר נָשׁ מִכֹּל וָכֹל, וְעָקַר לֵיהּ לְעָלְמִין, וּלְבָתַר אִשְׁתָּדַּל לְאִתְקַדְּשָׁא וּלְאַמְשָׁכָא קְדוּשָּׁה עָלֵיהּ. כְּדֵין וּלְוָאי דְּאִתְקַדֵשׁ. אֲמַר לֵיהּ רִבִּי יוֹסֵי, אִתְקָדָּשׁ מַמָּשׁ. (ס\"א אמאי והא אתדחי ואתקדש)</p>\n<p>אֲמַר לֵיהּ תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִיהוּ עָקַר קְדוּשָּׁה דְּנַפְשֵׁיהּ, וְשַׁרְיָא בְּאַתְרֵיהּ הַהוּא אֵל זָר דְּאִקְרֵי טָמֵא, אִסְתְּאָב בַּר נָשׁ, וְסָאִיב לְמַאן דְּקָרִיב בַּהֲדֵיהּ, וְהַהִיא קְדוּשָּׁה עָקְרַת מִנֵּיהּ, וְכֵיוָן דְּעָקְרַת מִנֵּיהּ זִמְנָא חֲדָא, כַּמָּה דְּיַעֲבִיד בַּר נָשׁ עוֹד, לָא תִּיתוּב לְאַתְרָהָא.</p>\n<p>אֲמַר לֵיהּ אִי הָכִי, כַּמָה מִסְאֲבִין אִינּוּן דְּמִּתְדָכָּאן. אֲמַר לֵיהּ שָׁאנִי מִסְאֲבוּ אַחֲרָא, דְּלָא יָכִיל לְמֶעְבַּד יַתִּיר. אֲבָל דָּא שַׁנְיָא מִכֹּלָּא, דְּכָל גּוּפָא סָאִיב מִגּוֹ וּמִבַּר, וְנַפְשָׁא, וְכֹלָּא מַסְאִיב. וּשְׁאַר מִסְאֲבוּ דְּעָלְמָא, לָאו אִיהוּ אֶלָּא גּוּפָא לְבַר בִּלְחוֹדוֹי, וּבְּגִין כָּךְ כְּתִיב חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ, דְּאַחְלָף קְדוּשָּׁה דְּמָארֵיהּ בְּגִין אַפּוֹ, דְּדָא אִיהוּ מִסְאֲבוּ דְּמַסְאִיב כֹּלָּא. כִּי בַמֶּה נֶחְשָׁב הוּא. בָּמָה כּוֹכָבִים וּמַזָּלוֹת וַדַּאי נֶחְשָׁב אִיהוּ.</p>\n<p>תָּא חֲזֵי, הַאי אִיהוּ רוּגְזָא דְּאִיהוּ כּוֹכָבִים וּמַזָּלוֹת, סִטְרָא אַחֲרָא, כְּמָה דְּאַמָרָן, דְּבָעֵי בַּר נָשׁ לְאִסְתַּמְּרָא מִנֵּיהּ וּלְאִתְפָּרָשָׁא מֵעֲלוֹי, וְעַל דָּא כְּתִיב (שמות לה) אֱלהֵי מַסֵּכָה לא תַעֲשֶׂה לָּךְ. לָּךְ: בְּגִין לְאַבְאָשָׁא גַּרְמָךְ. וּכְתִיב בַּתְרֵיהּ אֶת חַג הַמַּצּוֹת תִּשְׁמֹר. תִּשְׁמֹר: דָּא סִטְרָא דִּקְדוּשָּׁה, דְּבָעֵי בַּר נָשׁ לְנַטְרָא לֵיהּ, וְלָא יָחְלָף לֵיהּ בְּגִין סִטְרָא אַחֲרָא. וְאִי יֶחְלָף לֵיהּ הָא אִיהוּ מַסְאִיב, וְסָאִיב לְכָל מַאן דְּקָרִיב בַּהֲדֵיהּ.</p>"],[9520011809,"<p>אֶת חַג הַמַּצּוֹת תִּשְׁמֹר, הַאי אִיהוּ אֲתָר דְּאִקְרֵי שָׁמוֹר. וּבְּגִין כָּךְ כְּתִיב, אֶת חַג הַמַּצּוֹת תִּשְׁמֹר שִׁבְעַת יָמִים תֹּאכַל מַצּוֹת כַּאֲשֶׁר צִוִּיתִיךָ. שִׁבְעַת יָמִים אִלֵּין, לָאו אִינּוּן כְּשִׁבְעַת הַיָּמִים דְּסֻכּוֹת, דְּאִינּוּן עִלָּאִין וְאִלֵּין תַּתָּאִין. וְעַל דָּא, בְּאִינּוּן הַלֵּל גָּמוּר, וּבְהָנִי לָאו הַלֵּל גָּמוּר, וְעַל דְּאִינּוּן לְתַתָּא, שִׁבְעַת יָמִים תֹּאכַל מַצּוֹת. מַצֹּת כְּתִיב חָסֵר בְּלָא ו', דְּעַד לָא שָׁרָאן אִינּוּן יוֹמִין עִלָּאִין, רָזָא דְּו'.</p>\n<p>וְאִי תֵּימָא, כֵּיוָן דְּהַאי רָזָא דְּחַג הַמַּצּוֹת אִתְקַדָּשׁ, אֲמַאי נַחְתָּא, דְּהָא תָּנֵינָן מַעֲלִין בַּקֹּדֶשׁ וְלָא מוֹרִידִין, אֲמַאי נַחְתָּא לְתַתָּא בְּאִינּוּן יוֹמִין תַּתָּאִין.</p>\n<p>תָּא חֲזֵי, כְּתִיב (ויקרא ט״ז:ו׳) וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ וְגוֹ', מַאן דִּיְכַפֵּר, אִצְטְרִיךְ (נ\"א לכפרא) עָלֵיהּ בְּקַדְמִיתָא, וּבָתַר עַל בֵּיתֵיהּ. כְּגַוְונָא דָּא, הַאי דַּרְגָּא, שָׁאֲרִי לְאִתְקַדְּשָׁא וּלְנָפְקָא בִּקְדוּשָׁה, לְכַפְּרָא עָלֵיהּ, וְכֵיוָן דְּאִיהוּ אִתְקַדָּשׁ, בָּעֵי לְכַפָּרָא עַל בֵּיתֵיהּ, וּלְקַדְּשָׁא לוֹן, וְעַל דָּא נַחְתָּא לְתַתָּא לְקַדְּשָׁא בֵּיתֵיהּ. וּבְמָּה מְקַדֵּשׁ לוֹן, בְּיִשְׂרָאֵל דִּלְתַתָּא. בְּחוּשְׁבָּנָא דְעוֹמֵר וְכֵיוָן דְּאִלֵּין מִתְקַדְשָׁאן, בָּעֵינָן לְסַלְּקָא לָהּ לְעֵילָּא, דְּהָא כַּד בֵּיתָא דְּמַטְרוֹנִיתָא אִתְקַדְשַׁת, כְּדֵין סַלְקַת לְעֵילָּא, לְאִתְקַשְּׁרָא בְּאִינּוּן יוֹמִין עִלָּאִין <Nonei></i>לְעֵילָּא.</p>\n<p>וְעַל דָּא אֲנָן עַבְדִּין חוּשְׁבָּנָא, בְּקִיּוּמָא עַל קַיְימִין, בְּגִין דְּאִינּוּן יוֹמִין, יוֹמִין עִלָּאִין אִינּוּן, וְכֵן בְּכָל זִמְנָא דְּעָאל בַּר נָשׁ לְאִינּוּן יוֹמִין עִלָּאִין, בֵּין בִּצְלוֹתָא, בֵּין בִּשְׁבָחָא, אִצְטְרִיךְ לְקַיְּימָא עַל רַגְלוֹי, יַרְכִּין וְגוּפָא כַּחֲדָא תַּמָּן. יַרְכִּין וְגוּפָא לְקַיְּימָא, כִּדְכוּרָא דְּקַיְּימָא בְּחֵילֵיהּ, וְלָא כְּנוּקְבָא דְּאָרְחָהָא לְמֵיתַב. וְעוֹד בְּגִין שְׁבָחָא דְּעָלְמָא עִלָּאָה.</p>\n<p>וּבְגִין דְּאִיהוּ רָזָא דִּדְכוּרָא, נָשִׁים פְּטוּרוֹת מֵחוּשְׁבָּנָא דָּא, וְלָא מִתְחַיְיבָן לְמִימְנִי בַּר דְּכוּרִין, לְאִתְקַשְּׁרָא כָּל חַד כְּדְקָא יֵאוֹת. כְּגַוְונָא דָּא, (שמות כ״ג:י״ז) יֵרָאֶה כָּל זְכוּרְךָ, דְּכוּרִין, וְלָא נָשִׁין. בְּגִין דְּרָזָא דִּבְרִית בִּדְכוּרָא אִיהוּ, וְלָא בְּנוּקְבָּא, וּבְגִין דְּקַיְּימָא רָזָא לְעֵילָּא, נָשִׁין לָא מִתְחַיְיבָן.</p>\n<p>וְרָזָא אוֹלִיפְנָא הָכָא, דִּבְכָל שִׁבְעַת יוֹמִין, מֵאִלֵּין יוֹמִין עִלָּאִין, נַטְלָא קְדוּשָּׁא יוֹמָא חַד (ומתאחד) דְּאִלֵּין תַּתָּאֵי, וְהַאי תַּתָּאָה אִקְרֵי שָׁבוּעַ, דְּאִתְקַדָּשׁ בְּשִׁבְעָה יוֹמִין עִלָּאִין. וְכֵן בְּכָל שִׁבְעָה וְשִׁבְעָה מֵאִינּוּן חַמְשִׁין יוֹמִין, עַד וְלָא עַד בִּכְלָל, וְכַד אִשְׁתְּכָחוּ אַרְבְּעִין וּתֵשַׁע יוֹמִין עִלָּאִין, אִשְׁתְּכָחוּ לְתַתָּא שֶׁבַע יוֹמִין, דְּאִתְקַדָּשׁוּ בְּהוּ וְכָל חַד אִקְרֵי שָׁבוּעַ, דְּעָאל בְּאִינּוּן שֶׁבַע. וְעַל דָּא כְּתִיב, (ויקרא כ״ג:ט״ו) שֶׁבַע שַׁבָּתוֹת תְּמִימוֹת תִּהְיֶינָה. בְּגִין דְּאִינּוּן נוּקְבִין, נָקַט קְרָא לִישָׁנָא דְּנוּקְבִין.</p>\n<p>וְכַד אִתְקַדָּשׁוּ בְּהוּ, וּבֵיתָא, מִתַּתְקְנָא לְאִתְחַבְּרָא אִתְּתָא בְּבַעְלָהּ, כְּדֵין אִקְרֵי חַג שָׁבוּעוֹת, מֵאִינוּן נוּקְבֵי דְּשָׁארוּ עָלַיְיהוּ אִינּוּן יוֹמִין עִלָּאִין, דְּאִתְקַדָּשׁוּ בְּהוּ. וּבְּגִין כָּךְ כְּתִיב בְּשָׁבוּעוֹתֵיכֶם, אִינּוּן דִּלְכוֹן, וְלָא כְּתִיב בְּשָׁבוּעוֹת, בְּגִין דְּהָכִי נָמֵי מִתְקַדְּשִׁין יִשְׂרָאֵל לְתַתָּא עִמְּהוֹן.</p>\n<p>וְעַל דָּא כַּד מָטוּן לְתֵשַׁע וְאַרְבְּעִין יוֹמִין, הַהוּא יוֹמָא עִלָּאָה דְּעָלַיְיהוּ, דְּאִיהוּ יוֹמָא דְּחַמְשִׁין, דְּשַׁלִּיט עַל תִּשְׁעָה וְאַרְבְּעִין יוֹמִין, רָזָא דִּכְלָלָא דְּאוֹרַיְיתָא, בְּתִשְׁעָה וְאַרְבְּעִין אַנְפִּין, וּכְדֵין הַהוּא יוֹמָא עִלָּאָה, יוֹמָא דְּחַמְשִׁין, בְּאִתְעָרוּתָא דִּלְתַתָּא, אַפִּיק אוֹרַיְיתָא כְּלָלָא בְּתִשְׁעָה וְאַרְבְּעִין אַנְפִּין.</p>"],[9520011810,"<p>רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהילים פ״ד:ד׳) גַּם צִפּוֹר מָצְאָה בַיִת וּדְרוֹר קֵן לָהּ אֲשֶׁר שָׁתָה אֶפְרוֹחֶיהָ אֶת מִזְבְּחוֹתֶיךָ וְגוֹ'. גַּם צִפּוֹר מָצְאָה בַיִת, אִלֵּין צִפֳּרֵי שְׁמַיָא, דְּמִנְּהוֹן שַׁוְיָין מָדוֹרֵיהוֹן לְבַר, וּמִנְּהוֹן שַׁוְיָין מָדוֹרֵיהוֹן בְּבֵיתָא, כְּגוֹן דְּרוֹר, דְּאִיהוּ עוֹפָא דְּשַׁוֵּי דִּיוּרֵיהּ בְּבֵיתָא דְּכָל בַּר נָשׁ, וְלָא דָּחִיל. אֲמַאי. בְּגִין דְּכֹלָּא קָרָאן לֵיהּ דְּרוֹר. מַאי דְּרוֹר. חִירוּ, כְּמָה דְאַתְּ אָמֵר, (ויקרא כ״ה:י׳) וּקְרָאתֶם דְּרוֹר, וְתַרְגּוּמוֹ חִירוּ. וְדָא אִיהוּ צִפּוֹר דְּרוֹר. דְּהָא מִיּוֹמָא דְּעָבִיד קִנָּא בְּבֵיתָא אַפִּיק בְּנִין, מָדוֹרֵיהּ בְּבֵיתָא חַמְשִׁין יוֹמִין, וּלְבָתַר מִתְפָּרְשָׁן אִלֵּין מֵאִלֵּין, וְדָא הוּא עוֹפָא דְּאִקְרֵי דְּרוֹר: חִירוּ.</p>\n<p>תָּא חֲזֵי מַה כְּתִיב, וְקִדַּשְׁתֶּם אֵת שְׁנַת הַחֲמִשִּׁים שָׁנָה וּקְרָאתֶם דְּרוֹר בָּאָרֶץ. מֵהָכָא נָפְקָא חִירוּ לְכֹלָּא, וּבְגִין דְּנָפְקָא מִנֵּיהּ חִירוּ, אוֹרַיְיתָא דְּנַפְקַת מִנֵּיהּ אִקְרֵי חִירוּ. וְעַל דָּא כְּתִיב, (שמות ל״ב:ט״ז) חָרוּת עַל הַלֻּחֹת, אַל תִּקְרֵי חָרוּת, אֶלָּא חֵירוּת, וְדָא אוֹרַיְיתָא דְּאִתְקְרֵי חֵירוּת דְּהָא מָה דְּאַפִּיק יוֹמָא דָּא עִלָּאָה, אִקְרֵי חִירוּ, וְאִיהוּ חִירוּ דְּכֹלָּא. וְהַאי יוֹמָא אִיהוּ חִירוּ עִלָּאָה, בְּגִין דְּאִית חִירוּ תַּתָּאָה, וְחִירוּ עִלָּאָה. הֵ\"א עִלָּאָה, הֵ\"א תַּתָּאָה. חִירוּ עִלָּאָה. חִירוּ תַּתָּאָה שְׁמִטָּה וְיוֹבֵל כַּחֲדָא אִינּוּן.</p>"],[9520011811,"<p>תְּרֵין נַהֲמֵי אָכְלוּ יִשְׂרָאֵל, חַד, כַּד נָפְקוּ מִמִּצְרַיִם, אָכְלוּ מַצָּה, לֶחֶם עוֹנִי. וְחַד בְּמַדְבְּרָא, לֶחֶם מִן הַשָּׁמַיִם. (חד בפסח וחד בשבועות) דִּכְתִּיב, (שמות ט״ז:ד׳) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם וְעַל דָּא קָרְבָּנָא דְּיוֹמָא דָּא נָהֲמָא אִיהוּ. וְעַל נָהֲמָא, אִתְקְרִיבוּ כָּל שְׁאַר קָרְבָּנִין. דְּנָהֲמָא אִיהוּ עִקָר, דִּכְתִּיב, (ויקרא כ״ג:י״ח) וְהִקְרַבְתֶּם עַל הַלֶּחֶם שִׁבְעַת כְּבָשִׂים וְגוֹ', וּכְתִיב (ויקרא כ״ג:י״ז) מִמּוֹשְׁבוֹתֵיכֶם תָּבִיאוּ לֶחֶם תְּנוּפָה וְגוֹ', דְּדָא אִיהוּ נָהֲמָא דְּאֲחְכִּימוּ בֵּיהּ יִשְׂרָאֵל, חָכְמְתָא עִלָּאָה דְּאוֹרַיְיתָא, וְעָאלוּ בְּאָרְחָהָא.</p>\n<p>הַשְׁתָּא אִית לָן לְאִסְתַּכְּלָא, בַּפֶּסַח נָפְקוּ יִשְׂרָאֵל מִנָּהֲמָא דְּאִתְקְרֵי חָמֵץ, כְּתִיב, (שמות י״ג:ז׳) וְלָא יֵרָאֶה לְךָ חָמֵץ, וּכְתִיב (שמות י״ב:י״ט) כִּי כָּל אוֹכֵל מַחְמֶצֶת <Nonei></i>מַאי טַעֲמָא. בְּגִין יְקָרָא דְּהַהוּא נַהֲמָא דְּאִתְקְרֵי מַצָּה. הַשְׁתָּא דְּזָכוּ יִשְׂרָאֵל לְנַהֲמָא עִלָּאָה יַתִּיר לָא יֵאוֹת הֲוָה לְאִתְבַּטְּלָא חָמֵץ, וְלָא אִתְחַזְיָא כְּלַל. וַאֲמַאי קָרְבָּנָא דָּא, חָמֵץ הֲוָה, דִּכְתִּיב סֹלֶת תִּהְיֶינָה חָמֵץ תֵּאָפֶינָה. וְתוּ, דְּהַשְׁתָּא בְּיוֹמָא דָּא אִתְבָּטַּל יֵצֶר הָרָע, וְאוֹרַיְיתָא דְּאִתְקְרֵי חִירוּ אִשְׁתְּכַחַת.</p>\n<p>אֶלָּא, לְמַלְכָּא דְּהֲוָה לֵיהּ בַּר יְחִידָאי, וְחָלַשׁ. יוֹמָא חַד הֲוָה תָּאִיב לְמֵיכַל, אָמְרוּ יֵיכוּל בְּרֵיהּ דְּמַלְכָּא (ס\"א מיכלא דאסוותא דא) אַסְוָותָא דָּא, וְעַד דְּיֵיכוּל לֵיהּ, לָא יִשְׁתְּכַּח מֵיכְלָא וּמְזוֹנָא אַחֲרָא בְּבֵיתָא. עָבְדוּ הָכִי. כֵּיוָן דְּאָכַל הַהוּא אַסְוָותָא, אָמַר מִכָּאן וּלְהָלְאָה יֵיכוּל כָּל מָה דְּאִיהוּ תָּאִיב, וְלָא יָכִיל לְנַזְקָא לֵיהּ.</p>\n<p>כַּךָ כַּד נָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, לָא הֲוֵי יַדְעֵי עִקָרָא וְרָזָא דִּמְהֵימְנוּתָא, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, יִטְעֲמוּן יִשְׂרָאֵל אַסְוָותָא, וְעַד דְּיֵיכְלוּן אַסְוָותָא דָּא, לָא אִתְחָזֵי לְהוֹן מֵיכְלָא אַחֲרָא. כֵּיוָן דְּאָכְלוּ מַצָּה, דְּאִיהִי אַסְוָותָא לְמֵיעַל וּלְמִנְדַּע בְּרָזָא דִּמְהֵימְנוּתָא. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, מִכָּאן וּלְהָלְאָה אִתְחָזֵי לוֹן חָמֵץ, וְיֵיכְלוּן לֵיהּ, דְּהָא לָא יָכִיל לְנַזְקָא לוֹן. וְכָּל שֶׁכֵּן דִּבְיוֹמָא דְּשָׁבוּעוֹת, אִזְדָּמַן נַהֲמָא עִלָּאָה, דְּאִיהוּ אַסְוָותָא בְּכֹלָּא.</p>\n<p>וְעַל דָּא מְקָרְבִין חָמֵץ, לְאִתּוֹקְדָא עַל מַדְבְּחָא. וּמְקָרְבִין תְּרֵין נַהֲמִין אַחֲרָנִין כַּחֲדָא. וְחָמֵץ, אִתּוֹקְדָא בְּנוּרָא דְּמַדְבְּחָא וְלָא יָכִיל לְשַׁלְּטָאָה, וּלְנַזְקָּא לוֹן לְיִשְׂרָאֵל. וּבְגִינֵי כַּךְ, יִשְׂרָאֵל קַדִּישִׁין אִתְדָּבָקוּ בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, בְּאַסְוָותָא דְּאוֹרַיְיתָא בְּיוֹמָא דָּא. וְאִלְמָלֵי הֲווֹ נַטְרֵי יִשְׂרָאֵל תְּרֵין סִטְרִין דְּנַהֲמֵי אִלֵּין, לָא הֲווֹ עַיְילִין בְּדִינָא לְעָלְמִין.</p>\n<p>בְּיוֹמָא דְּרֹאשׁ הַשָּׁנָה, דְּאִיהוּ יוֹמָא דְּדִינָא, (בכל יומא) דְּלָאו אִיהוּ, אֶלָּא לְאִינּוּן דְּלָא נַטְלוּ מֵיכְלָא דְּאַסְוָותָא, וְשָׁבְקוּ לְאַסְוָותָא דְּאוֹרַיְיתָא, בְּגִין מֵיכְלָא אַחֲרָא דְּאִיהוּ חָמֵץ. דְּהָא בְּיוֹמָא דָּא דְּרֹאשׁ הַשָּׁנָה, הַהוּא חָמֵץ סַלְּקָא, וּמְקַטְרְגָא עָלֵיהּ דְּבַר נָשׁ, וְאַלְשִׁין עָלֵיהּ, וְאִיהוּ קַיְּימָא בְּיוֹמָא דָּא מְקַטְרְגָא עַל עָלְמָא. וְקוּדְשָׁא בְּרִיךְ הוּא יָתִיב בְּדִינָא עַל כֹּלָּא וְדָאִין עָלְמָא.</p>\n<p>וּבְגִינֵי כַּךְ כַּד יָהַב קוּדְשָׁא בְּרִיךְ הוּא אוֹרַיְיתָא לְיִשְׂרָאֵל, אֲטְעִים לְהוּ מֵהַהוּא נַהֲמָא עִלָּאָה, דְּהַהוּא אֲתָר, וּמִגּוֹ הַהוּא נַהֲמָא, הֲווֹ יַדְעִין וּמִסְתַּכְּלִין בְּרָזֵי דְּאוֹרַיְיתָא, לְמֵהַךְ בְּאֹרַח מֵישָׁר, וְהָא אוּקְמוּהָ מִלָּה אִינּוּן חַבְרַיָּיא בְּרָזִין (ס\"א אלין דקאמרן) אִלֵּין כִּדְקָאמְרָן.</p>\n<p>רִבִּי שִׁמְעוֹן וְרִבִּי אֶלְעָזָר בְּרֵיהּ, הֲווֹ אַזְלֵי בְּאָרְחָא, וַהֲווּ אַזְלִין עִמְּהוֹן, רִבִּי אַבָּא וְרִבִּי יוֹסֵי, עַד דַּהֲווֹ אַזְלֵי אִעֲרָעוּ בְּחַד סָבָא, וַהֲוָה אָחִיד בִּידֵיהּ חַד יַנּוּקָא, זָקַף עֵינוֹי רִבִּי שִׁמְעוֹן וְחָמָא לֵיהּ, אָמַר לֵיהּ לְרִבִּי אַבָּא וַדַּאי מִלִּין חַדְתִּין אִית גַּבָּן בְּהַאי סָבָא.</p>\n<p>כַּד מָטוּ לְגַבֵּיהּ, אָמַר רִבִּי שִׁמְעוֹן, בְּמָטוּל דְּקּוּפְטְרָךְ בְּגַבָּךְ קָא אָתִית, מַאן אַנְתְּ. אָמַר לֵיהּ, יוּדָאי אֲנָא. אָמַר, מִלִּין חַדְתִּין וַדַּאי יוֹמָא דָּא לְגַבָּךְ, אָמַר לֵיהּ לְאָן הוּא אַרְעָךְ. אָמַר לֵיהּ, דִּיוּרִי הֲוָה בְּאִינּוּן פְּרִישֵׁי מַדְבְּרָא, דַּהֲוֵינָא, מִשְׁתָּדַּל בְּאוֹרַיְיתָא, וְהַשְׁתָּא אֲתֵינָא לְיִשׁוּבָא, לְמֵיתַב בְּצִלָּא דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּאִלֵּין יוֹמֵי דְּיַרְחָא שְׁבִיעָאָה דָּא.</p>\n<p>חַדֵּי רִבִּי שִׁמְעוֹן, אָמַר, נֵתִיב, דְּוַדַּאי קוּדְשָׁא בְּרִיךְ הוּא שַׁדְרָךְ לְגַבָּן. אָמַר לֵיהּ, חַיֶּיךָ דְּנִשְׁמַע מִלָּה מִפּוּמָךְ, מֵאִינּוּן מִלִּין חַדְתִּין עַתִּיקִין, דִּנְטַעְתּוּן תַּמָּן בְּמַדְבְּרָא, מֵהַאי יַרְחָא שְׁבִיעָאָה. וַאֲמַאי אִתְפְּרַשְׁתּוּן הַשְׁתָּא מִמַּדְבְּרָא, לְמֵיתֵי לְיִשׁוּבָא. אָמַר לֵיהּ הַהוּא סָבָא, בִּשְׁאֶלְתָּא דָּא, יְדַעְנָא דְּחָכְמְתָא גַּבָּךְ, וּמִילָּךְ מָטוּ לִרְקִיעֵי דְּחָכְמְתָא. (ס\"א נטו לתקיעו דחכמתא)</p>"],[9520011812,"<p>פָּתַח הַהוּא סָבָא וְאָמַר, (דברים א׳:ל״א) וּבַמִּדְבָּר אֲשֶׁר רָאִיתָ אֲשֶׁר נְשָׂאֲךָ יְיָ' אֱלֹהֶיךָ כַּאֲשֶׁר יִשָּׂא אִישׁ אֶת בְּנוֹ וְגוֹ'. הַאי קְרָא הָכִי מִבָּעֵי לֵיהּ, וּבַמִּדְבָּר אֲשֶׁר נְשָׂאֲךָ, מַהוּ רָאִיתָ. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא דָּבַר לוֹן לְיִשְׂרָאֵל בְּמַדְבְּרָא, מַדְבְּרָא תַּקִּיפָא, כְּמָה דִּכְתִּיב, (דברים ח׳:ט״ו) נָחָשׁ שָׂרָף וְעַקְרָב וְגוֹ'. וּמַדְבְּרָא דְּאִיהוּ תַּקִּיף מִשְּׁאַר מַדְבְרִין בְּעָלְמָא. מַאי טַעֲמָא.</p>\n<p>בְּגִין דְּהַהוּא שַׁעֲתָא דְּנָפְקוּ <Nonei></i>יִשְׂרָאֵל מִמִּצְרַיִם וְאִשְׁתְּלִימוּ לְשִׁתִּין רִבְּבָן, אִתְתָּקַּף מַלְכוּתָא קַדִּישָׁא, וְאִסְתַּלָּק עַל כֹּלָּא, וְסִיהֲרָא אִתְנְהִירַת וּכְדֵין אִתְכַּפְיָא מַלְכוּ חַיָּיבָא סִטְרָא אַחֲרָא. וְאַפִּיק לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְמֵיהַךְ בְּמַדְבְּרָא תַּקִּיפָא. דְּאִיהוּ אֲתָר וְשֻלְטָנוּ דְּסָמָאֵ\"ל חַיָּיבָא, דְּאִיהוּ דִּילֵיהּ מַמָּשׁ, בְּגִין לְתַּבְרָא תּוּקְפֵּיהּ וְחֵילֵיהּ, וּלְכַתְּתָא רֵישֵׁיהּ, (ס\"א ולאחתא ליה) וּלְאַכְפְּיָא לֵיהּ, דְּלָא יִשְׁלוֹט. וְאִלְמָלֵא דְּחָאבוּ יִשְׂרָאֵל, בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַעְבְּרָא לֵיהּ מֵעָלְמָא, וְעַל דָּא אַעְבַּר לוֹן בְּאַחֲסַנְתֵּיהּ וְעַדְבֵיהּ וְחוּלָקֵיהּ מַמָּשׁ.</p>\n<p>כֵּיוָן דְּחָאבוּ בְּכַמָּה זִמְנִין, נָשִׁיךְ לוֹן חִוְיָא, וּכְדֵין אִתְקְיָּים (בראשית ג׳:ט״ו) הוּא יְשׁוּפְךָ רֹאשׁ וְגוֹ'. יִשְׂרָאֵל מָחוּ רֵישֵׁיהּ בְּקַדְמִיתָא, וְלָא יַדְעֵי לְאִסְתַּמְּרָא מִינֵּיהּ, וּלְבָתַר אִיהוּ מָחָא בְּבַתְרַיְיתָּא, וְנָפְלוּ כֻּלְּהוּ בְּמַדְבְּרָא, וְאִתְקָיָּים וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. וְאַרְבְּעִין שְׁנִין לָקוּ מִנֵּיהּ, לָקֳבֵל מ' מַלְקוּת דְּבֵי דִּינָא.</p>\n<p>וְעַל דָּא כְּתִיב אֲשֶׁר רָאִיתָ, בְּעֵינַיְיהוּ הֲוֹי חֲמָאן לְהַהוּא מָארֵי דְּמַדְבְּרָא, אָזִיל כָּפִית קָמַיְיהוּ, וְנַטְלֵי אַחַסַנְתֵּיהּ וְעַדְבֵיהּ. מְנָּלָן. מִדִּכְתִּיב (שמות ט״ו:ט״ו) אָז נִבְהֲלוּ אַלּוּפֵי אֱדוֹם, וְאִלֵּין אִינּוּן (דברים ח׳:ט״ו) נָחָשׁ שָׂרָף וְעַקְרָב. וַאֲנָן אוּף הָכִי אִתְפְּרַשְׁנָא מִיִשׁוּבָא לְמַדְבְּרָא תַּקִּיפָא, וּלְעַיְינָא תַּמָּן בְּאוֹרַיְיתָא, בְּגִין לְאַכְפְּיָא לְהַהוּא סִטְרָא.</p>\n<p>וְתוּ דְּלָא מִתְיַשְּׁבָן מִלֵּי דְּאוֹרַיְיתָא, אֶלָּא תַּמָּן. דְּלֵית נְהוֹרָא אֶלָּא הַהוּא דְּנָפִיק מִגּוֹ חֲשׁוֹכָא, דְּכַד אִתְכַּפְיָא סִטְרָא דָּא, אִסְתַּלָּק קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָּא, וְאִתְיָיקָּר בִּיקָרֵיהּ. וְלֵית פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא מִגּוֹ חֲשׁוֹכָא, וְלֵית טוּבָא אֶלָּא מִגּוֹ בִּישָׁא. וְכַד עָאל בַּר נָשׁ בְּאוֹרַח בִּישָׁא, וְשָׁבִיק לֵיהּ, כְּדֵין אִסְתַּלָּק קוּדְשָׁא בְּרִיךְ הוּא בִּיקָרֵיהּ, וְעַל דָּא שְׁלִימוּ דְּכֹלָּא טוֹב וָרָע כַּחֲדָא, וּלְאִסְתַּלְּקָא לְבָתַר בְּטוֹב, וְלֵית טוֹב אֶלָּא הַהוּא דְּנָפַק מִגּוֹ בִּישָׁא. וּבְהַאי טוֹב, אִסְתַּלָּק יְקָרֵיהּ, וְדָא אִיהוּ פּוּלְחָנָא שְׁלִים.</p>\n<p>וַאֲנָן, עַד הַשְׁתָּא יָתִיבְנָא תַּמָּן, כָּל יוֹמֵי שַׁתָּא, בְּגִין לְאַכְפְּיָא בְּמַדְבְּרָא לְהַהוּא סִטְרָא. הַשְּׁתָּא דְּמָטָא זִמְנָא דְּפוּלְחָנָא קַדִּישָׁא, דְּסִטְרָא דִּקְדוּשָׁא, אַהֲדַרְנָא לְיִשׁוּבָא דְּתַמָּן אִיהוּ פּוּלְחָנָא דִּילֵיהּ. וְתוּ, דְּהַשְׁתָּא בְּרֹאשׁ הַשָּׁנָה מָטָא זִמְנָא דְּהַהוּא חִוְיָא, לְמִתְבַּע דִּינָא מִקָּמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְתַמָּן אִיהוּ שַׁלִּיט. וּבְגִין כַּךְ נָפַקְנָא מִתַּמָּן וַאֲתֵינָא לְיִשׁוּבָא.</p>"],[9520011813,"<p>פָּתַח הַהוּא סָבָא וְאָמַר, (תהילים פ״א:ד׳) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ, הַשְׁתָּא אִיהוּ זִמְנָא, לְאִתְּעָרָא דִּינָא עִלָּאָה תַּקִּיפָא, וְכַד אִיהוּ אִתְּעַר סִטְרָא אַחֲרָא אִתְתָּקַּף בַּהֲדֵיהּ, וְכֵיוָן דְּאִיהוּ אִתְתָּקַּף, סָלִיק וְחַפְיָא לְסִיהֲרָא, דְּלָא נָהִיר נְהוֹרָא, וְאִתְמַלְיָא מִסִּטְרָא דְּדִינָא. כְּדֵין כָּל עָלְמָא אִיהוּ בְּדִינָא, עִלָּאִין וְתַתָּאִין, וְכָרוֹזָא כָּרִיז בְּכֻלְּהוּ רְקִיעִין, אַתְקִינוּ כּוּרְסְיָא דְּדִינָא, לְמָארֵיהּ דְּכֹלָּא, דְּאִיהוּ בָּעֵי לְמֵידָן.</p>\n<p>וְרָזָא הָכָא, וְאִתְנְהִיר לָן בְּמַדְבְּרָא, אֲמַאי אִתְּעַר דִּינָא עִלָּאָה בְּיוֹמָא דָּא. אֶלָּא כָּל רָזִין וְכָל קִדוּשִׁין יַקִירִין, כֻּלְּהוּ תַּלְיָין בִּשְׁבִיעָאָה. וְהַהוּא שְׁבִיעָאָה עִלָּאָה, עָלְמָא עִלָּאָה, דְּאִקְרֵי עָלְמָא דְּאָתֵי. מִנֵּיהּ נַהֲרִין כָּל בּוּצִינִין, וְכָל קִדוּשִׁין, וְכָל בִּרְכָּאן. וְכַד מָטֵי זִמְנָא, לְחַדְתּוּתֵי בִּרְכָּאן וְקִדּוּשִׁין לְאַנְהֲרָא, בָּעָא לְאַשְׁגָּחָא בְכָל תִּקּוּנָא דְּעָלְמִין כֻּלְּהוּ, וְכָל אִינּוּן תִּקּוּנִים לְאִתְקַיְּימָא כֻּלְּהוֹן, סַלְּקִין מִגּוֹ תַּתָּאֵי, אִי אִינּוּן כַּשְׁרָאן. וְאִי לָא כַּשְׁרָאן, כְּדֵין קַיְּימָא (ס\"א מלה) דְּלָא נָהִיר, עַד דְּאִתְפָּרְשָׁן חַיָּיבִין מִגּוֹ זַכָּאִין, כְּדֵין אִתְּעַר דִּינָא.</p>\n<p>וּמֵהַהוּא דִּינָא, אִתְתָּקַּף סִטְרָא אַחֲרָא, וְאִשְׁתְּכַח מְקַטְרְגָא, בְּגִין דְּיִנָתְנוּן לֵיהּ אִינּוּן, חַיָּיבַיָּא. בְּגִין דְּעָלֵיהּ כְּתִיב, (איוב כ״ח:ג׳) וּלְכָל תַּכְלִית הוּא חוֹקֵר. וְחַפְיָא לְסִיהֲרָא, אֲמַאי (ד\"א לא מסרא לון בידא דמקטרגא.) בְּגִין דְּלֵית תִּיאוּבְתֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, לְאוֹבָדָא לְעוֹבָדֵי יְדוֹי.</p>\n<p>וְהַהוּא סִטְרָא אַחֲרָא, קַיְּימָא קְלִיפָא תַּקִּיפָא, דְּלָא יָכִיל לְאִתָּבְּרָא, בַּר בְּהַהוּא עֵיטָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָהִיב לְיִשְׂרָאֵל, דִּכְתִּיב תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. בְּגִין לְתַּבְרָא הַהוּא כִּסֵּה דְּאִתְחֲפְיָא סִיהֲרָא, וְלָא נָהִיר.</p>\n<p>וְכַד מִתְּעֲרֵי יִשְׂרָאֵל לְתַתָּא בְּשׁוֹפָר, הַהוּא קַלָּא דְּנָפִיק מִשּׁוֹפָר, בָּטַשׁ בַּאֲוִירָא, וּבָקַע רְקִיעִין, עַד דְּסַלְּקָא לְגַבֵּי הַהוּא טִנָרָא תַּקִּיפָא, (נ\"א סטרא אחרא) דְּחָפֵי לְסִיהֲרָא, אַשְׁגַּח, וְאַשְׁכַּח אִתְעֲרוּתָא דְּרַחֲמֵי, כְּדֵין הַהוּא <Nonei></i>דְּסָלִיק וְקַיְּימָא לְעֵילָּא, אִתְעַרְבָב. כְּדֵין הַהוּא קַלָּא קַיְּימָא, וְאַעְבַּר הַהוּא דִּינָא, וְכֵיוָן דִּלְתַתָּא אַתְּעָרוּ רַחֲמֵי, הָכִי נָמֵי לְעֵילָּא, אִתְּעַר שׁוֹפְרָא אַחֲרָא עִלָּאָה, וְאַפִּיק קָלָא דְּאִיהוּ רַחֲמֵי, וְאַתְעָרְעוּ קָלָא בְּקָלָא, רַחֲמֵי בְּרַחֲמֵי, וּבְאִתְעָרוּתָא דִּלְתַתָּא, אִתְּעַר הָכִי נָמֵי לְעֵילָּא.</p>\n<p>וְאִי תֵּימָא, הֵיךְ יָכִיל קָלָא דִּלְתַתָּא, אוֹ אִתְּעָרוּתָא דִּלְתַתָּא לְאַתְעֲרָא, הָכִי נָמֵי. תָּא חֲזֵי, עָלְמָא תַּתָּאָה, קַיְּימָא לְקַבְּלָא תָּדִיר, וְהוּא אִקְרֵי אֶבֶן טָבָא. וְעָלְמָא עִלָּאָה לָא יָהִיב לֵיהּ, אֶלָּא כְּגַוְונָא דְּאִיהוּ קַיְּימָא. אִי אִיהוּ קַיְּימָא בִּנְהִירוּ דְּאַנְפִּין מִתַּתָּא, כְּדֵין הָכִי נַהֲרִין לֵיהּ מִלְעֵילָּא. וְאִי אִיהוּ קַיְּימָא בַּעֲצִיבוּ, יַהֲבִין לֵיהּ דִּינָא בְּקָבְלֵיהּ.</p>\n<p>כְּגַוְונָא דָּא, (תהילים ק׳:ב׳) עִבְדוּ אֶת יְיָ' בְּשִׂמְחָה. חֶדְוָה דְּבַּר נָשׁ, מָשִׁיךְ לְגַבֵּיהּ חֶדְוָה אַחֲרָא עִלָּאָה. הָכִי נָמֵי הַאי עָלְמָא תַּתָּאָה, כְּגַוְונָא דְּאִיהִי אִתְעַטְּרָת, הָכִי אַמְשִׁיךְ מִלְעֵילָּא. בְּגִין כָּךְ מְקַדְּמֵי יִשְׂרָאֵל, וְאַתְעֲרֵי בַּשּׁוֹפָר קָלָא דְּאִיהוּ (רזא דרחמי) כָּלִיל בְּאֶשָּׁא וּמַיָא וְרוּחָא, וְאִתְעָבִיד חַד, וְסַלְּקָא לְעֵילָּא, וּבָטַשׁ בְּהַאי אֶבֶן טָבָא, וְאִצְטְבַּע בְּאִינּוּן גַּוְונִין דְּהַאי קָלָא, וּכְדֵין כְּמָה דְּאִתְחַזִיאָת, הָכִי מָשִׁיךְ מִלְּעֵילָּא.</p>\n<p>וְכֵיוָן דְּאִתַּקְנַת בְּהַאי קָלָּא. רַחֲמֵי נַפְקֵי מִלְּעֵילָּא, וְשַׁרְיָין עָלָהּ, וְאִתְכְּלִילָא בְּרַחֲמֵי, מִתַּתָּא וּמִלְּעֵילָּא. וּכְדֵין אִתְעַרְבָּב סִטְרָא אַחֲרָא. (אסתכל וחמי בנהירו דאנפין) וְאִתְחַלָּשׁ תֻּקְפֵּיהּ, וְלָא יָכִיל לְקַטְרְגָא. וְהַאי אֶבֶן טָבָא, קַיְּימָא בִּנְהִירוּ דְּאַנְפִּין, מִכָּל סִטְרִין, בִּנְהִירוּ דִּלְתַתָּא, וּבִנְהִירוּ דִּלְעֵילָּא.</p>\n<p>אֵימָתַי קַיְּימָא בִּנְהִירוּ דִּלְעֵילָּא, הֲוֵי אוֹמֵר בְּיוֹמָא דְּכִפּוּרֵי. וּבְיוֹמָא דְּכִפּוּרֵי אִתְנְהִיר הַהוּא אֶבֶן טָבָא, בִּנְהִירוּ דִּלְעֵילָּא, מִגּוֹ נְהִירוּ דְּעָלְמָא דְּאָתֵי, (ואתערבב ההוא דלטורא) וּכְדֵין מְתַקְּנִין יִשְׂרָאֵל לְתַתָּא חַד שָׂעִיר, וּמְשַׁדְּרִין לְהַאי מַדְבְּרָא תַּקִּיפָא, דְּאִיהוּ שַׁלְטָא עָלֵיהּ.</p>"],[9520011814,"<p>וְהַהוּא סִטְרָא אַחֲרָא, אִיהוּ נְקוּדָה אֶמְצָעִיתָא דְּחָרִיבוּ דְּעָלְמָא, בְּגִין דְּכָל חָרִיבוּ וְשִׁמָמוֹן (ס\"א מניה, הוא מההוא סטרא אחרא דשליט) מִנֵיהּ, הַהוּא סִטְרָא אַחֲרָא שַׁלִּיט עָלֵיהּ. וּנְקוּדָה אֶמְצָעִיתָא דְּכָל יִשּׁוּבָא, סִטְרָא דִּקְדוּשָּׁה אִיהוּ, וְעַל דָּא, קַיְּימָא יְרוּשָׁלַ ם בְּאֶמְצָעִיתָא דְּכָל יִשּׁוּבָא דְּעָלְמָא.</p>\n<p>בִּתְרֵין נְקוּדִין אִתְפְּרָשַׁת מָלְכוּ שְׁמַיָא, סִטְרָא דִּקְדוּשָּׁא, חַד דִּילָהּ, וְחַד דְּעָלְמָא דְּאָתֵי, נְקוּדָה עִלָּאָה טְמִירָאָה, וְעַל דָּא קַיְּימָא בִּתְרֵין נְקוּדִין: נְקוּדָה דִּילָהּ קַיְּימָא תְּחוֹתָהּ, יְרוּשָׁלַ ם, אֶמְצָעִיתָא דְּכָל יִשּׁוּבָא. נְקוּדָא דְּנַטְלָא מֵאִימָא עִלָּאָה טְמִירָא, (רי\"ט ע\"ב, רפ\"א ע\"ב) אִיהוּ גַּן עֵדֶן דְּאַרְעָא, דְּקַיְּימָא בְּאֶמְצָעִיתָא דְּכָל עָלְמָא, לְכָל סִטְרִין, דְּחָרִיבוּ וְיִשׁוּבָא, וְכָל סִטְרִין דְּעָלְמָא.</p>\n<p>וְעַל דָּא, בְּאֶמְצָעִיתָא (קל\"ב ע\"ב) דְּגַן עֵדֶן, קַיְּימָא נְקוּדָה חֲדָא עִלָּאָה טְמִירָא וּגְנִיזָא, דְּלָא יְדִיעַ. וְחַד עַמּוּדָא, נָעִיץ מִתַּתָּא לְעֵילָּא, גּוֹ הַהִיא נְקוּדָה, וּמִתַּמָּן נַבְעֵי מַיָּא, דְּאִתְפְּרִישׁוּ לְאַרְבַּע סִטְרֵי עָלְמָא. אִשְׁתְּכָחוּ תְּלַת נְקוּדִין בְּעָלְמָא, דְּקַיְימָאן דָּא עַל דָּא, כְּגַוְונָא דִּתְלַת נְקוּדִין דְּאוֹרַיְיתָא.</p>"],[9520011815,"<p>תָּא חֲזֵי, הַהוּא שָׂעִיר דִּמְשַׁדְּרִין יִשְׂרָאֵל לַעֲזָאזֵל, לְהַהוּא מַדְבְּרָא, בְּגִין לְמֵיהַב חוּלָקָא לְהַהוּא סִטְרָא אַחֲרָא, לְאִתְעַסְּקָא בַּהֲדֵיהּ. וְאִי תֵּימָא, תְּרֵין שְׂעִירִין אֲמַאי הָכָא, חַד לַיְיָ' וְחַד לְהַהוּא סִטְרָא אַחֲרָא. תִּינַח הַהוּא שָׂעִיר דְּסִטְרָא אַחֲרָא. לַיְיָ' אֲמַאי.</p>\n<p>אֶלָּא לְמַלְכָּא דְּהֲוָה אַרְגִּיז עַל בְּרֵיהּ, קָרָא לְסַנְטִירָא, הַהוּא דְּעָבִיד דִּינָא בִּבְנֵי נָשָׁא תָּדִיר, בְּגִין דְּיִזְדָּמַּן לְמֶעְבַּד דִּינָא בִּבְרֵיהּ. הַהוּא סַנְטִירָא חַדֵּי, וְעָאל בְּבֵי מַלְכָּא לְמֵיכַל תַּמָּן, כֵּיוָן דְּאַשְׁגַּח בֵּיהּ בְּרֵיהּ, אָמַר, וַדַּאי לָא עָאל סַנְטִירָא דָּא בְּבֵי אַבָּא, אֶלָּא בְּגִין דְּאַרְגִּיז מַלְכָּא עָלַי. מָה עָבֵד, אָזַל וְאִתְפְּיָיס בַּהֲדֵיהּ. כֵּיוָן דְּאִתְפָּיַיס בַּהֲדֵיהּ, פָּקִיד מַלְכָּא לְמֶעְבַּד סְעוּדָתָא עִלָּאָה לֵיהּ וְלִבְרִיהּ, וּפָקִיד דְּלָא יָדַע בֵּיהּ הַהוּא סַנְטִירָא. לְבָתַר עָאל הַהוּא סַנְטִירָא. אָמַר מַלְכָּא הַשְׁתָּא אִי יִנְדַּע דָּא, מִסְּעוּדָתָא עִלָּאָה <Nonei></i>דְּאַתְקִינִית לִי וְלִבְרִי, יִתְעַרְבֵּב פָּתוֹרָא. מָה עֲבַד. קָרָא לַמְּמָנָא עַל סְעוּדָתָא, אָמַר לֵיהּ, אַתְקִין מִדִי, וּתְשָׁוֵי קַמָּאי, וּתְשָׁוֵי קַמֵּיהּ דְּהַהוּא סַנְטִירָא, בְּגִין דְּיַחְשִׁיב דְּסָעִיד קַמָּאי מִדִּילִי, וְלָא יִנְדַּע בְּהַהִיא סְעוּדָתָא יַקִּירָא דְּחֶדְוָה דִּילִי וְדִבְרִי, וְיִטּוֹל הַהוּא חוּלָקָא וְיֵזִיל לֵיהּ, וְיִתְפְּרַשׁ מִחֶדְוָה דִּסְעוּדָתָא דִּילָן. וְאִי לָאו דְּמַלְכָּא עָבִיד הָכִי, לָא יִתְפְּרַשׁ הַהוּא סַנְטִירָא מִבֵּי מַלְכָּא.</p>\n<p>כַּךָ אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, אַזְמִינוּ תְּרֵין שְׂעִירִין, חַד לִי וְחַד לְהַהוּא דַּלְטוֹרָא, בְּגִין דְּיַחְשִׁיב דְּמִסְּעוּדָתָא דִּילִי קָאֲכִיל, וְלָא יִנְדַּע בִּסְעוּדָתָא דְּחֶדְוָה אַחֲרָא דִּילָן, וְיִסַּב הַהוּא חוּלָקָא, וְיֵזִיל לְאָרְחֵיהּ, וְיִתְפְּרַשׁ מִבֵּיתִי. כֵּיוָן דְּאִמָא עִלָּאָה, עָלְמָא דְּאָתֵי, אָתֵי לְמִשְׁרֵי (ק' ע\"ב) גּוֹ הֵיכְלָא דְּעָלְמָא תַּתָּאָה, לְאַשְׁכְּחָא נְהִירוּ (נ\"א לאשגחא עלה בנהירו) דְּאַנְפִּין, דִּין הוּא דְּלָא יִשְׁתְּכַּח הַהוּא דַּלְטוֹרָא, וְלָא מָארֵי דְּדִינִין לְקַמֵּיהּ, כַּד אַפִּיק כָּל בִּרְכָאן, וְאַנְהִיר לְכֹלָּא. וְכָל הַהוּא חִירוּ יִשְׁתְּכַּח, וְיִשְׂרָאֵל נַטְלֵי מֵאִינּוּן בִּרְכָאן.</p>\n<p>דְּהָא כַּד עָלְמָא דְּאָתֵי, עָאל לְהֵיכָלָא דְּעָלְמָא תַּתָּאָה, וְאַשְׁכַּח דְּחַדֵּי עָלְמָא תַּתָּאָה עִם בְּנוֹי בְּהַהִיא סְעוּדָתָא עִלָּאָה, כְּדֵין אִיהוּ בָּרִיךְ פַּתוֹרָא, וְעָלְמִין כֻּלְּהוּ מִתְבָּרְכִין, וְכָל חִידוּ וְכָל נְהִירוּ דְּאַנְפִּין אִשְׁתְּכָחוּ תַּמָּן. הֲדָא הוּא דִכְתִיב, (ויקרא טז) לִפְנֵי יְיָ' תִּטְהָרוּ. (ק' ע\"ב)</p>\n<p>כְּתִיב (ויקרא ט״ז:ח׳) וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִים גּוֹרָלוֹת גּוֹרָל אֶחָד לַיְיָ' וְגוֹרָל אֶחָד לַעֲזָאזֵל. דָּא אִיהוּ הַהוּא חֶדְוָה דְּהַהוּא דַּלְטוֹרָא, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא יָטִיל עִמֵּיהּ גּוֹרָל, וְזַמִּין לֵיהּ, וְלָא יָדַע דְּנוּר דָּלִיק אַטִּיל עַל רֵישֵׁיהּ, וְעַל עַמָּא דִּילֵיהּ, כְּמָה דְאַתְּ אָמֵר (משלי כ״ה:כ״ב) כִּי גֶחָלִים אַתָּה חוֹתֶה עַל רֹאשׁוֹ.</p>\n<p>וְסִימָנִךָ, (אסתר ה׳:י״ב) אַף לֹא הֵבִיאָה אֶסְתֵּר הַמַלְכָּה עִם הַמֶּלֶךְ אֶל הַמִשְׁתֶּה אֲשֶׁר עָשָׂתָה כִּי אִם אוֹתִי. וּכְתִיב, וַיֵּצֵא הָמָן בַּיּוֹם הַהוּא שָׂמֵחַ וְטוֹב לֵב. בְּהַהוּא חוּלָקָא דְּנָטִיל, וְאָזִיל לֵיהּ. וּלְבָתַר כַּד אָתֵי מַלְכָּא עִלָּאָה, לְבֵי מַטְרוֹנִיתָא, מַטְרוֹנִיתָא תַּבְעַת עָלָהָא, וְעַל בְּנָהָא, וְעַל עַמָּא מִן מַלְכָּא.</p>\n<p>וַאֲפִילּוּ בְּזִמְנָא דְּיִשְׂרָאֵל בְּגָלוּתָא, וְצַלּוּ צְלוֹתִין בְּכָל יוֹמָא, אִיהִי סַלְקַת בְּיוֹמָא דָּא, לְקָמֵי מַלְכָּא עִלָּאָה, וְתַבְעַת עַל בְּנָהָא. וּכְדֵין אִתְגְּזָרוּ, כָּל אִינּוּן נוּקְמִין, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד עִם אֱדוֹם, וְאִתְגְּזַר הֵיךְ זַמִין דַּלְטוֹרָא דָּא לְאִתְעַבְּרָא מֵעָלְמָא, כְּמָה דְאַתְּ אָמֵר (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוֶת לָנֶצַח.</p>\n<p>וְסִימָנִךָ, בְּזִמְנָא דְּגָלוּתָא (אסתר ז׳:ד׳) כִּי נִמְכַּרְנוּ אֲנִי וְגוֹ'. כִּי אֵין הַצָּר שׁוֶֹה בְּנֶזֶק הַמֶּלֶךְ. מַאי בְּנְזֶק הַמֶּלֶךְ. כְּמָה דְאַתְּ אָמֵר, (יהושע ז׳:ט׳) וְהִכְרִיתוּ אֶת שְׁמֵנוּ מִן הָאָרֶץ וּמַה תַּעֲשֵׂה לְשִׁמְךָ הַגָּדוֹל. דְּהָא שְׁמָא עִלָּאָה, לָא אִתְקָיָּים בְּקִיּוּמֵיהּ, וְדָא אִיהוּ בְּנֶזֶק הַמֶּלֶךְ.</p>\n<p>וּכְדֵין וְהָמָן נִבְעָת מִלִּפְנֵי הַמֶּלֶךְ וְהַמַּלְכָּה כְּדֵין, נְהִירוּ דְּאַנְפִּין, וְכָל חִידוּ אִשְׁתְּכַח, וְיִשְׂרָאֵל נַפְקֵי לְחִירוּ, בְּהַהוּא יוֹמָא. כְּדֵין מֵהַהוּא יוֹמָא וּלְהָלְאָה, חִירוּ וְחֶדְוָה בְּאִתְגַּלְּיָא, לְשַׁלְּטָאָה עָלַיְיהוּ, כְּדֵין בָּעֵי לְמֵחדֵי עִמְּהוֹן, מִכָּאן וּלְהָלְאָה, כְּמָה דְּיָהֲבוּ לֵיהּ חוּלָקָא לְאִתְפָּרְשָׁא מִנְהוֹן, הָכִי נָמֵי יַהֲבִין לִשְׁאַר עַמִּין, לְאִתְפָּרְשָׁא מִנְּהוֹן לְתַתָּא.</p>\n<p>תָּא חֲזֵי, מָה הוּא רָזָא דְּקָרְבְּנָא, לְקָרְבָא שָׂעִיר, (לקבל שעיר) וְלָא מִלָּה אַחֲרָא. וַאֲמַאי שָׂעִיר בְּרֹאשׁ חֹדֶשׁ, וְהָכָא נָמֵי שָׂעִיר. אֶלָּא אִי תֵּימָא בְּגִין דְּאִיהוּ סִטְרָא דִּילֵיהּ יֵאוֹת. אֲמַאי לָא הֲוִי עֵז.</p>\n<p>אֶלָּא מִלָּה דָּא אִצְטְרִיךְ, וְאִיהִי אִשְׁתְּכָחַת לְמָארֵיהוֹן דְּחָרָשִׁין, דְּכָל עוֹבָדַיְיהוּ בְּמָה דְּלָא (אתחבר) יְהֵא בְּנוּקְבָּא. וְעַל דָּא שָׂעִיר לָא אִתְחַבָּר בְּנוּקְבָּא, בְּסִטְרִין דִּילֵיהּ כֻּלְּהוּ. עֵז כַּד אִתְחַבָּר בְּנוּקְבָּא. וּבְגִין דְּאִיהוּ מַלְכָּא, יַהֲבִין לֵיהּ בְּגִין יְקָרָא דִּילֵיהּ, הַאי דְּלָא אִתְחַבָּר בְּנוּקְבָּא, וְלָא יָהִיב חֵילֵיהּ לְאַחֲרָא. וְדָא אִשְׁתְּמוֹדָע לְאִינּוּן חָרָשִׁין, דְּמִשְׁתַּמְּשִׁין בְּהָנֵי עוֹבָדֵי. וּבְגִינֵי כַּךְ, שַׁרְיָין עַל הַהוּא שָׂעִיר, כָּל אִינּוּן חֲטָאֵיהוֹן.</p>\n<p>וְתָּא חֲזֵי, אַף עַל גַּב דְּאִיהוּ חוּלָקָא לְהַהוּא סִטְרָא אַחֲרָא, רָזָא הָכָא, כָּל הָנֵי סִטְרִין אַחֲרָנִין דִּלְתַתָּא, (דאקרון מצולות ים) כֻּלְּהוּ מִסְאֲבִין יַתִּיר. וְכָל מַה דְּנַחְתִּין דַּרְגִּין תַּתָּאִין, הָכִי מִסְאֲבוּ דִּלְהוֹן יַתִּיר. וּבְגִין כַּךְ, בָּעֵז יַתִּיר חוּלָקֵיהוֹן, בְּגִין דְּשַׂעֲרָא <Nonei></i>דִּילֵיהּ תַּלְיָא יַתִּיר מִבְּעִירָא אַחֲרָא, כְּמָה דְּדִינָא דִּלְהוֹן תָּלֵי לְתַתָּא בִּמְסָאֲבוּ. אֲבָל הַאי מַלְכּוּ חַיָּיבְתָא אַחֲרָא, מַלְכָּא דְּכֹלָּא בְּהַהוּא סִטְרָא, בָּרוּר אִיהוּ יַתִּיר מִסְאֲבוּ דִּילֵיהּ, וְלָא מִסְאֲבוּ שְׁלִים כְּהָנֵי תַּתָּאֵי. וְעַל דָּא שָׂעִיר, דִּשְׂעַר דִּילֵיהּ לָא תַּלְיָא, וְלָא שְׁעִיעַ. לָא שְׁעִיעַ, בְּגִין דְּהַהוּא מִסְאֲבוּ דִּילֵיהּ. וְלָא תַּלְיָא, בְּגִין דְּלָא יִתְתָּקַף בֵּיהּ מִסְאֲבוּ כְּהָנִי תַּתָּאֵי, וְעַל דָּא וַדַּאי שָׂעִיר וְלָא אַחֲרָא.</p>\n<p>כִּפּוּר, אֲמַאי אִקְרֵי כִּפּוּר, אֶלָּא בְּגִין דְּנָקִי כָּל מְסָאֲבוּ, וְאַעְבַּר לֵיהּ מִקַּמֵיהּ, בְּהַהוּא יוֹמָא. וְעַל דָּא, יוֹם כִּפּוּר: יוֹמָא דִּנְקִיוּתָא, וְהָכִי קָרֵינָא לֵיהּ. כְּתִיב (ויקרא ט״ז:ל׳) כִּי בַיוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם לְטַהֵר אֶתְכֶם, כִּי הַיּוֹם הַזֶּה מִבָּעֵי לֵיהּ, מַאי כִּי בַיוֹם הַזֶּה. אֶלָּא בְּגִין דְּאִתְדָכֵּי מַקְדְּשָׁא לְעֵילָּא, אִתְנַקֵי (נ\"א ואתנהיר') כְּתִיב כִּי בַיוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם, יְכַפֵּר וִינָקֵי בְּקַדְמִיתָא בַּיוֹם הַזֶּה, בְּגִין דְּיִתְדָּכֵי, וּלְבָתַר עֲלֵיכֶם.</p>\n<p>תּוּ, יְכַפֵּר בַּיוֹם הַזֶּה, וִינָקֵי לֵיהּ בְּקַדְמִיתָא, וְכָל דָּא עֲלֵיכֶם, בְּגִינֵכוֹן אִצְטְרִיךְ לְנַקָּאָה לֵיהּ, וּלְדַכְּאָה לֵיהּ בְּקַדְמִיתָא. יְכַפֵּר, מַאן יְכַפֵּר. אֶלָּא דָּא הוּא עָלְמָא עִלָּאָה, דְּנָהִיר וְנָקֵי לְכֹלָּא. וְעַל דָּא כֻּלְּהוּ סִטְרִין בִּישִׁין, דְּאִקְרוּן מְצוּלוֹת יָם, אִתְעֲבָרוּ. וּכְמָּה דְּאִינּוּן מְצוּלוֹת יָם תַּלְיָין, הָכִי נָמֵי תַּלְיָיא שַׂעֲרָא (ס\"א דיליה, דהוא סטרא וכו') דִּילֵיהּ כָּל הַהוּא סִטְרָא דִּלְהוֹן, וְשַׂעֲרָא דְּהַהוּא סִטְרָא לָא שְׁעִיעַ.</p>\n<p>כְּגַוְונָא דָּא כְּתִיב, (ויקרא ט״ז:ט״ז) וְכִפֶּר עַל הַקֹּדֶשׁ מִטוּמְאֹת בְּנִי יִשְׂרָאֵל וּמִפִּשְׁעֵיהֶם לְכָל חַטֹּאתָם. וְכָל חֲטֹאתָם מִּבָּעֵי לֵיהּ, אֶלָּא לְהַנָאָה לְהוֹן, מִכָּאן וּלְהָלְאָה לְכָל חֶטְאָם דְּלָא יָכִיל מְקַטְרְגָא לְשַׁלְּטָאָה עָלַיְיהוּ (ועל דא) בְּיוֹמָא דְּכִפּוּר, דְּאִיהוּ קִנּוּחָא דְּכָל חוֹבִין, וְנַקְיוּ דִּלְהוֹן. בָּעָאן יִשְׂרָאֵל לְנַקָּאָה גַּרְמַיְיהוּ, וּלְמֵהַךְ יְחֵפֵי רַגְלִין, כְּמַלְאָכֵי עִלָּאִין. חֲמֵשׁ עִנּוּיִין, בְּגִין לְאִסְתַּיְּיעָא בְּחָמֵשׁ סִטְרִין עִלָּאִין, דְּיוֹמָא דְּכִפּוּרֵי אַפִּיק לוֹן, וְאִינּוּן תַּרְעִין דִּילֵיהּ.</p>\n<p>וְאִי שְׁתִיָּה קָא חָשִׁיב, דְּאִיהוּ מִסִּטְרָא דְּיִצְחָק, הָא שִׁית, וְאַף עַל גַּב דְּבִכְלָל אֲכִילָה אִיהוּ, וּכְדֵין אִינּוּן שִׁית, וְעִנּוּיָא בַּתְרָאָה תַּשְׁמִישׁ הַמִּטָּה אִיהוּ, וּבְדַרְגָּא שְׁתִיתָאָה שְׁכִיחַ, וְלָקֳבְלֵיהּ אֲנָן עָבְדִין עִנּוּיָא דָּא.</p>"],[9520011816,"<p>כְּתִיב (במדבר כ״ט:ז׳) וּבֶעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה, וּכְתִיב (ויקרא כ״ג:כ״ז) אַך בֶּעָשׂוֹר לַחֹדֶשׁ. בֶּעָשׂוֹר, בָּעֲשִׂירִי מִבָּעֵי לֵיהּ, מַאי בֶּעָשׂוֹר. אֶלָּא, בְּגִין דְּהַשְׁתָּא בְּיוֹמָא דָּא, כָּל דַּרְגִּין עִלָּאִין, אַתְיָין אִלֵּין עַל אִלֵּין, לְמִשְׁרֵי עַל סִיהֲרָא, וּלְאַנְהֲרָא לָהּ. וְכֻלְּהוּ בְּרָזָא דְּעֶשֶׂר, עַד דְּסַלְּקָא לְמֵאָה. וְכַד קַיְּימָא בְּרָזָא דְּמֵאָה, כַּדִּין כֹּלָּא חַד, וְאִקְרֵי יוֹם הַכִּפּוּרִים. וְעַל דָּא בֶּעָשׂוֹר, כְּמָה דְּאַתְּ אָמַר זָכוֹר, שָׁמוֹר, דְּכֻלְּהוּ אַתְיָין בְּגִין לְעַשָׂרָא וּלְאַנְהָרָא בְּרָזָא דְּעֶשֶׂר.</p>\n<p>אַהְדָּר הַאי סָבָא רֵישֵׁיהּ לָקֳבְלֵיהּ דְּרַבִּי שִׁמְעוֹן, וְאָמַר לֵיהּ, (רבי שמעון) הָא יָדַעְנָא דִּשְׁאֶלְתָּא תִּבָּעֵי בְּהַאי, בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי. אֲמַר לֵיהּ רַבִּי שִׁמְעוֹן וַדַּאי, (ס\"א דא בעשירי יאות הוא, והכי הוא, אבל בעשור אמאי וכו') בֶּעָשׂוֹר יֵאוֹת הוּא. אִי הָכִי הוּא, אֲמַאי סָלִיק לְמֵאָה, וְהָא מִקְרָא לָא אִתְחָזֵי, אֶלָּא דְּסָלִיק לְשִׁבְעִין, מַשְׁמַע דִּכְתִּיב בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי, וְכַד מְעַשְּׂרֵי לְשְׁבִיעָאָה עֶשֶׂר זִמְנִין, הָא וַדַּאי סָלִיק לְשִׁבְעִין. אֲמַר לֵיהּ, עַל דָּא אַהֲדַרְנָא רֵישָׁא לְגַבָּךְ, דְּהָא יָדַעְנָא דְּחַכִּימָא אַנְתְּ.</p>\n<p>תָּא חֲזֵי, תְּרֵין רָזִין הָכָא, חַד דְּהָא סִיהֲרָא חֹדֶשׁ הַשְּׁבִיעִי אִקְרֵי, וּבְּגִין כָּךְ אִקְרֵי חֹדֶשׁ הַשְּׁבִיעִי עָשׂוֹר, בְּגִין דְּקָא מְנָהֲרִין לָהּ עֶשֶׂר זִמְנִין, הָא מֵאָה. וְתוּ, הַאי מִלָּה דְּקָאַמְרַת, וַדַּאי לְשִׁבְעִין סְלִיקָא בְּהַאי יוֹמָא, (ובדרגא דשבעין איהו, ובדרגא דמאה איהו. לדרגא דמאה לאשלמא ולאנהרא.) וּבְהַאי דַּרְגָּא דְּשִׁבְעִין, דְּהָא בְּיוֹמָא דָּא נָטִיל לְכָל עַמָּא דְּיִשְׂרָאֵל לְמֵידָן, וְכֻלְּהוּ קַיְימִין בְּנִשְׁמְתָא יַתִּיר מִגּוּפָא, דְּהָא בְּיוֹמָא דָּא עִנּוּיָא דְּנַפְשָׁא אִיהוּ, וְלָא מִגּוּפָא, כְּמָה דְּאַתְּ אָמַר וְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם כִּי כָל הַנֶּפֶשׁ אֲשֶׁר לא תְעוּנֶּה. וְהַאי יוֹמָא נָטִיל לְכָל נַפְשָׁאן וַהֲווּ בִּרְשׁוּתֵיהּ, וְאִי לָא קַיְּימָא בְּרָזָא (נ\"א ברשותא) דְּשִׁבְעִין, לֵית לֵיהּ רְשׁוּ בְּנַפְשָׁאן, (ס\"א לקיימא תמן) דְּקִיּוּמָא דְּנַפְשָׁאן בְּרָזָא <Nonei></i>דְּשִׁבְעִין, כְּמָה דְאַתְּ אָמֵר (תהילים צ׳:י׳) יְמֵי שְׁנוֹתֵינוּ בָּהֶם שִׁבְעִים שָׁנָה וְגוֹ'.</p>\n<p>וְאִי תֵּימָא נַפְשָׁאן דְּרַבְיֵי דְּלָא אַשְׁלִימוּ לְשִׁבְעִין שְׁנִין לָא שַׁלְטָא בְּהוּ. וַדַּאי שַׁלְטָא בְּהוּ, אֲבָל לָא בִּשְׁלִימוּ, כְּמַאן דְּזָכֵי יוֹמִין סַגִּיאִין לְפִקּוּדֵי אוֹרַיְיתָא, וְעִם כָּל דָּא בְּכֻלְּהוּ שִׁבְעִין שְׁנִין אַזְלָא. וְעַל דָּא תָּנֵינָן אֶחָד הַמַּרְבֶּה וְאֶחָד הַמַּמְעִיט. מַאן אֶחָד. בְּיִחוּדָא דְּשִׁבְעִין שְׁנִין, מַאן דְּאַסְגֵּי, וּמַאן דְּאַמְעִיט.</p>\n<p>וְעַל דָּא, בְּיוֹמָא דְּכִפּוּרֵי אַעְבַּר בְּכֻלְּהוּ שִׁבְעִין, וְאִשְׁתְּלִים הַאי דַּרְגָּא בְּכֻלְּהוּ, וְכָל נִשְׁמָתִין סַלְּקִין קָמֵיהּ, וְדָאִין לְהוֹן בְּדִינָא, וְקוּדְשָׁא בְּרִיךְ הוּא חַיִּיס עָלַיְיהוּ דְּיִשְׂרָאֵל בְּיוֹמָא דָּא, מַאן דְּלָא אַעֲבָר טִינָא מִרוּחֵיהּ לְכַפָּרָא עָלֵיהּ, (ביומא דא) כַּד סָלִיק צְלוֹתֵיהּ בְּהַאי יוֹמָא, טָבַע בְּהַהוּא אֲתָר דְּאִקְרֵי רֶפֶשׁ וָטִיט, וְאִיהוּ מְצוּלוֹת (שלח קס\"ג ע\"ב) יָם וְלָא סָלִיק לְאִתְעַטְּרָא בְּרֵישָׁא דְּמַלְכָּא.</p>\n<p>בְּיוֹמָא דָּא לָא אִצְטְרִיךְ בַּר נָשׁ (ויקרא רל\"א ע\"א) לְפָרְשָׁא חֲטָאוֹי קָמֵי אַחֲרָא, בְּגִין דְּכַמָּה אִינּוּן דְּנַטְלֵי הַהִיא מִלָּה, וְסַלְקֵי לָהּ לְעֵילָּא, וְאִית סָהֲדִין בְּהַהִיא מִלָּה. וּמַה (מיכה ז׳:ה׳) מִשֹּׁכֶבֶת חֵיקֶךָ שְׁמֹר פִּתְחֵי פִּיךָ, כָּל שֶׁכֵּן אִינּוּן דְּאַזְלֵי וְעַיְּינֵי לְקַטְרְגָא לוֹן, וְסָהֲדֵי עָלֵיהּ. וְכָל שֶׁכֵּן דְּחָצִיפוּ אִיהוּ לְקָמֵי כֹּלָּא, וְחִלוּל שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא כְּתִיב, (קהלת ה׳:ה׳) אֶל תִּתֵּן אֶת פִּיךָ לַחֲטִיא אֶת בְּשָׂרֶךָ. (מכאן והלאה רזא בגוון)</p>\n<p>פָּתַח וְאָמַר, (שמות י״ב:ב׳) הַחֹדֶשׁ הַזֶּה לָכֶם רֹאשׁ חֳדָשִׁים וְגוֹ', וְכִי כֻּלְּהוּ זִמְנִין וְחֳדָשִׁין לָאו אִינּוּן דְּקוּדְשָׁא בְּרִיךְ הוּא. (אלא חדשיכם לא כתיב) אֶלָּא הַחֹדֶשׁ הַזֶּה לָכֶם, דִּילִי אִיהוּ, אֲבָל אֲנָא מָסְרִית לֵיהּ לְכוֹן, דִּלְכוֹן אִיהוּ בְּאִתְגַּלְּיָא, אֲבָל שְׁבִיעָאָה דִּילִי אִיהוּ, וְעַל דָּא אִיהוּ בַּכֶּסֶה, וְלָא בְּאִתְגַּלְּיָא. יַרְחָא דִּלְכוֹן, אִיהוּ בְּסִדּוּרָא, כְּסֵדֶר דְּאַתְוָון אָבִיב, דְּאִיהוּ אב\"ג. י\"ב אִיהוּ רָזָא דְּג'. (ס\"א ואיהו אב\"ג כסדרא דאתוון) אֲבָל יַרְחָא שְׁבִיעָאָה דִּילִי אִיהוּ מִסּוֹפָא דְּאַתְוָון. (ס\"א תשרי) מַאי טַעֲמָא. אָתּוּן מִתַּתָּא לְעֵילָּא, וַאֲנָא מֵעֵילָּא לְתַתָּא.</p>\n<p>הַאי דִּילִי. בְּרִישָׁא דְּיַרְחָא, אֲנָא אִיהוּ בְּאִתְכַּסְיָיא. בַּעֲשָׂרָה דְּיַרְחָא, אֲנָא אִיהוּ, בְּגִין דַּאֲנָא בְּחָמֵשׁ קַדְמָאֵי, וּבְחָמֵשׁ אַחֲרָנִין, וּבְחָמֵשׁ תְּלִיתָאֵי. בְּקַדְמִיתָא דְּיַרְחָא אֲנָא אִיהוּ, בְּגִין חֲמִשָּׁא יוֹמִין. בַּעֲשָׂרָה דְּיַרְחָא אֲנָא אִיהוּ, בְּגִין חֲמֵשׁ יוֹמִין אַחֲרָנִין. בט\"ו דְּיַרְחָא אֲנָא אִיהוּ, בְּגִין חֲמֵשׁ תְּלִיתָאֵי.</p>\n<p>מַאי טַעְמָא כּוּלֵי הַאי. בְּגִין דְּכָל יַרְחָא דָּא מֵעָלְמָא עִלָּאָה אִיהוּ, וְעָלְמָא עִלָּאָה בְּרָזָא דְּחָמֵשׁ אִיהוּ, בְּכָל זִמְנָא וְזִמְנָא, וּבְגִינֵי כַּךְ יַרְחָא דָּא אִיהוּ בַּכֶּסֶה, וְלָא בְּאִתְגַּלְּיָא, בְּגִין דְּעָלְמָא עִלָּאָה בַּכֶּסֶה אִיהוּ, וְכָל מִלּוֹי בְּאִתְכַּסְיָיא. וְיַרְחָא דָּא דְּקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ בִּלְחוֹדוֹי. כֵּיוָן דְּמָטָא יוֹמָא דְּחָמֵיסָר, כְּדֵין גַּלְיָיא. כֹּלָּא אִיהוּ מָטָא בְּחַדְתּוּתָא דְּסִיהֲרָא, וְסִיהֲרָא אִשְׁתְּלִימָת, וְאִתְנְהִירַת מֵאִימָּא עִלָּאָה, וְקַיְּימָא לְאַנְהָרָא לְתַתָּאֵי מִגּוֹ נְהוֹרָא דִּלְעֵילָּא, וְעַל דָּא אִקְרֵי רִאשׁוֹן, כְּמָה דְאַתְּ אָמֵר (ויקרא כ״ג:מ׳) וּלְקַחְתֶּם לָכֶם בַּיוֹם הָרִאשׁוֹן. עַד הַשְׁתָּא קַיְימֵי כֻּלְּהוּ יוֹמִין בְּרָזָא עִלָּאָה, מִכָּאן נַחְתִּין לְרָזָא תַּתָּאָה.</p>\n<p>תָּא חֲזֵי, מִיּוֹמָא עִלָּאָה הֲווֹ אִלֵּין יוֹמִין קַדְמָאִין, רָזָא דְּעָלְמָא עִלָּאָה, מַאן דָּאִין דִּינָא דְּעָלְמָא, דְּהָא דִּינָא לָא אִשְׁתְּכַח בְּהַאי עָלְמָא, אֶלָּא מִדִּינָא תַּתָּאָה, (ס\"א רזא) דְּדָא (ישעיהו נ״ד:ה׳) אֱלֹהֵי כָל הָאָרֶץ יִקָּרֵא. דְּאִי תֵּימָא דִּינָא דְּעָלְמָא דָּאִין לְעֵילָּא, אִי הָכִי לָא אִתְקְרֵי עָלְמָא דְּחִירוּ, עָלְמָא דִּנְהִירוּ דְּכָל עָלְמִין. עָלְמָא דְּכָל חַיִּין, עָלְמָא דְּכָל חִירוּ. וְאִי תֵּימָא מִדִּינָא דְּיִצְחָק. אִי אִיהוּ אִתְּעַר דִּינָא לְגַבֵּי הַאי עָלְמָא, לָא יַכְלִין כָּל עָלְמָא לְמִסְבַּל, דְּהַהוּא אֶשָּׁא תַּקִּיפָא עִלָּאָה, לָא אִית מַאן דְּסָבִיל לֵיהּ, אֶלָּא אֶשָּׁא דִּלְתַתָּא, דְּאִיהוּ אֶשָּׁא דְּסָבִיל אֶשָּׁא.</p>\n<p>אֶלָּא, כְּמָה דְּעָלְמָא דָּא עָלְמָא תַּתָּאָה דְּכֻלְּהוּ עָלְמִין. הָכִי נָמֵי כָּל דִּינוֹי מֵעָלְמָא תַּתָּאָה, דֶּאֱלֹהִים שׁוֹפֵט. וְדָא אִקְרֵי דִּינָא עִלָּאָה עַל הַאי עָלְמָא, וּבְגִין דְּאִיהוּ דַּרְגָּא שְׁבִיעָאָה, לָא גָּזִיר גְּזֵרָה עַל בַּר נָשׁ, אֶלָּא מֵעֶשְׂרִין שְׁנִין וּלְעֵילָּא.</p>\n<p>אַשְׁגַּח הַאי סָבָא בַּרִבִּי שִׁמְעוֹן, וְחָמָא לֵיהּ דְּזַלְגִּין עֵינוֹי דִּמְעִין. אָמַר רִבִּי שִׁמְעוֹן, אִי הִיא שְׁבִיעָאָה, אֲמַאי <Nonei></i>מֵעֶשְׂרִין שְׁנִין וּלְעֵילָּא. אָמַר לֵיהּ, זַכָּאָה מַאן דְּמַלִּיל עַל אוּדְנִין דְּשַׁמְעִין.</p>\n<p>תָּא חֲזֵי, בֵּי דִּינָא דִּלְתַתָּא בְּאַרְעָא, לָא גַּזְרִין דִּינָא עַל בַּר נָשׁ, עַד תְּלֵיסַר שְׁנִין. מַאי טַעֲמָא. בְּגִין דְּשַׁבְקִין שֶׁבַע שְׁנִין לְשְׁבִיעָאָה, אֱלהֵי כָּל הָאָרֶץ יִקָּרֵא. וְלֵית רְשׁוּ לְבַר נָשׁ בְּאִינּוּן שֶׁבַע. וְאִינּוּן שֶׁבַע, לָא שָׁרָאן אֶלָּא עַל תְּלֵיסַר דִּלְתַתָּא, בְּאַרְעָא דְּאִינּוּן כּוּרְסְיָּיא לְגַבֵּיהּ, וּבְגִין כַּךְ, כָּל גִּזְרִין, וְכָל דִּינִין דִּלְתַתָּא, מֵאִינּוּן שֶׁבַע שְׁנִין דִּלְתַתָּא, כְּלָלָא דְּעֶשְׂרִין שְׁנִין אִיהוּ.</p>\n<p>וְדִינָא דְּעָלְמָא בְּרֹאשׁ הַשָּׁנָה, עַל יְדָא דְּהַאי דַּרְגָּא אִיהוּ, דְּאִיהוּ מַמָּשׁ קַיְּימָא בְּדִינָא עַל בְּנוֹי בְּהַאי עָלְמָא, בְּגִין לְאִתְדַּכְּאָה לְגַבֵּי עָלְמָא עִלָּאָה, בְּגִין דְּלֵית לֵיהּ סִיוּעַ לְסַלְּקָא וּלְאִתְדַכְּאָה אֶלָּא מִגּוֹ תַּתָּאֵי.</p>"],[9520011817,"<p>וְכַד יִשְׂרָאֵל אִינּוּן בַּחֲמֵיסָר יוֹמִין, כְּדֵין נָטִיל לִבְנוֹי, לְפָרְשָׂא גַּדְפּוֹי עָלַיְיהוּ, וּלְמֵחדֵי עִמְּהוֹן. וְעַל דָּא כְּתִיב וּלְקַחְתֶּם לָכֶם בַּיוֹם הָרִאשׁוֹן, (נח ס\"ב ע\"א) פְּרִי דָּא, אִיהוּ אִילָנָא דְּאִקְרֵי עֵץ פְּרִי, וְאִשְׁתְּכַח בֵּיהּ פְּרִי. עֵץ הָדָר: כְּמָה דְאַתְּ אָמֵר (תהילים צ״ו:ו׳) הוֹד וְהָדָר לְפָנָיו. מַאי טַעְמָא אִקְרֵי הָדָר, וּמַאן אִיהוּ הָדָר. אֶלָּא דָּא צַדִּיק.</p>\n<p>אֲמַאי אִקְרֵי הָדָר, וְהָא אֲתָר טְמִירָא אִיהוּ דְּלֵית לֵיהּ גִּלּוּיָא, וּצְרִיכָא לְאִתְכַּסְיָיא תָּדִיר, וְלֵית הָדָר אֶלָּא מַאן דְּאִתְגַּלְיָיא וְאִתְחַזֵּי. אֶלָּא, אַף עַל גַּב דְּאִיהוּ דַּרְגָּא טְמִירָא, הִדּוּרָא אִיהוּ דְּכָל גּוּפָא, וְלָא אִשְׁתְּכַח הִדּוּרָא לְגוּפָא, אֶלָּא בֵּיהּ. מַאי טַעֲמָא. מַאן דְּלֵית עִמֵּיהּ הַאי דַּרְגָּא, לֵית בֵּיהּ הִדּוּרָא, לְמֵיעַל בִּבְנֵי נָשָׁא. קָלָא לָאו עִמֵּיהּ בִּדְבוּרָא, (ס\"א כדכורא) וְהִדּוּרָא (ס\"א ודבורא) דְּקָלָא אִתְפְּסַק מִנֵּיהּ. דִּיקְנָא, וְהִדּוּרָא דְּדִיקְנָא לָאו עִמֵּיהּ, וְאַף עַל גַּב דְּאִתְכַּסְיָיא הַהוּא דַּרְגָּא, כָּל הִדּוּרָא דְּגוּפָא בֵּיהּ תַּלְיָא. וְאִתְכַּסֵּי וְאִתְגַּלְיָיא. וּבְּגִין כָּךְ עֵץ הָדָר אִיהוּ, עֵץ דְּכָל הִדּוּרָא דְּגוּפָא בֵּיהּ תַּלְיָא, וְדָא אִיהוּ (בראשית א׳:י״ב) עֵץ עוֹשֶׂה פְּרִי.</p>\n<p>כַּפֹּת תְּמָרִים, הָכָא אִתְכְּלִילַת אִתְּתָא בְּבַעְלָהּ בְּלָא פִּרוּדָא, כַּפּוֹת תְּמָרִים (ויחי ר\"כ) כַּחֲדָא. וַעֲנַף עֵץ עָבוֹת, תְּלָתָא. וְעָלִין דִּילֵיהּ, דָּא בְּסִטְרָא דָּא, וְדָא בְּסִטְרָא דָּא, וְחַד דְּשַׁלִּיט עָלַיְיהוּ. וְעַרְבֵי נַחַל, תְּרֵין. דְּלֵית לְהוּ רֵיחָא וְטַעְמָא, כְּשׁוֹקִין בִּבְנֵי נָשָׁא. (ובגין כך) לוּלָב נָטִיל כֻּלְּהוּ, כְּחוּטָא דְּשִׁדְרָה קַיָּימָא דְּגוּפָא. וּמַה דְּנָפִיק לְבַר טֶפַח, הָכִי הוּא, בְּגִין לְאַשְׁלְמָא וּלְאַפָּקָא כֹּלָּא, וּלְשַׁמְּשָׁא כַּדְקָא חֲזֵי.</p>\n<p>(ובגין כך) בְּהָנֵי זִינִין, בָּעֵי בַּר נָשׁ לְאִתְחֲזָאָה קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. עָלִין וְטַרְפִּין דְּהָנִי תְּמָרִים, אִינּוּן כָּל שְׁאַר חֵילִין דְּאִתְאַחֲדָן בְּאִינּוּן כִּנּוּיָין דְּקוּדְשָׁא בְּרִיךְ הוּא אִקְרֵי בְּהוֹן. בְּגִין דְּבָּעֵינָן (ס\"א לאתחדתא) לְתַתָּא כְּגַוְונָא דִּלְעֵילָּא, דְּלֵית לָךְ מִלָּה בְּעָלְמָא, דְּלָא אִית לָהּ דּוּגְמָא לְעֵילָּא, כְּגַוְונָא דִּלְעֵילָּא הָכִי אִית לְתַתָּא, וּבְעוּ יִשְׂרָאֵל לְאִתְאַחֲדָא בְּרָזָא דָּא דִּמְהֵימְנוּתָא, קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9520011818,"<p>כְּתִיב (ויקרא כ״ג:מ״ב) בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים, דָּא הוּא רָזָא דִּמְהֵימְנוּתָא, וְהַאי קְרָא עַל עָלְמָא עִלָּאָה אִתְּמַר, וְהָכִי תָּנֵינָן, כַּד אִתְבְּרֵי עָלְמָא, אִתְּמַר הַאי קְרָא.</p>\n<p>כַּד שָׁרָא חָכְמָה לְנָפְקָא, מֵאֲתָר דְּלָא יְדִיעַ וְלָא אִתְחֲזֵי, כְּדֵין נָפִיק חַד מִשְׁחָתָא, וּבָטַשׁ, וְהַהִיא חָכְמְתָא עִלָּאָה, נָצִיץ וְאִתְפָּשַּׁט לְכָל סִטְרִין, בְּרָזָא דְּמַשְׁכְּנָא עִלָּאָה. וְהַהוּא מַשְׁכְּנָא עִלָּאָה, אַפִּיק שִׁית סִטְרִין, וּכְדֵין הַהוּא נְצִיצוּ דְּמִשְׁחָתָא נָהִיר לְכֹלָּא, וְאָמַר בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים.</p>\n<p>מַאן סֻּכֹּת חָסֵר ו'. דָּא מַשְׁכְּנָא תַּתָּאָה, דְּאִיהוּ כַּעֲשָׁשִׁיתָא, לְאַחֲזָאָה לְכָל נְהוֹרִין, וּכְדֵין אָמַר, בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים. מַאן שִׁבְעַת יָמִים. מֵעָלְמָא עִלָּאָה לְתַתָּאָה, דְּכֻלְּהוּ קַיְימֵי בְּקִיּוּמָא, לְאַנְהָרָא לְהַאי סֻּכֹּת. וּמַאן אִיהִי. דָּא (עמוס ט׳:י״א) סֻכַּת דָּוִד הַנּוֹפֶלֶת. סֻכַּת שָׁלוֹם. וּבָעֵי עַמָּא קַדִּישָׁא לְמֵיתָב תְּחוֹת צִלָּהָא, בְּרָזָא דִּמְהֵימְנוּתָא, וּמַאן דְּיָתִיב בְּצִלָּא דָּא, יָתִיב בְּאִינּוּן יוֹמִין עִלָּאִין.</p>\n<p>וְעַל דָּא כֻּלְּהוּ בַּסֻּכֹּת בַּסֻּכֹּת וְחַד בַּסוּכּוֹת שְׁלִים, חַד שְׁלִים, לְאַחֲזָאָה דְּמַאן דְּיָתִיב בְּצִלָּא דָּא, יָתִיב בְּאִינּוּן יוֹמִין עִלָּאִין לְעֵילָּא, דְּקַיְימִין עַל הַאי תַּתָּאָה, לְאַנְהָרָא לֵיהּ, לְחַפְיָא עָלֵיהּ, וּלְאַגָּנָא לֵיהּ, בְּשַׁעֲתָא דְּאִצְטְרִיךְ.</p>\n<p>וְתוּ, כֻּלְּהוּ אִקְרוּן סֻכּוֹת בִּשְׁלִימוּ, וּכְתִיב סֻכַּת חָסֵר, דָּא עָלְמָא תַּתָּאָה, דְּבָעָא בְּהָנֵי ז' יוֹמִין <Nonei></i>קַדִּישִׁין, לְמֵיזָן לִשְׁאַר מְמָנָן רַבְרְבָן דְּעַמִּין, בְּעוֹד דְּאִיהִי נַטְלָא חֶדְוָה בְּבַעְלָהּ, וְלָא יְקַטְרְגוּן חֶדְוָותָא, בְּגִין דְיִתְרַבְרְבוּן (ס\"א דיתעדנון) בְּהַהוּא מְזוֹנָא, קָרְבָּנִין דִּלְהוֹן סַגִּיאִין יַתִּיר מִשְּׁאָר יוֹמִין, בְּגִין דְּיִתְעַסְּקוּן בְּהוּ, וְלָא יִתְעָרְבוּן לְבָתַר בְּחֶדְוָה דְּיִשְׂרָאֵל. וּמַאן חֶדְוָה דְּיִשְׂרָאֵל, דָּא יוֹמָא תְּמִינָאָה דַּעֲצֶרֶת.</p>\n<p>וְתָּא חֲזֵי, בְּעוֹד דְּאִינּוּן שְׁאַר מְמָנָן חַדָּאן, וְאַכְלִין בְּהַהוּא מְזוֹנָא דִּמְתַּקְנִי לוֹן יִשְׂרָאֵל. אִינּוּן מְתַקְּנֵי כּוּרְסְיָּיא לְקוּדְשָׁא בְּרִיךְ הוּא מִתַּתָּא, וּלְסַלְּקָא לֵיהּ לְעֵילָּא, בְּאִינּוּן זִינִין, וּבְחֶדְוָה, וּבְהִלּוּלָא, וּלְאַקְפָא מַדְבְּחָא. כְּדֵין אִיהִי סַלְּקָא, וְנַטְלָא בִּרְכָּאן וְחֶדְוָה בְּבַעְלָהּ.</p>\n<p>וּשְׁאַר חֵיוָון רַבְרְבָן מְמָנָן דְּעַמִּין, אָכְלָן וּמַדְקָן וְרַפְסָן וְאִתְּזָנוּ. וְאִיהִי נַקְטָא נַפְשָׁאן בְּעִנּוּגִין לְעֵילָּא, כְּמָה דְּאִתְּמַר. כֵּיוָן דְּנַחְתָּא, וְהָא נַקְטָא כָּל בִּרְכָּאן וְכָל קִדּוּשִׁין וְכָל עִנּוּגִין, וְיִשְׂרָאֵל כָּל הָנֵי שִׁבְעָה יוֹמִין הֲווֹ (ויקרא רצ\"ד ע\"ב) מַשְׁכִין לָהּ בְּאִינּוּן עוֹבָדִין דְּקָא עַבְדִּין וּמְקָרְבִין בַּהֲדָהּ, כְּדֵין נַחְתָּא לְקָרְבָא בִּבְנָהָא, וּלְמֵחדֵי לוֹן יוֹמָא חַד, וְהַהוּא יוֹמָא אִיהוּ יוֹמָא תְּמִינָאָה, בְּגִין דְּכָל ז' יוֹמִין אַחֲרָנִין בַּהֲדָהּ. וְעַל דָּא אִיהוּ תְּמִינָאָה, וּתְמַנְיָא יוֹמִין כַּחֲדָא. וּבְגִין כַּךְ אִקְרֵי עֲצֶרֶת: כְּנִישִׁין. כְּנִישִׁין כֻּלְּהוּ בְּהַאי יוֹמָא. וְאִקְרֵי שְׁמִינִי, וְלֵית שְׁמִינִי אֶלָּא מִגּוֹ שִׁבְעָה.</p>"],[9520011819,"<p>כְּתִיב (איוב א) יְהִי שֵׁם יְיָ' מְבוֹרָךְ. מַאי מְבוֹרָךְ. (אלא כלא ידעי), אֲבָל רָזָא חֲדָא יָדַע חַד מֵחַבְרָנָא, בְּמַדְבְּרָא אַחְזִיאוּ לֵיהּ בְּחֶלְמָא, וְרִבִּי יִצְחָק כַּפְתּוֹרָא שְׁמֵיהּ. מַאי מְבוֹרָךְ. שֵׁירוּתָא קָשֶׁה, וְסוֹפֵיהּ רַךְ. מ\"ב קָשֶׁה, וְדִינָא אִיהוּ וַדַּאי. (ולבתר כך) כְּגַוְונָא דָּא, יוֹמָא דְּרֹאשׁ הַשָּׁנָה מ\"ב, דְּהָא בְּמ\"ב (וברזא דמ\"ב) אַתְוָון אִתְבְּרֵי עָלְמָא, וְעַל דָּא אִתְבְּרֵי בְּדִינָא. לְבָתַר רַךְ, וְעַל דָא תָּנֵינָן, כָּל שֵׁירוּתִין קָשִׁין, וְסוֹפָא דִּלְהוֹן רָכִין. (ס\"א דא במ\"ב וברזא דמ\"ב אתוון אתברי עלמא ועל דא אתברי בדינא לבתר כך כגוונא דא) בְּיוֹמָא דְּרֹאשׁ הַשָּׁנָה מ\"ב קָשֶׁה בְּדִינָא. בְּיוֹמָא דַּעֲצֶרֶת רַךְ בְּחֶדְוָה.</p>\n<p>תָּא חֲזֵי, מָה בֵּין דִּינָא עִלָּאָה, לְהַאי דִּינָא. דִּינָא עִלָּאָה שֵׁירוּתָא וְסוֹפָא קָשֶׁה, וְלֵית מַאן דְּיֵקוּם בֵּיהּ, וְכָל מָה דְּאָזִיל אִתְתָּקַּף, וּבָתַר דְּשָׁאֲרִי, לָא סָלִיק מִנֵּיהּ, עַד דְּאָכִיל וְשֵׁצֵי כֹּלָּא, דְּלָא אִשְׁתְּאַר כְּלוּם. אֲבָל דִּינָא אַחֲרָא דְּתַתָּא, שֵׁירוּתָא קָשֶׁה, וְכָל מָה דְּאָזִיל אִתְחֲלָשׁ, עַד דְּנָהִיר אַנְפִּין, כְּגַוְונָא (ס\"א דא דינא דנוקבא) דְּנוּקְבָּא דְּחָלָשׁ חֵילָהָא.</p>\n<p>אֵימָתַי אִתְּעַר דִּינָא דִּלְעֵילָּא לְמִשְׁרֵי עַל עָלְמָא. בְּיוֹמָא דְּטוֹפָנָא. וְעַל דָּא לָא אִשְׁתְּאַר כְּלוּם בְּעָלְמָא, בַּר הַהוּא תֵּבוּתָא דְּנֹחַ, דְּאִיהִי כְּגַוְונָא עִלָּאָה, דְּסָבִיל לְהַהוּא תּוּקְפָּא. וְאִי לָאו דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא, וְאִשְׁתְּכַח בְּרַחֲמֵי עַל עָלְמָא, כָּל עָלְמָא אִתְאֲבִיד, דִּכְתִּיב, (תהילים כ״ט:י׳) יְיָ' לַמַּבּוּל יָשָׁב, וְעַל דָּא לָא שַׁרְיָא דִּינָא דִּלְעֵילָּא עַל עָלְמָא, דְּלָא יָכִיל עָלְמָא לְמִסְבַּל לֵיהּ, אֲפִילּוּ רִגְעָא חֲדָא.</p>"],[9520011820,"<p>אַדְּהָכִי הֲוָה רִבִּי שִׁמְעוֹן בָּכֵי וְחַדֵּי. זָקְפוּ עַיְינִין, וְחָמוּ חֲמִשָּׁה מֵאִינּוּן פְּרוּשִׁים, דַּהֲווֹ אַזְלֵי אֲבַתְרֵיהּ, לְמִתְבַּע לֵיהּ. קָמוּ. אָמַר רִבִּי שִׁמְעוֹן, מִכָּאן וּלְהָלְאָה מָה שְׁמָךְ. אָמַר, נְהוֹרָאי סָבָא, בְּגִין דִּנְהוֹרָאי אַחֲרָא אִית גַּבָּן. אַזְלוּ רִבִּי שִׁמְעוֹן וְאִינּוּן חַבְרַיָּיא עִמֵּיהּ תְּלַת מִילִין, אָמַר רִבִּי שִׁמְעוֹן, לְאִינּוּן אַחֲרָנִין, מַה אָרְחָא דָּא גַּבַּיְיכוּ. אָמְרוּ, לְמִתְבַּע לֵיהּ לְהַאי סָבָא, דְּמֵימוֹי אֲנָן שָׁתָאן בְּמַדְבְּרָא. אָתָא רִבִּי שִׁמְעוֹן וּנְשָׁקֵיהּ, אָמַר לֵיהּ, נְהוֹרָאי שְׁמָךְ, וּנְהוֹרָא אַנְתְּ, וּנְהוֹרָא עִמָּךְ שָׁרֵי.</p>\n<p>פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר, (דניאל ב׳:כ״ב) הוּא גָּלֵא עֲמִיקָתָא וּמְסַּתְּרָתָא יָדַע מָה בַחֲשׁוֹכָא וּנְהוֹרָא עִמֵּהּ שְׁרֵא. הוּא גָּלֵה עֲמִיקָתָא וּמְסַּתְּרָתָא, קוּדְשָׁא בְּרִיךְ הוּא גַּלֵּי עֲמִיקָתָא וּמְסַּתְּרָתָא, דְּכָל עֲמִיקִין סְתִימִין עִלָּאִין אִיהוּ גַּלֵּי לוֹן. וּמַאי טַעֲמָא גַּלֵּי לוֹן. בְּגִין דְּיָדַע מָה בַחֲשׁוֹכָא. דְּאִלְמָלֵא חֲשׁוֹכָא לָא אִתְיְדַע נְהוֹרָא. וְאִיהוּ יָדַע מָה בַחֲשׁוֹכָא. וּבְגִין כַּךְ גַּלֵּי עֲמִיקָתָא וּמְסַּתְּרָתָא, דְּאִי לָאו חֲשׁוֹכָא לָא יִתְגַּלְיָין עֲמִיקִין וּמְסַתְּרָאָן. וּנְהוֹרָא עִמֵּהּ שְׁרֵא. מַאן נְהוֹרָא דָּא. נְהוֹרָא <Nonei></i>דְּאִתְגַּלְיָיא מִגּוֹ חֲשׁוֹכָא.</p>\n<p>וַאֲנָן מִגּוֹ חֲשׁוֹכָא דְּהַוָה בְּמַדְבְּרָא, אִתְגְּלֵי לָן נְהוֹרָא דָּא. רַחֲמָנָא יַשְׁרֵי עִמָּךְ נְהוֹרָא, בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי. אָזְלֵי רַבִּי שִׁמְעוֹן וְחַבְרַיָּיא, אִלֵּין תְּלַת מִילִין אֲבַתְרֵיהּ, אָמַר לֵיהּ, אֲמַאי לָא אָזְלֵי אִלֵּין עִמָּךְ כְּקַדְמִיתָא. אֲמַר לֵיהּ, לָא בְּעֵינָא לְאַטְרְחָא לְבַר נָשׁ עִמִּי, הַשְׁתָּא דְּאָתוּ נֵזִיל כַּחֲדָא. אָזְלוּ, וְרַבִּי שִׁמְעוֹן אָזַל לְאָרְחֵיהּ. אָמַר רִבִּי אַבָּא, הָא אֲנָן יְדַעְנָא שְׁמֵיהּ, וְאִיהוּ לָא יָדַע שְׁמֵיהּ דְּמֹר, אָמַר לֵיהּ, מִנֵּיהּ יָדַעְנָא דְּלָא לְאִתְחֲזָאָה. בָּרוּךָ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן:</p>"],[9520011821,"<p>(שמות ל׳:י״א-י״ב) וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה לֵאמֹר. כִּי תִשָּׂא אֶת רֹאשׁ בְּנִי יִשְׂרָאֵל לִפְקוּדֵיהֶם וְגוֹ', רִבִּי אַבָּא וְרִבִּי אָחָא וְרִבִּי יוֹסֵי הֲווֹ אַזְלֵי מִטְּבֶרְיָה לְצִפֹּרִי. עַד דַּהֲווֹ אַזְלֵי, חָמוּ לֵיהּ לְרַ' אֶלְעָזָר דְּהֲוָה אָתֵי, וְרִבִּי חִיָּיא עִמֵּיהּ. אָמַר רִבִּי אַבָּא, וַדַּאי נִשְׁתַּתֵּף בַּהֲדֵי שְׁכִינְתָּא. אוֹרִיכוּ לְהוּ, עַד דְּמָטוּ לְגַבַּיְיהוּ. כֵּיוָן דְּמָטוּ גַּבַּיְיהוּ, אָמַר רִבִּי אֶלְעָזָר, וַדַּאי כְּתִיב, (תהלים לה) עֵינֵי יְיָ' אֶל צַדִּיקִים וְאָזְנָיו אֶל שַׁוְעָתָם. הַאי קְרָא קַשְׁיָא וְכוּ'. (זה המאמר תמצאנו בפרשת פקודי דף רכ\"ה ע\"ש, שם מקומו)</p>\n<p>תָּא חֲזֵי, הָא אוּקְמוּהָ, לֵית בִּרְכָתָא דִּלְעֵילָּא שַׁרְיָיא עַל מִלָּה דְּאִתְמְנֵי. וְאִי תֵּימָא, יִשְׂרָאֵל הֵיךְ אִתְמְנוּן. אֶלָּא כּוּפְרָא נָטִיל מִנַּיְיהוּ, וְהָא אוּקְמוּהָ, וְחוּשְׁבָּנָא לָא הֲוִי עַד דְּאִתְכְּנִישׁ כָּל הַהוּא כּוּפְרָא, וְסָלִיק לְחוּשְׁבָּנָא. וּבְקַדְמֵיתָא מְבָרְכִין לְהוּ לְיִשְׂרָאֵל, וּלְבָתַר מָנִין הַהוּא כּוּפְרָא, וּלְבָתַר אָהַדְרָן וּמְבָרְכִין לוֹן לְיִשְׂרָאֵל. אִשְׁתְּכָחוּ יִשְׂרָאֵל מִתְבָּרְכָאן בְּקַדְמִיתָא וּבְסוֹפָא, וְלָא סָלִיק בְּהוֹן מוֹתָנָא.</p>\n<p>מוֹתָנָא אֲמַאי סָלִיק בְּמִנְיָינָא. אֶלָּא בְּגִין דְּבִרְכָתָא לָא שַׁרְיָא בְּמִנְיָינָא, כֵּיוָן דְּאִסְתָּלַּק בִּרְכָתָא, סִטְרָא אַחֲרָא שַׁרְיָא עָלֵיהּ, וְיָכִיל לְאַנְזְקָא, בְּגִין כַּךְ נַטְלִין כּוּפְרָא וּפִדְיוֹנָא לְסַלְּקָא (ס\"א מעלייהו) עָלֵיהּ מִנְיָינָא, וְהָא אוּקְמוּהָ, וְאִתְּמַר.</p>"],[9520011822,"<p><Noneb>רעיא מהימנא</b> פִּקוּדָא לִיתֵּן מַחֲצִית הַשֶּׁקֶל בְּשֶׁקֶל הַקֹּדֶשׁ. מַאן מַחֲצִית הַשֶׁקֶל אִיהוּ כְּגוֹן חֲצִי הַהִין, וְדָא ו', מְמוּצָע בֵּין שֵׁנִי הֵהִי\"ן. אַבְנָא לְמִשְׁקָל בָּהּ, דָּא י', עֶשְׂרִים גֵּרָה הַשֶׁקֶל: דָּא יוֹ\"ד. הֶעָשִׁיר לָא יַרְבֶּה, דָּא עַמּוּדָא דְּאֶמְצָעִיתָא, לָא יַרְבֶּה עַל י'. וְהָכִי אִתְּמַר בְּסֵפֶר יְצִירָה, עֶשֶׂר סְפִירוֹת בְּלִימָּה, עֶשֶׂר וְלָא אֶחָד עָשָׂר. וְהַדַּל לָא יַמְעִיט, דָּא צַדִּיק, לָא יַמְעִיט מֵעֶשֶׂר, כְּמָה דְאַתְּ אָמֵר עֶשֶׂר וְלָא תֵּשַׁע. מִמַּחֲצִית הַשֶׁקֶל, דְּאִיהוּ י'. (נ\"א מחצית השקל עשר הוא)</p>\n<p>אֲמַר לֵיהּ רַעְיָא מְהֵימָנָא, (מלאך) אַנְתְּ בַּשָׁמַיִם, רָחִים אַנְתְּ מִמָּארֵיךְ, לֵית תַּוָוהָא בְכָל אִינּוּן מִלִּין יַקִּירִין דְּיִפְקוּן מִפּוּמָךְ, דְּהָא מַאן דְּאִיהוּ מַלְכָּא, אוֹ בְּרָא דְּמַלְכָּא, לֵית תַּוָוהָא, דְּיִפְקוּן מַרְגְלָאִין בְּפָתוֹרֵיהּ, מַלְיָין סְגוּלוֹת, מַלְיָין נְהוֹרִין. לְבַר נָשׁ אַחֲרָא, אִיהוּ תַּוָוהָא. אֲמַר לֵיהּ בְּרִיךְ אַנְתְּ רַעְיָא מְהֵימָנָא. מִתַּמָּן וְאֵילָךְ אֵימָא אַנְתְּ, דְּעִלָּאִין וְתַתָּאִין נַחְתּוּ לְמִשְׁמַע מִינָךְ. אָמַר לֵיהּ, אַשְׁלִים מִלּוּלָךְ, אָמַר לֵיהּ, לָא אִית כְּעַן לְמֵימַר יַתִּיר, אֵימָא אַנְתְּ עַד זִמְנָא אַחֲרָא.</p>\n<p>פָּתַח רַעְיָא מְהֵימָנָא, פִּקּוּדָא בָּתַר דָּא, לְקַדֵּשׁ אֶת הַחֹדֶשׁ. בְּגִין דְּסִיהֲרָא קַדִּישָׁא אִיהִי כַּלָּה, דְּמִתְקַדֶּשֶׁת <Nonei></i>עַל פִּי בֵּית דִּין, דְּאִיהוּ גְּבוּרָה, בְּגִין דְּתַמָּן לֵיוָאֵי, דְּאִתְּמַר בְּהוּ וְקִדַּשְׁתָּ אֶת הַלְוִיִּם. וּלְבָתַר דְּאִתְחֲזֵי סִיהֲרָא דְּיֵאוֹתוּ לְאוֹרָה, מְבָרֵךְ עָלֶיהָ בָּרוּךְ אַתָּה יְיָ' אֱלהֵינוּ מֶלֶךְ הָעוֹלָם, אֲשֶׁר בְּמַאֲמָרוֹ בָּרָא שְׁחָקִים, וּבְרוּחַ פִּיו כָּל צְבָאָם. וּבְמִי מִתְקַדֶשֶׁת וּמִתְבָּרֶכֶת, בְּתִפְאֶרֶת בְּגִין דְּאִיהוּ עֲטֶרֶת תִּפְאֶרֶת לַעֲמוּסֵי בָטֶן. (ע\"כ רעיא מהימנא) (תצא דף ר\"פ ע\"ב כי ישבו אחיו יחדיו וכו')</p>"],[9520011823,"<p>רִבִּי יוֹסֵי וְרִבִּי חִיָּיא הֲווֹ אַזְלֵי בְּאָרְחָא, עַד דַּהֲווֹ אַזְלִין רָמַשׁ לֵילְיָא, יָתְבוּ. אַדְהֲווֹ יַתְבִין, שְׁרִיאַת צַפְרָא לְאַנְהֲרָא, (ס\"א אמרו קום ונהך) קָמוּ וְאָזְלוּ. אָמַר רִבִּי חִיָּיא, חָמֵי אַנְפּוֹי דְּמִזְרָח דְּקָא מְנַהֲרִין, הַשְׁתָּא כָּל אִינּוּן בְּנֵי מְדִינְחָא דְּטוּרֵי נְהוֹרָא, סַגְדִּין לְגַבֵּי הַאי נְהוֹרָא, דְּנָהִיר בַּאֲתָר דְּשִׁמְשָׁא, עַד לָא יִפּוּק, וּפָלְחִין לֵיהּ, דְּהָא כֵּיוָן דְּנָפִיק שִׁמְשָׁא, כַּמָה אִינּוּן (ל\"ה ע\"א) דְּפָלְחִין לְשִׁמְּשָׁא. וְאִלֵּין אִינּוּן דְּקָא פַּלְחִין לִנְהוֹרָא דָּא, וּקְרָאן לְהַאי נְהוֹרָא, אֱלָהָא דְּמַרְגְּלָא דְּנָהִיר. וְאוֹמָאָה דִּלְהוֹן בֵּאֱלֹ\"הַּ דְּמַרְגְּלָא דְּנָהִיר.</p>\n<p>וְאִי תֵּימָא פּוּלְחָנָא דָּא לְמַגָּנָא הוּא. מִיּוֹמִין עַתִּיקִין קַדְמָאֵי, חָכְמְתָא יָדְעוּ בֵּיהּ. בְּזִמְנָא דְּשִׁמְשָׁא נָהִיר, עַד לָא יִפּוֹק, הַהוּא מְמָנָא דְּפָקִיד עַל שִׁמְשָׁא, נָפִיק, וְאַתְוָון (ק\"ל ע\"ב) קַדִּישִׁין דִּשְׁמָא עִלָּאָה קַדִּישָׁא רְשִׁימָן עַל רִישֵׁיהּ, (דשמשא) וּבְחֵילָא דְּאִינּוּן אַתְוָון, פָּתַח לְכָל כַּוֵּי שְׁמַיָא וּבָטַשׁ בְּהוּ, וְעָבַר. וְהַהוּא מְמָנָא עָאל גּוֹ הַהוּא זֹהֲרָא דְּנָהִיר סָחֲרָנֵיהּ דְּשִׁמְשָׁא, וְתַמָּן שְׁכִיחַ, עַד דְּנָפַק שִׁמְשָׁא, וְאִתְפָּשַּׁט בְּעָלְמָא.</p>\n<p>וְהַהוּא מְמָנָא, אִיהוּ פְּקִידָא, עַל דַּהֲבָא, וְעַל מַרְגְּלָן סוּמָקָן. וְאִינּוּן פַּלְחִין לְהַהוּא דִּיּוּקְנָא דְּתַמָּן, וּבְנִקוּדִין וְסִימָנִין דְּיַרְתּוּ מִקַּדְמָאֵי מִיּוֹמִין עַתִּיקִין, אַזְלֵי וְיַדְעֵי נְקוּדִין דְּשִׁמְשָׁא, לְמִשְׁכַּח אַתְרִין דְּדַהֲבָא וּמַרְגְּלָן, אָמַר רִבִּי יוֹסֵי, עַד כַּמָה יְהוֹן פּוּלְחָנִין סַגִּיאִין אִלֵּין בְּעָלְמָא, דְּהָא שִׁקְרָא לֵית לֵיהּ קַיְימִין לְקַיְּימָא.</p>"],[9520011824,"<p>פָּתַח אִידָךְ (ס\"א רבי חייא) וְאָמַר, (משלי י״ב:י״ט) שְׂפַת אֱמֶת תִּכּוֹן לָעַד וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר. תָּא חֲזֵי, אִלּוּ כָּל בְּנֵי עָלְמָא הֲווֹ פַּלְחִין לְשִׁקְרָא, הֲוָה הָכִי, אֲבָל הַאי נְהוֹרָא וְזִהֲרָא דְּנָהִיר, וַדַּאי קְשׁוֹט אִיהוּ. כֹּכְבֵי רוּמָא דִּרְקִיעָא קְשׁוֹט אִינּוּן. אִי בְּטִפְּשׁוּ וְחֶסְרוֹנָא דְּדַעְתָּא דִּלְהוֹן, אִינּוּן אַמְרֵי וְקָרָאן לְהוּ אֱלָהָא, לָא בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְשֵׁיצָאָה עוֹבָדוֹי מֵעָלְמָא. אֲבָל לְזִמְנָא דְּאָתֵי לָא יִשְׁתֵּצוּן כֹּכָבַיָא וּנְהוֹרִין דְּעָלְמָא. אֲבָל מַאן יִשְׁתְּצֵי. אִינּוּן דְּפַלְחוּ לוֹן.</p>\n<p>וּקְרָא דָּא הָכִי הוּא. שְׂפַת אֱמֶת תִּכּוֹן לָעַד, אִלֵּין יִשְׂרָאֵל, דְּאִינּוּן שְׂפַת אֱמֶת. (דברים ו׳:ד׳) יְיָ' אֱלהֵינוּ יְיָ' אֶחָד. וְכֹלָּא אִיהוּ אֱמֶת, וְרָזָא דֶּאֱמֶת, וּמְסַיְימֵי יְיָ' אֱלֹהֵיכֶם אֱמֶת. וְדָא אִיהוּ שְׂפַת אֱמֶת תִּכּוֹן לָעַד.</p>\n<p>וְעַד אַרְגִּיעָה, וְעַד רֶגַע מִבָּעֵי לֵיהּ, מַאי אַרְגִּיעָה. אֶלָּא, עַד כַּמָה יְהֵא קִיוּמָא דִּלְהוֹן בְּעָלְמָא, עַד זִמְנָא דְּיֵיתֵי, וִיּהֵא לִי נַיְיחָא מִפּוּלְחָנָא קַשְׁיָא דְּעָלוֹי. וּבְזִמְנָא דְּאַרְגִּיעָה, יִשְׁתְּצֵי לְשׁוֹן שָׁקֶר, אִינּוּן דְּקָרָאן אֱלָהָא, לְמַאן דְּלָאו הוּא אֱלָהָא. אֲבָל יִשְׂרָאֵל דְּאִינּוּן שְׂפַת אֱמֶת, כְּתִיב בְּהוּ, (ישעיהו מ״ג:כ״א) עַם זוּ יָצַרְתִּי לִי תְּהִלָּתִי יְסַפֵּרוּ.</p>\n<p>אַדְכַּרְנָא חֲדָא זִמְנָא דַּהֲוֵינָא אָזִיל בַּהֲדֵי רִבִּי אֶלְעָזָר, פָּגַע בֵּיהּ הֶגְמוֹנָא, אֲמַר לֵיהּ לְרִבִּי אֶלְעָזָר, אַנְתְּ יַדְעַת מֵאוֹרַיְתָא דִּיְהוּדָאֵי. אֲמַר לֵיהּ יָדַעְנָא. אֲמַר לֵיהּ, לֵית אַתּוּן אַמְרִין דִּמְהֵימְנוּתָא דִּלְכוֹן קְשׁוֹט, וְאוֹרַיְיתְכוֹן קְשׁוֹט, וַאֲנָן דִּמְהֵימְנוּתָא דִּילָן שֶׁקֶר, וְאוֹרַיְיתָא דִּילָן שֶּׁקֶר. וְהָא כְּתִיב שְׂפַת אֱמֶת תִּכּוֹן לָעַד וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר. אֲנָן מִיּוֹמִין דְּעָלְמָא, קַיְימִין בְּמַלְכוּתָא, וְלָא אַעְדִּי מִינָן לְעָלְמִין, דָּרָא בָּתַר דָּרָא, תִּכּוֹן לָעַד וַדַּאי. וְאַתּוּן, זְעֵיר הֲוָה לְכוּ מַלְכוּתָא, וּמִיַּד אַעְדֵּי מִנְּכוֹן, וּקְרָא אִתְקָיָּים בְּכוּ דִּכְתִּיב וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר.</p>\n<p>אֲמַר לֵיהּ, חֲמֵינָא בָּךְ דְּאַנְתְּ חַכִּים בְּאוֹרַיְיתָא. תִּפַּח רוּחֵיהּ <Nonei></i>דְּהַהוּא גַּבְרָא. אִלּוּ אָמַר קְרָא, שְׂפַת אֱמֶת כּוֹנַנְתָּ לָעַד, הֲוָה כִּדְקַאמְרָן, אֲבָל לָא כְּתִיב אֶלָּא תִּכּוֹן, זְמִינָא שְׂפַת אֱמֶת דְּתִכּוֹן, מַה דְּלָאו הָכִי הַשְׁתָּא, דְּהַשְׁתָּא שְׂפַת שֶׁקֶר קַּיְימָא, וּשְׂפַת אֱמֶת שְׁכִיבָא לְעַפְרָא, וּבְהַהוּא זִמְנָא דֶּאֱמֶת יְקוּם עַל קִיוּמֵיהּ, וּמִגּוֹ אֶרֶץ תִּצְמַח, כְּדֵין שְׂפַת אֱמֶת תִּכּוֹן לָעַד וְגוֹ'.</p>\n<p>אֲמַר לֵיהּ הַהוּא הֶגְמוֹן, זַכָּאָה אַנְתְּ. וְזַכָּאָה עַמָּא דְּאוֹרַיְיתָא דִּקְשׁוֹט יָרְתִין. בָּתַר יוֹמִין שְׁמַעְנָא דְּאִתְגְּיַיר. אָזְלוּ, מָטוּ חַד בֵּי חֲקָל, וְצַלּוּ צְלוֹתֵהוֹן. כֵּיוָן דְּצַלּוּ צְלוֹתֵהוֹן, אָמְרוּ מִכָּאן וּלְהָלְאָה נִתְחַבֵּר בִּשְׁכִינְתָּא, וְנֵזִיל וְנִתְעַסֵּק בְּאוֹרַיְיתָא.</p>"],[9520011825,"<p>פָּתַח רִבִּי יוֹסֵי וְאָמַר, (ישעיהו מ״א:י״א) הֵן יֵבוֹשׁוּ וְיִכָּלְמוּ כֹּל הַנֶּחרִים בָּךְ וְגוֹ'. זַמִין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד לְיִשְׂרָאֵל, כָּל אִינּוּן טָבָאן, דְּקָאָמַר עַל יְדֵי נְבִיאֵי קְשׁוֹט, וְיִשְׂרָאֵל סָבְלוּ עֲלֵיהוֹן, כְּמָה בִּישִׁין בְּגָלְוּתְהוֹן. וְאִלְמָלֵא כָּל אִינּוּן טָבָאן דְּקָא מְחַכָּאן וְחָמָאן כְּתִיבִין בְּאוֹרַיְיתָא, לָא הֲווֹ יַכְלִין לְמֵיקָם וּלְמִסְבַּל גָּלוּתָא.</p>\n<p>אֲבָל אַזְלִין לְבֵי מִדְרָשׁוֹת, פַּתְחִין סִפְרִין, וְחָמָאן כָּל אִינּוּן טָבָאן, דְּקָא מְחַכָּן, וְחָמָאן כְּתִיבִין בְּאוֹרַיְיתָא, דְּאַבְטַח לוֹן קוּדְשָׁא בְּרִיךְ הוּא עָלַיְיהוּ, וּמִתְנַחֲמִין בְּגָלְוּתְהוֹן, וּשְׁאַר עַמִין מְחָרְפִין וּמְגַּדְפִין לוֹן, וְאַמְרֵי אָן הוּא אלָהֲכוֹן, אָן אִינּוּן טָבָאן דְּאַתּוּן אַמְרִין דִּזְמִינִין לְכוֹן, וְכִי כָּל עַמִּין דְּעָלְמָא יִכְסְפוּן מִנַּיְיכוּ.</p>\n<p>הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ו:ה׳) שִׁמְעוּ דְּבַר יְיָ' הַחֲרֵדִים אֶל דְּבָרוֹ אָמְרוּ אֲחֵיכֶם שׂוֹנְאֵיכֶם וְגוֹ'. מַאי הַחֲרֵדִים אֶל דְּבָרוֹ, אִינּוּן דְּסַבְלוּ כַּמָה בִּישִׁין, כַּמָה שְׁמוּעוֹת שַׁמְעֵי, אִלֵּין עַל אִלֵּין, וְאִלֵּין בָּתַר אִלֵּין, וְחַרִידָן עֲלֵיהוֹן, כְּמָה דְאַתְּ אָמֵר (ירמיהו ל׳:ה׳) כִּי וְגוֹ' קוֹל חֲרָדָה שָׁמָעְנוּ פַּחַד וְאֵין שָׁלוֹם וְגוֹ'. אִינּוּן חַרֵדִים תָּדִיר אֶל דְּבָרוֹ כַּד אִתְעָבִיד דִּינָא.</p>\n<p>אָמְרוּ אֲחֵיכֶם שׂוֹנְאֵיכֶם, אִלֵּין אִינּוּן אֲחוּכוֹן בְּנֵי עֵשָׂו. מְנַדֵּיכֶם, כְּמָה דְאַתְּ אָמֵר (איכה ד׳:ט״ו) סוּרוּ טָמֵא קָרְאוּ לָמוֹ. דְּלֵית עַמָּא דְּקָא מְבַזִּין לוֹן בְּאַנְפֵּי, וּמְרַקְּקִין בְּאַנְפַּיְיהוּ לְיִשְׂרָאֵל כִּבְנֵי אֱדוֹם. וְאַמְרֵי כֻּלְּהוּ מִסְאֲבִין כַּנִּדָּה, וְדָא אִיהוּ מְנַדֵּיכֶם. לְמַעַן שְׁמִי יִכְבַּד יְיָ', אֲנָן (דאמרין) בְּנוֹי דְּאֵל חַי. דִּי בָּן יִתְיָיקָר שְׁמֵיהּ. אֲנָן שַׁלְטָנִין עַל עָלְמָא בְּגִין הַהוּא דְּאִקְרֵי גָּדוֹל. (בראשית כ״ז:ה׳) עֵשָׂו בְּנוֹ הַגָּדוֹל. וּבִשְׁמָא דָּא אִקְרֵי קוּדְשָׁא בְּרִיךְ הוּא גָּדוֹל, (תהילים קמ״ה:ג׳) גָּדוֹל יְיָ' וּמְהוּלָּל מְאֹד. אֲנָן בְּנֵי הַגָּדוֹל, וְאִיהוּ גָּדוֹל. וַדַּאי לְמַעַן שְׁמִי יִכְבַּד יְיָ'.</p>\n<p>אֲבָל אַתּוּן זְעִירִין מִכֹּלָּא, (בראשית כ״ז:ט״ו) יַעֲקֹב בְּנָהּ הַקָּטָן כְּתִיב, אָן הוּא אֱלָהֲכוֹן. אָן הוּא אִינּוּן טָבָאן, דְּיִכְסְפוּן כָּל עֲמַמְיָא מֵחֶדְוָה דִּלְכוֹן. מַאן יִתֵּן וְנִרְאֶה בְשִׂמְחַתְכֶם כְּמָה דְּאַתּוּן אַמְרִין. וְהֵם יֵבוֹשׁוּ (רוח הקדש אומר והם יבושו) (ס\"א תו כמאן) כְּמַאן דְּתָלֵי קִלְלָתָא בְּאַחֲרָא, בְּגִין דְּאַתּוּן אַמְרִין דִּכְדֵין יֵבוֹשׁוּ וְיִכָּלְמוּ, וּבְגִין דָּא רוּחַ קֻדְשָׁא הֲוָה אָמַר מִלָּה הָכִי, וְעַל דָּא, הֵן יֵבוֹשׁוּ וְיִכָּלְמוּ כֹּל הַנֶּחרִים בָּךְ. מַאי כֹּל הַנֶּחֱרִים בָּךְ. דְּאִתְקָפוּ נְחִירֵיהוֹן בְּרוּגְזָא עֲלָךְ בְּגָלוּתָא דָּא. בְּהַהוּא זִמְנָא, יֵבוֹשׁוּ וְיִכָּלְמוּ מִכָּל טָבִין דִּיֶחמוּן לְהוֹן לְיִשְׂרָאֵל.</p>"],[9520011826,"<p>אָמַר רִבִּי חִיָּיא הָכִי הוּא וַדַּאי, אֲבָל חֲמֵינָן וְהָכִי חָמוּ תַּקִיפֵי עָלְמָא, דְּהָא גָּלוּתָא אִתְמְשָׁךְ וַעֲדַיִין בְּרֵיהּ דְּדָוִד לָא אָתֵי. אָמַר רִבִּי יוֹסֵי, וְכָל דָּא הָכִי הוּא, אֲבָל מַאן עָבִיד דְּיִסְבְּלוּן יִשְׂרָאֵל גָּלוּתָא דָּא, כָּל אִינּוּן הַבְטָחוֹת דְּאַבְטַח לוֹן קוּדְשָׁא בְּרִיךְ הוּא. וְהָא אִתְּמַר, דְּעָאלִין לְבָתֵּי כְּנֵסִיּוֹת וּלְבָתֵי מִדְרָשׁוֹת, וְחָמָאן כָּל אִינּוּן נֶחָמוֹת, וְחָדָאן בְּלִבַּיְיהוּ לְמִסְבַּל כָּל מַה דְּיֵיתֵי עָלַיְיהוּ, וְאִלְמָלֵא דָּא לָא יַכְלִין לְמִסְבַּל.</p>\n<p>אָמַר רִבִּי חִיָּיא וַדַּאי הָכִי אִיהוּ, וְכֹלָּא בִּתְשׁוּבָה תַּלְיָא. וְאִי תֵּימָא דְּיִכְלוּן הַשְׁתָּא לְאַתְעָרָא תְּשׁוּבָה כֻּלְּהוּ כַּחֲדָא. לָא יַכְלִין. מַאי טַעְמָא לָא יַכְלִין. בְּגִין דִּכְתִּיב, (דברים ל׳:א׳) וְהָיָה כִּי יָבֹאוּ עָלֶיךָ כָּל הַדְּבָרִים הָאֵלֶּה. וּכְתִּיב וַהֲשֵׁבוֹתָ אֶל לְבָבֶךָ בְּכָל הַגּוֹיִם אֲשֶׁר הִדִּיחֲךָ וְגוֹ'. וּכְתִיב וְשַׁבְתָּ עַד יְיָ' אֱלֹהֶיךָ וְגוֹ'. וּכְדֵין (דברים ל׳:ד׳) אִם יִהְיֶה נִדַּחֲךָ בִּקְצֵה הַשָּׁמָיִם מִשָּׁם יְקַבֶּצְךָ וְגוֹ'. וְעַד דְּכָל אִינּוּן מִלִּין לָא יִתְקַיְּימוּן, לָא יַכְלִין <Nonei></i>לְאַתְעֲרָא תְּשׁוּבָה מִנַּיְיהוּ.</p>\n<p>אָמַר רִבִּי יוֹסֵי, כַּמָה סַתָמְתְּ כָּל אָרְחִין וּשְׁבִילִין מִכָּל בְּנִי גָּלוּתָא, וְלָא שַׁבְקַת לוֹן פִּתְחוֹן פֶּה. אִי הָכִי, לִהווֹ כְּמָה דַּהֲווֹ בְּכָל דָּרָא וְדָרָא, דְּלָא יִסְבְּלוּן גָּלוּתָא וְלָא אַגְרָא, וְיִפְקוּן (ס\"א אי הכי, להוו כמה דלהון בכל דרא ודרא, יסבלון גלותא ולא יפקון) מִדִּינָא דְּאוֹרַיְיתָא, וְיִתְעָרְבוּן בִּשְׁאַר עַמִּין.</p>\n<p>פָּתַח וְאָמַר, (ישעיהו כ״ו:י״ז) כְּמוֹ הָרָה תַּקְרִיב לָלֶדֶת תָּחִיל תִּזְעַק בַּחֲבָלֶיהָ וְגוֹ'. מַאי כְּמוֹ הָרָה, אָרַח אִיהוּ לְעוּבַּרְתָּא, לְאַעְבְּרָא עָלָהּ תֵּשַׁע יַרְחִין שְׁלֵמִין. וְאִית בְּעָלְמָא כַּמָה וְכַמָּה, דְּלָא עָבַר עָלָהּ אֶלָּא יוֹמָא חַד אוֹ תְּרֵין יוֹמִין מִתְּשִׁיעָאָה, וְכָל צִירִין וַחֲבָלִין דְּעוּבַּרְתָּא בִּתְשִׁיעָאָה אִינּוּן. וְאַף עַל גַּב דְּלָא אַעְבַּר עָלָהּ אֶלָּא יוֹמָא חֲדָא, אִתְחֲשִׁיב עָלָהּ כְּאִילּוּ אִתְעֲבָרוּ כָּל תְּשִׁיעָאָה שְׁלִים. אוּף הָכִי יִשְׂרָאֵל, כֵּיוָן דְּאִטְעַמֵי טַעַם גָּלוּתָא, אִי יָהַדְרוּן בִּתְשׁוּבָה, יִתְחֲשָׁב עָלַיְיהוּ כְּאִלּוּ אַעְבְּרוּ עָלַיְיהוּ כָּל אִינּוּן מִלִּין דִּכְתִּיבִין בְּאוֹרַיְיתָא. כָּל שֶׁכֵּן וְכָּל שֶׁכֵּן דְּכַמָּה וְכַמָּה יִסּוּרִין אַעְבְּרוּ עָלַיְיהוּ מִן יוֹמָא דְּגָלוּתָא שָׁרֵי.</p>\n<p>אֲבָל מַאי דִּכְתִּיב, (דברים ד׳:ל׳) בַּצַּר לְךָ וּמְצָאוּךָ כֹּל הַדְּבָרִים הָאֵלֶּה בְּאַחֲרִית הַיָּמִים. תָּא חֲזֵי, כַּמָּה רַחֲמָנוּתָא רָחִים קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל בְּמִלָּה דָּא. לְמַלְכָּא דְּהֲוָה לֵיהּ בְּרָא יְחִידָאָה, וְרָחִים לֵיהּ רְחִימוּ דְּנַפְשָׁא, וּמִגּוֹ רְחִימוּ דִּילֵיהּ, יָהַב לֵיהּ לְאִמֵּיהּ מַטְרוֹנִיתָא דִּתְרַבֵּי לֵיהּ, וְתוֹלִיף לֵיהּ אָרְחֵי מְתַתְקְנָן. זִמְנָא חֲדָא חָב לְגַבֵּי אֲבוּהָ, אָתָא אַבוֹהִי וְאַלְקֵי לֵיהּ, וּלְבָתַר אַעְבָּר עַל חוֹבֵיהּ. תָּב כְּמִלְּקַדְּמִין וְחָב לַאֲבוּהָ, וְאַפְקֵיהּ אֲבוּהָ מִבֵּיתֵיהּ, וְאַרְגִּיז עָלֵיהּ, נָפַק הַהוּא בְּרָא מִבֵּיתֵיהּ.</p>\n<p>וּבְאֲתָר דִּיְּהַךְ בְּאֹרַח קְשׁוֹט, וִיהֵא זַכָּאָה כְּדְקָא יֵאוֹת, בְּגִין דְּיִשְׁמַע מַלְכָּא אָבוּהָ, וִיהֵא תִּיאוּבְתֵּיהּ עָלֵיהּ. מָה עֲבַד. אָמַר הוֹאִיל וְנָפַקְנָא מֵהֵיכָלָא דְּאַבָּא, אַעְבִיד מִכָּאן וּלְהָלְאָה כָּל מָה דַּאֲנָא בָּעֵי. מָה עֲבַד. אָזַל וְאִתְחַבָּר בְּזוֹנוֹת, וְאִתְלַכְלָךְ בְּלִכְלוּכָא דְּטִנּוּפָא בַּהֲדַיְיהוּ, וְלָא הֲוָה מִשְׁתְּכַח אֶלָּא בַּהֲדַיְיהוּ, בְּחִבּוּרָא דִּלְהוֹן. דְּמַטְרוֹנִיתָא אִמֵּיהּ פַּקְדַת בְּכָל יוֹמָא עַל הַהוּא בְּרָא, וְיַדְעַת דִּבְרָהּ בַּהֲדֵי זוֹנוֹת אִתְחַבָּר, וְכָל חַבְרוּתָא דִּידֵיהּ בַּהֲדַיְיהוּ הֲוָות. שָׁרִיאַת לְמִבְכֵּי, וּלְאִתְמָרְרָא עַל בְּרָהּ.</p>\n<p>יוֹמָא חַד עָאל מַלְכָּא לְגַבָּהּ, חָמָא לָהּ דְּאִיהִי מְבַכָּה. שָׁאִיל לָהּ עַל מָה אַתְּ בָּכָאת. אָמְרָה וְלָא אֶבְכֶּה, דְּהָא בְּרָנָא לְבַר מְהֵיכָלָא דְּמַלְכָּא. וְלָא דַּי דְּהוּא לָא יָתִיב בְּהֵיכָלָא דְּמַלְכָּא, אֶלָּא דְּהוּא יָתִיב בַּהֲדֵי זוֹנוֹת. מַה יֵימְרוּן כָּל בְּנֵי עָלְמָא, בְּרֵיהּ דְּמַלְכָּא אִיהוּ דְּיָתִיב בְּבֵי זוֹנוֹת. שְׁרִיאַת לְמִבְכֵּי, וּלְאִתְחַנְּנָא לְמַלְכָּא. אָמַר מַלְכָּא, בְּגִינָךְ אַהְדָּר לֵיהּ, וְאַנְתְּ עַרְבָא דִּילֵיהּ. אַמְרַת הָא וַדַּאי.</p>\n<p>אָמַר מַלְכָּא הוֹאִיל וְכַךְ הוּא, לָא אִצְטְרִיךְ לְאָהַדְּרָא לֵיהּ בִּימָמָא בְּאִתְגַּלְּיָא. דְּכִסּוּפָא דִּילָן אִיהוּ לְמֵהַךְ בְּגִינִיהּ לְבֵי זוֹנוֹת. וְאִי לָא הֲוֵי כְּגַוְונָא דָּא, דְּטִנֵף גַּרְמֵיהּ הָכִי וְחִלֵּל יְקָרִי. הֲוֵינָא אֲנָא, וְכָל חַיָּילִין דִּילִי, אַזְלִין בְּגִינֵיהּ בְּכַמָּה יְקָר, בְּכַמָּה בּוּקִינָס קָמֵיהּ, בְּכַמָּה מָאנֵי קְרָבָא, מִימִינֵיהּ וּמִשְׂמָאלֵיהּ, עַד דְּכָל בְּנִי עָלְמָא יִזְדַּעְזְעוּן, וְיִנְדְעוּן כֹּלָּא, דִּבְּרָא דְּמַלְכָּא אִיהוּ. הַשְּׁתָּא כֵּיוָן דְּאִיהוּ טִנֵף גַּרְמֵיהּ, וְחִלֵּל יְקָרִי, אִיהוּ יֶהְדַּר בִּטְמִירוּ, דְּלָא יִנְדְּעוּן בֵּיהּ. אַהְדָּר לְגַבֵּי מַלְכָּא, יָהֲבֵיהּ לְגַבֵּי אִמֵּיהּ.</p>\n<p>לְיוֹמִין סָרַח כְּמִלְּקַדְּמִין. מָה עֲבַד מַלְכָּא. אַפִּיק לֵיהּ וּלְאִמֵּיהּ בַּהֲדֵיהּ מִגּוֹ הֵיכָלָא, אָמַר תַּרְוַויְיכוּ תֵּהַכוּן, וְתַּרְוַויְיכוּ תִּסְבְּלוּן גָּלוּתָא, וּמַלְקִיוּתָא תַּמָּן. כֵּיוָן דְּתַרְוַויְיכוּ תִּסְבְּלוּן כַּחֲדָא, כְּדֵין יָדַעְנָא דִּבְרִי יְתוּב כַּדְקָא חֲזֵי.</p>\n<p>כַּךָ יִשְׂרָאֵל בְּנוֹי דְּמַלְכָּא קַדִּישָׁא אִינּוּן. אָחִית לוֹן לְמִצְרַיִם. וְאִי תֵּימָא בְּהַהוּא זִמְנָא לָא חָאבוּ, גְזֵרָה דְּגָזַר קוּדְשָׁא בְּרִיךְ הוּא בֵּין הַבְּתָרִים הֲוָה אִתְחָזֵי לְמֶהוֵי קַיָּים, וְקוּדְשָׁא בְּרִיךְ הוּא אַשְׁגַּח לִתְרֵין מִלִּין, חַד בְּגִין הַהוּא מִלָּה דְּאָמַר אַבְרָהָם, (בראשית ט״ו:ח׳) בַּמָה אֵדַע כִּי אִירָשֶׁנָּה, דָּא הוּא <Nonei></i>סִבָּה וְעִילָה. אֲבָל עַד דְּנַפְקוּ מִמִּצְרַיִם, לָא הֲוֵי גּוֹי, וְלָא אִתְחָזוּ כַּדְקָא יֵאוּת.</p>\n<p>פָּתַח וְאָמַר, (שיר השירים ב׳:ב׳) כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים כֵּן רַעְיָתִי בֵּין הַבָּנוֹת. בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד לוֹן לְיִשְׂרָאֵל כְּגַוְונָא דִּלְעֵילָּא וּלְמֶהֱוֵי שׁוֹשַׁנָּה חֲדָא בְּאַרְעָא, כְּגַוְונָא עִלָּאָה. וְשׁוֹשַׁנָּה דְּסַלְּקָא רֵיחָא, וְאִתְבְּרִיר מִכָּל שְׁאַר וְורָדִין דְּעָלְמָא, לָא הֲוֵי אֶלָּא הַהִיא דְּסַלְּקָא בֵּין הַחוֹחִים. וְדָא אָרְחָא כְּדְקָא יֵאוֹת. וְעַל דָּא זָרַע שִׁבְעִין זוּגִין, דַּהֲווֹ שִׁבְעִין נֶפֶשׁ, וְאָעִיל לוֹן בֵּין הַחוֹחִים, וְאִינּוּן חוֹחִים, מִיַּד דַּהֲווֹ אִינּוּן זוּגִין תַּמָּן, סְלִיקוּ עַנְפִין וְטַרְפִּין וּשְׁלִיטוּ עַל עָלְמָא, וּכְדֵין פַּרְחַת שׁוֹשַׁנָה בֵּינַיְיהוּ.</p>\n<p>כֵּיוָן דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַפָּקָא שׁוֹשַׁנָה וְלָקִיט לָהּ מִבֵּינַיְיהוּ, כְּדֵין יָבְשׁוּ חוֹחִים, וְאִזְדְרִיקוּ, וְאִשְׁתֵּצִיאוּ, וְלָא אִתְחַשְׁבוּ לִכְלוּם. בְּשַׁעֲתָא דְּאָזִיל לְמִלְקַט שׁוֹשַׁנָה דָּא, לְאַפָּקָא בְּרֵיהּ בּוּכְרֵיהּ, בְּהַהוּא זִמְנָא אָזַל מַלְכָּא גּוֹ כַּמָה חַיָּילִין רַבְרְבָנִין וְשַׁלִּיטִין, עִם דְּגָלִין פְּרִישָׂן, וְאַפִּיק לִבְרֵיהּ בּוּכְרֵיהּ בְּכַמָּה גְּבוּרִין, וְאַיְיתֵי לֵיהּ לְהֵיכָלֵיהּ, וְיָתִיב סַגִּי בְּבֵי מַלְכָּא.</p>\n<p>כֵּיוָן דְּחַב לְגַבֵּי אֲבוּהָ, אוֹכַח לֵיהּ, וְאַלְקֵי לֵיהּ, דִּכְתִּיב, (שופטים ב׳:י״ד) וַיִּחַר אַף יְיָ' בְּיִשְׂרָאֵל וַיִּתְּנֵם בְּיַד שׁוֹסִים וְגוֹ', סָרַח כְּמִלְּקַדְּמִין, וּמָרַד בְּאָבוּהָ, אַפְקֵיהּ מִבֵּיתֵיהּ. מַה עַבְדוּ יִשְׂרָאֵל, חָמוּ דְּהָא אִתְבַּדְרוּ לְבָבֶל, אִתְעָרְבוּ בְּעַמְמַיָא, נָסִיבוּ נָשִׁין נָכְרִיּוֹת, וְאוֹלִידוּ בְּנִין מִנְּהוֹן. עִם כָּל דָּא, אִימָא קַדִּישָׁא הֲוַת אַפֹּטְרוֹפּוֹסָא עָלַיְיהוּ.</p>\n<p>וְעַל דְּעָבַד הָכִי, קוּדְשָׁא בְּרִיךְ הוּא אָמַר, הוֹאִיל וְכִסּוּפָא אִיהוּ, לֵיתֵי בְּרִי אִיהוּ מִגַּרְמֵיהּ, הוֹאִיל וְחִלֵּל יְקָרִי, לָא אִתְחָזֵי דְּאָנָא אֵיזִיל תַּמָּן לְאַפָּקָא לֵיהּ, וּלְמֶעְבַּד לֵיהּ נִסִּין וּגְבוּרָן כְּמִלְּקַדְּמִין. תָּבוּ אִינּוּן, בְּלָא סִיּוּעָא דְּאִתְחָזוּ לוֹן, בְּלָא פְּלִיאָן וְנִסִּין, אֶלָּא כֻּלְּהוּ מִתְבַּדְּרָן, כֻּלְּהוּ לְאָן בְּמִסְכְּנוּ, וְתָבוּ לְהֵיכָלָא דְּמַלְכָּא בְּכִסּוּפָא, וְאֵימָא קַדִּישָׁא עַרְבַת לוֹן.</p>"],[9520011827,"<p>חָאבוּ כְּמִלְּקַדְּמִין. מָה עֲבַד קוּדְשָׁא בְּרִיךְ הוּא. אַפִּיק לְהַאי בְּרָא כְּמִלְּקַדְּמִין מְהֵיכָלֵיהּ, וְאִימֵּיהּ בַּהֲדֵיהּ. אָמַר, מִכָּאן וּלְהָלְאָה, אִימָא וּבְרָהּ יִסְבְּלוּן כַּמָה בִּישִׁין כַּחֲדָא, הֲדָא הוּא דִכְתִיב, (ישעיה ג) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. וְעַל דָּא כְּתִיב, (דברים ד׳:ל׳) בַּצַּר לְךָ וּמְצָאוּךָ כֹּל הַדְּבָרִים הָאֵלֶּה בְּאַחֲרִית הַיָּמִים. מַאי בְּאַחֲרִית הַיָּמִים. אֶלָּא דָּא הִיא אִימָא קַדִּישָׁא, דְּהִיא אַחֲרִית הַיָּמִים, וְעִמָּהּ סַבְלוּ כָּל מָה דְּסַבְלוּ בְּגָלוּתָא.</p>\n<p>וְאִילּוּ יְהַדְרוּן בְּתִיּוּבְתָא, אֲפִילּוּ חַד בִּישׁ, אוֹ חַד צַעֲרָא, דִּיעָבַר עָלַיְיהוּ, אִתְחֲשֵׁב עָלַיְיהוּ, כְּאִלּוּ סַבְלוּ כֹּלָּא (ס\"א ואי לאו סתים קיצא) וְאִי לָא, כַּד יִסְתַּיֵים קִיצָא, (בישא) וְכָל דָּרִין דִּילֵיהּ. כְּמָה דְּאָמַר בּוּצִינָא קַדִּישָׁא, דִּכְתִּיב, (ויקרא כ״ה:ל׳) לִצְּמִיתוּת לַקּוֹנֶה אוֹתוֹ לְדוֹרוֹתָיו. וְכָל דָּא, בְּתִיּוּבְתָא תַּלְיָא מִילְּתָא. אָמַר רִבִּי חִיָּיא, וַדַּאי הָכִי הוּא. וְעַל דָּא גָּלוּתָא אִתְמְשָׁךְ.</p>\n<p>אֲבָל קוּדְשָׁא בְּרִיךְ הוּא, כָּל מָה דְּחָמֵי (ס\"א דמתא) (נ\"א דלקא) לוֹן לְיִשְׂרָאֵל, בְּהַאי אַחֲרִית הַיָּמִים, וּבְהַאי אַחֲרִית הַיָּמִים יַעֲבִיד לוֹן נִסִּין וְנוּקְמִין, דִּכְתִּיב, (ישעיהו ב׳:ב׳) וְהָיָה בְּאַחֲרִית הַיָּמִים נָכוֹן יִהְיֶה הַר בֵּית יְיָ' בְּרֹאשׁ הֶהָרִים. מַאן רֹאשׁ הֶהָרִים. דָּא אַבְרָהָם סָבָא, (רנ\"ב ע\"ב) כַּהֲנָא רַבָּא, רֹאשׁ דְּכֹלָּא. וּבְגִין דְּאִיהוּ רֹאשׁ, כּוֹס דִּבְרָכָה, יִהְיֶה נָכוֹן בְּרֹאשׁ הֶהָרִים, דָּא אַבְרָהָם סָבָא, קַדְמָאָה לִשְׁאַר הֶהָרִים. כּוֹס דִּבְרָכָה, אִצְטְרִיךְ לְמֶהֱוֵי מְתַקְּנָא בִּימִינָא.</p>\n<p>(רנ\"ב ע\"ב) וְנִשָּׂא (קי\"ב ע\"ב) מִגְּבָעוֹת. אִצְטְרִיךְ לְמֶהוֵי זָקִיף מִן פַּתּוֹרָא, שִׁיעוּרָא דְּאִקְרֵי (ס\"א דאיהו) זֶרֶת, לְבָרְכָא לְקוּדְשָׁא בְּרִיךְ הוּא, וְדָא הוּא וְנִשָּׂא מִגְּבָעוֹת. מִגְּבָעוֹת מַאי הוּא. אֶלָּא בֵּינָה, וּבֵין בְּתוּלוֹת אַחֲרֶיהָ רְעוֹתֵיהָ, שִׁיעוּרָא דְּזֶרֶת אִיהוּ. נִשָׂא כּוֹס דִּבְרָכָה מִגְּבָעוֹת וַדַּאי, וְעַל דָּא טָבָא דִּיהֵא לֵיהּ לְהַאי בְּרָא בּוּכְרָא, בְּאַחֲרִית הַיָּמִים אִיהוּ.</p>\n<p>אֲמַר לֵיהּ שַׁפִּיר קָאַמָרְתְּ, הַאי קְרָא וַדַּאי הָכִי הוּא. בְּרֹאשׁ הֶהָרִים, דָּא יְמִינָא, אַבְרָהָם סָבָא, דְּאִיהוּ רֹאשׁ הֶהָרִים וַדַּאי. וְנִשָּׂא מִגְּבָעוֹת, מִשִּׁיעוּרָא דִּגְבָעוֹת, דְּאִינּוּן רְעוּתֵיהּ. וְשַׁפִּיר קָאָמְרֵת. (ישעיהו ב׳:ב׳) וְנָהֲרוּ אֵלָיו כָּל הַגּוֹיִם. מַאי הוּא. אֲמַר לֵיהּ, וַאֲפִילּוּ נָשִׁים וּקְטַנִּים וְשַׁמָּשׁ דְּפָלַח עַל פַּתּוֹרָא, אַף עַל גַּב דְּאִיהוּ לָא אָכַל, אִצְטְרִיךְ לְמִשְׁמַע, וּלְמֵימָר אָמֵן. (ס\"א להריק ברכה לכוס דלא וכו') דְּלָא יִיִמָא בַּר נָשׁ, אֲנָא לָא אֲכָלִית, וְהוֹאִיל <Nonei></i>דְּלָא אִצְטְרִיפְנָא לְזִמּוּן, לָא אֶשְׁמַע וְלָא אֵימָא אָמֵן. הַכֹּל חַיָּיבִין בֵּיהּ.</p>\n<p>דָּבָר אַחֵר וְנָהֲרוּ אֵלָיו כָּל הַגּוֹיִם, אַף עַל גַּב דְּנָשִׁים וּקְטַנִים פְּטוּרִין מִן הַמִּצְוֹת, בְּכוֹס דִּבְרָכָה הַכֹּל חַיָּיבִין, בִּלְבַד דְּיִנְדְּעוּן לְמַאן מְבָרְכִין, וְדָא הִיא וְנָהֲרוּ אֵלָיו כָּל הַגּוֹיִם. אָתָא רִבִּי יוֹסֵי וּנְשָׁקֵיהּ, אָמַר כַּמָה שַׁפִּיר מִלָּה דָּא, וּמְתִיקָא לְחִכָּא.</p>\n<p>הַשְׁתָּא אִית לְדַיְיקָא, אִי הַאי אַחֲרִית הַיָּמִים, אִיהוּ כּוֹס דִּבְרָכָה מַמָּשׁ, מַהוּ הַר בֵּית יְיָ', הֲוָה לֵיהּ לְמִכְתַּב הָכִי, וְהָיָה אַחֲרִית הַיָּמִים נָכוֹן יִהְיֶה בְּרֹאשׁ הֶהָרִים. מַהוּ בְּאַחֲרִית הַיָּמִים נָכוֹן יִהְיֶה הַר בֵּית יְיָ'. אֲמַר לֵיהּ, אַחֲרִית הַיָּמִים אִיהוּ אִילָנָא כֹּלָּא, מֵרֵישֵׁיהּ וְעַד סֵיפֵיהּ, דְּהוּא אִילָנָא דְּטוֹב וָרָע. וְאָתָא קְרָא לְבָרְרָא בְּאַחֲרִית הַיָּמִים, וְאַפִּיק הַר בֵּית יְיָ', דָּא טוֹב בְּלָא רָע. הַר בֵּית יְיָ' וַדַּאי דְּלֵית תַּמָּן חוּלָקָא לְסִטְרָא אַחֲרָא, דְּהָא אִתְבְּרִיר הַר בֵּית יְיָ', מִגּוֹ אִילָנָא דְּאִיהוּ אַחֲרִית הַיָּמִים. וְדָא אִיהוּ כּוֹס דִּבְרָכָה, דְּאִיהוּ נָכוֹן בְּרֹאשׁ הֶהָרִים.</p>\n<p>אָמַר רִבִּי יוֹסֵי, זַכָּאָה אָרְחָא דָּא, דְּזָכֵינָא לְהַאי מִלָּה. אֲמַר לֵיהּ מִמָּאן שַׁמְעַת לָהּ. אֲמַר לֵיהּ, יוֹמָא חֲדָא הֲוֵינָא אָזִיל בְּאָרְחָא, וּשְׁמַעְנָא וַחֲמֵינָא לֵיהּ לְרַב הַמְנוּנָא סָבָא, (נ\"א לרבי שמעון) דְּהֲוָה דָּרִישׁ לְהַאי קְרָא לְרִבִּי אָחָא, וְכֵיוָן דְּשָׁמַעְנָא חַדֵּינָא בֵּיהּ, וּנְטִירְנָּא לֵיהּ צָרִיר בְּכַנְפָא דִּלְבוּשָׁאִי, דְּלָא יִתְעֲדֵי מִנַּאי לְעָלְמִין. אֲמַר לֵיהּ, וַדַּאי מִלָּה קַדִּישָׁא דָּא, מִנְּהִירוּ דְּבוּצִינָא קַדִּישָׁא אִתְנְהִיר. זַכָּאָה דָּרָא, דְּקַיְימֵי עָלְמָא וְסַמְכוֹי, שַׁרְיָין בְּגַוֵּיהּ. וְאִי אַנְתְּ צְּרִירַת לְהַאי מִלָּה בְּקִשְׁרָא חֲדָא דְּלָא יִתְעֲדֵי מִינָךְ. אֲנָא אֶצְרוֹר לָהּ בִּתְלָּתִין, אוֹ בְּאַרְבְּעִין קִשְׁרִין בְּכִיסָאִי, דְּלָא יִתְעֲדֵי מִינַּאי לְעָלְמִין. (כאן חסר).</p>\n<p>עַל הַהִיא מִלָּה דְּאַחְמֵי קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, בְּגִין דְּאַף עַל גַּב דְּיִשְׂרָאֵל חָבִין קָמֵיהּ בְּכָל דָּרָא וְדָרָא, לָא בָּעֵי מַאן דְּיֵימָא עָלַיְיהוּ דַּלְטוֹרִין. מְנָלָן. מְהוֹשֵׁעַ, דִּכְתִּיב, (הושע א׳:ב׳) תְּחִלַּת דִּבֶּר יְיָ' בְּהוֹשֵׁעַ, הָא אוּקְמוּהָ מִלָּה. וְעַל דָּא (הושע ב׳:א׳) וְהָיָה מִסְפָּר בְּנֵי יִשְׂרָאֵל כְּחוֹל הַיָּם וְגוֹ'. וּבְגִין דָּא בָּרִיךְ לוֹן בְּכַמָּה בִּרְכָּאן, לְאָהַדְּרָא בְּתִיּוּבְתָּא, וּלְאָתָבָא לוֹן לְגַבֵּי אֲבוּהוֹן דְּבִשְׁמַיָּא, וְלָא אַעְדֵּי מִתַּמָּן, עַד דְּקוּדְשָׁא בְּרִיךְ הוּא מָחַל עַל חוֹבַיְיהוּ, וְאִתְנְקִיאוּ קָמֵיהּ.</p>"],[9520011828,"<p>אֵלִיָּהוּ מָה כְּתִיב בֵּיהּ, (מלכים א י״ט:ד׳) וַיָּבֹא וַיֵּשֶׁב תַּחַת רֹתֶם אֶחָד וְגוֹ', אָמַר מָארֵיהּ דְּעָלְמָא, אִתְּתָא חֲדָא שַׁדְרַת לוֹן לְיִשְׂרָאֵל, וּדְבוֹרָה שְׁמָהּ, דִּכְתִּיב, (שופטים ד׳:ה׳) וְהִיא יוֹשֶׁבֶת תַּחַת תֹּמֶר דְּבוֹרָה. דָּא הוּא רֹתֶם, וְאָהַדְרַת לוֹן לְמוּטַב, דִּכְתִּיב, (שופטים ה׳:ז׳) עַד שַׁקַּמְתִּי דְּבוֹרָה. וְאָנָא עָאלִית בֵּינַיְיהוּ, וְאַכְרָזִית קָמַיְיהוּ וְלָא יָכִילְנָא.</p>\n<p>עַד דְּהֲוָה יָתִיב, אִתְגְּלֵי עָלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אֲמַר לֵיהּ מַה לְּךָ פֹה אֵלִיָּהוּ, בְּקַדְמִיתָא קָא הֲוֵית מְקַטְרְגָא וּמְקַנֵּי עַל בְּרִית, וּמִדְּחָמֵינָא בָּךְ דְּקַנִּית עָלַי בְּהַהוּא בְּרִית, נַטְלִית לֵיהּ בִּרְעוּ דְּמֹשֶׁה, וְיָהִיבְנָא לָךָ, עַד דְּמֹשֶׁה (רי\"ב ע\"א) הֲוָה אָמַר (במדבר כ״ה:י״ב) הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. הַשְׁתָּא דְּאִיהוּ דִּילָךְ, לָא אִתְחָזֵי לָךְ לְקַטְרְגָא עֲלוֹי, הֲוָה לְךָ לְמִשְׁבַּק קִנוּיָיךָ לִי, כְּמָה בְּקַדְמִיתָא דְּהֲוָה דִּילִי, שְׁבַקְנָא לֵיהּ לִידָא אַחֲרָא, וְלָא קַטְרִיגְנָא עֲלוֹי.</p>\n<p>מַה לְּךָ פֹה, מַאי פֹה. בְּרִית קַיָּימָא, פֶּה יְיָ' אִיהוּ. כֵּיוָן דְּלָא בָּעָאת לְשַׁבְקָא לִי פּוּמָךְ, יֵתוּב בַּאֲתָר דְּהַהוּא פּוּמָא. תְּנָן, בְּהַהִיא שַׁעֲתָא, אִתְעַבָּר מִנֵּיהּ הַהוּא נְבַזְבְּזָא דְּיָהַב לֵיהּ מֹשֶׁה. דִּתְנָן, מַאי דִּכְתִּיב, (מלכים א י״ט:ח׳) וַיֵּלֶךְ בְּכֹחַ הָאֲכִילָה הַהִיא וְגוֹ'. עַד הַר הָאֱלהִים חוֹרֵבָה. לְמִתְבַּע מִתַּמָּן, וְכִי מִתַּמָּן הֲוָה בָּעֵי. אֶלָּא לְמִתְבַּע כְּמִלְּקַדְּמִין, מֵהַהוּא דְּיָרִית בְּהַר הָאֱלהִים, בְּרִית דָּא. פִּנְחָס הוּא אֵלִיָּהוּ, וַדַּאי בְּדַרְגָּא חֲדָא. אֲמַר לֵיהּ מֹשֶׁה, לֵית אַנְתְּ יָכִיל לְקַבְּלָא מִנַּאי, אֶלָּא זִיל לְיַנּוֹקַיְּיהוּ דְּיִשְׂרָאֵל, וּמֵאִינּוּן תִּרְוָח, וְאִינּוּן יַהֲבֵי לָךְ, וְכַךְ הוּא עָבִיד. (חסר).</p>"],[9520011829,"<p>כַּמָה טִיבוּ עָבִיד קוּדְשָׁא בְּרִיךְ הוּא בְּכָל דָּרָא וְדָרָא לְיִשְׂרָאֵל. תָּא חֲזֵי, מָה כְּתִיב, (מיכה ו׳:ד׳) וָאֶשְׁלַח לְפָנְיךָ אֶת מֹשֶׁה אַהֲרֹן וּמִרְיָם. וְהָא כַּמָה נְבִיאֵי הֲווֹ לְבָתַר מֹשֶׁה, <Nonei></i>וָאֶשְׁלַח לְפָנְיךָ אֶת מֹשֶׁה אַהֲרֹן וְאֶלְעָזָר וּפִנְחָס יְהוֹשֻׁעַ וְאֵלִיָּהוּ וְאֱלִישָׁע, וְכַמָּה שְׁאַר צַדִּיקֵי וַחֲסִידֵי מִבָּעֵי לֵיהּ. אִלֵּין תְּלָתָא אֲמַאי. אֶלָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא, עַמִּי, בָּנַי, אֲמַאי לָא תִּדְכְּרוּן לְכָל טָבִין דַּעֲבָדִית לְכוּ, דְּשַׁדָּרִית לְכוּ לְמֹשֶׁה אַהֲרֹן וּמִרְיָם.</p>\n<p>לְמֶלֶךָ בָּשָׂר וָדָם, דְּאִית לֵיהּ מְדִּינְתָּא, וְשָׁדַר לְגַבָּהּ, גּוּבְרִין, אִפַּרְכִּין רַבְרְבָנִין, דִּיהוֹן מְנַהֲלֵי עַמָּא, וּמְעַיְינִין בְּהוּ, וּבְדִּינַיְיהוּ. מַאן אִצְטְרִיךְ לְמֶהֱוֵי זָקוּק בִּמְזוֹנַיְיהוּ, בְּמִלִּין דְּיִּצְטְרִכוּן. לָאו עַמָּא דִּמְדִּינְתָּא, בַּעַל כָּרְחַיְּיהוּ יִצְטְרָכוּ לְעַיְינָא בְּהוּ, וּלְמֵיהַב לְהוּ יְקָרָא.</p>\n<p>שַׁדָּרִית לְמֹשֶׁה, אִיהוּ אַיְיתֵי קָמַיְיכוּ מָן לְמֵיכַל, וְנָהִיל לְכוּ וּלְבָנַיְיכוּ וְלִבְעִירַיְיכוּ, וְאִשְׁתְּדַּל בְּדִינַיְיכוּ, (ס\"א במזונייכו) וּבְכָל מָה דְּאִצְטְרִיךְ לְכוּ. שַׁדָּרִית לְאַהֲרֹן, אַיְיתֵי (ס\"א לכו ענני) הֵיכָלִין דַּעֲנָנִי יְקָר לְחֹפָּאָה עָלַיְיכוּ, כְּמַלְכִין. אַסְחֵי לְכוּ בְּטַלֵּי יְקָר, דְּלָא אִתְרַקְבוּ לְבוּשֵׁיכוֹן וּמִנְעֲלֵיכוֹן, וַהֲווּ מִתְחַדְּשֵׁי בְּכָל יוֹמָא. שַׁדָּרִית לְמִרְיָם, אַיְיתִיאָת בֵּירָא לְאַשְׁקָאָה לְכוּ, וְשָׁתִיתוּן אַתּוּן וּבְעִירְכוֹן. אִינּוּן יָהַבוּ לְכוֹן, וּמִדִּלֵהוֹן אָכַלְתּוּן וְשָׁתִיתוּן, וִיְתִיבְתּוּן בְּחוּפָּאָה דִּיקָר דִּלְהוֹן. וּמִדִּלְכוֹן לָא יָהַבְתּוּן לוֹן. וְלא עוֹד, אֶלָּא דְּאִשְׁתַּדְּלוּ עֲלֵיכוֹן, וְנַטְלוּ עַל צַוָארֵיהוֹן מָטוּלְכוֹן, וַהֲוִיתוּן מְחָרְפִין וּמְגַּדְפִין לוֹן.</p>"],[9520011830,"<p>אָמַר רִבִּי יוֹסֵי, לָאו הֲוָה אַבָּא רַחֲמָן עַל בְּנוֹי כְּקוּדְשָׁא בְּרִיךְ הוּא, וּקְרָא הוּא דִּכְתִּיב, (מלכים א ח׳:נ״ו) לֹא נָפַל דָּבָר אֶחָד מִכֹּל דְּבָרוֹ הַטּוֹב וְגוֹ'. תָּא חֲזֵי רַחְמָנוּ דִּילֵיהּ, אִלּוּ אָמַר לֹא נָפַל דָּבָר אֶחָד מִכֹּל דְּבָרוֹ וְלָא יַתִּיר, נֹחַ לְעָלְמָא דְּלָא אִתְבְּרֵי. אֲבָל מִדְּאָמַר מִכֹּל דְּבָרוֹ הַטּוֹב, וְאַפִּיק בִּישׁ לַאֲחוֹרָא, דְּהָא מִלָּה דְּבִישׁ לָא בָּעֵי לְמֶעְבַּד.</p>\n<p>וְאַף עַל גַּב דְּאַגְזִים, וְאָרִים רְצוּעָה, אָתָאת אִמָא וְאִתָּקָפָת בִּדְרוֹעֵיהּ יְמִינָא, וְקָם רְצוּעָה בְּקִיּוּמֵיהּ, וְלָא נָחִית לְתַתָּא, וְלָא אִתְעַבִיד, בְּגִין דִּבְעֵיטָא חֲדָא הֲווֹ תַּרְוַויְיהוּ, אִיהוּ דְּאַגְזִים, וְאִיהוּ דַּאֲחִידַת בִּיְמִינֵיהּ.</p>\n<p>וְאִי תֵּימָא מְנָלָן. מִמִּלָּה דְּאִיהִי בְּאִתְגַּלְּיָא, דִּכְתִּיב לֵךְ רֵד כִּי שִׁחֵת עַמְּךָ, שָׂרֵי לְאָרָמָא רְצוּעָה, וּמֹשֶׁה דְּלָא הֲוָה יָדַע אָרְחָא דְּאִמָא, שָׁתִיק. כֵּיוָן דְּחָמָא קוּדְשָׁא בְּרִיךְ הוּא כַּךְ, אַנְקִיד לֵיהּ, וּבָטַשׁ בֵּיהּ וְאָמַר וְעַתָּה הַנִּיחָה לִּי, מִיָּד אַרְגִּישׁ מֹשֶׁה, וְאָחִיד בִּדְרוֹעֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב זְכוֹר לְאַבְרָהָם, דָּא דְּרוֹעֵיה יְמִינָא, וּבְּגִין כָּךְ לָא נָחִית רְצוּעָה.</p>\n<p>וְאִי תֵּימָא, אִמָא דְּאִיהִי רְגִּילָה לְאַחֲדָא בִּרְצוּעָה דְּמַלְכָּא, אָן הֲוַת, דְּשַׁבְקַת מִלָּה לְמֹשֶׁה. שָׁאִילְנָא וַאֲמֵינָא וְהָא לָא יְדַעְנָא בְּרִירָא דְּמִלָּה, עַד דְּנְהֱוֵי קָמֵיהּ דְּבוּצִינָא קַדִּישָׁא. כַּד אָתוּ לְקָמֵיהּ דְּרַבִּי שִׁמְעוֹן, חָמָא בְּאַנְפַּיְיהוּ סִימָן. אָמַר עוּלוּ בְּנֵי קַדִּישִׁין, עוּלוּ רְחִימִין דְּמַלְכָּא, עוּלוּ רְחִימִין דִּילִי, עוּלוּ רְחִימִין אִלֵּין בְּאִלֵּין.</p>\n<p>דְּאָמַר רִבִּי אַבָּא, כָּל אִלֵּין חַבְרַיָּיא, דְּלָא רְחִימִין אִלֵּין לְאִלֵּין, אִסְתָּלָקוּ מֵעָלְמָא עַד לָא מָטָא זִמְנַיְיהוּ, כֹּל חַבְרַיָּיא בְּיוֹמוֹי דְּרַבִּי שִׁמְעוֹן, רְחִימוּ דְּנַפְשָׁא וְרוּחָא הֲוָה בֵּינַיְיהוּ, וּבְּגִין כָּךְ בְּדָרָא דְּרִבִּי שִׁמְעוֹן בְּאִתְגַּלְּיָיא הֲוָה, דְּהֲוָה אָמַר רִבִּי שִׁמְעוֹן, כָּל חַבְרַיָּיא דְּלָא רַחֲמִין אִלֵּין לְאִלֵּין, גַּרְמִין דְּלָא לִיהַךְ בְּאֹרַח מֵישָׁר. וְעוֹד דְּעַבְדִין פְּגִימוּ בָּהּ, דְּהָא אוֹרַיְיתָא רְחִימוּ וְאַחֲוָה וּקְשׁוֹט אִית בָּהּ. אַבְרָהָם רָחִים לְיִצְחָק, יִצְחָק לְאַבְרָהָם, מִתְחַבְּקָן דָּא בְּדָא, יַעֲקֹב תַּרְוַויְיהוּ אֲחִידָן בֵּיהּ, בִּרְחִימוּ, וּבְאַחֲוָה, יָהֲבִין רוּחַיְיהוּ דָּא בְּדָא. חַבְרַיָּיא כְּהַהוּא דּוּגְמָא אִצְטְרִיכוּ, וְלָא לְמֶעְבַּד פְּגִימוּ.</p>\n<p>כֵּיוָן דְּחָמָא סִימָן בְּאַנְפַּיְיהוּ, וְאָמַר לוֹן הָכִי. אָמְרוּ לֵיהּ וַדַּאי רוּחַ נְבוּאָה שָׁרָא עַל בּוּצִינָא קַדִּישָׁא, וְהָכִי אִצְטְרִיךְ לָן לְמִנְדַּע. בָּכָה רִבִּי שִׁמְעוֹן וְאָמַר, חַד מִלָּה מֵאִינּוּן מִלִּין דִּלְחִישׁוּ לִי מִגּוֹ רֵישׁ מְתִיבְתָּא דְּגִּנְתָּא דְּעֵדֶן, דְּלָא אָמְרוּ בְּאִתְגַּלְּיָא מִלָּה דָּא סִתְרָא אִיהִי, וְאֵימָא לְכוּ בָּנַי רְחִימָאי, בָּנַי רְחִימִין דְּנַפְשָׁאי, מָה אַעֲבִיד, אֲמַרוּ לִי בִּלְחִישָׁא, וַאֲנָא אֵימָא בְּאִתְגַּלְיָיא. וּלְזִמְנָא דְּנֶחמֵי אַנְפִּין בְּאַנְפִּין, <Nonei></i>כָּל אַנְפִּין יִסְתַּמְּכוּן בְּדָא.</p>\n<p>בָּנַי. חוֹבָא דְּעָבְדוּ (ערב רב) עַמָּא דִּלְבַר. וְאִשְׁתָּתָּפוּ בֵּיהּ עַמָּא קַדִּישָׁא, בְּאִמָּא חָאבוּ, דִּכְתִּיב קוּם עֲשֵׂה לָנוּ אֱלהִים, אֱלֹהִים וַדַּאי. כְּבוֹד יִשְׂרָאֵל דָּא, אִיהוּ דְּשַׁרְיָא עָלַיְיהוּ כְּאִמָּא עַל בְּנִין, וְדָא הוּא רָזָא דִּכְתִּיב, (תהילים ק״ו:כ׳) וַיָּמִירוּ אֶת כְּבוֹדָם בְּתַבְנִית שׁוֹר. דָּא כְּבוֹדָם דְּיִשְׂרָאֵל, אִמָּא דִּלְהוֹן. וְדָא הוּא דִּכְתִּיב, (שמואל א ד׳:כ״א) גָּלָה כָבוֹד. דְּגָרְמוּ לִשְׁכִינְתָּא דְּאִתְגְלֵי בְּגָלוּתָא עִמְּהוֹן. וְעַל דָּא וַיָּמִירוּ אֶת כְּבוֹדָם, בְּמָה. בְּתַבְנִית שׁוֹר.</p>\n<p>הָכָא אִיהוּ רָזָא דְּמִלָּה, תָּא חֲזֵי, לְתַתָּא גּוֹ שְׁמָרִים דְּחַמְרָא, דּוּרְדְיָין בִּישִׁין, נָפַק חַד עִרְעוּרָא, מְקַטְרְגָא, מַזִיקָא קַדְמָאָה, וְאִיהוּ בְּרָזָא דִּיּוּקְנָא דְּאָדָם. כַּד קָרִיב לְגוֹ קֻדְשָׁא. כֵּיוָן דְּאִתְעֲבָר מִתַּמָּן, וּבָעֵי לְנַחְתָּא לְתַתָּא. בָּעֵי לְאִתְלַבְּשָׁא בִּלְבוּשָׁא, לְנַזְקָא עָלְמָא. וְנָחִית הוּא וּרְתִיכוֹי. וּלְבוּשָׁא (קצ\"ג ע\"ב) קַדְמָאָה דְּקָא נָקִיט, תַּבְנִית שׁוֹר, דִּיּוּקְנָא דְּשׁוֹר, וְקַדְמָאָה לַנְּזִיקִין מֵאִינּוּן אַרְבַּע, שׁוֹר אִיהוּ. וְאִינּוּן אַרְבַּע (קי\"ח ע\"א) אָבוֹת לְנַזְקָא עָלְמָא. וְכֻלְּהוּ תְּלָתָא דְּאָבוֹת נְזִיקִין בַּר שׁוֹר, כֻּלְּהוּ דִּילֵיהּ, וְעַל דָּא כְּתִיב, וַיָּמִירוּ אֶת כְּבוֹדָם בְּתַבְנִית שׁוֹר.</p>\n<p>מַהוּ אוֹכֵל עֵשֶׂב. הָא דַּרְשִׁינָן בֵּיהּ. אֲבָל עִקָּרָא דְּמִלָּה, מִתַּמְצִית דְּלֶחֶם וְשִׁבְעָה זִינֵי דָּגָן, לֵית לֵיהּ בְּהוּ חוּלָקָא. וּבְגִינֵי כַּךְ, אִימָא לָא הֲוַת תַּמָּן, וְלָא יֵאוֹת לָהּ לְמֶהוֵי תַּמָּן. וּבְגִין דְּאַבָּא הֲוָה יָדַע רָחֲמָנוּ דְּאִמָא וְאָרְחָא דִּילָהּ, אָמַר לְמֹשֶׁה, בְּנִי רְחִימָאי, עֵיטָא בְּתַרְוַויְיהוּ בְּדָא תָּדִיר. וְדָא הוּא דִּלְחִישׁוּ לִי בִּלְחִישׁוּ, דְּלָא חֲזֵי לְגַלָּאָה, דִּבְּרָא לָא יִנְדַּע, וְיֶחְמֵי דְּהָא רְצוּעָה אִתְתַּקְנַת, וְיִדְחַל תָּדִיר. אֲבָל תַּרְוַיְיהוּ בְּעֵיטָא דָּא, וּבְעֵיטָא חֲדָא.</p>"],[9520011831,"<p>תָּא חֲזֵי כְּתִיב (שמות לכ) וַיַּרְא הָעָם כִּי בֹשֵׁשׁ מֹשֶׁה. מַאן הָעָם. אִינּוּן עֵרֶב רַב. מַאן עֵרֶב רַב. וְכִי לּוּדִים וְכוּשִׁים וְכַפְתּוֹרִים וְתוּגַרְמִים הֲווֹ, דְּקָרָאן לוֹן עֵרֶב רַב, וַהֲלֹא מִצְרִיִּים הֲווֹ, וּמִמִּצְרַיִם נַטְלוּ, וְאִלּוּ הֲווֹ עִרְבּוּבְיָא דְּעַמִּין סַגִּיאִין, הָכִי הֲוָה לֵיהּ לְמִכְתַּב, עֵרֶב רַב עָלוּ אִתָּם לְפִי עִרְבּוּבְיָא דִּלְהוֹן.</p>\n<p>אֶלָּא (שמות י״ב:ל״ח) עֵרֶב רַב עָלָה אִתָּם. עַמָּא חַד הֲוָה, וְלִישָׁן חַד, אֲבָל כָּל חֲרָשֵׁי מִצְרַיִם, וְכָל חַרְטוּמֵי דִּלְהוֹן הֲווֹ, דִּכְתִּיב בְּהוּ, (שמות ז׳:י״א) וַיַּעֲשׂוּ גַּם הֵם חַרְטוּמֵּי מִצְרַיִם. דְּבָעוּ לְמֵיקָם לָקֳבֵל פְּלִיאָן דְּקוּדְשָׁא בְּרִיךְ הוּא, כֵּיוָן דְּחָמוּ נִסִּין וּפְלִיאָן דְּעֲבַד מֹשֶׁה בְּמִצְרַיִם, אָהַדְרוּ לְגַבֵּי מֹשֶׁה. אֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, לָא תְּקַבֵּל לוֹן. אָמַר מֹשֶׁה, מָארֵיהּ דְּעָלְמָא, כֵּיוָן דְּחָמוּ גְּבוּרְתָּא דִּילָךְ, בָּעָאן לְאִתְגַּיְּירָא. יֶחמוּן גְּבוּרְתָּךְ בְּכָל יוֹמָא, וְיִנְדְּעוּן דְּלֵית אֱלָהָא בַּר מִנָךְ. וְקַבִּל לוֹן מֹשֶׁה.</p>\n<p>אֲמַאי קָרָא לוֹן עֵרֶב רַב. אֶלָּא כָּל חֲרָשִׁין דְּמִצְרַיִם הֲווֹ, וּבְרֵישֵׁיהוֹן (בלק קצ\"ד ע\"א) יוֹנוֹס (אמרו המגיהים אולי אלו הם יוחני וממרא שנזכרו בשמות רבה פרשת ט' דף ע\"ב ע\"ג שורה ל\"א אמרו יוחני וממרא אל משה תבן אתה מכניס לעפריים) וְיִּמְבְּרוּס, וּבְשַׁעֲתֵּי דְּיוֹמָא הֲווֹ עַבְדֵי תָּדִיר חֲרָשַׁיְיהוּ. וְכָל אִלֵּין חֲרָשִׁין עִלָּאִין, הֲווֹ מִסְתַּכְּלֵי מִכִּי נָטֵי שִׁמְשָׁא, מִשֵּׁירוּתָא דְּשִׁית שָׁעוֹת וּמֶחְצָה, עַד שֵׁירוּתָא דְּתֵשַׁע וּמֶחְצָה. דְּהַיְינוּ עֵרֶב רַבְרְבָא. כָּל אִינּוּן חֲרָשִׁין זְעִירִין, מִשֵּׁירוּתָא דְּתֵשַׁע וּמֶחְצָה, עַד פַּלְגוּת לֵילְיָא.</p>\n<p>אִינּוּן עִלָּאִין דִּבְהוּ, הֲווֹ מִסְתַּכְּלֵי מִכִּי נָטֵי שִׁמְשָׁא. דְּהָא כְּדֵין שָׁרָאן תְּשַׁע מְאָה וְתִשְׁעִין וַחֲמֵשׁ דַּרְגִּין, לִמְשַׁטְּטָא עַל טוּרֵי חָשׁוּךְ. וְרוּחָא דִּלְהוֹן, הֲוָה (בלק קצ\"א ע\"א) מְשַׁטְּטָא עַל כָּל אִינּוּן חֲרָשִׁין (נ\"א דרגין) בְּחַרְשַׁיְיהוּ. וְאִלֵּין הֲווֹ עַבְדֵי, כָּל מַה דְּאִינּוּן בָּעָאן. עַד דְּכָל מִצְרָאֵי רָחְצָנוּ דִּלְהוֹן בְּאִלֵּין הֲוָה. וְקָרָאן לוֹן עֵרֶב רַב. בְּגִין דְּאִית עֵרֶב זְעֵירָא, מִתְּשַׁע שָׁעוֹת <Nonei></i>וּמֶחֱצָה וּלְתַתָּא, דָּא עֵרֶב זְעֵירָא. וּתְרֵי עַרְבֵי אִינּוּן, וְעַל דָּא וְגַם עֵרֶב רַב עָלָה אִתָּם.</p>\n<p>וְחָכְמְתָא דִּלְהוֹן, הֲוָה סַגִּי. וְאִינּוּן אִסְתָּכָּלוּ בְּשַׁעְתֵּי דְּיוֹמָא, וְאִסְתָּכָּלוּ בְּדַרְגָּא דְּמֹשֶׁה, וְחָמוּ דְּהָא בְּכָל סִטְרִין בְּשֵׁשׁ מֹשֶׁה: בְּשֵׁשׁ שַׁעְתֵּי קַדְמָאִין דְּיוֹמָא, דְּאִינּוּן לָא יַכְלִין לְשַׁלְּטָאָה בְּהוּ, (נ\"א בגין שית) בְּשִׁית דַּרְגִּין עִלָּאִין דְאַחְדִינָן בֵּיהּ (נ\"א דאחיד בהו.) וּבְכָל סִטְרִין בְּשִׁית הֲוָה, וּבְעִטְרִין דְּאִלֵּין שִׁית, הֲוָה זַמִּין לָרֶדֶת מִן הָהָר, דִּכְתִּיב כִּי בֹשֵׁשׁ מֹשֶׁה לָרֶדֶת מִן הָהָר.</p>\n<p>מִיַּד וַיִּקָּהֵל הָעָם עַל אַהֲרֹן, (דהכי תנינן דבההיא שעתא דנחית משה וקביל אורייתא בלחודוי כללא דכל ישראל ואיהו קביל אורייתא בעלמא. ואפילו מגילת אסתר דכתיב (אסתר ט׳:כ״ג) וקבל היהודים. וקבלו היהודים מבעי ליה. מאי וקבל אלא דא משה דאיהו היהודים כללא דיהודאי. ויקהל העם על אהךן) אֲמַאי עַל אַהֲרֹן. בְּגִין לְאִתְכַּלְּלָא בְּסִטְרָא דִּימִינָא, דְּהָא אִינּוּן שְׂמָאלָא בָּעוּ מִנֵּיהּ, וּבְגִין דְּלִהֱוֵי כָּלִיל בִּימִינָא, אִתְכְּנָשׁוּ עַל אַהֲרֹן, וַיֹּאמְרוּ אֵלָיו קוּם עֲשֵׂה לָנוּ אֱלהִים. (אלהים ודאי בעו סטר שמאלא. אשר ילכו אשר ילך מבעי ליה. מאי אשר ילכו. אלא אלהים שית דרגא אינון (ד\"א ששת ימי המעשה) כלהו בסטר שמאלא דאלהים שית אינון. דאי תימא דהא שבע אינון. ההוא אלהים עילאה לא עאל בכללא).</p>\n<p>תָּא חֲזֵי, כָּל זִמְנָא דְּהֲוָה מֹשֶׁה בְּמִצְרַיִם, שְׁמָא דֶּאֱלֹהִים לָא דָּכִיר, אֶלָּא שְׁמָא דַּיְיָ', וְעַל דָּא קַשְׁיָא לֵיהּ לְפַרְעֹה בְּגִין דְּלָא יְהֵא תּוּקְפָּא לְהַהוּא סִטְרָא אַחֲרָא, וְלָא יִתְתָּקַף בְּעָלְמָא. הַשְׁתָּא בָּעוּ הַהִיא מִלָּה, וְהַיְינוּ קוּם עֲשֵׂה לָנוּ אֱלהִים. לָנוּ דַּיְיקָא, דְּאֲנָן צְרִיכִין לְהַאי מִלָּה, לְתַקְּפָא סִטְרָא דִּילָן, דְּהֲוָה אִתְדַּחְיָא עַד הַשְׁתָּא.</p>\n<p>אֲשֶׁר יֵלְכוּ לְפָנִינוּ. מַאי אָמְרוּ. אֶלָּא הָכִי אָמְרוּ, חֲמֵינָן דְּאַתּוּן יִשְׂרָאֵל, כָּל טוּב וְכָל יְקָר דְּעָלְמָא לְכוּ, וַאֲנָן דַּחְיָין לְבַר. דִּלְכוּ, (שמות י״ג:כ״א) וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם. אוּף הָכִי אֱלהִים אֲשֶׁר יֵלְכוּ לְפָנֵינוּ, כְּמָה דְּאָזִיל קָמַיְיכוּ יְיָ'. דְּהָא רְשׁוּ אִית לְסִטְרָא דִּילָן לְמֵהַךְ אוּף הָכִי לְקָמָנָא, אִי נַזְמִין לֵיהּ עוֹבָדָא.</p>\n<p>תָּא חֲזֵי, כָּל עֲנָנֵי יְקָר דְּאָזְלוּ בְּמַדְבְּרָא, לָא הֲווֹ חַפְיָין אֶלָּא לִבְנִי יִשְׂרָאֵל לְחוֹדַיְיהוּ. וְהַהוּא עֲנָנָא דִּיקָר, דִּכְתִּיב וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם, אַזְלָא לְקָמַיְיהוּ. וְאִלֵּין עֵרֶב רַב, וְכָל אִינּוּן בְּעִירֵי עָאנִין וְתוֹרִין, הֲווֹ אַזְלוּ לְבַר מִמַשִׁרְיָּיתָא, לְבַתְרַיְיתָא. וְתָּא חֲזֵי, כָּל אִינּוּן אַרְבְּעִין שְׁנִין דְּקָא אָזְלוּ יִשְׂרָאֵל בְּמַדְבְּרָא, שׁוּם לִכְלוּכָא וְטִנּוּפָא לָא הֲוָה גּוֹ עֲנָנִי לְגוֹ. וְעַל דָּא עָאנֵי וְתוֹרֵי דַּהֲווֹ אָכְלֵי עֵשֶׂב לְבַר הֲווֹ, וְכָל אִינּוּן דְּנַטְרֵי לוֹן.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, אַבָּא, אִי הָכִי אִינּוּן עֵרֶב רַב לָא הֲווֹ אַכְלֵי מִן מַנָּא. אֲמַר לֵיהּ וַדַּאי הָכִי הוּא. אֶלָּא מָה דְּיָהֲבִין לוֹן יִשְׂרָאֵל, כְּמַאן דְּיָהִיב לְעַבְדֵיהּ. וּמִמַּה הֲווֹ אַכְלֵי. מִתַּמְצִית, מָה דְּאִשְׁתְּאַר מִבָּתַר רֵיחַיָא, פְּסוֹלֶת. וּקְרָא אַכְרִיז וְאָמַר, (שמות ט״ז:ל״ה) וּבְנֵי יִשְׂרָאֵל אָכְלוּ אֶת הַמָּן אַרְבָּעִים שָׁנָה. בְּנֵי יִשְׂרָאֵל, וְלָא אַחֲרָא. וַיִּרְאוּ בְנִי יִשְׂרָאֵל וַיֹּאמְרוּ מָן הוּא, וְלָא שְׁאַר עֵרֶב רַב, עָאנִי וְתוֹרֵי, דַּהֲווֹ בֵּינַיְיהוּ.</p>\n<p>עַד הַשְׁתָּא, הֲווֹ אִתְכַּפְיָין אִינּוּן עֵרֶב רַב וְהַשְׁתָּא קָמוּ וּבָעוּ עוֹבָדָא, לְאַתָּקְפָא לְסִטְרָא אַחֲרָא. אָמְרוּ, אוֹ נְהֵא כֻּלָּנָא עַמָּא חֲדָא, וְנֶהֱוֵי בִּכְלָלָא עִמְּכוֹן, אוֹ יְהֵא לָן מַאן דְּיֵּהַךְ קָמָנָא, כְּמָה דְּיֵּהַךְ אֱלָהֲכוֹן קָמֵיכוֹן. אָמַר אַהֲרֹן, חַס וְשָׁלוֹם דְּאִלֵּין יִשְׁתַּתְּפוּן בְּעַמָּא קַדִּישָׁא, לְמֶהוֵי כֹּלָּא כְּלָלָא חֲדָא, וְלָא יִתְעָרְבוּן עַמָּא קַדִּישָׁא בְּעַמָּא דָּא, כְּלָלָא חֲדָא, אֶלָּא טָב אִיהוּ לְאַפְרְשָׁא לוֹן מִגּוֹ עַמָּא קַדִּישָׁא, עַד דְּיֵיתֵי מֹשֶׁה.</p>\n<p>וְאַהֲרֹן לְטָב אִתְכְּוָון, אֶלָּא סַגִּיאִין הֲווֹ מִיִשְׂרָאֵל דְּאִשְׁתָּתָּפוּ בַּהֲדַיְיהוּ בְּלִבָּא. וּבְגִין כַּךְ, כַּד אָתָא מֹשֶׁה, אִצְטְרִיךְ לְבָרְרָא וּלְלַבְּנָא לְעַמָּא קַדִּישָׁא מֵהַהוּא חוֹבָא, וְאַשְׁקֵי לוֹן שַׁקְיוּ, עַד דְּאִתְבְּרִירוּ <Nonei></i>כֻּלְּהוּ וְלָא אִשְׁתְּאַר בְּהוּ פְּסוֹלֶת כְּלַל.</p>\n<p>אָמַר לוֹן אַהֲרֹן, (שמות ל״ב:ב׳) פָּרֲקוּ נִזְמֵי הַזָּהָב, וְכִי לָא הֲוָה לוֹן דַּהֲבָא אַחֲרָא. אֶלָּא אָמַר אַהֲרֹן, בְּעוֹד דְּאִית לוֹן קְטָטָה בִּבְנַיְיהוּ וּבְנָשַׁיְיהוּ, יִתְעַכְּבוּן, וּבֵין כַּךְ יֵיתֵי מֹשֶׁה. תָּא חֲזֵי, תָּנֵינָן קָשִׁים גֵּרִים לְיִשְׂרָאֵל כְּסַּפַּחַת בִּבְשַׂר הַחַי, כָּל שֶׁכֵּן אִלֵּין, דְּלָא הֲווֹ גֵּרִים כְּדְקָא יֵאוֹת. אִינּוּן מָה עָבְדוּ. וַיִּתְפָּרַקוּ כָּל הָעָם אֶת נִזְמֵי הַזָּהָב אֲשֶׁר בְּאָזְנֵיהֶם. כַּמָה אַלְפֵי וְרִבְוָון הֲווֹ מִנִּזְמֵיהוֹן תַּמָּן.</p>\n<p>מַה כְּתִיב, וַיִּקַּח מִיָּדָם וַיָּצַר אוֹתוֹ בַּחֶרֶט וְגוֹ'. אַהֲרֹן לָא אִסְתָּמַּר, מֵאִינּוּן תְּרֵין חַכִּימִין, דַּהֲווֹ בְּרֵישֵׁיהוֹן דְּהַהוּא עֵרֶב רַב. חַד מִנַּיְיהוּ הֲוָה קָמֵיהּ, וְאַחֲרָא הֲוָה עָבִיד בְּחַרְשׁוֹי. כֵּיוָן דְּתַרְוַויְיהוּ אִתְיָיעֲטוּ כַּחֲדָא, נַטְלוּ הַהִיא דַּהֲבָא, (חד) תְּרֵין שְׁלִישֵׁי בִּידָא דְּחַד, וּשְׁלִישׁ בִּידָא דְּאַחֲרָא. בְּגִין דְּהָכִי אִצְטְרִיךְ בְּהַהוּא זִינָא דְּחַרְשָׁא.</p>\n<p>בָּכָה רַבִּי שִׁמְעוֹן, אָמַר אִי חֲסִידָא קַדִּישָׁא, אַהֲרֹן מְשִׁיחָא דֶּאֱלָהָא רַבָּא, בַּחֲסִידוּתָךְ נַפְלוּ כַּמָה מֵעַמָּא קַדִּישָׁא. וְאַנְתְּ לָא הֲוֵית יָדַע לְאִסְתַּמְּרָא. מַהוּ עֲבַדוּ. כַּד מָטוּ שִׁית שַׁעֲתִּין, וְיוֹמָא הֲוָה בְּמַתְקְלָא, נַטְלוּ הַהוּא דַּהֲבָא דְּפָרִיקוּ מֵאוּדְנֵיהוֹן. מַאי טַעְמָא. בְּגִין דְּמַאן דְּאִצְטְרִיךְ לְמֶעְבַּד חַרְשָׁא, לָא בָּעֵי לְמֵיחַס עֵינוֹי עַל מָמוֹנָא. וְאִינּוּן אַמְרִי, שַׁעֲתָא קַיָּימָא לָן, אִי אֲנָן לָא מְעַכְּבִין. לָאו שַׁעֲתָא לְמֵיחַס עַל דַּהֲבָא, מִיַּד וַיִּתְפָּרַקוּ כָּל הָעָם. מַאי וַיִּתְפָּרַקוּ. כְּמָה דְאַתְּ אָמֵר (מלכים א י״ט:י״א) מְפָרֵק הָרִים וּמְשַׁבֵּר סְלָעִים, דְּחַבִּילוּ וְתַבְרוּ אוּדְנַיְיהוּ. בָּכָה כְּמִלְּקַדְּמִין וְאָמַר אִי עַמָּא קַדִּישָׁא אִי עַמָּא קַדִּישָׁא, דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן בְּבִכְיָה, וְאָמַר, (שמות כ״א:ו׳) וְהִגִּישׁוֹ אֲדֹנָיו אֶל הָאֱלהִים וְגוֹ'. הָא אוּקְמוּהָ חַבְרַיָּיא, אֹזֶן דְּשָׁמַע בְּסִינַי, (ויקרא כה) כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים וְגוֹ'. וְאִיהוּ פָּרִיק עוֹל מַלְכוּת שָׁמַיִם מֵעָלֵיהּ, וְזָבִין גַּרְמֵיהּ לְאַחֵר, תִּרָצַע. וְאִלֵּין חַיָּיבַיָּא רְשִׁיעִין, גּוּבְרִין בִּישִׁין, בְּתִיאוּבְתָּא דִּלְהוֹן לְמֶהֲדָר לְסָרְחָנַיְיהוּ, לָא בָּעוּ מִנְּשֵׁיהוֹן וּבְנֵיהוֹן אֶלָּא חֲבִילוּ אוּרְחַיְיהוּ (ס\"א אודנייהו) וְאִתְפְּרָקוּ מֵעוֹל שְׁמַיָא דְּפָקִיד לְהוּ מֹשֶׁה, וְתַבְרוּ אוּדְנַיְיהוּ, דְּלֵית לוֹן חוּלָקָא בִּשְׁמָא קַדִּישָׁא, וְעַמָּא קַדִּישָׁא.</p>\n<p>מָה עֲבַדוּ. פְּלִיגוּ תַּרְוַויְיהוּ הַהוּא דַּהֲבָא, חַד נָטִיל תְּרֵין שְׁלִישִׁין, וְחַד שְׁלִישׁ. קָמוּ לָקֳבֵל שִׁמְשָׁא, בְּשִׁית שַׁעְתִּין. עֲבַדוּ חַרְשַׁיְיהוּ, וּבַלְטוּ בְּלָטֵיהוֹן בְּחַרְשָׁא דְּפוּמָא. כֵּיוָן דְּמָטָא שֵׁירוּתָא דִּשְׁבַע, אָרִימוּ תַּרְוַויְיהוּ יְדַיְיהוּ עַל יְדוֹי דְּאַהֲרֹן. (ומנלן דמידא דתרויהו יד מכל חד נטל ולא יתיר) דִּכְתִּיב וַיִּקַּח מִיָּדָם, תַּרְוַויְיהוּ הֲווֹ, וְלָא יַתִּיר. כֵּיוָן דְּאִיהוּ קַבִּיל מִיָּדָם (ס\"א תרי ולא ידיהם), קַלָּא נָפִק וְאָמַר, (משלי י״א:כ״א) יָד לְיָד לא יִנָּקֶה רַע, דִּכְתִּיב כִּי בְרָע הוּא. אַיְיתֵי רָע לְעָלְמָא.</p>\n<p>רָזָא דְּמִלָּה. אִינּוּן רְשָׁעִים חַיָּיבִין חַרְשִׁין בְּנוֹי דְּבִלְעָם חַיָּיבָא, בְּנִי בְּנוֹי דְּלָבָן רְשִׁיעָא, חָמוּ דְּכוֹס שֶׁל בְּרָכָה בִּימִין אִיהוּ, וּמִן יְמִינָא אִתָּקַף תָּדִיר. (ס\"א יתיר) אָמְרוּ, אִי יְהֵא בִּסְטַר דָּא, הַהוּא רֵישָׁא דִּימִינָא, הָא תּוּקְפָּא דִּילָן כְּדְקָא יֵאוֹת.</p>\n<p>כֵּיוָן דְּמָטָא שֶׁבַע שַׁעְתִּין דְּיוֹמָא, יָהֲבוּ לֵיהּ לְאַהֲרֹן מִיָּד. אִי אִיהוּ הֲוָה אָמַר לוֹן שַׁווּ לֵיהּ בְּאַרְעָא בְּקַדְמִיתָא, וָאֲנָא אֶטוֹל, לָא הֲווֹ יַכְלִין בְּחַרְשַׁיְיהוּ כְּלוּם, אֶלָּא מִיָּדָם נָטַל. וּקְרָא מִתְרָעַם וְאָמַר, וַיִּקַּח מִיָּדָם, חָמוּ מָה עֲבַד אַהֲרֹן גְּבַר נְבִיאָה גְּבַר חַכִּים, לָא יָדַע לְאִסְתַּמְּרָא, דְּאִילּוּ נָטִיל מֵאַרְעָא, כָּל חַרְשִׁין דְּעָלְמָא לָא הֲווֹ יַכְלִין לְאַצְלְחָא. אֲבָל בְּמָה אַצְלָחוּ בְּעוֹבָדָא דָּא, בְּגִין דְּוַיִּקַח מִיָּדָם וְלָא מֵאַרְעָא.</p>\n<p>(שמות ל״ב:ד׳) וַיָּצַר אוֹתוֹ בַּחֶרֶט, לָאו כְּמָה דְּחַשְׁבִין בְּנֵי נָשָׁא, דְּעֲבַד צִיּוּרִין בִּמְחוּגָה, אוֹ בְּמִלָּה אַחֲרָא. אֶלָּא אָתָא קְרָא לְאוֹכָחָא מִלָּה, דְּאַהֲרֹן לָא יָדַע לְאִסְתַּמְּרָא. אִילוּ כַּד נָטַל מִיְּדֵיהוֹן, הֲוָה שַׁדֵּי לְאַרְעָא, וְאַף עַל גַּב דְּיִטּוֹל לֵיהּ לְבָתַר, לָא הֲוָה <Nonei></i>אַצְלַח עוֹבָדָא בִּישָׁא דָּא. אֲבָל בְּכֹלָּא סִיּוּעָא בִּישָׁא הֲוָה, דְּנָקִיט דַּהֲבָא, וּטְמָרֵיהּ מֵעֵינָא, בִּישׁ בָּתַר בִּישׁ, מַאי וַיָּצַר אוֹתוֹ בַּחֶרֶט. דְּשַׁוֵּי כָּל דַּהֲבָא בְּכִיסָא חֲדָא, וְאִסְתְּמַר מֵעֵינָא. כְּדֵין סָלִיק כֹּלָּא לְעוֹבָדָא.</p>\n<p>בְּסִפְרָא דְּחֲנוֹךְ אַשְׁכַּחְנָא, דְּהֲוָה אָמַר הָכִי, בְּרָא יְחִידָאָה יִתְיְּילִד לְהַהוּא רִישָׁא חִוָּורָא, וְכַד יִיִתוּן מִבִּשְׂרָא דַּחֲמָרֵי, יָטְעִין לֵיהּ, בְּהַהוּא דְּעָיִיל (נ\"א דנטיל) מַרְגְּלָן בְּזָגִין דְּדַהֲבָא, בְּלָא דַּעְתָּא דִּילֵיהּ, וּדְיּוּקְנָא יְצֻיַיר בְּצִיּוּרָא בַּחֶרֶט. מַאי בַּחֶרֶט. בְּחֶרֶט אֱנוֹשׁ. דָּא קֹלְמוּסָא דֶּאֱנוֹשׁ חַיָּיבָא, דְּאַטְעֵי לִבְנֵי נָשָׁא.</p>\n<p>וַדַּאי דָּא בְּרִירָא דְּמִלָּה, דֶּאֱנוֹשׁ כַּד אַטְעֵי עָלְמָא, בְּקֹלְמוּסָא הֲוָה רָשִׁים רְשִׁימִין, דְּכָל דִּיוּקְנִין וּפֻלְחָנִין נֹכְרָאִין בְּהַהוּא קֹלְמוּסָא, (ס\"א רשים רשימין) וְעַל דָּא כְּתִיב בַּחֶרֶט, הַהוּא דְּאִשְׁתְּמוֹדַע לְמֶעְבַּד הָכִי. וְדָא הוּא בְּרִירוּ דְּמִלָּה.</p>\n<p>וְכֹלָּא הֲוָה, דְּוַדַּאי בְּכִיסָא אַרְמֵי דַּהֲבָא, וְכַסֵּי לֵיהּ מֵעֵינָא, כְּמָה דְּאָמְרוּ אִינּוּן חַרְשִׁין, וְהָכִי אִצְטְרִיךְ בְּזִינֵי דְּחָרָשִׁין אִלֵּין. וְדָא הוּא עוֹבָדָא דְּחַרְשִׁין אִלֵּין, מִלָּה דְּאִצְטְרִיךְ בְּאִתְגַּלְּיָא, לְאִתְגַּלָּאָה לְבָתַר, אִצְטְרִיךְ טְמִירוּ וְכִסוּיָא בְּקַדְמִיתָא, דְּיִתְכַּסֵי מֵעֵינָא, וּבָתַר יִפּוֹק אוּמָנָא לְאוּמָנוּתֵיהּ. וּמִלָּה דְּאִצְטְרִיךְ בְּכִסּוּיָא לְבָתַר, אִצְטְרִיךְ בְּאִתְגַּלְּיָא בְּקַדְמִיתָא.</p>\n<p>הַשְׁתָּא בָּנַי רְחִימָאי, רְחִימִין דְּנַפְשָׁאי, מָה אַעְבִּיד, וַדַּאי אִצְטְרִיכְנָא לְגַלָּאָה, אֲצִיתוּ וְאַטְמִירוּ מִלִּין. בִּסְטַר קְדוּשָּׁה הַהוּא, אֱלהִים דִּקְשׁוֹט, מֶלֶךְ עַל עָלְמָא, בִּתְלַת (מילין) עָלְמִין (אלין) אִתְתָּקַּף. (בראשית קע\"ז ע\"ב, ר\"ח ע\"א) בִּבְּרִיאָה. בִּיְצִירָה. בַּעֲשִׂיָּה. וְהָא אִתְּמַר, רָזָא דְּכָל חֲדָא וַחֲדָא הָכָא. לָקֳבֵל בְּרִיאָה, וַיִּקַּח מִיָּדָם, מִלָה דְּלָא הֲוָה בֵּיהּ עַד כְּעַן כְּלוּם. לָקֳבֵל יְצִירָה, וַיָּצַר אוֹתוֹ בַּחֶרֶט. לָקֳבֵל עֲשִׂיָּה, וַיַּעֲשֵׂהוּ עֶגֶל מַסֵּכָה. מַאן חָמָא חַרְשִׁין בְּכָל עָלְמָא כְּאִלֵּין.</p>\n<p>הַשְׁתָּא אִית לְמֵימַר, וְכִי לָא כְּתִיב וָאַשְׁלִיכֵהוּ בָּאֵשׁ, וְלָא יַתִּיר, וּכְדֵין וַיֵּצֵא הָעֵגֶּל הַזֶּה. וְהַשְּׁתָּא אַתְּ אַמָרְתְ וַיַּעֲשֵׂהוּ עֵגֶל מַסֵּכָה אֶלָּא חַס וְשָׁלוֹם דְּאַהֲרֹן עֲבַד, וּקְרָא אוֹכַח דִּכְתִּיב וַיִּקַּח אֶת הָעֵגֶּל אֲשֶׁר עָשׂוּ. אֲבָל מִמַּה דִּכְתִּיב וַיִּקַּח מִיָּדָם, וּכְתִיב וַיָּצַר אוֹתוֹ. מֵחֵילָא דִּתְרֵין אִלֵּין, אִתְעָבִיד כֹּלָּא. כִּבְיָכוֹל הוּא עָבִיד לֵיהּ, דְּאִי תְּרֵין אִלֵּין לָא הֲווֹ, לָא אִתְעָבִיד וְלָא נָפַק לְאוּמָנוּתָא. אֲבָל מַאן גָּרַם דְּאִתְעָבִיד. אִינּוּן תְּרֵין. (כביכול ויעשהו איהו ודאי עשהו) בְּעוֹד דְּאִיהוּ לָקַח מִיָּדָם, אִינְהוּ עַבְדֵי חַרְשַׁיְיהוּ, וּמְלַחֲשֵׁי בְּפוּמַיְיהוּ, וּמְשָׁכֵי רוּחָא לְתַתָּא, מִן סִטְרָא אַחֲרָא.</p>\n<p>וּמְשָׁכוּ תְּרֵין רוּחִין כַּחֲדָא, חַד מִן דְּכָר, וְחַד מִן נוּקְבָּא. דְּכַר אִתְלָבַשׁ בְּדִיּוּקְנָא דְּשׁוֹר. נוּקְבָּא בְּדִיּוּקְנָא דְּחֲמוֹר, תַּרְוַויְיהוּ הֲווֹ כְּלִילָן כַּחֲדָא. אֲמַאי תְּרֵין אִלֵּין. אֶלָּא שׁוֹר הָא אִתְּמַר. חֲמוֹר אֲמַאי. בְּגִין דְּחַרְשִׁין אִלֵּין דְּמִצְרָאֵי, כְּתִיב בְּהוּ, (יחזקאל כ״ג:כ׳) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם.</p>\n<p>וְעַל דָּא, כָּל אִינּוּן דְּיִשְׂרָאֵל דְּמִיתוּ, אִתְחַבָּרוּ בַּהֲדַיְיהוּ בְּלִבְּהוֹן. וּבְגִין דַּהֲווֹ תְּרֵין דִּיוּקְנִין, כְּתִיב אֵלֶּה אֱלהֶיךָ יִשְׂרָאֵל, וְלָא כְּתִיב זֶה, אֶלָּא אֵלֶּה, תְּרֵין הֲווֹ כַּחֲדָא, אֲשֶׁר הֶעֱלוּךָ מֵאֶרֶץ מִצְרָיִם. הֶעֱלוּךָ וְלָא הֶעֱלְךָ כְּתִיב.</p>\n<p>(שמות ל״ב:ד׳) וַיַּעֲשֵׂהוּ עֵגֶל מַסֵּכָה וַיֹּאמְרוּ. וַיֹּאמֶר לָא כְּתִיב, אֶלָּא וַיֹּאמְרוּ, דְּאַהֲרֹן לָא אָמַר מִדִי. תָּנֵינָן, (ויקרא ע\"ט ע\"א) מֵאָה וְעֶשְׂרִים וְחָמֵשׁ קַנְטְרִין הֲווֹ בֵּיהּ.</p>\n<p>הֵיךְ כְּתִיב וַיִּקַּח מִיָּדָם, וְכִי בְּיָדָם הֲווֹ כָּל אִלֵּין קַנְטְרִין. אֶלָּא מִכְּלָלָא דְּאִינּוּן קַנְטְרִין נַטְלוּ מָלֵי יְדַיְיהוּ. וְהַהוּא זְעֵיר, אִסְתַּלָּק עַל כֹּלָּא, כְּאִילּוּ הֲוָה כֹּלָּא בִּידַיְיהוּ.</p>\n<p>תָּא חֲזֵי, מָה כְּתִיב וַיַּרְא אַהֲרֹן וַיִּבֶן מִזְבֵּחַ לְפָנָיו. אִי חֲסִידָא קַדִּישָׁא, כַּמָה רְעוּתָךְ הֲוָה לְטָב, וְלָא יַדְעַת לְאִסְתַּמְּרָא. כֵּיוָן דְּאַרְמֵי לֵיהּ בְּנוּרָא, אִתְתָּקַּף חֵילָא דְּסִטְרָא אַחֲרָא תַּמָּן בְּנוּרָא, וְנָפַק <Nonei></i>דִּיּוּקְנָא דְּשׁוֹר, כְּמָה דְּאִתְּמַר בִּתְרֵין מְשִׁיכִין דְּסִטְרָא אַחֲרָא. מִיַּד וַיַּרְא אַהֲרֹן. מַהוּ וַיַּרְא אַהֲרֹן. חָמָא דְּסִטְרָא אַחֲרָא אִתְתָּקַּף, מִיַּד וַיִּבֶן מִזְבֵּחַ לְפָנָיו, דְּאִלְמָלֵא דְּאַקְדִּים וּבָנָה מִזְבֵּחַ דָּא, עָלְמָא אִתְהַדָּר לְחָרְבָּנָא.</p>\n<p>לְלִסְטִים דְּהֲוָה נָפִיק לְקַפְּחָא וּלְקָטְלָא בְּנֵי נָשָׁא, חָמָא לִגְיוֹנָא דְּמַלְכָּא, דְּהַהוּא לִסְטִים נָפַק בְּחֵילָא תַּקִּיף מָה עֲבַד הַהוּא לִגְיוֹנָא, אִשְׁתָּדַּל בַּהֲדֵי מַלְכָּא לְנָפְקָא בְּאָרְחָא. וּמָשִׁיךְ לֵיהּ הַהוּא לִגְיוֹנָא בְּהַהוּא אָרְחָא, עַד דְּאָזִיל הַהוּא לִסְטִים בְּהַהוּא אָרְחָא, חָמָא דִּיּוּקְנָא דְּמַלְכָּא קָאִים קָמֵּיהּ, כֵּיוָן דְּחָמָא לֵיהּ לְמַלְכָּא דְּהֲוָה אָזִיל קָמֵּיהּ בְּאָרְחָא, מִיַּד נִרְתָּע וְאַהְדָּר לַאֲחוֹרָא.</p>\n<p>כַּךָ וַיַּרְא אַהֲרֹן דִּסְטָר אַחֲרָא אִתָּקַף, אָחִיד בְּאַסְוָותָא, וְאַתְקִיף בִּסְטַר קְדוּשָׁה וְשַׁוֵּי לֵיהּ קָמֵיהּ. כֵּיוָן דְּחָמָא סִטְרָא בִּישָׁא דִּיּוּקְנָא דְּמַלְכָּא דְּקָאִים קָמֵיהּ, מִיַּד אַהְדָּר לַאֲחוֹרָא, וְאִתְחַלָּשׁ תֻּקְפֵּיהּ וְחֵילֵיהּ, דְּהָא אִתְתָּקַּף, (מיד ויבן מזבח לפניו) וּמִזְבֵּחַ דָּא אִתְגַּבָּר, וְאִתְחַלָּשׁ סִטְרָא אַחֲרָא.</p>\n<p>תָּא חֲזֵי מָה כְּתִיב (שמות ל״ב:ה׳) וַיִּקְרָא אַהֲרֹן וַיֹּאמַר חַג לַיְיָ' מָחָר. חַג לַיְיָ', וְלָא לָעֵגֶל. וְלִסְטַר קְדוּשָּׁה עֲבַד, וְלִסְטַר קְדוּשָּׁה קָרָא וְאָמַר. וְדָא אַסְוָותָא אַקְדִּים, דְּאִלְמָלֵא דְּעָבַד דָּא, לָא קָאִים עָלְמָא עַל קִיּוּמֵיהּ, וְעִם כָּל דָּא, לָא שָׁכִיךְ רוּגְזֵיהּ מֵאַהֲרֹן, אַף עַל גַּב דְּלָא אִתְכַּוָון לְבִישׁ.</p>\n<p>אֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אַהֲרֹן, תְּרֵין חַרְשִׁין אִלֵּין מַשְׁכוּ לָךְ לְמַּה דְּבָעוּ. חַיֶּיךָ, תְּרֵין בְּנָךְ יִפְּלוּן, וְעַל חוֹבָא דָּא יִתְפָּסְקוּן (ס\"א ובחובא דא יתפסון) הֲדָא הוּא דִכְתִיב, (דברים ט׳:כ׳) וּבְאַהֲרֹן הִתְאַנַּף יְיָ' מְאֹד לְהַשְׁמִידוֹ. מַאי לְהַשְׁמִידוֹ. אִלֵּין בְּנוֹי, כְּמָה דְאַתְּ אָמֵר (עמוס ב׳:ט׳) וָאַשְׁמִיד פִּרְיוֹ מִמַּעַל, דִּפְרִי דְּבַר נָשׁ בְּנוֹי אִינּוּן.</p>\n<p>תָּא חֲזֵי, אַהֲרֹן שַׁוֵּי לֵיהּ לְהַהוּא מִזְבֵּחַ לְפָנָיו, וְעֶגְּלָא תָּב לַאֲחוֹרָא. בְּנוֹי שַׁווּ לִסְטַר אַחֲרָא לְפָנָיו, וּסְטָר קְדוּשָּׁה אַהְדָּר לַאֲחוֹרָא, דִּכְתִּיב, (ויקרא י׳:א׳) וַיַּקְרִיבוּ לִפְנֵי יְיָ', לִפְנֵי יְיָ' שַׁווּ. אִתְפָּסוּ בְּחוֹבָה דָּא.</p>\n<p>אַהֲרֹן חָשַׁב, דְּבֵין כַּךְ יֵיתֵי מֹשֶׁה, וְעַל דָּא הַהוּא מִזְבֵּחַ לָא סָתִיר לֵיהּ מֹשֶׁה, דְּאִילּוּ הֲוָה כְּמָה דְּחַשְׁבִין בְּנִי נָשָׁא, מִלָה קַדְמָאָה דְּאִבָעֵי לְמֹשֶׁה, לְנַתְּצָא לְהַהוּא מִזְבֵּחַ אִצְטְרִיךְ, כְּמָה דְּנַבֵּי עִדּוֹ עַל מִזְבֵּחַ דְּבֵית אֵל, וּנְבוּאָתֵיהּ עַל הַהוּא מִזְבֵּחַ הֲוָה. אֲבָל הָכָא מִלָה אַחֲרָא הֲוָה כְּמָה דְּאִתְּמַר. וּכְתִּיב, וַיִּקַּח אֶת הָעֵגֶּל אֲשֶׁר עָשׂוּ, וְלָא כְּתִיב וַיִּנְתֹּץ אֶת הַמִּזְבֵּחַ.</p>\n<p>תָּא חֲזֵי וַיִּקְרָא אַהֲרֹן. אַכְרִיז אִיהוּ בְּקָלָא וְאָמַר. כְּתִיב הָכָא וַיִּקְרָא וַיֹּאמַר, וּכְתִיב בְּיוֹנָה (יונה ג׳:ד׳) וַיִּקְרָא וַיֹּאמַר, מָה לְּהַלָּן כָּרִיז לְדִינָא, אוּף הָכָא כָּרִיז לְדִינָא. חַג לַיְיָ' מָחָר, נָבֵּי נְבוּאָה בְּהַהוּא רוּחַ דְּמִזְבֵּחַ, דְּזַמִּין דִּינָא לְשַׁרְיָא עָלַיְיהוּ. חַג לַיְיָ', לְמֶעְבַּד בְּכוּ דִּינָא.</p>\n<p>וּתְלַת דִּינִין הֲווֹ, חַד, וַיִּגּוֹף יְיָ' אֶת הָעָם. וְחַד, בִּבְנֵי לֵוִי. וְחַד, דְּאַשְׁקֵי לִבְנֵי יִשְׂרָאֵל. וְהַיְינוּ חַג דִּבְנֵי לֵוִי. לַיְיָ', דְּוַיִגּוֹף יְיָ'. מָחָר, דְּאַשְׁקֵי לוֹן מֹשֶׁה. וּבִיתוֹ בְּהַהוּא לֵילְיָא, וּלְמָחָר אִשְׁתְּכָחוּ נְפִיחִין וּמֵתִין. וְאִינּוּן מַיִין הֲווֹ מְכַשְׁכְּשִׁין בִּמְעֵיהוֹן כָּל לֵילְיָא, וּבְצַפְרָא אִשְׁתְּכָחוּ מֵתִין, וְעַל דָּא חַג לַיְיָ' מָחָר. וְכָל אַסְוָתָא דְּעָבַד אַהֲרֹן, בְּגִין דִּכְתִּיב וַיִּבֶן מִזְבֵּחַ לְפָנָיו.</p>\n<p>תָּא חֲזֵי, (ההוא מזבח דקדושה הוה) דִּכְתִּיב וַיַּרְא אֶת הָעֵגֶל וּמְחוֹלוֹת, וְאִלּוּ מִזְבֵּחַ לָא כְּתִיב. דְּהָא אַהֲרֹן מִנְדַּע הֲוָה יָדַע, דִּכְתִּיב, (שמות כ״ב:י״ט) זֹבֵחַ לָאֱלֹהִים יָחֳרָם בִּלְתִּי לַיְיָ' לְבַדּוֹ, וַדַּאי אִשְׁתְּזִיב אַהֲרֹן בְּעֵיטָא טָבָא דְּדָבַר לְנַפְשֵׁיהּ, וְכֹלָּא בִּרְעוּתָא שְׁלִים טָב, דְּלָא אִתְכַּוָּין לְבִישׁ.</p>\n<p>אֲמַר לֵיהּ רִבִּי אֶלְעָזָר, אַבָּא וַדַּאי הָכִי הוּא, וְיִשְׂרָאֵל לָא הֲווֹ. אֲבָל יָרָבְעָם דְּעָבַד עֲגָלִין, הָא יִשְׂרָאֵל הֲווֹ, וְעֵגֶל עָבְדוּ. אֲמַר לֵיהּ וַדַּאי, וְאוּקְמוּהָ, אֲבָל יָרָבְעָם חָטָא וְהֶחטִיא, וְלָאו כְּמָה דְּאָמְרוּ. דְּוַדַּאי חוֹבָא בִּישָׁא עָבֵד וּבַמַּלְכוּת חָטָא.</p>\n<p>אָמַר יָרָבְעָם, וַדַּאי יָדַעְנָא דְּהָא סְטָר קְדוּשָׁה לָא שַׁרְיָא, אֶלָּא בְּלִבָּא דְּכָל עָלְמָא, וְדָא יְרוּשָׁלַם. אֲנָא לָא יָכִילְנָא לְאַמְשָׁכָא לְהַהוּא סְטָר הָכָא, מָה אַעְבִּיד. מִיַּד (מלכים א י״ב:כ״ח) וַיִּוָּעַץ הַמֶּלֶךְ וַיַּעַשׂ וְגוֹ'. נָטַל עֵיטָא בִּישָׁא, אָמַר הָא <Nonei></i>סִטְרָא אַחֲרָא, דְּאִתְמַשְּׁכָא מִיַּד לְכָל אֲתָר. וְכָּל שֶׁכֵּן בְּאַרְעָא דָּא, דְּתִיאוּבְתֵּיה לְאַשְׁרָאָה בְּגַוָּיהּ, אֲבָל לָא יַכְלָא לְאִתְלַבְּשָׁא אֶלָּא בְּדִיּוּקְנָא דְּשׁוֹר.</p>\n<p>תְּרֵין עֲגָּלִים אֲמַאי. אֶלָּא אָמַר יָרָבְעָם, (ס\"א במצרים ובמדברא) בְּמַדְבְּרָא הֲווֹ אִינּוּן חַרְשִׁין, דִּכְתִּיב, (יחזקאל כ״ג:כ׳) בְּשַׂר חֲמוֹרִים בְּשָׂרָם. (ס\"א לאאינון מצרים אלא) הָכָא, אִינּוּן תְּרֵין רוּחִין בִּישִׁין, יִתְלַבְּשׁוּ כַּדְקָא חֲזֵי לוֹן, דְּכַר וְנוּקְבָּא אִינּוּן. דְּכַר הֲוָה בְּבֵית אֵל, וְנוּקְבָּא הֲוַת בְּדָן. וּמִגּוֹ דִּכְתִּיב, (משלי ה׳:ג׳) נֹפֶת תִּטֹּפְנָה שִׂפְתֵי זָרָה, אִתְמָשְׁכוּ יִשְׂרָאֵל אֲבַתְרֵהּ יַתִּיר, דִּכְתִּיב וַיֵּלְכוּ הָעָם לִפְנֵי הָאֶחָד עַד דָּן. וּבְּגִין כָּךְ תְּרֵין עֲגָלִין הֲווֹ. וּמָשִׁיךְ לוֹן יָרָבְעָם בְּאַרְעָא קַדִּישָׁא, וַהֲוָה חוֹבָא עָלֵיהּ וְעַל יִשְׂרָאֵל, וּמָנַע בִּרְכָּאן מִן עָלְמָא. וְעָלֵיהּ כְּתִיב (משלי כ״ח:כ״ד) גוֹזֵל אָבִיו וְאִמּוֹ וְגוֹ'.</p>\n<p>וְעַל דָּא הֲווֹ עֲגָלִין, דְּהָא לְבוּשָׁא קַדְמָאָה דְּמִתְלַבַּשׁ סִטְרָא אַחֲרָא שׁוֹר אִיהוּ, (קצ\"א ע\"א) כְּמָה דְּאִתְּמַר. וְאִי תֵּימָא אֲמַאי אִיהוּ עֵגֶל וְלָא שׁוֹר. אֶלָּא וַדַּאי כַּךְ אִתְחָזֵי, וְכֵן בְכָל סִטְרִין, שֵׁירוּתָא דִּלְבוּשָׁא זוּטָא אִיהוּ, וְהָא אוֹקִימְנָא.</p>\n<p>וְעַל דָּא בָּנַי רְחִימָאי, כֵּיוָן דֶּאֱלֹהִים בָּעוּ, וּבִסְטַר דֶּאֱלהִים אִתְבְּנֵי עוֹבָדָא, אֱלֹהִים קַדִּישָׁא, אִימָא, דַּאֲחִידַת תָּדִיר בִּדְרוֹעָא דְּמַלְכָּא, וּסְלִיקַת רְצוּעָה, לָא הֲוַת תַּמָּן, וְאִצְטְרִיךְ לֵיהּ לְמֹשֶׁה לְמֶהֱוֵי תַּמָּן בְּאַתְרָהָא, כֵּיוָן דְּאַנְקִּיד לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אִסְתָּכַּל.</p>\n<p>תְּלַת זִמְנִין אַנְקִּיד לֵיהּ, אִי מֹשֶׁה רַעְיָא מְהֵימָנָא, כַּמָּה חֵילָךְ תַּקִּיף, כַּמָּה גְּבוּרְתָּךְ רַב, תְּלַת זִמְנִין אַנְקִּיד לֵיהּ, דִּכְתִּיב וְעַתָּה הַנִּיחָה לִי הָא חַד. וַיִּחַר אַפִּי בָהֶם וַאֲכַלֵּם, הָא תְּרֵין. וְאֶעֱשֶׂה אוֹתְךָ לְגוֹי גָּדוֹל, הָא תְּלַת. חָכְמְתָא דְּמֹשֶׁה בִּתְלַת נְקוּדִין אִלֵּין. אָחִיד בִּדְרוֹעֵיהּ יְמִינָא, לָקֳבֵל הַנִּיחָא לִי. אָחִיד בִּדְרוֹעֵיהּ שְׂמָאלָא, לָקֳבֵל וַיִּחַר אַפִּי בָהֶם וַאֲכַלֵּם. אִתְחַבָּק בְּגוּפָא דְּמַלְכָּא, לָקֳבֵל וְאֶעֱשֶׂה אוֹתְךָ לְגוֹי גָּדוֹל. וְכַד אִתְחַבָּק בְּגוּפָא, תְּרֵין דְּרוֹעִין מִסִּטְרָא דָּא וּמִסִּטְרָא דָּא, לָא יָכִיל לְאִתְנַעְנְעָא לְסִטְרָא בְּעָלְמָא. דָּא הֲוֵי חָכְמְתָא דְּמֹשֶׁה, (ס\"א דבמילי) דְּמִינִי נְקוּדִין דְּמַלְכָּא יָדַע בְּכָל חַד מִנַּיְיהוּ, בְּאָן אֲתָר יִתְתָּקַף, וּבְחָכְמְתָא עֲבַד.</p>\n<p>אָתוּ רִבִּי אֶלְעָזָר וְחַבְרַיָּא, וְנַשְׁקוּ יְדוֹי. הֲוָה תַּמָּן רִבִּי אַבָּא, אָמַר, אִלְמָלֵי לָא אָתֵינָא לְעָלְמָא אֶלָּא לְמִשְׁמַע דָּא, דַּי לָן. בָּכָה וְאָמַר, וַוי רִבִּי, כַּד תִּסְתָּלַּק מֵעָלְמָא, מַאן יַנְהֵר וִיגַלֵּי נְהוֹרִין דְּאוֹרַיְיתָא. מִלָּה דָּא, בַּחֲשׁוֹכָא אִתְטְמַר עַד הַשְׁתָּא, דְּנָפַק מִתַּמָּן, וְהָא נָהִיר עַד רוּם רְקִיעָא, וּבְכֻרְסְיָּא דְּמַלְכָּא רָשִׁים, וְקוּדְשָׁא בְּרִיךְ הוּא חַדֵּי הַשְׁתָּא בְּהַאי מִלָּה. וְכַמָּה חֵדוּ עַל חֵדוּ, אִתּוֹסָף מִקַּמֵּי מַלְכָּא קַדִּישָׁא. מַאן יִתְּעַר מִלֵּי דְּחָכְמְתָא בְּעָלְמָא דֵּין כְּוָותָיךְ.</p>\n<p>תָּא חֲזֵי, עַד לָא חָטָא אָדָם, הֲוָה סָלִיק וְקָאִים (בראשית נ\"ב ע\"ב) בְּחָכְמָה דִּנְהִירוּ עִלָּאָה, וְלָא הֲוָה מִתְפְּרַשׁ מֵאִילָנָא דְּחַיֵּי. כֵּיוָן דְּאַסְגֵּי תִּיאוּבְתָּא לְמִנְדַּע, וּלְנַחְתָּא לְתַתָּא, אִתְמְשִׁיךְ אֲבַתְרַיְיהוּ, עַד דְּאִתְפְּרַשׁ מֵאִילָנָא דְּחַיֵּי, וְיָדַע רַע וְשָׁבַק טוֹב. וְעַל דָּא כְּתִיב, (תהילים ה׳:ה׳) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לא יְגוּרְךָ רָע, מַאן דְּאִתְמְשָׁךְ בְּרָע, לֵית לֵיהּ דִּיּוּרָא עִם אִילָנָא דְּחַיֵּי. וְעַד לָא חָטְאוּ, הֲווֹ שַׁמְעִין קַלָּא מִלְעֵילָּא, וְיַדְעִין חָכְמְתָא עִלָּאָה, וְלָא דַּחֲלֵי. כֵּיוָן דְּחָטְאוּ, אֲפִילּוּ קַלָּא דִּלְתַתָּא, לָא הֲווֹ יַכְלִין לְמֵיקָם בֵּיהּ.</p>\n<p>כְּגַוְונָא דָּא, עַד לָא חָאבוּ יִשְׂרָאֵל, בְּשַׁעֲתָא דְּקַיְימוּ יִשְׂרָאֵל עַל טוּרָא דְּסִינַי, אִתְעֲבָר מִנַּיְיהוּ זוּהֲמָא דְּהַאי חִוְיָא, דְּהָא כְּדֵין בִּטוּל יֵצֶר הָרַע הֲוָה מֵעָלְמָא, וְדָחוּ לֵיהּ מִנַּיְיהוּ. וּכְדֵין אִתְאֲחִידוּ בְּאִילָנָא דְּחַיֵּי, וּסְלִיקוּ לְעֵילָּא, וְלָא נַחְתּוּ לְתַתָּא. כְּדֵין הֲווֹ יַדְעִין, וַהֲווּ חֲמָאן, אַסְפַּקְלַרְיָאן עִלָּאִין, וְאִתְנַהֲרָן עֵינַיְיהוּ, וְחַדָּאן לְמִנְדַּע וּלְמִשְׁמַע. וּכְדֵין חָגַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא, חַגִּירִין דְּאַתְוָון דִּשְׁמָא קַדִּישָׁא, דְּלָא יָכִיל לְשַׁלְּטָאָה עָלַיְיהוּ הַאי חִוְיָא, וְלָא יְסָאַב לוֹן כְּדִבְּקַדְמֵיתָא.</p>\n<p>כֵּיוָן דְּחָטוּ בַּעֶגְלָא, אִתְעֲבָרוּ מִנַּיְיהוּ כָּל אִינּוּן דַּרְגִּין, וּנְהוֹרִין עִלָּאִין, וְאִתְעֲבָר מִנַּיְיהוּ חֲגִירוּ מְזַיְּינִין, דְּאִתְעַטָּרוּ מִשְּׁמָא קַדִּישָׁא עִלָּאָה, וְאַמְשִׁיכוּ עָלַיְיהוּ חִוְיָא בִּישָׁא כְּמִלְּקַדְּמִין, וְגָרִימוּ מוֹתָא לְכָל עָלְמָא. וּלְבָתַר מָה כְּתִיב. וַיַּרְא אַהֲרֹן וְכָל בְּנֵי יִשְׂרָאֵל אֶת מֹשֶׁה וְהִנֵּה <Nonei></i>קָרַן עוֹר פָּנָיו וַיִּירְאוּ מִגֶּשֶׁת אֵלָיו.</p>\n<p>תָּא חֲזֵי, מָה כְּתִיב בְּקַדְמִיתָא, (שמות י״ד:ל״א) וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה, וְכֻלְּהוּ חֲמָאן זָהֲרִין עִלָּאִין, אִתְנָהֲרִין בְּאַסְפַּקְלַרְיָא דְּנַהֲרָא, דִּכְתִּיב, (שמות כ) וְכָל הָעָם רוֹאִים אֶת הַקּוֹלוֹת. וְעַל יַמָּא, הֲווֹ חֲמָאן וְלָא דַּחֲלִין, דִּכְתִּיב זֶה אֵלִי וְאַנְוֵהוּ, לְבָתַר דְּחָטוּ, פְּנֵי הַסִּרְסוּר לָא הֲווֹ יַכְלֵי לְמֵחמֵי. מָה כְּתִיב, וַיִּירְאוּ מִגֶּשֶׁת אֵלָיו.</p>\n<p>וְתָּא חֲזֵי, מָה כְּתִיב בְּהוּ (שמות ל״ג:ו׳) וַיִּתְנַצְּלוּ בְנִי יִשְׂרָאֵל אֶת עֶדְיָם (ע\"ג ע\"ב) מֵהַר חֹרֵב, דְּאִתְעֲבֵרוּ מִנַּיְיהוּ, אִינּוּן מְזַיְּינִין דְּאִתְחַבָּרוּ בְּהוּ בְּטוּרָא דְּסִינַי, בְּגִין דְּלָא יִשְׁלוֹט בְּהוּ הַהוּא חִוְיָא בִּישָׁא, כֵּיוָן דְּאִתְעַבָּר מִנַּיְיהוּ, מָה כְּתִיב, וּמֹשֶׁה (רל\"ו) יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנְה הַרְחֵק מִן הַמַּחֲנֶה. אָמַר רִבִּי אֶלְעָזָר, מַאי הַאי קְרָא לְגַבֵּי הַאי. אֶלָּא, כֵּיוָן דְּיָדַע מֹשֶׁה, דְּאִתְעֲבָרוּ מִנַּיְיהוּ דְּיִשְׂרָאֵל אִינּוּן זַיְינִין עִלָּאִין, אָמַר, הָא וַדַּאי מִכָּאן וּלְהָלְאָה, חִוְיָא בִּישָׁא יֵיתֵי לְדַיָּירָא בֵּינַיְיהוּ, וְאִי יְקוּם מַקְדְּשָׁא הָכָא בֵּינַיְיהוּ יִסְתְּאָב, מִיַּד וּמֹשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה הַרְחֵק מִן הַמַּחֲנֶה. בְּגִין דְּחָמָא מֹשֶׁה, דְּהָא כְּדֵין יִשְׁלוֹט חִוְיָא בִּישָׁא, מַה דְּלָא הֲוָה מִקַּדְמָת דְּנָא.</p>\n<p>וְקָרָא לוֹ אֹהֶל מוֹעֵד, וְכִי לָא הֲוָה בְּקַדְמִיתָא אֹהֶל מוֹעֵד. אֶלָּא, בְּקַדְמִיתָא אֹהֶל סְתָם, הַשְׁתָּא אֹהֶל מוֹעֵד. מַאי מוֹעֵד. רִבִּי אֶלְעָזָר אָמַר לְטָב, רִבִּי אַבָּא אָמַר לְבִישׁ, רִבִּי אֶלְעָזָר אָמַר לְטָב, מָה מוֹעֵד דְּאִיהוּ יוֹם חֶדְוָה דְּסִיהֲרָא, דְּאִיתּוֹסְפָא בֵּיהּ קְדוּשָּׁה, לָא שַׁלְטָא בָּהּ פְּגִימוּתָא, אוּף הָכָא קָרֵי לֵיהּ בִּשְׁמָא דָּא, לְאַחֲזָאָה דְּהָא אִתְרְחִיק מִבֵּינַיְיהוּ, וְלָא אִתְפְּגִים, וְעַל דָּא וְקָרָא לוֹ אֹהֶל מוֹעֵד כְּתִיב.</p>\n<p>וְרִבִּי אַבָּא אָמַר לְבִישׁ, דְּהָא בְּקַדְמִיתָא הֲוָה אֹהֶל סְתָם, כְּמָה דְאַתְּ אָמֵר (ישעיהו ל״ג:כ׳) אֹהֶל בַּל יִצְעָן בַּל יִסַּע יְתֵדוֹתָיו לָנְצַח. וְהַשְׁתָּא אֹהֶל מוֹעֵד. בְּקַדְמִיתָא, לְמֵיהַב חַיִּין אֲרוּכִין לְעָלְמִין, דְּלָא יִשְׁלוֹט בְּהוּ מוֹתָא. מִכָּאן לְהַלְאָה אֹהֶל מוֹעֵד, כְּמָה דְאַתְּ אָמֵר (איוב ל׳:כ״ג) וּבֵית מוֹעֵד לְכָל חָי, הַשְׁתָּא, אִתְיְיהִיב בֵּיהּ זִמְנָא וְחַיִּין קְצוּבִין לְעָלְמָא. בְּקַדְמִיתָא לָא אִתְפְּגִים, וְהַשְׁתָּא אִתְפְּגִים. בְּקַדְמִיתָא חַבְרוּתָא וְזִוּוּגָא לְסִהֲרָא בְּשִׁמְשָׁא, דְּלָא יַעְדוּן. הַשְׁתָּא אֹהֶל מוֹעֵד, זִוּוּגָא דִּלְהוֹן מִזְּמַן לִזְמַן, וּבְּגִין כָּךְ וְקָרָא לוֹ אֹהֶל מוֹעֵד, מָה דְּלָא הֲוָה קוֹדֶם.</p>"],[9520011832,"<p>רִבִּי שִׁמְעוֹן, הֲוָה יָתִיב לֵילְיָא חֲדָא, וְלָעֵי בְּאוֹרַיְיתָא, וַהֲווּ יַתְבֵי קָמֵיהּ רִבִּי יְהוּדָה וְרִבִּי יִצְחָק וְרִבִּי יוֹסֵי. אָמַר רִבִּי יְהוּדָה, הָא כְּתִיב וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חֹרֵב. וְקָאַמְרֵינָן דְּגַרְמוּ מוֹתָא עָלַיְיהוּ, מֵהַהוּא זִמְנָא וּלְעֵילָּא, וְשָׁלִיט בְּהוּ הַהוּא חִוְיָא בִּישָׁא, דְּאַעְדֵּי לֵיהּ מִנַּיְיהוּ בְּקַדְמִיתָא. יִשְׂרָאֵל תִּינַח. יְהוֹשֻׁעַ דְּלָא חָטָא, אִתְעָדֵי מִנֵּיהּ הַהוּא זַיְינָא עִלָּאָה דְּקַבִּיל עִמְּהוֹן בְּטוּרָא דְּסִינַי, אוֹ לָא.</p>\n<p>אִי תֵּימָא דְּלָא אִתְעָדֵי מִנֵּיהּ. אִי הָכִי, אֲמַאי מִית כִּשְׁאַר כָּל בְּנֵי נָשָׁא. וְאִי תֵּימָא דְּאִתְעָדֵי מִנֵּיהּ, אֲמַאי. וְהָא לָא חָטָא, דְּהָא אִיהוּ עִם מֹשֶׁה הֲוָה בְּשַׁעֲתָא דְּחָבוּ יִשְׂרָאֵל. וְאִי תֵּימָא דְּלָא קַבִּיל הַהוּא עִטְרָא בְּטוּרָא דְּסִינַי, כְּמָה דְּקַבִּילוּ יִשְׂרָאֵל. אֲמַאי.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהילים י״א:ז׳) כִּי צַדִּיק יְיָ' צְדָקוֹת אָהֵב יָשָׁר יֶחזוּ פָנִימוֹ, הַאי קְרָא אָמְרוּ בֵּיהּ חַבְרַיָּיא מָה דְּאָמְרוּ, אֲבָל כִּי צַדִּיק יְיָ', צַדִּיק הוּא, וּשְׁמֵיהּ צַדִּיק, וּבְּגִין כָּךְ צְדָקוֹת אָהֵב. יָשָׁר. וְאִיהוּ יָשָׁר, כְּמָה דְאַתְּ אָמֵר (דברים לכ) צַדִּיק וְיָשָׁר. וְעַל דָּא יְחֱזוּ פָנֵימוֹ, כָּל בְּנֵי עָלְמָא, וִיתַקְנוּן אָרְחַיְיהוּ, לְמֵהַךְ בְּאֹרַח מֵישָׁר כְּדְקָא יֵאוֹת.</p>\n<p>וְתָּא חֲזֵי, כַּד דָּאִין קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, לָא דָּן לֵיהּ אֶלָּא לְפוּם רוּבָּן דִּבְנֵי נָשָׁא. וְתָּא חֲזֵי, כַּד חָב אָדָם בְּאִילָנָא דְּאָכַל מִנֵּיהּ, גָּרַם לְהַהוּא אִילָנָא, דְּשָׁרֵי בֵּיהּ מוֹתָא לְכָל עָלְמָא, וְגָרַם פְּגִימוּ לְאַפְרְשָׁא אִתְּתָא מִבַּעְלָהּ, וְקָאִים חוֹבָה דִּפְגִּימוּ דָּא בְּסִיהֲרָא, עַד דְּקַיְימָן יִשְׂרָאֵל בְּטוּרָא דְּסִינַי, כֵּיוָן דְּקַיְימוּ יִשְׂרָאֵל בְּטוּרָא <Nonei></i>דְּסִינַי, אִתְעַבָּר הַהוּא פְּגִימוּ דְּסִיהֲרָא, וְקַיְּימָא לְאַנְהָרָא תָּדִיר. כֵּיוָן דְּחָבוּ יִשְׂרָאֵל בְּעֶגְלָא, תָּבַת סִיהֲרָא כְּמִלְּקַדְּמִין לְאִתְפַּגְּמָא, וְשַׁלְטָא חִוְיָא בִּישָׁא, וְאָחִיד בָּהּ, וּמָשִׁיךְ לָהּ לְגַבֵּיהּ, וְאִתְפְּגִימַת.</p>\n<p>וְכַד יָדַע מֹשֶׁה דְּחָבוּ יִשְׂרָאֵל, וְאִתְעֲבָרוּ מִנַּיְיהוּ אִינּוּן זַיְינִין קַדִּישִׁין, יָדַע וַדַּאי, דְּהָא חִוְיָא אָחִיד בָּהּ בְּסִיהֲרָא, לְאַמְשָׁכָא לָהּ לְגַבֵּיהּ, וְאִתְפְּגִימַת. כְּדֵין אַפִּיק לֵיהּ לְבַר. וְכֵיוָן דְּקַיְּימָא לְאִתְפַּגְּמָא, אַף עַל גַּב דִּיהוֹשֻׁעַ קָאִים בְּעִטְרָא דְּזַיְינִין דִּילָהּ, כֵּיוָן דִּפְגִּימוּ שַׁרְיָא בָּהּ, וְאִתְהַדְּרַת כְּמָה דְּאִתְפְּגִימַת בְּחוֹבָא דְּאָדָם, לָא יָכִיל בַּר נָשׁ לְאִתְקַיְּימָא. בַּר מֹשֶׁה, דְּהֲוָה שַׁלִּיט בָּהּ, וּמוֹתֵיהּ הֲוָה בִּסְטַר אַחֲרָא. וְעַל דָּא לָא הֲוָה רְשׁוּ בָּהּ, לְקַיְּימָא לִיְהוֹשֻׁעַ תָּדִיר, וְלָא לְאַחֲרָא. וְעַל דָּא אֹהֶל מוֹעֵד קָרֵי לֵיהּ, דְּהָא שַׁרְיָא בֵּיהּ זְמַן קָצִיב, לְכָל עָלְמָא.</p>\n<p>וְעַל דָּא, רָזָא דְּמִלָּה, אִית יְמִינָא לְעֵילָּא, וְאִית יְמִינָא לְתַתָּא. אִית שְׂמָאלָא לְעֵילָּא, וְאִית שְׂמָאלָא לְתַתָּא. אִית יְמִינָא לְעֵילָּא, בִּקְדוּשָּׁה עִלָּאָה. וְאִית יְמִינָא לְתַתָּא, דְּאִיהוּ בְּסִטְרָא אַחֲרָא. אִית שְׂמָאלָא לְעֵילָּא בִּקְדוּשָּׁה עִלָּאָה, לְאַתְעֲרָא רְחִימוּתָא, לְאִתְקַשְּׁרָא סִיהֲרָא, בַּאֲתָר קַדִּישָׁא לְעֵילָּא, לְאִתְנָהֲרָא.</p>\n<p>וְאִית שְׂמָאלָא לְתַתָּא, דְּאַפְרִישׁ רְחִימוּתָא דִּלְעֵילָּא, וְאַפְרִישׁ לָהּ מִלְּאַנְהָרָא בְּשִׁמְשָׁא, וּלְאִתְקָרְבָא בַּהֲדֵיהּ, וְדָא הוּא סִטְרָא דְּחִוְיָא בִּישָׁא. דְּכַד שְׂמָאלָא דָּא דִּלְתַתָּא אִתְּעָרָא, כְּדֵין מָשִׁיךְ לָהּ לְסִיהֲרָא, וְאַפְרִישׁ לָהּ מִלְּעֵילָּא, וְאִתְחַשְּׁכַת נְהוֹרָהָא, וְאִתְדַּבְּקַת בְּחִוְיָא, וּכְדֵין שָׁאִיבָת מוֹתָא לְתַתָּא, לְכֹלָּא דְּאִתְדָבָּקַת בְּחִוְיָא, וְאִתְרָחֲקַת מֵאִילָנָא דְּחַיֵּי, וְעַל דָּא גָּרִים מוֹתָא לְכָל עָלְמָא. וְדָא הוּא כַּד אִסְתְּאַב מַקְדְּשָׁא, עַד זִמְנָא קָצִיב, דְּאִתְתָּקָּנַת סִיהֲרָא, וְתָבַת לְאַנְהֲרָא, וְדָא הוּא אֹהֶל מוֹעֵד.</p>\n<p>וְעַל דָּא יְהוֹשֻׁעַ לָא מִית, אֶלָּא בְּעֵיטָא דְּנָחָשׁ דָּא, דְּקָרִיב וּפָגִים מַשְׁכְּנָא כִּדְקַדְמֵיתָא. וְדָא הוּא רָזָא דִּכְתִּיב, (שמות ל״ג:י״א) יְהוֹשֻׁעַ בִּן נוּן נַעַר. דְּאַף עַל גַּב דְּאִיהוּ נַעַר לְתַתָּא, לְקַבְּלָא נְהוֹרָא, לא יָמִישׁ מִתּוֹךְ הָאֹהֶל, כְּמָה דְּאִתְפְּגִים דָּא, הָכִי נָמֵי אִתְפְּגִים דָּא אַף עַל גַּב דְּזִינָא קַדִּישָׁא הֲוָה לֵיהּ, כֵּיוָן דְּאִתְפְּגִים סִיהֲרָא, הָכִי הוּא וַדַּאי לָא אִשְׁתְּזִיב בִּלְחוֹדוֹי מִנֵּיהּ, מֵהַהוּא גַּוְונָא מַמָּשׁ, וְהָא אִתְּמַר.</p>\n<p>זַכָּאִין אִינּוּן צַדִּיקַיָּא, דְּיַדְעִין רָזִין דְּאוֹרַיְיתָא, וּמִתְדַּבְּקִין בָּהּ בְּאוֹרַיְיתָא, וּמְקַיְּימִין קְרָא דִּכְתִּיב, (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה וְגוֹ'. וּבְגִינָהּ יִזְכּוּן לְחַיֵּי עָלְמָא דְּאָתֵי, דִּכְתִּיב, (דברים ל׳:כ׳) כִּי הוּא חַיֶּיךָ וְאוֹרֶךְ יָמֶיךָ וְגוֹ'.</p>"],[9520011833,"<p>(שמות ל״ה:א׳) וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנִי יִשְׂרָאֵל וְגוֹ'. רִבִּי חִיָּיא פָּתַח, (שמואל א ט״ו:ו׳) וַיֹּאמֶר שָׁאוּל אֶל הַקֵּנִי לְכוּ סוּרוּ רְדוּ וְגוֹ'. תָּא חֲזֵי, מָה כְּתִיב בַּעֲמָלֵק, (שמואל א ט״ו:ו׳) פָּקַדְתִּי אֵת אֲשֶׁר עָשָׂה עֲמָלֵק לְיִשְׂרָאֵל וְגוֹ'. וְקוּדְשָׁא בְּרִיךְ הוּא בְּכֻלְּהוּ קְרָבִין דְּעָבְדוּ שְׁאָר עַמְמִין לְגַבַּיְיהוּ דְּיִשְׂרָאֵל, מַאי טַעְמָא לָא אַקְשֵׁי קַמֵּיהּ, כְּהַאי קְרָבָא דְּעָבַד עֲמָלֵק לְגַבַּיְיהוּ. אֶלָּא וַדַּאי, קְרָבָא דְּעֲמָלֵק הֲוָה בְּכָל סִטְרִין, לְעֵילָּא וְתַתָּא, דְּהָא בְּהַהוּא זִמְנָא אִתְתָּקַּף חִוְיָא בִּישָׁא לְעֵילָּא, ואִתְתָּקַּף לְתַתָּא.</p>\n<p>מָה חִוְיָא בִּישָׁא כַּמִין עַל פָּרָשַׁת אָרְחִין, אוּף הָכָא נָמֵי עֲמָלֵק, חִוְיָא בִּישָׁא הֲוָה לְגַבַּיְיהוּ דְּיִשְׂרָאֵל, דְּכַמִין לוֹן <Nonei></i>עַל פָּרָשַׁת אָרְחִין, דִּכְתִּיב, (שמואל א ט״ו:ב׳) אֲשֶׁר שָׂם לוֹ בַּדֶּרֶךְ בַּעֲלוֹתוֹ מִמִּצְרָיִם. כַּמִין הֲוָה לְעֵילָּא, לְסָאֳבָא מַקְדְּשָׁא. וְכָמִין הֲוָה לְתַתָּא, לְסָאֲבָא לְיִשְׂרָאֵל. מְנָלָן, דִּכְתִּיב (דברים כ״ה:י״ח) אֲשֶׁר קָרְךָ בַּדֶּרֶךְ. כְּתִיב הָכָא אֲשֶׁר קָּרְךָ, וּכְתִיב הָתָם (דברים כ״ג:י״א) כִּי יִהְיֶה בְךָ אִישׁ אֲשֶׁר לָא טָהוֹר מִקְרֵה לָיְלָה.</p>\n<p>ועַל דָּא בְּבִלְעָם כְּתִיב, (במדבר כ״ג:ד׳) וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם. וַיִּקָּר לִישָׁנָא דִּמְסָאֲבָא נָקַט. וְאִי תֵּימָא, הָא כְּתִיב אֱלהִים. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא אַזְמִין לֵיהּ הַהוּא אֲתָר דִּמְסָאֲבָא, לְאִסְתַּאֲבָא בֵּיהּ, בְּהַהוּא דַּרְגָּא דְּאִיהוּ אִתְדַּבָּק לְאִסְתַּאֲבָא בֵּיהּ. מָה עֲבַד בִּלְעָם. אִיהוּ חָשִׁיב בְּאִינּוּן קָרְבָּנִין לְסַלְּקָא לְעֵילָּא, מִיַּד זַמִין לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא הַהוּא אֲתָר. אֲמַר לֵיהּ הָא מִסְאֲבוּ לְגַבָּךְ, כְּמָה דְּאִתְחָזֵי לָךְ, וְעַל דָּא וַיִּקָּר אֱלהִים אֶל בִּלְעָם.</p>\n<p>כְּגַוְונָא דָּא אֲשֶׁר קָרְךָ בַּדֶּרֶךְ וְגוֹ'. אַזְמִין לְגַבָּךְ הַהוּא חִוְיָא בִּישָׁא לְעֵילָּא, לְסָאֲבָא לְךָ בְּכָל סִטְרִין. וְאִלְמָלֵא דְּאִתְתָּקַּף מֹשֶׁה לְעֵילָּא, וִיהוֹשֻׁעַ לְתַתָּא, לָא יָכִילוּ יִשְׂרָאֵל לֵיהּ. וּבְגִין כַּךְ, נָטִיר קוּדְשָׁא בְּרִיךְ הוּא הַהוּא דְּבָבוּ, לְדָרֵי דָּרִין. מַאי טַעְמָא. בְּגִין דְּחָשִׁיב לְאַעְקְרָא אָת קַיָּימָא מֵאַתְרֵיהּ. וּבְגִין כַּךְ פָּקַדְתִּי, בִּפְקִידָּה, דְּהָא תַּמָּן (ויצא קנ\"ט ע\"ב) אִתְרְמִיז רָזָא דְּאָת קַיָּימָא קַדִּישָׁא.</p>\n<p>תָּא חֲזֵי, מָה כְּתִיב, וַיֹּאמֶר שָׁאוּל אֶל הַקֵּנִי. מַאן קֵנִי. דָּא יִתְרוֹ. וְכִי מַאן יָהִיב בְּנֵי יִתְרוֹ הָכָא, לְמֶהוֵי דִּיּוּרֵיהוֹן בַּעֲמָלֵק, וְהָא בִּירִיחוֹ הֲווֹ שַׁרְיָין. אֶלָּא הָא כְּתִיב, (שופטים א׳:ט״ז) וּבְנֵי קֵנִי חֹתֵן מֹשֶׁה עָלוּ מֵעִיר הַתְּמָרִים אֶת בְּנֵי יְהוּדָה מִדְבָּר יְהוּדָה וְגוֹ'. וְכַד עָלוּ מִתַּמָּן, שָׁרוּ בִּתְחוּמָא דַּעֲמָלֵק, עַד הַהוּא זִמְנָא דְּאָתָא שָׁאוּל מַלְכָּא, דִּכְתִּיב וַיָּסַר קֵנִי מִתּוֹךְ עֲמָלֵק.</p>\n<p>בְּגִין דְּהָא בְּזִמְנָא דְּחַיָּיבַיָּא אִשְׁתְּכָחוּ, (נ\"א אתענשו) אִינּוּן חֲסִידֵי וְזַכָּאֵי דְּמִשְׁתַּכְחִין בֵּינַיְיהוּ, מִתָּפְסָן בְּחוֹבֵיהוֹן, וְהָא אוּקְמוּהָ. כְּגַוְונָא דָּא, אִלְמָלֵא הַהוּא עִרְבּוּבְיָא דְּאִתְחַבָּרוּ בְּהוּ בְּיִשְׂרָאֵל, לָא אִתְעֲנָשׁוּ יִשְׂרָאֵל, עַל עוֹבָדָא דְּעֶגְלָא.</p>\n<p>וְתָּא חֲזֵי מָה כְּתִיב (קצ\"ז, רכ\"ד ע\"א) בְּקַדְמִיתָא, (שמות כ״ה:ב׳) מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ, לְאַכְלְלָא כֹּלָּא, בְּגִין דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד עוֹבָדָא דְּמַשְׁכְּנָא מִכָּל סִטְרִין, בְּמוֹחָא וּקְלִיפָה. וּבְגִין דַּהֲווֹ אִינּוּן עֵרֶב רַב בְּגַּוַּויְיהוּ, אִתְּמַר מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ, לְאַכְלְלָא לוֹן בֵּינַיְיהוּ דְּיִשְׂרָאֵל, דְּאִינּוּן מוֹחָא. וְכֻלְּהוּ אִתְפְּקָדוּ.</p>\n<p>לְבָתַר סָטָא זִינָא לְזִינֵיהּ, וְאָתוּ אִינּוּן עֵרֶב רַב וְעָבָדוּ יַת עֶגְלָא, וְסָטוּ אֲבַתְרַיְיהוּ אִינּוּן דְּמִיתוּ, וְגָרְמוּ לוֹן לְיִשְׂרָאֵל מוֹתָא וְקָטוֹלָא. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, מִכָּאן וּלְהָלְאָה עוֹבָדָא דְּמַשְׁכְּנָא לָא יְהֵא, אֶלָּא (קצ\"ז ע\"א) מִסִּטְרָא דְּיִשְׂרָאֵל בִּלְחוֹדַיְיהוּ. מִיַּד וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנִי יִשְׂרָאֵל וְגוֹ'. וּכְתִיב בַּתְרֵיהּ קְחוּ מֵאִתְּכֶם תְּרוּמָה לַיְיָ'. מֵאִתְּכֶם וַדַּאי, וְלָא כְּקַדְמִיתָא דִּכְתִּיב, מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ. וַיַּקְהֵל מֹשֶׁה וְגוֹ', מֵאָן אֲתָר כָּנִישׁ לוֹן. אֶלָּא בְּגִין דַּהֲווֹ אִינּוּן עֵרֶב רַב בֵּינַיְיהוּ, אִצְטְרִיךְ מֹשֶׁה לְאַכְנָשָׁא לוֹן, וּלְיַחֲדָא לוֹן מִבֵּינַיְיהוּ.</p>\n<p>(שמות ל״ה:א׳) וַיַּקְהֵל מֹשֶׁה. רִבִּי אַבָּא פָּתַח, (דברים ל״א:י״ב) הַקְהֵל אֶת הָעָם הָאֲנָשִׁים וְהַנָּשִׁים וְהַטַּף. מָה לְּהַלָּן כְּלָלָא דְּכֻלְּהוּ יִשְׂרָאֵל, אוּף הָכָא כְּלָלָא דְּכֻלְּהוּ יִשְׂרָאֵל, וּמַאן אִינּוּן. שִׁתִּין רִבּוֹא.</p>\n<p>רִבִּי אֶלְעָזָר פָּתַח קְרָא בְּיִשְׂרָאֵל, כַּד נָחִית מֹשֶׁה מִן טוּרָא דְּסִינַי, דִּכְתִּיב, (שמות ל״ב:י״ז) וַיִּשְׁמַע יְהוֹשֻׁעַ אֶת קוֹל הָעָם בְּרֵעֹה וַיֹּאמֶר אֶל מֹשֶׁה קוֹל מִלְחָמָה בַּמַּחֲנֶה. וַיִּשְׁמַע יְהוֹשֻׁעַ, וְכִי יְהוֹשֻׁעַ שָׁמַע, וּמֹשֶׁה לָא שָׁמַע. אֶלָּא וַדַּאי, עַד הַשְׁתָּא יְהוֹשֻׁעַ לָא הֲוָה יָדַע, וּמֹשֶׁה הֲוָה יָדַע. אִי הָכִי מַהוּ בְּרֵעֹה. אֶלָּא בְּרֵעֹה בְּהֵ' כְּתִיב, דְּהַהוּא קַלָּא בְּסִטְרָא אַחֲרָא הֲוָה. וִיהוֹשֻׁעַ דְּהֲוָה אַנְפּוֹי דְּסִיהֲרָא, אִסְתָּכַּל בְּהַהוּא קָלָא, דְּהֲוָה דְּסִטְרָא דְּרָעָה, מִיַּד וַיֹּאמֶר אֶל מֹשֶׁה קוֹל מִלְחָמָה בַּמַּחֲנְה.</p>\n<p>בְּהַהִיא שַׁעֲתָא אִתְבָּרוּ תְּרֵין לוּחֵי אַבְנָא דַּהֲווֹ בְּקַדְמִיתָא. וְהָא אוֹקִימְנָא, דְּאִינּוּן אִתְיָיקָרוּ עַל יְדוֹי <Nonei></i>וְנָפְלוּ וְאִתְבָּרוּ. מַאי טַעְמָא. בְּגִין דְּפָרְחוּ אַתְוָון מִגּוֹ לוּחֵי אֲבָנִין. (פ\"א ע\"א, ויקרא ע\"ו)</p>\n<p>תָּא חֲזֵי, בְּד' תְּקוּפִין דְּשַׁתָּא, קָלָא אִתְּעַר, בְּד' סִטְרִין דְּעָלְמָא, בְּהַהוּא קָלָּא אִתְּעָרוּתָא דְּסִטְרָא אַחֲרָא אִתְּעַר בֵּיהּ. וְהַהוּא אִתְּעָרוּתָא דְּסִטְרָא אַחֲרָא עָאל בֵּין קַלָּא לְקָלָא, וְאִתְחֲשָׁךְ נְהוֹרָא בְּקָלָא דִּלְתַתָּא. בְּגִין דְּלָא מָטָא נְהוֹרָא דְּקָלָא דִּלְעֵילָּא, לְקָלָא דִּלְתַתָּא, כְּדֵין אַקְדִּים הַהוּא אִתְּעָרוּתָא, וְעָאל בֵּין דָּא לְדָא נָחָשׁ דִּמְפַתֵּי לְאִתְּתָא, וְנָטִיל נְהוֹרָא. וְהַהוּא קָלָא, הוּא קוֹל מִלְחָמָה, קוֹל רָעָה. וְדָא אִיהוּ בְּרֵעֹה.</p>\n<p>וְעַל דָּא שָׁמַע יְהוֹשֻׁעַ וְלָא מֹשֶׁה, בְּגִין דְּנָטַל הַהוּא רָעָה נְהוֹרָא דְּסִיהֲרָא דְּהֲוָה אָחִיד בָּהּ יְהוֹשֻׁעַ. וּמֹשֶׁה דְּהֲוָה אָחִיד בְּשִׁמְשָׁא, לָא שָׁמַע. וְיִשְׂרָאֵל כֻּלְּהוּ אִתְחֲשָׁךְ נְהוֹרָא דִּילְהוֹן, בְּגִין הַהוּא רָעָה דְּאִתְדַּבְּקָת בְּהוּ. כֵּיוָן דְּמָחַל קוּדְשָׁא בְּרִיךְ הוּא חוֹבֵיהוֹן, כְּדֵין וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל וַיֹּאמֶר אֲלֵיהֶם אֵלֶּה הַדְּבָרִים וְגוֹ', דְּהָא הַהוּא עֵרֶב רַב אִתְעַבָּר מִנַּיְיהוּ.</p>"],[9520011834,"<p>רִבִּי אֶלְעָזָר וְרִבִּי יוֹסֵי הָווֹ יַתְבֵי לֵילְיָא חַד, וְקָא מִתְעַסְקֵי בְּאוֹרַיְיתָא, עַד לָא אִתְפְּלִיג לֵילְיָא. אַדְּהָכִי קָרָא גַּבְרָא, בְּרִיכוּ בִּרְכָתָא, (אמר ליה רבי אלעזר, השתא הוא זמנא דקודשא בריך הוא עאל בגנתא דעדן לאשתעשעא עם צדיקיא, אמר ליה רבי יוסי, אמאי משתעשע קודשא בהך הוא) בָּכָה רִבִּי אֶלְעָזָר וְאָמַר, תָּא חֲזֵי, עַד הַשְׁתָּא קוּדְשָׁא בְּרִיךְ הוּא אִזְדַּעְזָע, תְּלָת מְאָה וְתִשְׁעִין רְקִיעִין, וּבָטַשׁ בְּהוּ, וּבָכָה עַל חָרְבַּן בֵּי מַקְדְּשָׁא, וְאוֹרִיד תְּרֵין (י\"ט ע\"ב) דִּמְעִין לְגוֹ יַמָּא רַבָּא, וְאַדְכַּר לִבְנוֹהִי מִגּוֹ בִּכְיָה.</p>\n<p>בְּגִין דְּלִתְלַת סִטְרִין אִתְפְּלַג לֵילְיָא, בִּתְרֵיסַר שַׁעְתֵּי דַּהֲווֹ רְשִׁימִין בֵּיהּ, וְאִי אִתּוֹסְפָן שַׁעְתֵּי בְּלֵילְיָא, אִינּוּן שַׁעְתֵּי דְּמִתּוֹסְפָאן, דִּימָמָא אִינּוּן, וְלָא אִתְחַשִׁיבוּ מִלֵילְיָא, בַּר תְּרֵיסַר דְּאִינּוּן דִּילֵהּ. וְאִינּוּן תְּרֵיסַר, אִתְפְּלָגוּ לִתְלַת סִטְרִין, (זהר רות כ\"ו ע\"א) וּתְלַת מַשִׁרְיָין דְּמַלְאָכִין קַדִּישִׁין, אִתְפְּלָגוּ (ס\"א אתמנון) בְּאִינּוּן תְּלַת סִטְרִין.</p>\n<p>מַשִּׁרְיָיא קַדְמָאָה, אִתְמַנָּא בְּד' שַׁעְתֵּי קָמַיְיתָא, דְּשֵׁירוּתָא דְּלֵילְיָא, לְשַׁבְּחָא לְמָארֵיהוֹן, וּמָה קָאַמְרֵי. (תהילים כ״ד:ג׳) לַיְיָ' הָאָרֶץ וּמְלֹאָהּ וְגוֹ', כִּי הוּא עַל יַמִים יְסָדָהּ וְגוֹ', מִי יַעֲלֶה בְהַר יְיָ' וְגוֹ', נְקִי כַפַּיִם וּבַר לֵבָב וְגוֹ'. מַאי טַעְמָא דָּא. בְּגִין דְּכַד לֵילְיָא פָּרִישׂ גַּדְפּוֹי עַל עָלְמָא, כְּדֵין, כָּל בְּנֵי עָלְמָא טַעֲמִין טַעֲמָא דְּמוֹתָא, וְנַפְקֵי נִשְׁמָתַיְיהוּ לְסַלְּקָא לְעֵילָּא, וְאִינּוּן מַלְאָכִין קַיְימִין וְקָא אַמְרֵי, מִי יַעֲלֶה בְהַר יְיָ'. הַר יְיָ', דָּא הַר הַבַּיִת. מְקוֹם קָדְשׁוֹ, דָּא עֲזָרַת יִשְׂרָאֵל. כְּגַוְונָא דִּלְעֵילָּא, הָכִי נָמֵי לְתַתָּא.</p>\n<p>בְּגִין דִּבְכָל רְקִיעָא וּרְקִיעָא, כַּמָּה מְמָנָן, וּכְמָּה סַרְכִין קַיְימִין תַּמָּן. וְכַד נִשְׁמָתִין נָפְקִין, בָּעָאן לְסַלְּקָא לְעֵילָּא, וְאִי לָא זַכְיָין אִינּוּן דַּחְיָין לוֹן לְבַר, וְאַזְלִין וְשָׁאטִין בְּעָלְמָא, וְנַטְלִין לוֹן כַּמָה חֲבִילֵי טְהִירִין, וְאוֹדְעִין לוֹן מִלִּין כְּדִיבָן, וּלְזִמְנִין מִלִּין דִּקְשׁוֹט, מִמַּה דְּאָתֵי לִזְמַן (רנ\"ב ע\"ב) קָרִיב, כְּמָה דְּאוּקְמוּהָ.</p>\n<p>וְאִינּוּן נִשְׁמָתִין דְּצַדִּיקַיָּיא, אָזְלִין וְשָׁאטָן לְעֵילָּא, וּפַתְחִין לוֹן פִּתְחִין, וְסַלְּקִין לוֹן לְגוֹ הַהוּא אֲתָר דְּאִקְרֵי הַר יְיָ', כְּגַוְונָא דְּרָזָא דְּהַר הַבַּיִת לְתַתָּא. וּמִתַּמָּן עָאלִין לְגוֹ הַהוּא אֲתָר דְּאִקְרֵי מְקוֹם קָדְשׁוֹ. דְּתַמָּן אִתְחַזְיָין כָּל נִשְׁמָתִין לְקָמֵי מָארֵיהוֹן. כְּגַוְונָא דָּא הַהוּא אֲתָר, דְּאִתְחָזוּן יִשְׂרָאֵל קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אֲתָר דְּאִקְרֵי עֲזָרַת יִשְׂרָאֵל. בְּשַׁעֲתָא דְּנִשְׁמָתִין קַיְימִין תַּמָּן, כְּדֵין חֶדְוָה דְּמָארִיהוֹן, לְאִתְתָּקְנָא בְּהוּ אֲתָר, דְּאִקְרֵי קֹדֶשׁ (רנ\"ח ע\"ב) הַקָּדָשִׁים. וְתַמָּן רְשִׁימִין כָּל עוֹבָדֵיהוֹן וְזַכְוָון דִּלְהוֹן.</p>\n<p>מַשִּׁרְיָיא תִּנְיָינָא, אִתְמַנָּא בְּאַרְבַּע שַׁעְתֵּי אַחֲרָנִין, וְלָא אַמְרֵי שִׁירָתָא, בַּר תְּרֵי שַׁעְתֵּי, עַד דְּאִתְפְּלַג לֵילְיָא, וְעָאל קוּדְשָׁא בְּרִיךְ הוּא בְּגִנְתָּא דְּעֵדֶן.</p>\n<p>וְאִלֵּין אִינּוּן אֲבֵלֵי צִיּוֹן, וְאִינּוּן דְּבָכוּ עַל חָרְבַּן בֵּי מַקְדְּשָׁא. וּבְשֵׁירוּתָא דְּאַרְבַּע שַׁעְתֵּי אֶמְצָעֲיָּן, פַּתְחֵי וְאַמְרֵי, (תהילים קל״ז:א׳) עַל נַהֲרוֹת בָּבֶל שָׁם יָשַׁבְנוּ גַּם בָּכִינוּ וְגוֹ', וְאִלֵּין אִינּוּן דְּבָכוּ עַל נַהֲרוֹת בָּבֶל, עִמְּהוֹן דְּיִשְׂרָאֵל, <Nonei></i>מִמַּשְׁמַע דִּכְתִּיב גַּם בָּכִינוּ. וּמְנָלָן דְּבָכוּ תַּמָּן. דִּכְתִּיב, (ישעיהו ל״ג:ז׳) הֵן אֶרְאֶלָּם צָעֲקוּ חוּצָה. מַהוּ חוּצָה. דָּא בָּבֶל, בְּגִין דְּכֻלְּהוּ אוֹזְפוּהָ לִשְׁכִינָה עַד בָּבֶל. וְתַמָּן בָּכוּ עִמְּהוֹן דְּיִשְׂרָאֵל. וְעַל דָּא פַּתְחֵי בְּהַאי, וּמְסַיְּימֵי זְכוֹר יְיָ' לִבְנִי אֱדוֹם וְגוֹ'.</p>\n<p>כְּדֵין אִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא בְּדַרְגּוֹי, וּבָטַשׁ בִּרְקִיעִין כִּדְאַמָרָן, וְאִזְדַּעֲזָעוּ תְּרֵיסַר אַלְפֵי עָלְמִין, וְגָעֵי וּבָכֵי, דִּכְתִּיב, (ירמיהו כ״ה:ל׳) יְיָ' מִמָּרוֹם יִשְׁאָג וּמִמְּעוֹן קָדְשׁוֹ יִתֵּן קוֹלוֹ שָׁאוֹג יִשְׁאַג עַל נָוִהוּ, וְאַדְכַּר לוֹן לְיִשְׂרָאֵל, וְאָחִית תְּרֵין דִּמְעִין לְגוֹ יַמָּא רַבָּא. וּכְדֵין אִתְּעַר שַׁלְהוֹבִיתָא חַד דְּבִסְטַר צָפוֹן, וּבָטַשׁ רוּחָא חַד דְּבִסְטַר צָפוֹן בְּהַהוּא שַׁלְהוֹבִיתָא, וְאַזְלָא וְשָׁאֲטָא בְּעָלְמָא, וְהַהִיא שַׁעֲתָא אִתְפְּלַג לֵילְיָא, וְשַׁלְהוֹבִיתָא אַזְלָא וּבָטַשׁ בְּגַדְפוֹי דְּתַרְנְגוֹלָא, וְקָארֵי, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא עָאל בְּגִּנְתָּא דְּעֵדֶן.</p>\n<p>וְקוּדְשָׁא בְּרִיךְ הוּא לֵית לֵיהּ נַיְיחָא עַד דְּעָאל לְגִנְתָּא דְּעֵדֶן לְאִשְׁתַּעְשְׁעָא בְּנִשְׁמָתֵהוֹן דְּצַדִּיקַיָּיא. וְסִימָן (אסתר ז׳:ד׳) כִּי נִמְכַּרְנוּ אֲנִי וְעַמִּי וְגוֹ'. וַיֹּאמֶר הַמֶּלֶךְ מִי הוּא זֶה וְגוֹ', וְהַמֶּלֶךְ קָם בַּחֲמָתוֹ מִמִּשְׁתֵּה הַיַּיִן אֶל גִּנַּת הַבִּיתָן וְגוֹ'.</p>\n<p>בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא עָאל בְּגִּנְתָּא דְּעֵדֶן, כְּדֵין כָּל אִינּוּן אִילָנִין דְּגִּנְתָּא, וְכָל אִינּוּן נִשְׁמָתִין דְּצַדִּיקַיָּיא, פַּתְחֵי וְאַמְרֵי, (תהילים כ״ד:ז׳) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְגוֹ'. מִי זֶה מֶלֶךְ הַכָּבוֹד וְגוֹ'. שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְגוֹ'. וּבְשַׁעֲתָא דְּנִשְׁמָתְהוֹן דְּצַדִּיקַיָּיא דִּי בְּאַרְעָא אָהַדְרוּ לְגוּפַיְיהוּ, כְּדֵין אַתְקִיפוּ בְּהוּ כָּל אִינּוּן מַלְאָכִין, וְאַמְרֵי (תהילים קל״ד:א׳) הִנֵּה בָּרְכוּ אֶת יְיָ' כָּל עַבְדֵּי יְיָ'. וְאוֹלִיפְנָא דְּדָא מַשִּׁרְיָיא תְּלִיתָאָה קָא אַמְרֵי דָּא, בְּאַרְבַּע שַׁעְתֵּי בַּתְרַיְיתָא.</p>\n<p>וְקָאֲמְרֵי שִׁירָתָא, עַד דְּסָלִיק נְהוֹרָא דְּצַפְרָא, דִּכְדֵין מְשַׁבְּחִין לְמָרֵיהוֹן כָּל אִינּוּן כֹּכָבַיָא וּמַזָּלֵי, וְכָל אִינּוּן מַלְאָכִין עִלָּאִין, דִּי שֻׁלְטָנֵיהוֹן בִּימָמָא, כֻּלְּהוּ מְשַׁבְּחָן לְמָארִיהוֹן, וְאַמְרֵי שִׁירָתָא. הֲדָא הוּא דִכְתִיב, (איוב ל״ח:ז׳) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים.</p>\n<p>בְּשַׁעֲתָא דְּשִׁמְשָׁא נָפִיק, בִּימָמָא, יִשְׂרָאֵל נַטְלֵי שִׁירָתָא לְתַתָּא, וְשִׁמְשָׁא לְעֵילָּא, דִּכְתִּיב, (תהילים ע״ב:ה׳) יִירָאוּךָ עִם שָׁמֶשׁ. בְּשַׁעֲתָא דְּנָטִיל שִׁמְשָׁא בְּגַלְגְלוֹי, פָּתַח קַל נְעִימוּתָא, וְאָמַר שִׁירָתָא. וּמַאי שִׁירָתָא קָאַמְרֵי. (תהילים ק״ה:א׳) הוֹדוּ לַיְיָ' קִרְאוּ בִשְׁמוֹ וְגוֹ'. (תהילים ק״ה:א׳) שִׁירוּ לוֹ זַמְּרוּ לוֹ וְגוֹ'. וְיִשְׂרָאֵל מְשַׁבְּחָן לְקוּדְשָׁא בְּרִיךְ הוּא בִּימָמָא, עִם שִׁמְשָׁא. הֲדָא הוּא דִכְתִיב יִירָאוּךָ עִם שָׁמֶשׁ, וְאַף עַל גַּב דְּהָא אוֹקִימְנָא לְהַאי קְרָא, אָמַר רִבִּי אֶלְעָזָר, אִלְמָלֵא דִּבְנֵי עָלְמָא אֲטִימִין לִבָּא וּסְתִימִין עַיְינִין לָא יַכְלִין לְמֵיקָם מִקָּל נְעִימוּתָא דְּגַלְגָלָא דְּשִׁמְשָׁא, כַּד נָטִיל (ונפיק) וּמְשַׁבַּח קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9520011835,"<p>אַדְּהָכִי דְּאִתְעַסְּקוּ בְּאוֹרַיְיתָא, נָהַר יְמָמָא. קָמוּ וְאָתוּ לְקָמֵיהּ דְּרַבִּי שִׁמְעוֹן, כֵּיוָן דְּחָמָא לוֹן, אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּרִי, אַנְתְּ וְחַבְרַיָּיא אַסְתִּימוּ גַּרְמַיְיכוּ אִלֵּין תְּלַת יוֹמִין, דְּלָא תִּפְקוּן לְבַר בְּגִין דְּמַלְאָךְ הַמָּוֶת אִשְׁתְּכַח בְּמָתָא, וְאִית לֵיהּ רְשׁוּ לְחַבְּלָא, וְכֵיוָן דְּאִתְיְיהִיב לֵיהּ רְשׁוּ לְחַבְּלָא, יָכִיל לְחַבְּלָא, לְכָל מַאן דְּאִתְחָזֵי קַמֵיהּ.</p>\n<p>וְתוּ דְּבַר נָשׁ דְּאִתְחָזֵי קַמֵּיהּ, סָלִיק וְאַסְטֵי עָלֵיהּ, וְאַדְכַּר חוֹבוֹי, וּבָעֵי דִּינָא מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְלָא אִתְעָדֵי מִתַּמָּן, עַד דְּאִתְּדָּן הַהוּא בַּר נָשׁ, וְאִתְיְיהִיב לֵיהּ רְשׁוּ וְקָטִיל לֵיהּ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, הָאֱלהִים, רוּבָּא דְּעָלְמָא, לָא מִיתוּ, עַד לָא מָטָא זִמְנַיְיהוּ, בַּר דְּלָא יַדְעֵי לְאִסְתַּמְּרָא גַּרְמַיְיהוּ, דְּהָא בְּשַׁעֲתָא דְּמִיתָא אַפְקֵי לֵיהּ מִבֵּיתֵיהּ לְבֵי קִבְרֵי, מַלְאָךְ הַמָּוֶת אִשְׁתְּכַח בֵּינֵי נְשֵׁי, אֲמַאי בֵּינֵי נְשֵׁי. דְּהָכִי (רכ\"ז ע\"א) הוּא אוֹרְחוֹי, מִיּוֹמָא דְּפַתֵּי לְחַוָּה, וּבְגִינָהּ גָּרִים מוֹתָא לְכָל עָלְמָא. וְעַל דָּא (כד) קָטִיל בַּר נָשׁ, וְגוּבְרֵי אִשְׁתְּכָחוּ עִם מִיתָא, עָאל בֵּינֵי נְשֵׁי בְּאָרְחָא.</p>\n<p>וְאִית לֵיהּ רְשׁוּ, לְמִקְטַל בְּנֵי נָשָׁא, וְאִסְתָּכַּל בְּאַנְפַּיְיהוּ בְּאָרְחָא דְּאִתְחֲזִיאוּ קַמֵּיהּ, מִשַׁעֲתָא דְּמָפְקֵי לֵיהּ מִבֵּיתֵיהּ לְבֵי קִבְרֵי, עַד דְּאָהַדְרוּ לְבֵיתַיְּיהוּ וּבְגִינֵיהוֹן גָּרִים מוֹתָא לְכַמָּה גּוּבְרִין בְּעָלְמָא, עַד לָא מָטָא זִמְנַיְיהוּ. וְעַל דָּא כְּתִיב, (משלי י״ג:כ״ג) וְיֵשׁ נִסְפֶּה בְּלא מִשְׁפָּט. בְּגִין דְּסָלִיק וְאַסְטִין, וְאַדְכַּר חוֹבוֹי דְּבַר נָשׁ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְאִתְדַן עַל אִינּוּן חוֹבִין וְאִסְתַּלָּק עַד לָא מָטָא זִמְנֵיהּ.</p>\n<p>מַאי תַּקָנְתֵּיה. בְּשַׁעֲתָא דְּנַטְלֵי מֵיתָא לְבֵי קִבְרֵי, יֶהְדַּר בַּר נָשׁ <Nonei></i>אַנְפּוֹי וְיִּשְׁבּוֹק לְנָשֵׁי בָּתַר כַּתְפּוֹי. וְאִי אִינּוּן מְקַדְּמֵי, יְהַךְ לַאֲחוֹרָא, בְּגִין דְּלָא יִתְחָזֵי עִמְּהוֹן אַנְפִּין בְּאַנְפִּין. וּלְבָתַר דִּמְהֲדְרֵי מִבֵּי קִבְרֵי, לָא יֶהְדַּר בְּהַהוּא אָרְחָא דְּנָשֵׁי קַיְימָן, וְלָא יִסְתָּכַּל בְּהוּ כְּלַל, אֶלָּא יִסְטֵי בְּאָרְחָא אַחֲרָא. וּבְגִין דִּבְנֵי נָשָׁא לָא יַדְעֵי, וְלָא מִסְתַּכְּלִן דָּא רוּבָּא דְּעָלְמָא, אִתְדָּנוּ בְּדִינָא, וְאִסְתַּלָּקוּ עַד לָא מָטָא זִמְנַיְיהוּ.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, אִי הָכִי, טָב לֵיהּ לְבַר נָשׁ דְּלָא יוֹזִיף לְמִיתָא. אֲמַר לֵיהּ לָא. דְּהָא בַּר נָשׁ דְּאִסְתָּמַר כְּהַאי גַּוְונָא, אִתְחָזֵי לְאַרְכָּא דְּיוֹמִין, וְכָל שֶׁכֵּן לְעָלְמָא דְּאָתֵי.</p>\n<p>תָּא חֲזֵי, לָאו לְמַגָּנָא אַתְקִינוּ קַדְמָאֵי שׁוֹפָר, לְאַמְשָׁכָא מִיתָא מִן בֵּיתָא לְבֵי קִבְרֵי. אִי תֵּימָא דְּעַל מֵיתָא וִיּקָרָא דִּילֵיהּ לְחוּד אִיהוּ. לָא. אֶלָּא, בְּגִין לְאַגָּנָא עַל חַיָּיא, דְּלָא יִשְׁלוֹט עָלַיְיהוּ מַלְאָךְ הַמָּוֶת, לְאַסְטָאָה לְעֵילָּא וְיִסְתַּמְרוּן מִנֵּיהּ.</p>\n<p>פָּתַח וְאָמַר, (במדבר י׳:ט׳) וְכִי תָבֹאוּ מִלְחָמָה בְּאַרְצְכֶם עַל הַצָּר הַצּוֹרֵר אֶתְכֶם וְגוֹ', וְדָּיִּיקְנָא עַל הַצָּר, דָּא מַלְאָךְ הַמָּוְת. הַצּוֹרֵר אֶתְכֶם תָּדִיר, וְקָטִיל לִבְנֵי נָשָׁא, (ואעיק לון לחיי) וּבָעֵי לְקָטְלָא אַחֲרָנִין. מַאי תַּקָנְתֵּיהּ. וַהֲרֵעוֹתֶם. אִם בְּרֹאשׁ הַשָּׁנָה, דְּהוּא יוֹמָא דְּדִינָא לְעֵילָּא, הַאי מַלְאָךְ הַמָּוֶת נָחִית לְתַתָּא, בְּגִין לְאַשְׁגָּחָא בְּעוֹבָדִין דִּבְנֵי נָשָׁא, וּלְסַלְּקָא לְעֵילָּא לְאַסְטָאָה לוֹן. וְיִשְׂרָאֵל דְּיַדְעֵי דְּהָא מַלְאָךְ הַמָּוֶת נָחִית לְתַתָּא וְסָלִיק לְעֵילָּא, בְּגִין לְמֶהוֵי קַטֵיגוֹרָא עָלַיְיהוּ. מְקַדְּמֵי בַּשּׁוֹפָר לְיַבְּבָא עָלֵיהּ, דְּלָא יָכִיל לוֹן וּלְאַגָּנָא עָלַיְיהוּ.</p>\n<p>וְכָל שֶׁכֵּן בְּשַׁעֲתָא דְּעָבִיד דִּינָא וְקָטִיל בְּנֵי נָשָׁא, וְאִשְׁתְּכַח לְתַתָּא. וְכָל שֶׁכֵּן בְּשַׁעֲתָא דְּאַזְלֵי לְבֵי קִבְרֵי, וְאָהַדְרוּ מִבֵּי קִבְרֵי, דְּהָא בְּשַׁעֲתָא דְּנָשֵׁי נַטְלֵי רַגְלַיְיהוּ עִם מִיתָא, אִיהוּ נָחִית וְאִשְׁתְּכַח קָמַיְיהוּ, דִּכְתִּיב, (משלי ה׳:ה׳) רַגְלֶיהָ יוֹרְדוֹת מָוֶת, יוֹרְדוֹת לְמַאן. לְהַהוּא אֲתָר דְּאִקְרֵי מָוֶת. וְעַל דָּא חַוָּה גַּרְמַת מוֹתָא לְכָל עָלְמָא, רַחֲמָנָא לִשֵׁזְבִינָן.</p>\n<p>תָּא חֲזֵי, כְּתִיב (משלי ל׳:כ׳) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת וְגוֹ'. וְהָא אוֹקִימְנָא. אֲבָל כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת, דָּא הוּא מַלְאָךְ הַמָּוֶת, וְהָכִי הוּא, וְהָכִי אִקְרֵי. אָכְלָה וּמָחֲתָה פִיהָ, אוֹקִידַת עָלְמָא בְּשַׁלְהוֹבוֹי, וְקַטְלַת בְּנֵי נָשָׁא עַד לָא מָטָא זִמְנַיְיהוּ, וְאָמְרָה לֹא פָעַלְתִּי אָוֶן, דְּהָא דִּינָא בָּעָא עָלַיְיהוּ, וְאִשְׁתְּכָחוּ בְּחוֹבִין, וּבְדִינָא קְשׁוֹט מִיתוּ.</p>\n<p>בְּשַׁעֲתָא דְּעָבְדוּ יִשְׂרָאֵל יַת עֶגְלָא, וּמִיתוּ כָּל אִינּוּן אוּכְלוֹסִין, הֲוָה מַלְאָךְ הַמָּוֶת אִשְׁתְּכַח בֵּינֵי נְשֵׁי, בְּגוֹ מַשִׁרְיָּיתָא דְּיִשְׂרָאֵל. כֵּיוָן דְּאִסְתָּכַּל מֹשֶׁה, דְּהָא מַלְאָךְ הַמָּוֶת אִשְׁתְּכַח בֵּינִי נְשֵׁי, וּמַשִׁרְיָּיתָא דְּיִשְׂרָאֵל בֵּינַיְיהוּ, מִיַּד כָּנִישׁ לְכָל גּוּבְרִין לְחוֹדַיְיהוּ, הֲדָא הוּא דִכְתִיב וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל. אִלֵּין גּוּבְרִין, דְּכָנִישׁ לוֹן וְאַפְרִישׁ לוֹן לְחוֹדַיְיהוּ.</p>\n<p>וּמַלְאַךָ הַמָּוֶת לָא הֲוָה מִתְפְּרַשׁ מִגּוֹ נָשִׁין, עַד דְּאִתּוֹקָם מַשְׁכְּנָא, דִּכְתִּיב וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. וַאֲפִילּוּ בְּשַׁעֲתָא דְּנָשִׁין הָווֹ מַיְיתִין נְדָבָה לְמַשְׁכְּנָא, לָא הֲוָה מִתְעֲדֵי מִבֵּינַיְיהוּ, עַד דְּחָמָא מֹשֶׁה, וְיָהַב לְגוּבְרִין עֵיטָא, דְּלָא יִיִתוּן בְּחִבּוּרָא חֲדָא עִמְּהוֹן, וְלָא יִתְחֲזוּן אַנְפִּין בְּאַנְפִּין, אֶלָּא לְבָתַר כִּתְפַּיְיהוּ. הֲדָא הוּא דִכְתִיב וַיָבֹאוּ הָאֲנָשִׁים עַל הַנָּשִׁים (נ\"א ויבואו האנשים על הנשים לא כתיב, אלא ויבואו על) וַיָּבִיאוּ לָא כְּתִיב, אֶלָּא וַיָּבֹאוּ בְּאָרְחָא חֲדָא לָא הָווֹ אַזְלִין, אֶלָּא לְבָתַר כַּתְפַּיְיהוּ. בְּגִין דְּמַלְאָךְ הַמָּוֶת לָא אִתְפְּרַשׁ מִבֵּינַיְיהוּ עַד דְּאִתּוֹקָם מַשְׁכְּנָא.</p>\n<p>תָּא חֲזֵי, לָא אִשְׁתְּכַח בֵּינֵי נְשֵׁי, פָּחוּת מִשֶּׁבַע נָשִׁים, וְלָא פָּחוּת מֵעֶשֶׂר. וּבְאָרְחָא בְּאִתְגַּלְּיָא, בְּשֶׁבַע אִשְׁתְּכַח, וּבָעֵי דִּינָא. בְּעֶשֶׂר, אַסְטֵי לְקָטְלָא. וּבְגִין דְּאִשְׁתְּכַח בֵּינַיְיהוּ בְּאָרְחָא בְּאִתְגַּלְּיָא, כְּתִיב וַיָּבֹאוּ הָאֲנָשִׁים עַל הַנָּשִׁים. וְאִסְתְּמָרוּ כָּל הַהוּא יוֹמָא כֻּלְּהוּ חַבְרַיָּיא, וְאִשְׁתָּדָּלוּ בְּאוֹרַיְיתָא.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית ז׳:א׳) וַיֹּאמֶר יְיָ' אֶל נֹחַ בֹּא אַתָּה וְכָל בֵּיתְךָ אֶל הַתֵּבָה. הַאי קְרָא אוֹקִימְנָא, אֲבָל תָּא חֲזֵי, וְכִי לָא יָכִיל קוּדְשָׁא בְּרִיךְ הוּא לְנַטְרָא לֵיהּ לְנֹחַ, בְּאֲתָר חַד בְּעָלְמָא. דִּיְהֵא <Nonei></i>מַבּוּל בְּכָל עָלְמָא, וְלָא יְהֵא בְּהַהוּא אֲתָר, כְּמָה דִּכְתִּיב בְּגִּדְעוֹן, (שופטים ו׳:מ׳) וַיְהִי חוֹרֶב אֶל הַגִזָּה לְבַדָּהּ. אוֹ לְנַטְרָא לֵיהּ בְּאַרְעָא דְּיִשְׂרָאֵל, דִּכְתִּיב בָּהּ, (יחזקאל כ״ב:כ״ד) לָא גֻּשְׁמָהּ בְּיוֹם זָעַם, דְּלָא נַחְתּוּ עָלָהּ מִי טוֹפָנָא.</p>\n<p>אֶלָּא, כֵּיוָן דִּמְחַבְּלָא נָחַת לְעָלְמָא, מַאן דְּלָא סָגִיר גַּרְמֵיהּ, וְאִשְׁתְּכַח קָמֵיהּ בְּאִתְגַּלְיָיא, אִתְחַיָּיב בְּנַפְשֵׁיהּ, דְּאִיהוּ קָטִיל גַּרְמֵיהּ. מְנָא לָן. מִלוֹט, דִּכְתִּיב, (בראשית י״ט:י״ז) הִמָּלֵט עַל נַפְשֶׁךָ אַל תַּבִּיט אַחֲרֶיךָ. מַאי טַעֲמָא אַל תַּבִּיט אַחֲרֶיךָ. בְּגִין דִּמְחַבְּלָא אָזִיל בָּתַר כַּתְפּוֹי, וְאִי אָהֲדָר רֵישֵׁיהּ, וְאִסְתָּכַּל בֵּיהּ אַנְפִּין בְּאַנְפִּין, יָכִיל לְנַזְקָא לֵיהּ.</p>\n<p>וְעַל דָּא כְּתִיב, (בראשית ז) וַיִסְגוֹר יְיָ' בַּעֲדוֹ. דְּלָא יִתְחָזֵי קַמֵּי מְחַבְּלָא, וְלֹא יִשְׁלוֹט עָלֵיהּ מַלְאָךְ הַמָּוֶת. וְעַד דְּהַווּ טְמִירִין, מִיתוּ תְּלֵיסָר גּוּבְרִין בְּמָתָא. אָמַר רִבִּי שִׁמְעוֹן, בְּרִיךְ רַחֲמָנָא, דְּלָא אִסְתָּכַּל בְּדִיּוּקְנַיְיכוּ מַלְאָךְ הַמָּוֶת.</p>\n<p>(שמות ל״ה:א׳) וַיַּקְהֵל מֹשֶׁה וְגוֹ'. (קצ\"ה ע\"א) אָהֲדָר לוֹן כְּמִלְּקַדְּמִין, עוֹבָדָא דְּמַשְׁכְּנָא. אָמַר רִבִּי חִיָּיא, כֹּלָּא כְּמָה דְּאִתְּמַר. וְעוֹבָדָא דְּמַשְׁכְּנָא לָא אִתְעָבִיד אֶלָּא מִיִשְׂרָאֵל בִּלְחוֹדַיְיהוּ, וְלָא מֵאִינּוּן עֵרֶב רַב, בְּגִין דְּאִינּוּן עֵרֶב רַב אַמְשִׁיכוּ לֵיהּ לְמַלְאַךְ הַמָּוֶת לְנַחְתָּא לְעָלְמָא. כֵּיוָן דְּאִסְתָּכַּל מֹשֶׁה בֵּיהּ, אַשְׁדֵּי לְאִינּוּן עֵרֶב רַב, לְבַר, וְכָנִישׁ לוֹן לְיִשְׂרָאֵל בִּלְחוֹדַיְיהוּ, הֲדָא הוּא דִּכְתִּיב וַיַּקְהֵל מֹשֶׁה וְגוֹ'.</p>"],[9520011836,"<p>רִבִּי שִׁמְעוֹן פָּתַח, (משלי ל׳:ד׳) מִי עָלָה שָׁמַיִם וַיֵּרַד מִי אָסַף רוּחַ בְּחָפְנָיו מִי צָרַר מַיִם בַּשִּׂמְלָה מִי הֵקִים כָּל אַפְסֵי אָרֶץ מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדַע. הַאי קְרָא הָא אוֹקִימְנָא, וְכַמָּה סַמְכִין אִית בֵּיהּ. וְכֹלָּא בְּקוּדְשָׁא בְּרִיךְ הוּא אִתְּמַר, דְּאִיהוּ כֹּלָּא. (ע\"ט ע\"א) וְאִתְּמַר, מָה שְׁמוֹ וּמַה שֵׁם בְּנוֹ כִּי תֵּדַע, דָּא קוּדְשָׁא בְּרִיךְ הוּא. מָה שְׁמוֹ יְדוָֹ\"ד. וּמַה שֵׁם בְּנוֹ, יִשְׂרָאֵל דִּכְתִּיב, (שמות ד) בְּנִי בְּכֹרִי יִשְׂרָאֵל, וְהָא אוֹקִימְנָא. מִי עָלָה שָׁמַיִם. הָא אוּקְמוּהָ, דָּא מֹשֶׁה, דִּכְתִּיב, (שמות כ״ד:א׳) וְאֶל מֹשֶׁה אָמַר עֲלֵהּ אֶל יְיָ'.</p>\n<p>דָּבָר אַחֵר מִי עָלָה שָׁמַיִם, דָּא אֵלִיָּהוּ, דִּכְתִּיב בֵּיהּ (מלכים ב ב׳:י״א) וַיַּעַל אֵלִיָּהוּ בַּסֳּעָרָה הַשָּׁמָיִם. וְכִי הֵיךְ יָכִיל אֵלִיָּהוּ לְסַלְּקָא לַשָּׁמַיִם. וְהָא כֻּלְּהוּ שָׁמַיִם, לָא יַכְלִין לְמִסְבַּל, אֲפִילּוּ גַּרְעִינָא כְּחַרְדַּל מִגּוּפָא דְּהַאי עָלְמָא, וְאַתְּ אַמָרְתּ וַיַּעַל אֵלִיָּהוּ בַּסֳּעָרָה הַשָּׁמָיִם.</p>\n<p>אֶלָּא כְּמָה דְּאַתְּ אָמַר, (שמות י״ט:י״א) וַיֵּרֶד יְיָ' עַל הַר סִינַי. וּכְתִיב (שמות כ״ד:י״ח) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר. וְכִי קוּדְשָׁא בְּרִיךְ הוּא דְּהֲוָה בְּטוּרָא דְּסִינַי, וּכְתִּיב (שמות כ״ד:י״ז) וּמַרְאֶה כְּבוֹד יְיָ' כָּאֵשׁ אוֹכֶלֶת בְּרֹאשׁ הָהָר, אֵיךְ יָכִיל מֹשֶׁה לְסַלְּקָא לְגַבֵּיהּ. אֶלָּא בְּמֹשֶׁה כְּתִיב, וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר. דְּעָאל גּוֹ עֲנָנָא, כְּמַאן דְּאִתְלָבַּשׁ בִּלְבוּשָׁא. הָכִי נָמֵי אִתְלָבָּשׁ בַּעֲנָנָא, וְעָאל בְּגַוֵּיהּ. וּבְעֲנָנָא אִתְקְרִיב לְגַבֵּי אֶשָּׁא, וְיָכִיל לְמִקְרָב. אוּף הָכִי אֵלִיָּהוּ, דִּכְתִּיב וַיַּעַל אֵלִיָּהוּ בַּסֳּעָרָה הַשָּׁמַיִם, דְּעָאל בְּהַהִיא סְעָרָה, וְאִתְלָבַּשׁ בֵּיהּ בְּהַהִיא סְעָרָה, וְסָלִיק לְעֵילָּא.</p>\n<p>וְרָזָא אַשְׁכַּחְנָא, בְּסִפְרָא דְּאָדָם קַדְמָאָה, דְּאָמַר בְּאִינּוּן תּוֹלְדוֹת דְּעָלְמָא, רוּחָא חֲדָא יְהֵא דְּיֵּחוֹת לְעָלְמָא בְּאַרְעָא, וְיִתְלַבָּשׁ בְּגוּפָא, וְאֵלִיָּהוּ שְׁמֵיהּ. וּבְהַהוּא גּוּפָא יִסְתָּלַק, וְאִשְׁתְּלִיל מִגוּפֵיהּ, וְיִשְׁתְּאַר בַּסֳּעָרָה. וְגוּפָא דִּנְהוֹרָא אַחֲרָא יִזְדָּמַן לֵיהּ, לְמֶהוֵי גּוֹ מַלְאֲכֵי. וְכַד יֵחוּת, יִתְלַבָּשׁ בְּהַהוּא גּוּפָא, דְּיִשְׁתְּאַר בְּהַהוּא עָלְמָא, וּבְהַהוּא גּוּפָא יִתְחָזֵי לְתַתָּא, וּבְגוּפָא אַחֲרָא יִתְחָזֵי לְעֵילָּא. וְדָא אִיהוּ רָזָא, דְּמִי עָלָה שָׁמַיִם וַיֵּרַד. לָא הֲוָה בַּר נָשׁ דְּסָלִיק לִשְׁמַיָּא רוּחָא דִּילֵיהּ, וְנָחִית לְבָתַר לְתַתָּא, בַּר אֵלִיָּהוּ, דְּאִיהוּ סָלִיק לְעֵילָּא וְנָחִית לְתַתָּא.</p>\n<p>דָּבָר אַחֵר מִי עָלָה שָׁמַיִם, דָּא אֵלִיָּהוּ. וַיֵּרַד, דָּא יוֹנָה, דְּנָחַת לֵיהּ נוּנָא גּוֹ תְּהוֹמֵי, לְעִמְקֵי יַמָּא. יוֹנָה מֵחֵילָא דְּאֵלִיָּהוּ קָא אָתָא, אֵלִיָּהוּ סָלִיק, יוֹנָה נָחִית, דָּא שָׁאִיל נַפְשֵׁיהּ לְמֵימַת, וְדָא שָׁאִיל נַפְשֵׁיהּ לְמֵימַת, וּבְגִין כַּךְ אִקְרֵי בֶּן אֲמִתַּי. וּכְתִיב, (מלכים א י״ז:כ״ד) וּדְבַר יְיָ' בְּפִיךָ אֱמֶת.</p>\n<p>מִי צָרַר מָיִם, דָּא אֵלִיָּהוּ, דְּצָּרִיר צְרוֹרָא דְּמַיָּא בְּעָלְמָא, וְלָא נַחְתּוּ טַלָּא וּמִטְרָא דִּשְׁמַיָּא. בַּשִּׂמְלָה, דָּא אֵלִיָּהוּ, דְּהֲוָה (נ\"א מחי אדרתיה) מַיְיתֵי <Nonei></i>אַדַּרְתֵּיהּ לְמֶעְבָּד נִסִּין. מִי אָסַף רוּחַ בְּחָפְנָיו, דָּא אֵלִיָּהוּ, דְּאַהֲדָר רוּחָא דְּבַר נָשׁ לְגוֹ מֵעוֹי. (אסף כמה דאת אמר (מלכים ב ה׳:י״א) ואסף המצורע).</p>\n<p>מִי הֵקִים כָּל אַפְסֵי אָרֶץ. דָּא אֵלִיָּהוּ, דִּלְבָתַר דְּצָרַר מַיִם, וְאוֹמֵי עַל (ס\"א מטרא') שְׁמַיָא לְבָתַר אָהֲדַּר בִּצְלוֹתֵיהּ, וְאוֹקִים כָּל עָלְמָא, וְנָחִית מִטְרָא, וְאִתְיְהִיב מְזוֹנָא לְכֹלָּא. מַה שְּׁמוֹ, דָּא אֵלִיָּהוּ. וּמַה שֶּׁם בְּנוֹ, דָּא אֵלִיָּהוּ. מַה שְּׁמוֹ, כַּד סָלִיק לְעֵילָּא, אֵלִיָּהוּ. וּמַה שֶּׁם בְּנוֹ, כַּד נָחִית לְתַתָּא, וְאִתְעָבִיד שְׁלִיחָא לְמֶעְבַּד נִסִּין, אֵלִיָּהוּ שְׁמֵיהּ.</p>\n<p>דָּבָר אַחֵר מִי עָלָה שָׁמַיִם, דָּא קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאוֹקִימְנָא. וְרָזָא דְּמִלָּה, מִ\"י, וְהָא אוֹקִימְנָא. וְהָכָא אִיהוּ רָזָא דִּרְתִיכָא עִלָּאָה, (כ\"ג ע\"ב) אַרְבַּע סִטְרִין דְּעָלְמָא, דְּאִינּוּן יְסוֹדֵי קַדְמָאֵי דְּכֹלָּא, וְכֻלְּהוּ תַּלְיָין בְּהַהוּא אֲתָר עִלָּאָה דְּאִקְרֵי מִ\"י, כְּמָה דְּאִתְּמַר.</p>\n<p>תָּא חֲזֵי, כַּד קַיְּימָא שַׁעֲתָא דִּרְעוּתָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, לְיַחֲדָא רְתִיכָא עִלָּאָה (ס\"א ברתיכא תתאה') לְמֶהוֵי כֹּלָּא חַד. כְּדֵין קָלָא נָפִיק, מֵהַהוּא אֲתָר עִלָּאָה קַדִּישָׁא, דְּאִקְרֵי שָׁמַיִם, וְכָנִישׁ כָּל אִלֵּין קַדִּישִׁין דִּלְתַתָּא, וְכָל אִינּוּן רַבְרְבָן קַדִּישִׁין, וּמַשִׁרְיָין עִלָּאִין, לְמֶהֱוֵי כֻּלְּהוּ זְמִינִין כַּחֲדָא, הֲדָא הוּא דִכְתִיב, וַיַּקְהֵל מֹשֶׁה, דָּא רָזָא דְּשָׁמַיִם. אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל, אִלֵּין אִינּוּן תְּרֵיסַר מַשִׁרְיָין עִלָּאִין קַדִּישִׁין.</p>\n<p>וַיֹּאמֶר אֲלֵיהֶם. וּמַאי קָאָמַר זֶה הַדָּבָר וְגוֹ', קְחוּ מֵאִתְּכֶם תְּרוּמָה, אִתְתָּקָנוּ כֻּלְּכוּן, לְסַלְּקָא עָלַיְיכוּ, וּלְמֵיטַל עָלַיְיכוּ, יְקָרָא דְּכֻרְסְיָיא קַדִּישָׁא, לְסַלְּקָא לְעֵילָּא.</p>\n<p>אַפְרִישׁוּ מִנַּיְיכוּ אִינּוּן יַקִּירִין, אִינּוּן רַבְרְבִין עִלָּאִין, לְסַלְּקָא לְהַהִיא תְּרוּמָה, רָזָא דְּכֻרְסְיָיא קַדִּישָׁא, לְאִתְחַבְּרָא בַּאֲבָהָן, (נ\"א בבעלה) דְּהָא מַטְרוֹנִיתָא לָא אִתְחֲזֵי לְמֵיתֵי לְבַעְלָהּ, אֶלָּא בְּאִינּוּן בְּתוּלְתָּן עוּלֶמְתָּהָא, דְּיֵיתוּן עִמָּהּ, וּמְדַּבְּרָן לָהּ, עַד דְּמָטַת לְבַעְלָהּ, כְּמָה דְּאַתְּ אָמַר, (תהילים מ״ה:ט״ו) בְּתוּלוֹת אַחֲרֶיהָ רְעוּתֵיהּ וְגוֹ', וְכָל כַּךְ לָמָּה, לְמֵיתֵי לְאִתְחַבְּרָא בְּבַעְלָהּ.</p>"]]});
